INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-511a92d180408e0a', 'trung-hap-thit-bam-nam-huong-mem-min', 75, 'Trứng hấp thịt bằm nấm hương mềm mịn', 'Trứng gà đánh tan lọc mịn hấp cách thủy cùng thịt heo xay và nấm hương thơm dịu, mềm mượt như tàu hũ non', 'Món trứng hấp thịt bằm nấm hương béo bùi nhưng thanh nhẹ, bề mặt mịn mượt không bị rỗ nhờ lọc rây kỹ và hấp lửa nhỏ, kết hợp vị ngọt đậm của thịt heo xay cùng hương nấm đông cô đặc trưng.', 'Dọn nóng nguyên tô trứng hấp ra bàn, rắc thêm hành lá xanh và tiêu xay, ăn kèm cơm trắng nóng rất hợp cho cả trẻ nhỏ và người lớn tuổi.', 'Món ngon nhất khi dùng nóng ngay sau khi hấp. Nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và hấp cách thủy lại 5 phút ở lửa nhỏ.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 20, 22, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trẻ em thích","Thanh đạm","Cơm nhà","Dễ nấu"]', '["lunch","dinner"]', '["steam"]', '["egg","fish","pork","sesame"]', 309, 308.8, 1291, 20, 21.4, 7.3, 8.9, 1.2, 2.3, 1128, 2.82, '["USDA FDC 167902","USDA FDC 168436","USDA FDC 169655","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd91ad3e96b3d5fe9b53589eef07b7461230ac22c3d3722b2e571b3c1957cb739', '14a6a69bf67a386f1edf0b02f4dd265e9fed98ad082555288d2e3e415c23af6f', 4),
('imp-d02c9b83214f81be', 'goi-dua-leo-tom-thit-gion-mat', 76, 'Gỏi dưa leo tôm thịt giòn mát', 'Dưa leo bỏ ruột thái lát ngâm đá giòn rụm trộn cùng tôm rim ngọt thịt, ba chỉ luộc mỏng, cà rốt và húng lủi thấm đẫm nước mắm chanh tỏi ớt', 'Gỏi dưa leo tôm thịt là món khai vị thanh mát đặc trưng Nam Bộ với từng lát dưa leo xanh giòn không chảy nước, kết hợp thịt ba chỉ luộc mềm, tôm rim đỏ cam săn ngọt và nước trộn mắm chanh tương ớt chua cay mặn ngọt hài hòa.', 'Bày gỏi ra đĩa lớn, rắc đậu phộng rang giã dập và hành phi giòn lên trên, dọn ăn ngay kèm bánh phồng tôm giòn rụm.', 'Gỏi dưa leo ngon nhất ngay sau khi trộn để giữ độ giòn của rau củ; nếu chuẩn bị trước, giữ riêng phần dưa leo cà rốt đã vắt ráo, tôm thịt và nước mắm trộn trong hộp kín ngăn mát tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi dưa leo","Khai vị","Giải ngán","Nam Bộ","Tôm thịt"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["crustaceans","fish","peanut","pork","shrimp"]', 656, 656.3, 2746, 28.1, 42.6, 13.9, 43.4, 4.3, 16.9, 1458, 3.65, '["USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 175179","USDA FDC Sriracha Ref","VN Banh Da Ref"]', '7b732d74488a13acf783528365b074d26386e514c85dd4e10e01bcc1960a8f60', '2d65ffb6ee5906c1577b7275839087dc53b37f1dec36c3256d31261249e263f7', 4),
('imp-9ae951bec7fbf21b', 'hu-tieu-xao-tom-gia-he-kieu-sai-gon', 77, 'Hủ tiếu xào tôm giá hẹ kiểu Sài Gòn', 'Sợi hủ tiếu dai mềm thấm đẫm xì dầu và dầu hào thơm lừng, xào nhanh trên lửa lớn cùng tôm tươi giòn ngọt, giá đỗ và lá hẹ xanh mướt', 'Món hủ tiếu xào tôm giá hẹ mang đậm phong vị quán ăn Sài Gòn với sợi hủ tiếu tơi mềm không bết dính, áo màu nâu cánh gián bóng bẩy từ nước tương và dầu hào, kết hợp tôm sú giòn ngọt cùng giá hẹ tươi mát.', 'Bày hủ tiếu xào ra đĩa nóng, điểm ngò rí và ớt tươi thái lát lên trên; dọn ăn ngay kèm nước tương ớt xắt hoặc tương ớt.', 'Món xào ngon nhất khi ăn nóng ngay sau khi nấu để giữ độ giòn của giá hẹ; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo chống dính với chút nước lọc.', 'vietnamese', 'mon_bun_pho', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu xào","Sài Gòn","Món nhanh","Hải sản"]', '["breakfast","lunch","dinner"]', '["stir_fry","boil","assemble"]', '["crustaceans","molluscs","shrimp","soybean","wheat"]', 515, 515.4, 2157, 21.7, 12.8, 2, 77.5, 3.5, 5.9, 1273, 3.18, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169745","USDA FDC 169963","USDA FDC 169994","USDA FDC 169997","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '822622d83aef402c57ad1616c1f04130d359be90f90d81c3090e6954eeddfba3', '3d6ab2c517d1d5df65ae2617e3ea1411c40abf798672f6eb5f19fe44a8c66bc3', 4),
('imp-5ab5c1053b7371f0', 'dau-phu-chien-sa-ot-chay-dam-da', 78, 'Đậu phụ chiên sả ớt chay đậm đà', 'Miếng đậu phụ chiên vàng giòn rụm áo kín sả ớt băm phi thơm lừng, thấm xì dầu mặn ngọt đưa cơm', 'Đậu phụ trắng chiên vàng giòn bên ngoài nhưng vẫn mềm béo bên trong, xóc đều cùng sả băm, tỏi và ớt tươi phi thơm với nước tương đậm đà, tạo nên món mặn chay dân dã dậy hương sả ớt vô cùng đưa cơm.', 'Bày đậu phụ chiên sả ớt ra đĩa, rắc thêm chút tiêu xay và dọn nóng cùng cơm trắng, dưa leo thái lát hoặc rau luộc.', 'Ngon nhất khi ăn nóng ngay để cảm nhận lớp vỏ giòn thơm; nếu bảo quản ngăn mát tối đa 2 ngày, hãy áp chảo nhanh trên lửa vừa 3 phút cho đậu nóng giòn trở lại.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Chiên sả ớt","Đậm vị","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["soybean","wheat"]', 214, 214.2, 896, 13.9, 14.2, 2.1, 11.9, 1.5, 3.6, 1251, 3.13, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '875cd9c905c1d8c12ddc98caa50f74e59877981f56644e259aa1a370dc8a1748', '5ecf33351bded411ef149f66f577b94d9483a0b1cb3127d5be5588227396904b', 4),
('imp-67054d03e5a5b011', 'chao-trung-ga-hanh-la-gung-am-bung', 79, 'Cháo trứng gà hành lá gừng ấm bụng', 'Cháo trắng ninh nhừ sánh mịn quyện vân trứng gà béo mượt, thêm gừng thái chỉ và hành lá thơm ấm', 'Bát cháo trứng gà nóng hổi với hạt gạo tẻ nấu nhừ sánh quyện, vân trứng gà mềm mịn không tanh, nổi bật hương cay ấm dịu của gừng tươi thái chỉ, hành lá xanh mát và chút dầu mè.', 'Múc cháo nóng sôi trực tiếp lên bát đã lót hành lá và gừng thái chỉ, nhỏ vài giọt dầu mè thơm và rắc tiêu đen xay rồi dùng ngay.', 'Cháo trứng ngon nhất khi nấu tới đâu ăn nóng tới đó. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đun nóng lại trên lửa nhỏ cùng chút nước sôi.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 5, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Cháo trứng","Ăn sáng","Dưới 20 phút","Dễ tiêu","Ấm bụng"]', '["breakfast","dinner"]', '["boil","simmer"]', '["egg","fish","sesame"]', 276, 275.6, 1153, 9.6, 6.9, 1.8, 42.6, 1.2, 0.9, 1353, 3.38, '["USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647"]', '82bdf026928964ed652d9f9571899a34b05b413a19bcdaa3e6f245406a6378ca', '4264d139701e4ca8ea91902a80971094b56c5a4026b263ad314e70912330e76e', 4),
('imp-e375595daced53af', 'lau-bo-nhung-dua-chua-thanh', 80, 'Lẩu bò nhúng dứa chua thanh', 'Nước lẩu ngọt thanh từ nước dừa tươi và dứa chín, thơm sả hành phi, nhúng thịt thăn bò thái mỏng chín tới cuốn bánh tráng chấm mắm nêm', 'Lẩu bò nhúng dứa chua thanh mang phong vị phóng khoáng của ẩm thực Nam Bộ. Nước dùng kết hợp nước dừa tươi ngọt dịu, dứa chín, cà chua và chút giấm gạo tạo vị chua thanh rất dễ chịu, dùng nhúng thịt thăn bò thái mỏng cuốn cùng bánh tráng, rau sống và chấm mắm nêm đậm đà.', 'Bày đĩa thịt thăn bò thái mỏng, bánh tráng, bún tươi, rau muống, xà lách và chén mắm nêm dứa băm tỏi ớt quanh nồi lẩu sôi; nhúng bò chín tái 15–20 giây rồi cuốn ăn nóng.', 'Thịt bò tươi chưa nhúng giữ trong ngăn mát tối đa 24 giờ; phần nước lẩu còn dư đun sôi lại 3 phút trước khi dùng tiếp, không để thịt bò chín ngâm qua đêm trong nồi.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Bò nhúng","Dứa chín","Nam Bộ","Cuốn bánh tráng"]', '["lunch","dinner"]', '["simmer","boil","assemble"]', '["beef","fish"]', 796, 796.2, 3331, 41.4, 21.6, 7.3, 109.9, 7.7, 19.9, 1680, 4.2, '["NIN VN Fresh Bun Ref","USDA FDC 168573","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169247","USDA FDC 169378","USDA FDC 170000","USDA FDC 170106","USDA FDC 170174","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC Rice Paper Ref","USDA FDC Sucrose Ref","VN Mam Nem Ref"]', '97f842e02cd37690116aade03a0feb390a824ccb8bb0adc06e747b12d983743c', '6ca07cd11d4bbe29abf089c5fd460da4893a0731cbaf4a8d84fe85b5dbd6bd61', 4),
('imp-9b4ea97916a44e67', 'canh-rau-muong-nau-tom-thanh-mat', 81, 'Canh rau muống nấu tôm thanh mát', 'Rau muống xanh mướt giòn ngon hòa cùng vị ngọt đậm của tôm tươi giã dập, món canh thanh nhiệt nhanh gọn kiểu miền Bắc', 'Món canh mùa hè thanh mát đậm chất cơm nhà Bắc Bộ với từng cọng rau muống xanh giòn, nước dùng trong ngọt thanh vị tôm tươi giã nhuyễn và mùi thơm dịu nhẹ của hành tím phi.', 'Dọn canh nóng vào tô lớn, có thể vắt thêm vài giọt chanh tươi khi dùng hoặc ăn kèm cà pháo muối, cơm trắng và món mặn kho tiêu.', 'Canh rau muống nên dùng hết ngay trong bữa để giữ màu xanh và độ giòn của rau; không khuyến khích đun lại nhiều lần vì rau dễ chuyển màu thẫm.', 'vietnamese', 'mon_canh', 'bac', 'easy', 12, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Dưới 20 phút","Thanh mát","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 103, 103.1, 431, 12.9, 3.8, 0.6, 6.1, 2.4, 2.3, 1238, 3.1, '["USDA FDC 169378","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '50f66046d1e252ea6781d0e0f2faecd69622c94c5c606939b51b600bc49e3776', '487b988233f9fcfbb50fed836f354f6d80e660dc599db6dfbe3efd3520a1de61', 4),
('imp-6d7fc503ade5df6e', 'thit-ba-chi-xao-sa-ot-kieu-mien-trung', 82, 'Thịt ba chỉ xào sả ớt kiểu miền Trung', 'Thịt ba chỉ thái mỏng áp chảo xém cạnh vàng ươm, quyện sả ớt băm thơm nồng và nước mắm mặn ngọt cực đưa cơm', 'Thịt ba chỉ xào sả ớt kiểu miền Trung hấp dẫn với phần thịt ba chỉ săn giòn xém cạnh không hề ngấy mỡ, thấm đẫm hương thơm nồng nàn của sả băm, vị cay bùng nổ từ ớt tươi và mặn ngọt hài hòa của nước mắm ngon.', 'Gắp thịt ba chỉ xào sả ớt ra đĩa, rắc hành lá và tiêu đen xay lên trên; ăn nóng kèm cơm trắng dẻo và rau luộc hoặc dưa leo thái lát.', 'Món mặn này bảo quản được trong hộp kín ngăn mát tủ lạnh 2–3 ngày; khi ăn chỉ cần đảo nóng lại trên chảo khô ở lửa vừa khoảng 2 phút.', 'vietnamese', 'mon_xao', 'trung', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt heo","Miền Trung","Cay nồng","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["fish","pork"]', 635, 634.7, 2655, 11.7, 59.7, 21.4, 13.1, 0.5, 3.6, 785, 1.96, '["USDA FDC 167820","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","VN/Asian Seasoning Powder Avg"]', '63340daf71353016cc681651a99ae080431bdcc8c15274757c2ddd812413b2fa', 'fff27227d4391a9de0a7f603f0d348d91009b02daf5f4a6efed946657862092d', 4),
('imp-364497296cfcf033', 'muc-nhoi-thit-hap-gung-hanh', 83, 'Mực nhồi thịt hấp gừng hành', 'Mực ống tươi nhồi đầy thịt heo xay trộn nấm hương thơm bùi, hấp chín mềm cùng gừng sợi và hành lá chấm muối tiêu chanh', 'Những khoanh mực ống trắng giòn ôm trọn phần nhân thịt heo xay dẻo ngọt quyện hương nấm hương, hành tím và gừng thơm nồng; món hấp thanh nhẹ nhưng đậm đà, đẹp mắt cho mâm cơm gia đình lẫn tiệc đãi khách.', 'Cắt mực nhồi thịt thành khoanh dày khoảng 1,5 cm xếp xen lớp ra đĩa, trang trí hành lá và gừng sợi; ăn nóng chấm cùng muối tiêu chanh hoặc nước mắm ớt.', 'Mực nhồi thịt đã hấp bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi ăn hấp lại 5–6 phút cho nhân thịt nóng đều mà vỏ mực không bị dai.', 'vietnamese', 'mon_hap_luoc', 'trung', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Đãi khách","Thanh đạm","Miền Trung"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","pork","squid"]', 297, 297.1, 1243, 28.4, 14.9, 5.3, 11.5, 1.2, 2, 1112, 2.78, '["USDA FDC 167902","USDA FDC 168155","USDA FDC 168436","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '22ba22fae19d88be2589b4bf28bff3bd07cbb502fbc17ecf507ea5e8c6c28783', 'a4d5fcb658c1edf506484e10c9679dc6d5bde4e3549da2fcfe4e72435a2c6e55', 4),
('imp-806780abda4b5205', 'com-chien-dua-tom-hai-san', 84, 'Cơm chiên dứa tôm hải sản', 'Cơm chiên vàng ươm mùi cà ri nhẹ quyện tôm mực giòn ngọt, dứa chín chua dịu và hạt điều rang bùi', 'Món cơm chiên dứa hải sản Nam Bộ rực rỡ sắc màu với từng hạt cơm tơi vàng ươm hương bột cà ri dịu, tôm tươi và mực giòn ngọt, dứa chín mọng nước cân bằng vị cùng hạt điều rang bùi béo.', 'Có thể múc cơm chiên vào lòng nửa trái dứa khoét rỗng để tăng hương thơm và vẻ bắt mắt; rắc hành lá, tiêu xay và hạt điều rang rồi ăn nóng kèm xì dầu ớt.', 'Ngon nhất khi ăn nóng ngay sau khi chiên để hạt điều giòn và hải sản không bị dai. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng nhanh trên chảo lửa vừa.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Hải sản","Nam Bộ","Ăn sáng","Dứa thơm"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["cashew","crustaceans","egg","fish","molluscs","shrimp","squid","tree_nuts"]', 544, 543.8, 2275, 28.3, 15.7, 3.1, 73.1, 4.2, 11.7, 986, 2.47, '["USDA FDC 168878","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170162","USDA FDC 170393","USDA FDC 170499","USDA FDC 170924","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 174223","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '9d66ac84afccb043c6748e238ef4147f94fd4d229ab1ea0cd321aa182402b368', '97bb44c0f21c43c290dd68d7ac3b50def40357e028027d0813373a09bd8eaa93', 4),
('imp-a48b19224e397cea', 'com-bo-hanh-tay-gyudon-kieu-nhat', 85, 'Cơm bò hành tây Gyudon kiểu Nhật', 'Thịt bò thái mỏng mềm ngọt quyện hành tây om trong nước dùng dashi, sake và xì dầu đậm đà, phủ trên tô cơm Nhật dẻo nóng', 'Gyudon là món cơm bò quốc dân của Nhật Bản với những lát thịt bò có vân mỡ mỏng tang được om nhanh cùng hành tây thái múi trong sốt xì dầu, rượu sake, mirin và dashi thanh ngọt.', 'Xới cơm trắng nóng ra tô sâu lòng, gắp thịt bò và hành tây phủ kín mặt cơm, rưới thêm vài muỗng nước sốt om rồi rắc hành lá thái khoanh; có thể ăn kèm trứng lòng đào hoặc gừng hồng muối.', 'Phần thịt bò và nước sốt nguội có thể cho vào hộp kín bảo quản tủ mát tối đa 2 ngày; khi dùng hâm nóng trên bếp lửa nhỏ 2–3 phút rồi mới chan lên cơm nóng.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cơm donburi","Thịt bò","Nhanh gọn","Bữa trưa"]', '["lunch","dinner"]', '["simmer"]', '["beef","egg","fish","soybean","wheat"]', 638, 637.6, 2668, 39.3, 18.2, 6.7, 70.3, 2.3, 12.8, 1467, 3.67, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168878","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 171287","USDA FDC 174277"]', 'a84f0f142a805de472824bc5f9732bb465e6d53af8cb4441df8c4d10b0c83c6c', '73737099a5b243548474a25d21553695e4b6dfc47f0f7e99b38b8bd043a4b123', 4),
('imp-79819e1b0c75f4da', 'mi-udon-xao-thit-heo-bap-cai-yaki-udon', 86, 'Mì Udon xào thịt ba chỉ bắp cải Yaki Udon', 'Sợi mì Udon trắng tròn dai mềm xào lửa lớn cùng thịt ba chỉ xém cạnh, bắp cải giòn ngọt, cà rốt và nấm hương đậm vị xì dầu Nhật', 'Yaki Udon là món mì xào trứ danh của ẩm thực đường phố Nhật Bản với sợi mì udon dày mềm dai quyện vị béo thơm của thịt ba chỉ, rau củ tươi giòn và nước sốt xì dầu pha rượu mirin, sake cùng cá bào katsuobushi.', 'Bày mì Udon xào nóng hổi ra đĩa sâu lòng, rắc ngay cá bào khô Katsuobushi để từng lát cá múa nhẹ theo hơi nóng và thưởng thức liền tay.', 'Mì ngon nhất khi ăn nóng ngay sau khi xào; phần dư có thể cất hộp kín tủ lạnh tối đa 2 ngày, khi ăn xào lại trên chảo lửa vừa với 1 muỗng canh nước lọc để sợi mì mềm tơi trở lại.', 'japanese', 'mon_xao', NULL, 'easy', 12, 18, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì xào","Yaki Udon","Thịt ba chỉ","Bữa tối"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["fish","pork","soybean","wheat"]', 779, 778.5, 3257, 18.6, 50.2, 16.7, 59.7, 6.6, 8.8, 1474, 3.69, '["MEXT Boiled/Fresh Udon","MEXT Hon-Mirin 16031","MEXT Katsuobushi 10099","MEXT Sake 16021","USDA FDC 167820","USDA FDC 169251","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '0171afac52ea4477abebed5a7679929fe4dee43327ee2ffbc64c100965c37574', '13fd627ec21a15b26423d315c7ff1e7308790596b211c5e12beecf8402785dc6', 4),
('imp-ac255bcc36d1324e', 'ca-hoi-ap-chao-sot-teriyaki-bong-dep', 87, 'Cá hồi áp chảo sốt Teriyaki kiểu Nhật', 'Phi lê cá hồi còn da áp chảo giòn rụm, thịt cá mềm mọng ẩm quyện lớp sốt Teriyaki sánh bóng đậm đà hương bơ, gừng tỏi', 'Cá hồi phi lê còn da được phủ nhẹ lớp bột mì giữ trọn nước ngọt bên trong, áp chảo mặt da giòn vàng với bơ lạt rồi rim nhanh trong sốt Teriyaki tự pha từ nước tương Nhật, rượu mirin, sake và đường.', 'Xếp từng miếng cá hồi ra đĩa với mặt da giòn quay lên trên, rưới phần sốt Teriyaki sánh bóng còn lại trong chảo, rắc hành lá thái nhỏ và dọn kèm cơm trắng nóng cùng bông cải xanh luộc.', 'Phần cá thừa bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi ăn làm nóng nhanh trong chảo lửa nhỏ có thêm 1 muỗng canh nước hoặc quay lò vi sóng 1 phút.', 'japanese', 'mon_chien', NULL, 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cá hồi","Teriyaki","Áp chảo","Bổ dưỡng"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["fish","milk","salmon","soybean","wheat"]', 468, 468, 1958, 32.9, 27.8, 7.9, 15.9, 0.5, 9.7, 1258, 3.15, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169761","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175167"]', 'c5bcbee07e09ace8f3444007688b69f58b40baee2e0231eacf872eb27cb9bca5', '045a8c482be0a614ac650c3c134a74b9934c17b2c6367ff84e1be41275a4a459', 4),
('imp-bb07db73fb381724', 'dau-phu-lanh-hiyayakko-gung-hanh', 88, 'Đậu phụ non lạnh Hiyayakko gừng hành', 'Đậu phụ non ướp lạnh mềm tan trong miệng, phủ gừng tươi mài nhuyễn, hành lá và cá bào, rưới xì dầu Nhật quyện dầu mè thanh mát', 'Hiyayakko là món đậu phụ lạnh truyền thống ngày hè của Nhật Bản, giữ trọn vị béo mát nguyên bản của đậu phụ non kết hợp cùng gừng mài cay ấm, hành lá giòn thơm và nước tương pha dầu mè thanh dịu.', 'Dọn lạnh ngay sau khi rưới nước tương lên đậu phụ; dùng làm món khai vị giải nhiệt hoặc ăn kèm cơm trắng và cá nướng.', 'Món ăn dùng lạnh ngay trong ngày để giữ độ tươi mịn của đậu phụ non; không hâm nóng hay cấp đông vì sẽ làm đậu bị rỗ xốp.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 1, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Khai vị","Không cần nấu","Đậu phụ","Thanh mát"]', '["lunch","dinner"]', '["assemble"]', '["fish","sesame","soybean","wheat"]', 155, 154.8, 648, 12.1, 8.5, 1.2, 8.2, 1.1, 1.8, 718, 1.79, '["MEXT Katsuobushi 10099","USDA FDC 168456","USDA FDC 169231","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 172476","USDA FDC 174277"]', 'ef1b6ae09d334a06363aa0a518c6383d16eb9318e2965d3568455f6d3bd50dc5', '5be84c00e33fa803659f68ba420bb3b5520deabb9fb2cd30189802e030248523', 4),
('imp-a9398d96945ba6f7', 'canh-kim-chi-dau-phu-thit-ba-chi-kimchi-jjigae', 89, 'Canh kim chi đậu phụ thịt ba chỉ (Kimchi Jjigae)', 'Nồi canh Kimchi Jjigae sôi sục đậm đà từ kim chi cải thảo ủ chua, thịt ba chỉ béo mềm, nấm đùi gà và đậu phụ trắng thanh mát', 'Canh kim chi đậu phụ thịt ba chỉ (Kimchi Jjigae) là món canh hầm quốc dân xứ Hàn với nước dùng đỏ rực sóng sánh vị chua thanh từ kim chi ủ kỹ, béo ngọt từ thịt ba chỉ xào săn và mềm mịn tan nhẹ của từng miếng đậu phụ.', 'Dọn canh trong nồi đất giữ nhiệt khi còn sôi lăn tăn, rắc thêm hành lá xanh và ăn kèm cơm trắng nóng hổi cùng rong biển khô.', 'Canh kim chi để qua ngày càng thấm đậm vị; bảo quản hộp kín trong ngăn mát tối đa 3 ngày và đun sôi kỹ trên lửa vừa 5 phút trước khi dùng.', 'korean', 'mon_canh', NULL, 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Kim chi","Ấm bụng","Cay đậm"]', '["lunch","dinner"]', '["simmer","stir_fry"]', '["fish","pork","sesame","soybean","wheat"]', 445, 444.8, 1861, 14.8, 36.3, 11.9, 16.6, 4.1, 7.8, 1566, 3.91, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","MEXT Hon-Mirin 16031","USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277"]', '0a8dc85e316cfc8b5ea740cecc5c37a0c80b26f7c009715e776dc9b73fd09721', '07897b85ecdf2f8d832f733a27eef616ac6a62509788cc877a2f11a0d6cdc69d', 4),
('imp-af8a9cdb17d5e9fd', 'bo-xao-bulgogi-hanh-tay-ca-rot', 90, 'Bò xào Bulgogi hành tây cà rốt', 'Thịt bò thăn thái mỏng ướp xì dầu, tỏi gừng và đường nâu mềm mọng, xào lửa lớn thơm lừng cùng hành tây giòn ngọt và cà rốt', 'Bò xào Bulgogi hành tây cà rốt là món mặn trứ danh của ẩm thực Hàn Quốc với từng lát thịt bò thăn mềm mọng thấm gia vị mặn ngọt hài hòa từ nước tương, đường nâu, rượu ngọt Mirin và dầu mè rang, xào cùng hành tây cà rốt giòn thanh.', 'Dọn bò Bulgogi nóng ra đĩa, rắc thêm hạt mè trắng rang và hành lá xanh; ăn kèm cơm trắng nóng hoặc cuốn lá xà lách chấm tương đậu Hàn.', 'Bảo quản thịt bò đã xào trong hộp kín ngăn mát tối đa 2 ngày; hâm nhanh trên chảo nóng với lửa vừa 2–3 phút, tránh đun quá lâu khiến thịt bò bị khô dai.', 'korean', 'mon_xao', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món xào","Thịt bò","Bulgogi","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","sesame","soybean","wheat"]', 428, 427.6, 1790, 31.5, 25.1, 7.2, 17.9, 1.9, 11.8, 874, 2.19, '["MEXT Hon-Mirin 16031","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174277"]', 'dc3c3114bc763283bb36858331bcccdcfde5fcea55d124619f59b58e9a4d27aa', 'f78f0306f368694d76535fd7279fd60a19526cb534e96ad99b35820c391b5378', 4),
('imp-d3d0c59e0cfa845d', 'banh-kim-chi-chien-kimchi-jeon-gion-rum', 91, 'Bánh kim chi chiên giòn (Kimchi Jeon)', 'Bánh xèo kim chi cải thảo chiên áp chảo vàng rụm hai mặt, viền giòn tan kết hợp nước chấm xì dầu giấm gạo chua ngọt thanh dịu', 'Bánh kim chi chiên giòn (Kimchi Jeon) là món bánh dân dã nhưng cực kỳ bắt miệng của Hàn Quốc với lớp bột pha nước lạnh giòn rụm bên ngoài, bên trong đậm vị chua cay của kim chi cải thảo chín, hành tây và hành lá thơm nồng.', 'Cắt bánh thành từng miếng tam giác vừa ăn khi còn nóng giòn, chấm kèm chén nước tương pha giấm gạo và hạt mè trắng rang.', 'Nên thưởng thức ngay khi vừa chiên xong để giữ độ giòn. Nếu còn dư, bọc kín cất ngăn mát tối đa 24 giờ và áp chảo lại trên chảo không dầu ở lửa vừa 3–4 phút cho giòn lại.', 'korean', 'mon_chien', NULL, 'easy', 10, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món chiên","Kim chi","Ăn vặt","Giòn rụm"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["egg","sesame","soybean","wheat"]', 512, 512.2, 2143, 12.8, 19.8, 3.3, 70.6, 4.7, 3.9, 1134, 2.84, '["Korean Chili Flake Ref","USDA FDC 169655","USDA FDC 169698","USDA FDC 169761","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 171287","USDA FDC 171413","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', 'ba1dd3f2abbc5a1436721aefd4fc1807c0c596d67cc4dbefeb27841548f535be', '40073301c2b41c95bf8952a73bd33ff5bc68950a3cb369d99dac7fb8a44af743', 4),
('imp-262caf09e6f38c59', 'bong-cai-xanh-xao-toi-kieu-quang-dong', 92, 'Bông cải xanh xào tỏi kiểu Quảng Đông', 'Bông cải xanh chần nhanh giữ màu xanh ngọc giòn ngọt, xào lửa lớn cùng tỏi gừng thơm lừng và sốt xì dầu sánh bóng', 'Bông cải xanh xào tỏi kiểu Quảng Đông giữ trọn độ giòn ngọt tự nhiên và màu xanh mướt nhờ kỹ thuật chần nước sôi trước khi xào nhanh trên lửa lớn cùng tỏi băm, gừng thơm và lớp sốt xì dầu sánh nhẹ.', 'Bày ngay ra đĩa khi vừa tắt bếp, dùng nóng làm món rau ăn kèm các món kho, món chiên trong bữa cơm gia đình.', 'Món rau xào nên ăn hết trong bữa để giữ độ giòn xanh; nếu bảo quản tủ mát tối đa 24 giờ, làm nóng nhanh trên chảo nóng trong 1–2 phút.', 'chinese', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Rau xanh","Xào tỏi","Thanh nhẹ"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["sesame","soybean","wheat"]', 142, 141.7, 593, 4.8, 8.6, 1.2, 14.2, 3.5, 3.7, 731, 1.83, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170379","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '554becbc09c4e21bdb4394fea115bdc8b96e50683bd92f8583a1a05b9b27bd87', '34535a9e60e495fb8e1cfc1efd2e6b854111b536c059879e587ee76d3e0e6c92', 4),
('imp-352999f711c710d9', 'ga-xao-gung-hanh-kieu-quang-dong', 93, 'Gà xào gừng hành kiểu Quảng Đông', 'Thịt đùi gà tẩm bột bắp áp chảo vàng xém, xào nhanh với gừng lát thơm nồng, hành tím, rượu Thiệu Hưng và sốt dầu hào sánh đậm', 'Gà xào gừng hành kiểu Quảng Đông sử dụng thịt đùi gà lọc xương ướp kỹ thuật giữ ẩm, áp chảo xém thơm rồi quyện cùng hương gừng già cay ấm, hành lá giòn ngọt và nước sốt xì dầu dầu hào sánh óng.', 'Dọn nóng ra đĩa cùng cơm trắng dẻo thơm và một đĩa rau cải thìa chần hoặc xào tỏi thanh nhẹ.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa vừa với 1–2 muỗng canh nước lọc hoặc nước dùng gà trong 3 phút.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Thịt gà","Gừng hành","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["chicken","molluscs","sesame","soybean","wheat"]', 448, 448.1, 1876, 35, 25.2, 6, 16.3, 1.4, 4, 1326, 3.32, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 172883","USDA FDC 173468","USDA FDC 174277"]', '2a46ce996a47f75e90f4a61faa02b5278ee886521465f0e5d2083b824a704869', '24217c294b834356e1472d5afbcf02b5df32060e803f2379326d83be5b218794', 4),
('imp-b3f99919ea9f17f8', 'canh-bi-dao-thit-bam-kieu-hoa', 94, 'Canh bí đao thịt bằm viên kiểu Hoa', 'Nước dùng gà thanh ngọt ninh cùng bí đao trong mướt và những viên thịt heo quết tay dai giòn thơm mùi gừng hành', 'Canh bí đao thịt bằm viên kiểu Hoa mang vị thanh tao, nước dùng trong ngọt từ nước dùng gà hòa quyện bí đao mềm mọng và viên thịt heo quết một chiều dai ngọt tự nhiên.', 'Múc canh ra tô lớn khi còn nóng hổi, rắc thêm lá hành xanh, ngò rí và chút tiêu trắng xay; dùng kèm cơm trắng và các món mặn.', 'Ngon nhất khi dùng trong ngày để bí đao không bị bở. Nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhẹ lại trên lửa vừa trong 3–5 phút trước khi dùng.', 'chinese', 'mon_canh', NULL, 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thanh mát","Trung Hoa","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","pork","sesame","soybean","wheat"]', 296, 295.7, 1237, 17.3, 21.3, 6.9, 7.5, 3.9, 3, 1481, 3.7, '["Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169214","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '86156f50b6791659643318468b57950c2eabb8586584821eadee63a4fabfa2ca', 'fb64d6cadd97a28f86ff9ab80ac32c21425ead3655ecd384baf2462c6b598ed9', 4),
('imp-b6dae711698259d6', 'canh-tom-chua-cay-tom-yum-kieu-thai', 95, 'Canh tôm chua cay Tom Yum kiểu Thái', 'Nước dùng tôm ngọt thanh nấu cùng sả, riềng, lá chanh Thái và nấm tươi, hòa quyện vị chua thanh của chanh và cay ấm của sốt Tom Yum', 'Tom Yum Goong là món canh quốc hồn quốc túy của Thái Lan với nước dùng chiết xuất từ vỏ đầu tôm phi thơm cùng bộ ba thảo mộc sả, riềng, lá chanh Kaffir và vị chua cay bừng vị.', 'Múc canh Tom Yum nóng hổi ra tô lớn, rắc ngò rí thái nhỏ lên trên, ăn kèm cơm trắng gạo lài hoặc dùng làm món canh khai vị ấm bụng.', 'Canh hải sản ngon nhất khi ăn ngay; nếu cần bảo quản, để nguội và cất ngăn mát trong 24 giờ, khi hâm lại chỉ đun nóng vừa tới để tôm không bị dai.', 'thai', 'mon_canh', NULL, 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Tom Yum","Chua cay","Hải sản"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 171, 171.4, 717, 20.7, 5.4, 0.8, 11.8, 2.4, 6.4, 1462, 3.65, '["Citrus Leaf Culinary Ref","Thai Tom Yum Paste Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169251","USDA FDC 169655","USDA FDC 169997","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179"]', 'c8144fb55f1a9758164d6c7abd8f882e39ce9c663e87b112b22300eeab82a659', '449eaf4ba0ba8808cf8fb74f42dfd9d45dc936de49ec71c9994591c79d713c9f', 4),
('imp-f729957329cd75f5', 'mi-xao-pad-thai-tom-gia-do', 96, 'Mì xào Pad Thai tôm giá đỗ', 'Bánh phở gạo mềm dai áo đẫm sốt me thốt nốt chua ngọt mặn mà, xào lửa lớn cùng tôm tươi, đậu phụ, trứng tơi và đậu phộng giòn bùi', 'Pad Thai chuẩn vị với sự hòa quyện tinh tế giữa sợi bánh phở gạo dai mềm, sốt me chua ngọt nấu từ đường thốt nốt, tôm áp chảo săn ngọt, đậu phụ chiên vàng, trứng gà đánh tơi cùng giá đỗ và hẹ tươi.', 'Gắp Pad Thai nóng ra đĩa, xếp tôm áp chảo lên trên, rắc đậu phộng rang giã dập và ớt vảy khô; dọn kèm giá sống, hẹ tươi và múi chanh để vắt trực tiếp khi ăn.', 'Pad Thai ngon nhất khi thưởng thức ngay lúc vừa xào xong; nếu dư có thể cất ngăn mát tối đa 24 giờ và xào nóng lại trên chảo với 1 muỗng canh nước lọc để sợi mì tơi mềm.', 'thai', 'mon_xao', NULL, 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Thai","Mì xào","Hải sản","Chua ngọt"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","peanut","shrimp","soybean"]', 691, 691.3, 2893, 38.1, 24.5, 4.1, 83.1, 5.8, 24.4, 1425, 3.56, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169745","USDA FDC 169918","USDA FDC 169963","USDA FDC 169994","USDA FDC 170499","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 172475","USDA FDC 173647","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', '3552f74b93350768169de073d22ec4f964a3bec47fa2da6e7fb70790f1d3b453', '53c8c3cac646056883acf6c09e3a58d1df92608f2b9991a1260afaed5a13bb81', 4),
('imp-04d0b94d17ce080c', 'ga-xao-gung-nam-kieu-thai-gai-pad-khing', 97, 'Gà xào gừng nấm kiểu Thái (Gai Pad Khing)', 'Ức gà thái lát mềm ngọt xào lửa lớn cùng gừng non thái sợi chỉ, nấm hương tươi và hành tây, thấm đẫm sốt dầu hào xì dầu thơm nồng', 'Gai Pad Khing là món xào gia đình thanh đạm nhưng rất bắt cơm của Thái Lan, kết hợp thịt ức gà mềm mọng với hương cay ấm của gừng tươi thái sợi chỉ, vị ngọt tự nhiên từ nấm hương và hành tây giòn nhẹ.', 'Múc gà xào gừng nấm nóng hổi ra đĩa sâu lòng, rắc chút tiêu nếu thích và dọn ăn ngay với cơm trắng dẻo thơm.', 'Nên dùng nóng ngay để hành tây và gừng giữ độ giòn; nếu bảo quản ngăn mát tối đa 2 ngày, hâm nóng nhanh trên chảo lửa vừa với chút nước lọc để sốt bóng trở lại.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món xào","Ức gà","Gừng nấm","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish","molluscs","soybean","wheat"]', 272, 272.2, 1139, 32, 9.3, 1.6, 14.7, 2.3, 5.5, 987, 2.47, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 171477","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277"]', '71b2d6e0501083f7d3704b14a2647077f67cd93a274cb437e1adfb2a04bf2a4e', '900b8a16362866947ee6225801f193c98449f98d36e751b8641fa426ad67e531', 4),
('imp-b01569fd0df22f66', 'mi-y-aglio-e-olio-toi-ot-dau-olive', 98, 'Mì Ý Aglio e Olio tỏi ớt dầu ô liu', 'Món mì Ý tối giản trứ danh với sợi Spaghetti bóng mượt nhũ tương dầu ô liu nguyên chất, tỏi thái lát vàng thơm và ớt sừng cay dịu', 'Mì Ý Aglio e Olio là món mì đêm khuya kinh điển của người Ý chỉ dùng những nguyên liệu mộc mạc nhất: tỏi lát phi vàng dịu trong dầu ô liu nguyên chất, chút ớt sừng cay nhẹ và nước luộc mì giàu tinh bột tạo lớp sốt óng mượt.', 'Chia mì ra đĩa sâu lòng đã làm ấm, rưới phần dầu tỏi ớt còn lại trong chảo và rắc thêm ngò tây tươi băm nhuyễn nếu thích, dùng nóng ngay.', 'Món mì trộn dầu nhũ tương ngon nhất khi thưởng thức ngay lúc vừa chế biến; nếu còn dư nên bảo quản ngăn mát tối đa 1 ngày và đảo nhanh trên chảo cùng chút nước ấm.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Aglio e Olio","Dưới 30 phút","Tối giản"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["wheat"]', 483, 483.3, 2022, 12.1, 17.4, 2.5, 69, 3.1, 2.6, 473, 1.18, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'ebfe0610823914364f6694fa21c115b70b5be262243085bd4c2e55e5db471287', '3b3b6eb8994c62d2d40174e3ba14683f8dc8636f49d2570457baf66806538964', 4),
('imp-d463228be1e6e7c0', 'com-risotto-nam-bo-pho-mai-beo-ngay', 99, 'Cơm Risotto nấm bơ phô mai béo ngậy', 'Gạo Ý Arborio rang thơm rồi om chậm cùng nước dùng rau củ nóng, nấm xào vàng xém và đánh bóng cuối bằng bơ lạt lạnh cùng phô mai Parmesan', 'Cơm Risotto nấm bơ phô mai là món cơm kem đặc trưng của miền Bắc nước Ý. Hạt gạo Arborio hạt tròn giàu tinh bột được rang nhẹ rồi om từng vá nước dùng rau củ nóng, hòa quyện vị ngọt umami từ nấm áp chảo và độ béo mịn của bơ lạnh, phô mai Parmesan.', 'Múc cơm Risotto ra đĩa sâu lòng để giữ độ sóng sánh, xếp phần nấm xào để riêng lên mặt, rắc thêm ngò tây băm, tiêu đen xay và chút phô mai Parmesan.', 'Cơm Risotto ngon nhất khi ăn nóng ngay sau khi hoàn thiện; phần dư bảo quản ngăn mát tối đa 2 ngày, khi hâm lại thêm ít nước dùng rau củ khuấy trên lửa nhỏ.', 'italian', 'mon_kho', NULL, 'medium', 15, 30, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cơm Risotto","Nấm tươi","Bơ phô mai","Ấm bụng"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["milk","sulphites"]', 595, 594.9, 2488, 15.1, 23.2, 11, 78.8, 4.3, 5.1, 1434, 3.58, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171595","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC Arborio Rice Ref"]', '30688cfa2bfdb73a26e165321e2aa818cb26723e7e8729a877ab337e4ef4ae3b', 'c3de2c7a2cc424d1170c0b3280f1e77fef5ca16f1fbdb0611f392a26500e5305', 4),
('imp-9d575ec5c01896f0', 'mi-y-sot-kem-ca-hoi-rau-bina', 100, 'Mì Ý sốt kem cá hồi rau bina', 'Spaghetti dai mềm quyện sốt kem tươi béo ngậy cùng phi lê cá hồi áp chảo vàng thơm, rau bina xanh non và hương chanh vàng thanh mát', 'Mì Ý sốt kem cá hồi rau bina mang đến sự cân bằng tinh tế giữa phi lê cá hồi áp chảo béo ngọt, sốt kem tươi sánh mịn thơm mùi phô mai Parmesan và rau bina tươi mát cùng chút vỏ và nước cốt chanh vàng dịu nhẹ.', 'Gắp mì ra 3 đĩa sâu lòng khi còn nóng, xếp đều các miếng cá hồi lên trên, rắc thêm ngò tây tươi thái nhỏ, tiêu đen xay và chút phô mai Parmesan bào.', 'Món mì sốt kem hải sản ngon nhất khi ăn nóng ngay; nếu còn dư bảo quản hộp kín ngăn mát tối đa 24 giờ và hâm nhẹ trên chảo lửa nhỏ với chút kem tươi hoặc nước lọc.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Cá hồi","Rau bina","Sốt kem"]', '["lunch","dinner"]', '["boil","pan_fry","simmer","toss_mix"]', '["fish","milk","salmon","wheat"]', 881, 881.2, 3686, 41.5, 45.9, 20.6, 75.5, 5, 5.4, 818, 2.05, '["USDA FDC 167746","USDA FDC 168462","USDA FDC 168927","USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175167"]', '2015c780b485afef6808301caea8896920d7b82d737ecf8e84849b221c02dab2', '1eddfa104b39f9159a0a8bbab15919f5a4d2a518a7dae5ae920c994bea009c5c', 4),
('imp-810c132a4d2cd4e0', 'canh-chua-tom-dua-nam-bo', 101, 'Canh chua tôm dứa Nam Bộ', 'Nước canh chua thanh dịu từ me chín, dứa và cà chua hòa quyện tôm tươi giòn ngọt, đậu bắp, bạc hà và giá đỗ chuẩn vị miền Tây', 'Tô canh chua tôm Nam Bộ bắt mắt với sắc đỏ cà chua, vàng dứa, xanh mướt của đậu bắp, dọc mùng và vị chua thanh ngọt dịu từ nước cốt me quyện tôm tươi săn giòn.', 'Múc canh nóng ra tô lớn, rắc rau ngổ, ngò gai, hành lá và ớt thái lát lên trên; ăn kèm cơm trắng hoặc bún tươi cùng chén nước mắm ớt nguyên chất để chấm tôm.', 'Nên dùng hết trong bữa để giá đỗ và bạc hà giữ được độ giòn tươi; nếu cần bảo quản tủ mát tối đa 24 giờ, nên vớt riêng phần rau giòn và đun sôi lại phần nước canh cùng tôm.', 'vietnamese', 'mon_canh', 'nam', 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Chua ngọt","Thanh nhiệt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 213, 212.8, 891, 19.8, 5.2, 0.8, 24.6, 3.5, 16.8, 1379, 3.45, '["NIN VN Doc Mung Ref","USDA FDC 169124","USDA FDC 169230","USDA FDC 169260","USDA FDC 169655","USDA FDC 169918","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN Culinary Herb Ref","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', '50b2a618ac17be01e252b58ec7d3bba64fb8c24898a6ed92d2becf13bf3c1d45', '702862dfe6d5d4bda12efb0a0454cc459781dd55a3ee5abe2196658a466ab8a2', 4),
('imp-59015074541ba061', 'canh-kho-qua-nhoi-tom', 102, 'Canh khổ qua nhồi tôm thịt', 'Từng khoanh khổ qua xanh mềm dịu vị đắng ôm trọn nhân tôm tươi và thịt heo băm dai ngọt quyện nấm hương thơm lừng', 'Phiên bản nâng tầm của canh khổ qua nhồi truyền thống với phần nhân kết hợp thịt heo xay béo mềm và tôm tươi băm dai ngọt, điểm xuyết nấm hương thơm bùi trong nước canh thanh trong.', 'Múc các khoanh khổ qua nhồi tôm thịt vào tô lớn, chan ngập nước dùng nóng trong, rắc hành lá và chút tiêu xay; ăn kèm cơm trắng hoặc chấm cùng nước mắm ớt.', 'Mở hé vung cho canh nguội tự nhiên trước khi cất tủ mát để tránh đọng hơi nước làm canh chua; bảo quản tối đa 24 giờ và đun sôi lại kỹ trước khi dùng.', 'vietnamese', 'mon_canh', 'nam', 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Thanh nhiệt","Hải sản","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["crustaceans","fish","pork","shrimp"]', 235, 234.7, 982, 21.7, 11.3, 4.1, 13, 4.9, 4.3, 1254, 3.14, '["USDA FDC 167902","USDA FDC 168393","USDA FDC 168436","USDA FDC 169655","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'cd6a707d509ba6b034868a87d41e07d9fcb9b3445da0c291d6b82fd534736e8d', '9ca216dce2b47a369237747ce4f653b832212a6d5a81e0f4a0ba7af9265342b3', 4),
('imp-9c678f92a5cb0812', 'canh-bi-dao-tom-tuoi', 103, 'Canh bí đao nấu tôm tươi', 'Bí đao xanh non thanh mát nấu cùng tôm tươi băm ngọt dịu, nước canh trong veo nhẹ bụng cho bữa cơm ngày nóng', 'Món canh giải nhiệt nhẹ nhàng với miếng bí đao vừa chín tới giữ nguyên độ thanh ngọt, hòa quyện thịt tôm tươi băm săn mềm và hương hành tím phi dịu nhẹ.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay; dọn kèm cơm trắng và các món mặn đậm đà như thịt kho tàu hoặc cá chiên sả.', 'Dùng hết trong ngày để cảm nhận trọn vẹn độ giòn ngọt của bí đao; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại nhanh trên lửa vừa tránh làm bí nhũn.', 'vietnamese', 'mon_canh', 'nam', 'easy', 12, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Thanh mát","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 96, 95.5, 399, 10.9, 3.8, 0.6, 5.4, 3.3, 2.1, 1434, 3.59, '["USDA FDC 169214","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '2d4b6f2b25e8abe6caef7d0fd326bd951507e9b2f8a4bfd689952efa5bfbaa5b', '8008c0461ec02e4fa1449d6724e1c6a1fd2c87524a7e0ce5c92f137e3040adaa', 4),
('imp-80ce5736becc08da', 'canh-ca-chua-trung-nha-la', 104, 'Canh cà chua trứng (Canh mây)', 'Trứng gà đánh tơi tạo vân mây vàng óng bồng bềnh trong nước dùng cà chua đỏ dịu thanh mát, nấu gọn chỉ trong 15 phút', 'Món canh dân dã nhanh gọn với nước dùng chua thanh tự nhiên từ cà chua chín xào mềm, nổi bật những dải vân trứng gà mềm mịn vàng ươm và mùi thơm tươi của hành lá, ngò rí.', 'Múc canh nóng ra tô ngay khi vừa tắt bếp, rắc hành lá, ngò rí và chút tiêu xay; ăn kèm cơm trắng nóng hoặc bún đều rất ngon miệng.', 'Canh cà chua trứng ngon nhất khi dùng hết trong bữa vì trứng hâm lại dễ bị bở và tanh; nếu còn dư, đậy kín trong tủ mát tối đa 12 giờ và đun sôi lại nhanh.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 8, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Dưới 20 phút","Dễ nấu","Cơm nhà","Thanh đạm"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish"]', 145, 145, 606, 7.5, 8.9, 2.1, 9.7, 1.9, 5.9, 1389, 3.47, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '501f3757d45eeeab73b835d54059a9fa1cc5f877219322cd2c32723fa730a102', '156cddd8ff4f8343ad01a6f6b1df2f0020244c382a91427d68753f69a94a3b0d', 4),
('imp-9473faeacd64d970', 'canh-nam-ga-xe-soi', 105, 'Canh nấm đùi gà ức gà xé sợi', 'Thịt ức gà luộc mềm xé sợi ngọt thanh kết hợp nấm đùi gà giòn sần sật và cà rốt trong nước dùng gà trong veo không cần xương', 'Tô canh thanh đạm giàu đạm nhưng nhẹ bụng với nước dùng nấu trực tiếp từ thịt ức gà xào săn, nấm đùi gà xé sợi giòn ngọt tự nhiên và sắc cam tươi của cà rốt.', 'Dọn canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay; rất thích hợp ăn kèm cơm trắng hoặc dùng như món canh khai vị nhẹ nhàng.', 'Để canh nguội rồi bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 24 giờ; hâm nóng lại ở lửa vừa đến khi sôi đều trước khi dùng.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Không xương","Giàu đạm","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["chicken","fish"]', 191, 191.2, 800, 25.6, 5.2, 1, 10.7, 2.7, 4.1, 1312, 3.28, '["USDA FDC 168580","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'bd1302d5fd53c3bad546a4f837d60363fd3be8d41385db44dc256beb4aa3918f', '399c295ef3582cb1e4cedb101c701e7459e0d6eaf61c5c446bb6bcb9af103854', 4),
('imp-9ab5767266722397', 'canh-muc-ca-chua-chua-nhe', 106, 'Canh mực cà chua chua nhẹ', 'Mực ống thái khoanh giòn ngọt nấu cùng cà chua chín chua dịu và gừng thơm ấm bụng, món canh hải sản nhanh gọn cho bữa tối', 'Món canh biển thanh nhẹ dễ nấu với từng khoanh mực ống giòn sần sật, nước canh ánh đỏ cam từ cà chua xào mềm, dậy hương gừng thái sợi ấm áp và chút chanh tươi chua dịu.', 'Dọn canh nóng vào tô ngay khi mực vừa chín tới, vắt nhẹ nước cốt chanh tùy thích, rắc hành lá và tiêu xay; ăn kèm cơm trắng và chén nước mắm ớt chấm mực.', 'Canh mực ngon nhất khi dùng hết ngay trong bữa; không nên đun lại nhiều lần vì mực sẽ bị dai và tiết nước tanh.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Hải sản","Dưới 20 phút","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["fish","molluscs","squid"]', 177, 177.3, 742, 17.5, 6.1, 1.1, 13.4, 2.1, 5.8, 1431, 3.58, '["USDA FDC 168155","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '78ceb42b4a9a7fb2c5fd50eba41946dd16f7a1c0f7ac1e39a62c22d379855b70', '306798046fb51a21de059fe3037de3d6f23d9a26697e2bf70999b602de85ccb1', 4),
('imp-61eac17e8f3042a9', 'canh-su-su-bam-thit', 107, 'Canh su su nấu thịt bằm', 'Su su non giòn ngọt tự nhiên nấu cùng thịt heo băm xào tơi đậm đà, món canh mộc mạc thanh mát cho mâm cơm gia đình', 'Tô canh su su băm thịt dân dã có nước dùng ngọt trong, thịt heo băm tơi thơm mùi hành phi hòa quyện cùng từng miếng su su non chín tới giữ nguyên độ giòn ngọt mát lành.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và tiêu xay; dùng kèm cơm trắng cùng các món cá kho nghệ hoặc thịt rang sả ớt.', 'Canh su su nên ăn hết trong ngày; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại nhanh trên lửa vừa để su su không bị mềm nhũn.', 'vietnamese', 'mon_canh', 'trung', 'easy', 15, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Trung","Dễ nấu","Thanh mát","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["fish","pork"]', 204, 204.2, 854, 10.8, 15.1, 4.9, 6.8, 2.1, 2.5, 1203, 3.01, '["USDA FDC 167902","USDA FDC 169990","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'f614fbeb3f31e559cca501cf2c64e9cec0fe8401fb993d192ae6a5186608b49d', '20370ef46f6858601c425e141b855d94d0bee2d4be451dee473b5320b3fedd14', 4),
('imp-ad2b55ed85f0d109', 'canh-bap-cai-trung-cuon', 108, 'Canh bắp cải trứng cuộn', 'Bắp cải thái sợi giòn ngọt nấu cùng cà rốt và những dải trứng gà đánh tơi cuộn vàng mềm mịn trong nước dùng thanh đạm', 'Món canh gia đình thanh đạm dễ ăn với những sợi bắp cải xanh mướt giòn ngọt tự nhiên, điểm xuyết lát cà rốt cam tươi và những vân trứng gà vàng óng mềm mượt.', 'Dọn canh nóng vào tô lớn, rắc hành lá, ngò rí, vài lát ớt đỏ (nếu ăn cay) và tiêu xay; ăn kèm cơm trắng cùng thịt rim hoặc đậu phụ rán tẩm hành.', 'Món canh bắp cải trứng nên ăn hết ngay khi vừa nấu để rau còn giòn và trứng mềm thơm; tránh đun lại lâu khiến bắp cải nồng mùi.', 'vietnamese', 'mon_canh', 'bac', 'easy', 10, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Thanh đạm","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish"]', 151, 150.8, 632, 8.1, 7.7, 1.9, 13.7, 4, 7.9, 1562, 3.9, '["USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '79118e20cc1752ddbd78f1ec899ec6df774b32599c6ea4c170bcfc803b579d1d', 'cad7b6316ee97b7b61f6cccecf451356cdc533f0e8e13e54ee6aaff11fd67be0', 4),
('imp-7cfc6a2e9d8bf8a3', 'canh-rau-muong-tom-dong', 109, 'Canh rau muống nấu tôm đồng cà chua', 'Ngọn rau muống non xanh giòn nấu cùng tôm đồng giã thô ngọt nước và cà chua chín chua dịu đậm chất đồng quê Nam Bộ', 'Món canh dân dã mang hương vị đồng quê với phần nước dùng ánh đỏ cam dịu nhẹ từ cà chua xào mềm, ngọt thanh đậm vị tôm đồng giã thô cùng từng cọng rau muống xanh mướt giòn ngon.', 'Múc canh nóng ra tô lớn, dùng kèm cơm trắng nóng hổi cùng cá rô kho tộ hoặc thịt ba rọi cháy cạnh rất đưa cơm.', 'Nên dùng hết ngay trong ngày để rau muống giữ màu xanh tươi và độ giòn; tránh hâm đi hâm lại nhiều lần khiến rau ngả thẫm.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Đồng quê","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 115, 115.2, 482, 11.4, 4.9, 0.8, 8.4, 3, 3.8, 1220, 3.05, '["USDA FDC 169378","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'c8f70f5490649a04508361a38834a7190ff0db37b7909d4e6de956879fa6780e', '02d58ceea1258175631a28ec11c3b7376f6a2bea4166c60cae8792e6d9f0a889', 4),
('imp-24cdd0b61f9ed162', 'canh-cua-dong-dau-phu', 110, 'Canh riêu cua đồng đậu phụ cà chua', 'Riêu cua đồng kết mảng béo ngọt nấu cùng đậu phụ rán vàng giòn, cà chua chua thanh từ me chín và rau răm thơm lừng chuẩn vị Bắc', 'Món canh riêu cua đậu phụ đậm hương vị đồng bằng Bắc Bộ với phần nước canh chua thanh nhẹ của me và cà chua, từng miếng đậu phụ rán vàng thấm vị quyện mảng riêu cua ngọt béo và rau răm dậy mùi.', 'Múc canh nóng ra bát tô, xếp nhẹ mảng riêu cua và rắc hành phi giòn lên trên; ăn kèm cơm trắng, cà muối hoặc chan bún tươi kèm rau sống chẻ nhỏ đều rất ngon.', 'Để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 24 giờ; khi hâm lại nên đun sôi lăn tăn nhẹ nhàng tránh làm nát đậu phụ và vỡ mảng riêu cua.', 'vietnamese', 'mon_canh', 'bac', 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Cua đồng","Truyền thống","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["crab","crustaceans","fish","soybean"]', 183, 183.2, 766, 17.5, 9.2, 1.4, 9.5, 2.1, 5.3, 1521, 3.8, '["USDA FDC 169918","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', 'ba3ec0b694c9b6f3519c4010478412f99efbe8c27eb39fff22e9d98f1fe957b3', 'd3c47f99736bc95673e0e94ffac5322b30b4b30ae6adaa4b5530e1e8cf6d514a', 4),
('imp-15155ec6cc7b7713', 'ba-chi-nuong-sa-mat-ong', 111, 'Ba chỉ nướng sả mật ong', 'Thịt ba chỉ thái dải ướp sả băm, tỏi gừng và mật ong nướng vàng xém cạnh thơm lừng, ăn kèm nước mắm chua ngọt đậm vị', 'Những dải thịt ba chỉ nạc mỡ hài hòa thấm đẫm hương thơm sả băm, hành tỏi gừng và vị ngọt dịu của mật ong, nướng chín vàng ruộm xém cạnh bên ngoài mà vẫn mềm mọng bên trong.', 'Thái lát vừa ăn, vắt nhẹ chanh tươi nếu thích và dọn nóng cùng chén nước mắm chua ngọt tỏi ớt, bún tươi, rau sống hoặc bánh tráng cuốn.', 'Thịt đã nướng bọc kín bảo quản ngăn mát tối đa 2 ngày; khi ăn nướng lại bằng nồi chiên không dầu ở 180°C khoảng 4–5 phút cho nóng giòn.', 'vietnamese', 'mon_kho', 'toan_quoc', 'medium', 25, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Ba chỉ nướng","Mật ong","Sả ớt","Cuối tuần","Cuốn bánh tráng"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","pork"]', 660, 660.3, 2762, 11.4, 59.6, 21, 20.5, 0.7, 13.8, 1301, 3.25, '["USDA FDC 167820","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647"]', '5d4fa93e9ad4ad601567f3e450b6db19d04d5e3df8ba87dfa6beba1089086a56', 'ea679e4e8013caa8b81e35017469ddbf35ea3785225c41562b8223aeda4e24bc', 4),
('imp-363ca9ee2c5f7738', 'bo-kho-banh-mi-dam-vi', 112, 'Bò kho bánh mì đậm vị', 'Thịt nạm bò hầm mềm tan trong nước dùng dừa tươi thơm hương sả, hồi quế và màu điều đỏ cam, chấm bánh mì nóng giòn chuẩn vị Sài Gòn', 'Thịt nạm bò có gân mỡ đan xen được hầm nhừ cùng nước dừa tươi, cà rốt, sả, hoa hồi, quế thanh và màu điều đỏ cam sóng sánh, tỏa mùi thơm quyến rũ khó cưỡng.', 'Múc bò kho nóng vào tô sâu lòng, rắc húng quế, ngò gai và ớt thái lát lên trên, ăn kèm ổ bánh mì nướng giòn rụm và muối tiêu chanh.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng trên lửa nhỏ và thêm ít nước lọc nếu nước sốt quá đặc.', 'vietnamese', 'mon_kho', 'nam', 'medium', 25, 75, 5, '/frigo/illustrations/delicious-meal.png', '["Bò kho","Bánh mì","Nam Bộ","Món hầm","Ăn sáng"]', '["breakfast","lunch","dinner"]', '["braise","stir_fry","simmer"]', '["beef","fish","wheat"]', 687, 686.5, 2872, 36.4, 24.7, 9.2, 79.2, 7.6, 18.4, 1751, 4.38, '["Annatto Infused Oil Ref","Five Spice USDA Ref","MEXT Sake 16021","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169717","USDA FDC 170000","USDA FDC 170174","USDA FDC 170198","USDA FDC 170393","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171316","USDA FDC 171320","USDA FDC 172185","USDA FDC 172232","USDA FDC 172686","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', 'aaa0abd69cb130b33ff2f5592d144f3022e705db7a8a2ea94afdb2b8a4b99c2d', '3819e0fff916f637c30211acff2d794d832e715f7d6b826201e07c9bf36fd383', 4),
('imp-3ec27a2b8f5e4345', 'ga-kho-gung-ot-hiem', 113, 'Gà kho gừng ớt hiểm', 'Thịt đùi gà kho săn cùng gừng tươi thái sợi và ớt hiểm cay nồng, nước kho sánh màu cánh gián đậm đà cực kỳ đưa cơm', 'Những miếng đùi gà giữ nguyên da săn chắc thấm đẫm vị mặn ngọt hài hòa, quyện cùng hương thơm cay ấm của gừng tươi thái sợi và vị cay nồng đặc trưng từ ớt hiểm.', 'Múc gà kho ra đĩa sâu lòng, rắc hành lá cắt khúc và tiêu xay lên trên, ăn nóng với cơm trắng và dưa leo thái lát.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại trên lửa nhỏ với 1–2 muỗng canh nước ấm.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Gừng ớt","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["chicken","fish"]', 347, 346.9, 1452, 29.2, 20.4, 4.9, 10.7, 0.9, 6.6, 1474, 3.68, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647"]', '49690959195da2adcfd4f554f4c773e3e39c0e2c17eaf6ac271f46ee1b821861', '6d8d8ffc933c54550e87c00ba0ef16ecbeff49f6f3333a42dfdd06ca37ffd894', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-323aae415415eb28', 'tom-kho-tieu-xanh', 114, 'Tôm kho tiêu xanh', 'Tôm tươi thịt chắc kho sánh keo với tiêu xanh tươi đập dập cay tê thơm nồng, món mặn nhanh gọn cực bắt cơm', 'Tôm tươi rang săn rồi kho mở nắp với nước mắm đường và những chùm tiêu xanh tươi đập dập, mang lại vị cay tê dịu nhẹ và hương thơm tinh dầu tiêu đặc trưng miền Nam.', 'Xếp tôm cùng chùm tiêu xanh ra đĩa, rưới phần nước kho sánh bóng và rắc hành lá cắt khúc; ăn nóng với cơm trắng và rau luộc.', 'Dùng hết trong ngày để giữ độ ngọt giòn của tôm và hương thơm tươi của tiêu xanh; nếu bảo quản ngăn mát tối đa 24 giờ, hâm nhanh trên chảo lửa nhỏ.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Hải sản","Tiêu xanh","Nhanh gọn","Nam Bộ"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","shrimp"]', 203, 203.3, 851, 22.6, 7.6, 1.2, 12.5, 1.4, 7.5, 1290, 3.23, '["Green Peppercorn Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '8df46b54fc7e31187a4822b4ac23c2d80fa58ba91fac3f61f84b9d321920e19d', '819180201a427845ba7563469c1fad3e09381efa3087f98664c55e2e4806e0d8', 4),
('imp-3f1ad35e1f1ec87f', 'muc-rim-dua-mien-trung', 115, 'Mực rim dứa miền Trung', 'Mực khô nướng thơm đập mềm xé sợi rim cùng nước cốt dứa chín, tương ớt, dầu hào và mè rang đậm vị cay ngọt miền Trung', 'Đặc sản miền Trung với từng thớ mực khô nướng thơm đập mềm thấm đẫm sốt dứa chín chua ngọt quyện tương ớt cay nồng, dầu hào đậm đà và mè rang bùi béo.', 'Xếp mực rim dứa ra đĩa, rắc thêm chút tiêu xay, ăn nóng với cơm trắng kèm dưa leo thái lát hoặc nhâm nhi cùng bánh tráng nướng.', 'Để nguội hoàn toàn rồi cho vào hũ thủy tinh đậy kín, bảo quản ngăn mát tối đa 7 ngày; có thể ăn nguội trực tiếp hoặc đảo nhanh trên chảo ấm.', 'vietnamese', 'mon_kho', 'trung', 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món rim","Miền Trung","Hải sản","Mực khô","Đưa cơm"]', '["lunch","dinner"]', '["braise","grill_roast"]', '["fish","molluscs","sesame","soybean","squid","wheat"]', 372, 372.1, 1557, 50.5, 10.3, 1.7, 18.6, 1.7, 13, 1552, 3.88, '["MEXT Surume Ref","USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC Sriracha Ref"]', '122078d83d8a839c7cd8216001bdbec1a01821c8b9d387b345ad32e5767ad63c', '0524b625beac80e3f6c253accc98c11f89e79231eb080adbe39996f5c8f85acd', 4),
('imp-64e505d497388f4a', 'ca-hoi-ap-chao-toi-chanh', 116, 'Cá hồi áp chảo sốt tỏi chanh', 'Cá hồi phi lê áp chảo da giòn thịt hồng mọng nước, rưới sốt bơ tỏi chanh nước mắm chua thanh đậm đà', 'Cá hồi áp chảo sốt tỏi chanh là sự kết hợp tinh tế giữa kỹ thuật áp chảo da giòn kiểu Âu và hương vị sốt bơ tỏi chanh pha nước mắm hài hòa theo khẩu vị Việt. Miếng cá giữ được độ béo mọng đặc trưng bên trong, hòa quyện lớp sốt chua thanh thơm lừng giúp ăn không bị ngấy.', 'Dọn nóng từng miếng cá hồi ra đĩa, rưới đều sốt bơ tỏi chanh lên mặt, rắc hành lá và tiêu xay, ăn kèm cơm trắng nóng hoặc salad cà chua tươi.', 'Cá hồi ngon nhất khi ăn nóng ngay để thịt mềm mọng và da giòn; nếu bảo quản tủ mát tối đa 24 giờ, nên hâm nhẹ bằng chảo nắp kín ở lửa nhỏ 2–3 phút tránh làm khô thịt cá.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Áp chảo","Cá hồi","Nhanh gọn","Hiện đại"]', '["lunch","dinner"]', '["pan_fry"]', '["fish","milk","salmon"]', 541, 541.3, 2264, 42.6, 36.3, 9.5, 10.3, 1.6, 4.9, 1010, 2.53, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173430","USDA FDC 173468","USDA FDC 175167"]', '8a0cbe2830df3ec718a7e935fbdae9ebcb037d5c6f02c16e8eef1342df55c7ed', '4efacea3a138c24e530d8c7bc5100040028c0f5e63bbde4d9b519caf0a2b97c3', 4),
('imp-6e4c264764981b8b', 'ga-xao-sa-ot-non', 117, 'Gà xào sả ớt Nam Bộ', 'Thịt đùi gà săn mềm thấm vị mặn ngọt đậm đà cùng sả băm vàng ruộm, ớt cay nồng và hành tây giòn thơm', 'Gà xào sả ớt kiểu Nam Bộ quyến rũ với màu nâu cánh gián óng ả từ đường nâu thắng nhẹ, từng miếng thịt đùi gà mềm ngọt thấm sâu hương sả thơm nồng, vị cay kích thích của ớt hiểm và chút giòn ngọt của hành tây.', 'Múc gà xào sả ớt ra đĩa sâu lòng cùng phần nước sốt sền sệt, dùng nóng với cơm trắng và dưa leo xắt lát.', 'Có thể bảo quản trong hộp kín ngăn mát tối đa 2 ngày; hâm nóng lại trên chảo với 1–2 muỗng canh nước lọc ở lửa vừa đến khi nóng đều.', 'vietnamese', 'mon_xao', 'nam', 'easy', 20, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Nam Bộ","Cay nồng","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish"]', 396, 396, 1657, 30.6, 24.2, 5.6, 13.3, 0.7, 4.7, 1426, 3.57, '["USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 170000","USDA FDC 170106","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '95bebba763d2dc8f7ab8df85ca43e61a5a29557f4c4a250121f49edf334286d4', '7f9abe593a19b8d2e73165b38ae20c99c42ca8708ff90adc258ee364858c0a30', 4),
('imp-53760c13ec1e452b', 'tom-xao-gia-do', 118, 'Tôm xào giá đỗ thanh ngọt', 'Giá đỗ trắng mập giòn mọng xào nhanh trên lửa lớn cùng tôm tươi săn ngọt và hương hành lá thơm dịu', 'Tôm xào giá đỗ là món ăn thanh nhẹ giải ngấy cực nhanh gọn cho bữa cơm hằng ngày. Từng con tôm đỏ cam săn chắc quyện cùng cọng giá đỗ chín tới giòn tan, mọng nước ngọt tự nhiên mà không hề bị nát hay chảy nước.', 'Gắp tôm xào giá đỗ ra đĩa khi vừa tắt bếp, rắc thêm tiêu đen xay; dùng nóng ngay cùng cơm trắng và chén nước mắm ớt.', 'Món giá đỗ xào nên ăn hết ngay trong bữa để giữ độ giòn tươi và tránh giá bị chảy nước thâm sẫm.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Thanh đạm","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","fish","shrimp"]', 154, 154.4, 647, 18.1, 6.1, 0.9, 8.9, 2.1, 4.5, 1200, 3, '["USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '8907853cfd0dbee39d952ef18167bc660d1cd3c82ce605930268727753b3ccaf', '39fa681738390b5cd63a4fa030cdf3dafd52efd127f2f291325594f4938dacbf', 4),
('imp-a47ef9289f5d0136', 'ca-rot-xao-trung', 119, 'Cà rốt xào trứng gà', 'Cà rốt thái sợi mềm ngọt tự nhiên quyện cùng trứng gà đánh bông tơi vàng ươm và hương thơm dịu của ngò rí', 'Cà rốt xào trứng gà là món ăn bình dị, giàu dinh dưỡng với sợi cà rốt mềm ngọt tự nhiên ôm quyện lấy từng mảng trứng gà vàng óng béo nhẹ, thơm mùi nước mắm, tiêu xay và rau ngò rí.', 'Dọn cà rốt xào trứng ra đĩa khi còn nóng hổi, rắc thêm ngò rí và tiêu xay; ăn kèm cơm trắng hoặc kẹp bánh mì đều rất hợp.', 'Nên dùng hết ngay trong bữa để trứng giữ độ bông mềm và thơm ngon; không nên để qua đêm hoặc hâm lại nhiều lần.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Trứng","Dưới 20 phút","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","fish"]', 147, 146.6, 613, 6.6, 9.9, 2.2, 8.2, 2.2, 3.7, 624, 1.56, '["USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC Monosodium Glutamate","VN/Asian Seasoning Powder Avg"]', '5986303c355f339928d247962ef21ab22cdd836df68149766994bb2aea0546ac', '7103aa4dc5dd34c5841a1ccd7ef09ef5c08074ae771ba3d5464562ab0e0d982c', 4),
('imp-abdcd797955a6d6a', 'dau-phu-xao-ca-chua', 120, 'Đậu phụ xào cà chua', 'Đậu phụ chiên vàng giòn cạnh xào cùng sốt cà chua chín nhừ đậm đà vị mặn ngọt, món cơm nhà thanh đạm cực bắt cơm', 'Đậu phụ xào cà chua hấp dẫn với từng miếng đậu phụ ngoài vàng nhẹ, bên trong béo mềm thấm đẫm phần sốt cà chua đỏ au sóng sánh vị chua ngọt hài hòa, thơm mùi hành lá và ngò rí.', 'Trút đậu phụ xào cà chua ra đĩa sâu lòng, rưới đều nước sốt cà chua lên mặt cùng hành lá, ngò rí và tiêu xay; ăn nóng với cơm trắng rất hao cơm.', 'Bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa nhỏ cùng 1–2 muỗng canh nước lọc khoảng 3 phút cho sốt mềm sánh trở lại.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Đậu phụ","Cà chua","Tiết kiệm","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["fish","soybean"]', 245, 244.6, 1023, 14.1, 17.7, 2.6, 11.8, 3.2, 6.5, 1098, 2.75, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '6cbb8fbab240e3147be14bf4644b3f6d83e9d33c1183c28905b42fc333508385', '502958b5caf5a97d5297ed72cfecc18d660268e90247ba983c4bc0dc2fe042d1', 4),
('imp-97f26ff4abe44f9b', 'nem-ran-nhan-cua-thit', 121, 'Nem rán nhân cua thịt', 'Nem cua bể gói vuông giòn rụm hai lần lửa, nhân thịt nạc vai quyện thịt cua ngọt thanh và rau củ', 'Nem rán nhân cua thịt (nem cua bể) là đặc sản trứ danh miền duyên hải Bắc Bộ. Từng chiếc nem gói vuông vức, lớp vỏ bánh đa nem giòn tan ôm trọn phần nhân đầy đặn gồm thịt cua biển tươi, thịt nạc vai xay, nấm hương, mộc nhĩ, miến dong và các loại củ bào sợi ngọt mát.', 'Cắt nem làm đôi hoặc làm tư ngay khi còn nóng để lộ phần nhân cua thịt hấp dẫn, dọn kèm rau sống, bún tươi và chén nước mắm chanh tỏi ớt chua ngọt.', 'Nem rán sơ lần một để nguội có thể xếp hộp lót giấy nến bảo quản ngăn đá tới 3 tuần; trước khi ăn đem rán lại ở lửa vừa 4–5 phút đến khi vỏ vàng giòn rụm.', 'vietnamese', 'mon_chien', 'bac', 'hard', 40, 25, 6, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Nem cua bể","Bắc Bộ","Hải sản","Tiệc tùng"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["crab","crustaceans","egg","fish","pork"]', 549, 548.6, 2295, 25.1, 24.6, 6.8, 56.9, 5.3, 5.5, 1147, 2.87, '["USDA FDC 167902","USDA FDC 168155","USDA FDC 168436","USDA FDC 168437","USDA FDC 168482","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170072","USDA FDC 170106","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173647","USDA FDC 174208","USDA FDC Rice Paper Ref","VN/Asian Seasoning Powder Avg"]', '7c9f1e5ba65664929e959922d2542b536a7c8c1d34abbe4c28c82bef3a7a16d0', 'e0bde82b6807cc18f4c4aacc0226319e1a0da672521281f7470b947010c6352e', 4),
('imp-03cb4c492e643034', 'tom-chien-trung-mong', 122, 'Tôm chiên trứng mỏng', 'Tôm tươi xào săn xếp trên lớp trứng gà đánh bột bắp chiên mỏng vàng ươm, mềm mịn thơm hành', 'Tôm chiên trứng mỏng là món ăn đơn giản nhưng rất được lòng trẻ nhỏ và gia đình bận rộn. Tôm tươi bóc vỏ được xào nhanh cho chín đỏ rồi trải đều trên lớp trứng gà đánh cùng chút bột bắp hòa nước, chiên lửa nhỏ đậy vung để mặt trứng mềm mịn, không bị khô xác.', 'Trượt nguyên miếng trứng chiên tôm ra đĩa phẳng, cắt miếng vừa ăn và dùng nóng ngay với cơm trắng, có thể chấm thêm tương ớt hoặc nước mắm chua ngọt.', 'Món ăn ngon nhất khi vừa chiên xong còn nóng mềm; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hâm lại trên chảo chống dính lửa nhỏ có nắp đậy trong 2 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 12, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Tôm tươi","Trứng chiên","Trẻ em thích","Dưới 30 phút"]', '["lunch","dinner"]', '["pan_fry"]', '["crustaceans","egg","fish","shrimp"]', 227, 227.3, 951, 20.9, 13.8, 3, 4.8, 0.4, 0.7, 735, 1.84, '["USDA FDC 169698","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '15d45f3ab29439fe685076a6a795e1203f373111a2f2af0db38fedf5f2eae265', '5ea0e12f93d1e042278eee320903344dd19299704a62dbc01f79c1542df74e15', 4),
('imp-c4a65718d5cd4b3c', 'cha-gio-chay-nam-dau', 123, 'Chả giò chay nấm đậu', 'Vỏ bánh tráng giòn rụm chiên hai lửa, nhân đậu phụ vắt ráo quyện nấm đùi gà, đậu xanh bùi và củ sợi', 'Chả giò chay nấm đậu có lớp vỏ giòn tan không thua kém chả giò mặn nhờ bí quyết vắt ráo đậu phụ, hấp khô đậu xanh và chiên hai lần lửa. Nhân nấm đùi gà dai ngọt hòa quyện với đậu xanh bùi béo, khoai lang và củ đậu thanh mát, chấm nước mắm chay chua ngọt cực kỳ bắt vị.', 'Bày chả giò chay ra đĩa cùng rau xà lách, rau thơm các loại và bún tươi, chấm đẫm chén nước mắm chay chanh ớt có cà rốt băm giòn.', 'Chả giò chiên sơ lần một để nguội hoàn toàn có thể cấp đông trong hộp kín tới 3 tuần; khi ăn chỉ cần chiên lại ở lửa vừa 3–4 phút hoặc quay nồi chiên không dầu 180°C trong 6 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'medium', 35, 20, 5, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Món chay","Chả giò","Giòn rụm","Thanh đạm"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["soybean","wheat"]', 462, 462.1, 1934, 15.2, 15.4, 2.3, 69.5, 9, 10.2, 1037, 2.59, '["USDA FDC 168155","USDA FDC 168437","USDA FDC 168482","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170005","USDA FDC 170072","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174256","USDA FDC Rice Paper Ref","Vegetarian Fish Sauce Ref","Vegetarian Seasoning Powder Ref"]', '10dd0e29862c1e71e8a4846ce564a6f6a12d862f64f836f5da5fe5ff47898e7c', 'a1e6d87801799347ed60e0ef0b5bc404906d65760c60c307a907c9a5a2650a12', 4),
('imp-f3c2431be267b74d', 'ca-hap-dua-gung', 124, 'Cá điêu hồng hấp dứa gừng thanh mát', 'Cá điêu hồng tươi nguyên con ướp sốt mắm tương đậm đà hấp cùng dứa chín chua ngọt và gừng sợi thơm ấm', 'Cá điêu hồng tươi hấp cách thủy cùng những lát dứa chín vàng óng và gừng sợi cay nhẹ tạo nên nước hấp chua ngọt thanh tao, giúp thịt cá trắng mềm thơm ngọt mà hoàn toàn không có vị tanh.', 'Dọn nguyên đĩa cá hấp dứa gừng nóng hổi lên bàn, có thể ăn kèm cơm trắng hoặc cuốn bánh tráng cùng bún tươi, rau sống chấm nước mắm gừng.', 'Món cá hấp ngon nhất khi ăn nóng ngay trong bữa. Nếu còn dư, gỡ bỏ xương cá bảo quản ngăn mát tối đa 24 giờ và hấp lại 5 phút trước khi dùng.', 'vietnamese', 'mon_hap_luoc', 'nam', 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Cá tươi","Thanh mát","Món Nam","Đãi khách"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","sesame","soybean","wheat"]', 265, 265, 1108, 36.5, 5.7, 1.4, 16.2, 2, 9.5, 1436, 3.59, '["USDA FDC 169124","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '5cecf42e18bc24e1cd503ced7e9a0df903da078935fb429f91ce1c6e22deedd3', '7d589d8d7c3f371eb548c1aba2a3b20881758fe04fc53c555334dd512dfe839f', 4),
('imp-6118e8aa010584af', 'trung-hap-tom-chung', 125, 'Trứng hấp tôm chưng mềm mượt', 'Trứng gà lọc mịn hấp cách thủy cùng tôm tươi băm ngọt thanh, mặt trứng láng mịn như gương nhẹ bụng dễ tiêu', 'Món trứng hấp tôm chưng mềm mịn như đậu hũ non, mặt trứng bóng mượt không một vết rỗ hòa quyện vị ngọt tự nhiên của tôm tươi bóc vỏ và hương thơm dịu từ hành lá, dầu mè.', 'Dùng muỗng múc từng phần trứng hấp tôm nóng hổi ăn kèm cơm trắng, rất phù hợp cho bữa tối thanh nhẹ hoặc thực đơn trẻ nhỏ.', 'Món ăn ngon nhất khi dùng nóng ngay sau khi hấp; không nên để qua ngày vì trứng và tôm hấp lại dễ bị tách nước.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trứng","Thanh đạm","Dễ nấu","Nhẹ bụng"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","egg","fish","sesame","shrimp"]', 146, 146, 611, 17.3, 7.4, 2.1, 2.2, 0.4, 0.7, 675, 1.69, '["USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '8b0dfbd74796209e49da7453aeae34c49d919569c130be2adadb3fe4db32522c', '651c1b527562ea400c13980e0f0fda9be64d7b2a67c73993e86b0c321242c67d', 4),
('imp-4ced29ad30507f2c', 'goi-cuon-tom-thit-rau-song', 126, 'Gỏi cuốn tôm thịt rau sống chấm mắm tỏi ớt', 'Gỏi cuốn truyền thống bánh tráng mỏng dẻo bọc tôm sú luộc, ba chỉ thái mỏng, bún tươi, giá đỗ và rau thơm chấm nước mắm chanh tỏi ớt thanh nhẹ', 'Gỏi cuốn tôm thịt rau sống mang hương vị thanh nhẹ chuẩn Nam Bộ với bánh tráng mềm dẻo ôm trọn tôm luộc đỏ tươi, thịt ba chỉ béo mềm, bún sợi nhỏ, dưa leo giòn mát, hẹ lá và ngò gai thơm dịu, chấm cùng chén nước mắm chanh tỏi ớt đậm đà.', 'Xếp gỏi cuốn ra đĩa, dọn ăn ngay kèm chén nước mắm chanh tỏi ớt pha vừa vị chua cay mặn ngọt.', 'Thưởng thức ngay sau khi cuốn để bánh tráng không bị khô cứng; nếu chưa ăn ngay, bọc từng cuốn bằng màng bọc thực phẩm giữ trong ngăn mát tối đa 4 giờ.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi cuốn","Rau sống","Nam Bộ","Nước mắm tỏi ớt","Khai vị"]', '["lunch","dinner"]', '["boil","assemble"]', '["crustaceans","fish","pork","shrimp"]', 584, 583.8, 2443, 22.8, 33.5, 12.1, 48.6, 2.4, 6.1, 1107, 2.77, '["NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169994","USDA FDC 170106","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref","VN Culinary Herb Ref"]', '551a8df5d104294b244ed2fa43129559314e5da7e63f85c73b54cb5e5bb2ae2e', '027b0156a3993310a786833d84fa008f798d5fd834e34ce9e19d2992acf58b71', 4),
('imp-3a06ac78b572f3ae', 'nom-dua-leo-tom-chua-cay', 127, 'Nộm dưa leo tôm chua cay', 'Dưa leo bỏ ruột thái lát ngâm đá giòn sần sật quyện tôm rim săn ngọt, cà rốt, rau thơm và nước trộn chanh ớt hiểm cay nồng sảng khoái', 'Nộm dưa leo tôm chua cay là món khai vị bùng vị với dưa leo và cà rốt ngâm đá giữ trọn độ giòn mát, kết hợp tôm tươi rim muối ngọt thịt và nước mắm chanh tương ớt giã tỏi ớt hiểm cay nồng, rắc lạc rang thơm bùi.', 'Gắp nộm ra đĩa, rắc đậu phộng rang giã dập lên mặt và dọn ăn ngay kèm bánh phồng tôm giòn tan.', 'Dùng ngon nhất trong vòng 30 phút sau khi trộn; nếu chưa ăn ngay, để riêng dưa leo cà rốt đã vắt ráo, tôm rim và nước trộn trong tủ lạnh.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 20, 10, 4, '/frigo/illustrations/delicious-meal.png', '["Nộm dưa leo","Tôm tươi","Chua cay","Khai vị","Mát lành"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 350, 349.9, 1465, 24.8, 7.4, 1.1, 50.2, 4.5, 19.3, 1612, 4.03, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 175179","USDA FDC Sriracha Ref","VN Banh Da Ref"]', 'ff21aa25c5a6765c36bc5d9eeaf0a246983d7f0f385ec6d6a6fd299b71c81947', '378c335561ebcd27ae665ce3c61f642cebe2748d9d327b8c9ba9912c0873b50a', 4),
('imp-21f32dccd464c605', 'pho-ga-pho-co', 128, 'Phở gà phố cổ Hà Nội', 'Nước dùng phở gà trong veo ngọt thanh từ gà ta luộc và hạt mùi rang thơm, quyện sợi bánh phở mềm dai, thịt gà xé thơm lá chanh thái chỉ', 'Phở gà phố cổ Hà Nội tinh tế với nước dùng trong vắt thơm hương hạt mùi rang, hành gừng nướng, thịt gà ta chín tới da vàng giòn ngọt mềm, điểm lá chanh thái chỉ thanh mát.', 'Xếp bánh phở và thịt gà xé vào tô, thêm đầu hành chẻ, hành tây thái mỏng, hành lá, ngò rí, lá chanh thái chỉ rồi chan nước dùng sôi nóng; ăn kèm giá đỗ, chanh tươi và ớt tươi.', 'Nước dùng và thịt gà lọc xương bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi nước dùng, trụng bánh phở mới và xếp thịt gà vào chan ngập nước sôi cho nóng.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 25, 80, 4, '/frigo/illustrations/delicious-meal.png', '["Phở gà","Phố cổ Hà Nội","Nước dùng trong","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["boil","simmer","assemble"]', '["chicken","fish"]', 728, 728, 3047, 42, 28.8, 8.2, 72.2, 3.8, 7.1, 1891, 4.73, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 169231","USDA FDC 169745","USDA FDC 169963","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170922","USDA FDC 171077","USDA FDC 171316","USDA FDC 171320","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', 'b675c4937599393368ccbf57ce5ff719712f303ffd585d8b184ea1a8ea6ed272', '9ac538c925a47779e8a23d2ff10528ada9b4b41e742ae0c25ddb966b59cd44eb', 4),
('imp-ba737c5583985a50', 'bun-bo-hue-sa-ot', 129, 'Bún bò Huế sả ớt', 'Nước dùng xương bò nạm bò ninh sả đậm đà hương mắm ruốc Huế và sa tế sả ớt đỏ gạch cay nồng, ăn kèm viên giò sống dai ngọt và rau sống', 'Bún bò Huế sả ớt phiên bản cay nồng thơm sả nổi bật với nạm bò ướp sả ớt xào săn trước khi hầm mềm, viên giò sống dai giòn, nước dùng đậm đà mắm ruốc Huế cùng chén sa tế sả ớt tự làm đỏ rực bắt mắt.', 'Xếp bún sợi to, thịt nạm bò thái lát và viên giò sống vào tô, chan ngập nước dùng nóng rực sắc điều, rắc hành lá, hành tây, rau răm rồi dọn kèm giá đỗ, chanh tươi và chén sa tế sả ớt.', 'Nước dùng, thịt nạm và sa tế sả ớt có thể bảo quản ngăn mát 2 ngày; khi ăn hâm sôi nước dùng, thả nạm bò làm nóng lại rồi chan lên bún vừa trụng.', 'vietnamese', 'mon_bun_pho', 'trung', 'hard', 35, 120, 4, '/frigo/illustrations/delicious-meal.png', '["Bún bò Huế","Sả ớt","Cay nồng","Ẩm thực miền Trung"]', '["breakfast","lunch","dinner"]', '["simmer","stir_fry","boil","assemble"]', '["beef","crustaceans","fish","pork","shrimp"]', 839, 839.3, 3512, 41.1, 41.9, 14.1, 76.3, 5.3, 10.7, 1612, 4.03, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","USDA Beef Rib / Bone Ref","USDA FDC 167902","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169963","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170198","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC Sucrose Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', 'd7f940303fbf34edb34928df8c5775f65c932997463d17788cb1f618438d4848', '33a90caed19048909422c315158a7661a138486cbdc3fd3a63473c0a94d6b938', 4),
('imp-37a39eaa1edcd2e4', 'hu-tieu-tom-thit-nam-vang', 130, 'Hủ tiếu tôm thịt Nam Vang', 'Nước lèo trong vắt ngọt thanh từ xương ống heo, tôm khô và khô mực nướng, quyện sợi hủ tiếu dai cùng tôm tươi, thịt ba chỉ, thịt băm và trứng cút', 'Tô hủ tiếu Nam Vang trứ danh đất Sài Gòn gây thương nhớ bởi nồi nước lèo trong veo ngọt dịu từ xương heo hầm củ cải trắng, tôm khô và khô mực nướng, điểm xuyết tỏi phi vàng thơm cùng thịt ba chỉ, tôm tươi, thịt băm và trứng cút.', 'Trụng hủ tiếu trộn chút dầu tỏi phi vào tô, xếp thịt ba chỉ thái lát, thịt băm xào, tôm luộc và trứng cút bổ đôi; chan nước lèo sôi nóng, rắc hẹ lá, cần tây, hành lá, tỏi phi và dọn kèm giá đỗ, rau tần ô, chanh tươi.', 'Nước lèo và các phần nhân chín bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi nước lèo, trụng lại hủ tiếu mới và làm nóng thịt tôm bằng cách nhúng nhanh qua nước dùng sôi.', 'vietnamese', 'mon_bun_pho', 'nam', 'medium', 30, 90, 4, '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu Nam Vang","Tôm thịt","Ẩm thực Nam Bộ","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["simmer","boil","stir_fry","assemble"]', '["celery","crustaceans","egg","fish","molluscs","pork","shrimp","squid"]', 833, 833.2, 3486, 37.4, 39.6, 12.3, 80.3, 4.5, 9.6, 1841, 4.6, '["MEXT Surume Ref","Pork Bone Stock Extraction Ref","USDA / Asian Dried Shrimp Ref","USDA FDC 167820","USDA FDC 167902","USDA FDC 168155","USDA FDC 168452","USDA FDC 169230","USDA FDC 169249","USDA FDC 169745","USDA FDC 169963","USDA FDC 169988","USDA FDC 169994","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172191","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', 'fe6fb9628d4dafd0f6f583d53482ed754e16daaec82aaa8e59df84e7f94ad17a', '11efacb29d63ad8cff74fb5f8576b327051a3c5470afc52974f5dd8f8ef8d397', 4),
('imp-0efa407066cdc8dd', 'bun-ca-tom-ca-chua', 131, 'Bún cá nấu dứa cà chua', 'Cá lóc ướp nghệ chiên săn nấu cùng dứa chín và cà chua tạo nước dùng chua ngọt thanh dịu, ăn kèm bún tươi và rau thơm', 'Tô bún cá nấu dứa cà chua ấm bụng với từng khúc cá lóc ướp nghệ chiên áp chảo vàng nhẹ không tanh, thấm nước dùng chua thanh tự nhiên từ cà chua chín và dứa thơm.', 'Xếp bún tươi đã trụng vào tô, đặt khúc cá lóc lên trên, chan nước dùng cà chua dứa nóng hổi rồi rắc hành lá, thì là, ngò rí và ớt tươi thái lát.', 'Nước dùng và cá chín nên tách riêng bảo quản ngăn mát tối đa 24 giờ; khi ăn đun sôi nước dùng, thả cá vào hâm nóng nhẹ 2 phút rồi chan lên bún mới trụng.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Bún cá","Cà chua","Chua thanh","Món nước"]', '["breakfast","lunch","dinner"]', '["pan_fry","simmer","boil","assemble"]', '["fish"]', 416, 416.4, 1742, 26.2, 10.5, 1.9, 54.7, 4, 9, 1300, 3.25, '["NIN VN Fresh Bun Ref","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '907811221a2637bcccd8ace0310ee14e92d5f0a810977402782eba053bbf0568', 'fb1eea93fe31c3d6c262bcd9304d3d95f11362430fd5d5411ec24839cc9cc4d5', 4),
('imp-b6aeb931b882e8a3', 'com-chay-dau-kho-nam', 132, 'Cơm chay đậu phụ kho nấm đùi gà', 'Cơm trắng dẻo thơm ăn kèm đậu phụ rán vàng kho sánh cùng nấm đùi gà giòn ngọt đậm đà nước tương', 'Mâm cơm chay giản dị mà tròn vị với phần cơm trắng nấu chín dẻo thơm ăn kèm nồi đậu phụ chiên vàng kho cùng nấm đùi gà thái lát dày, ngấm đượm nước tương sánh đậm, thoảng vị cay ấm của tiêu xay và hành lá.', 'Xới cơm trắng nóng ra chén, gắp đậu phụ kho nấm ra đĩa sâu lòng, rưới thêm nước kho sánh lên mặt và dùng ngay khi còn nóng hổi.', 'Phần cơm và phần đậu kho nấm nên bảo quản riêng trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; hâm nóng lại nồi kho trên lửa nhỏ với 1–2 muỗng nước lọc trước khi ăn.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món chay","Cơm nhà","Món kho","Đậu phụ","Nấm đùi gà"]', '["lunch","dinner"]', '["boil","pan_fry","braise"]', '["soybean","wheat"]', 608, 608.4, 2545, 23, 14.3, 2.2, 99, 4.5, 3.8, 1348, 3.37, '["USDA FDC 168580","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '3325e845f0207c0c08ff5cf14b613819d413ea516c6b24dae68f99cd4bc57d9a', '0d5832b367586890a31c25a11b8ba07052bacaa1190876f00bd4606b3d69b326', 4),
('imp-f0039d3d3f6299b3', 'nam-kho-dau-phu-tuong', 133, 'Nấm đùi gà kho đậu phụ tương đậm vị', 'Nấm đùi gà giòn ngọt kho cùng đậu phụ rán và cà chua trong nước sốt tương sánh màu cánh gián đậm đà', 'Đĩa nấm đùi gà kho đậu phụ thơm nồng quyến rũ với màu nâu cánh gián óng ả từ xì dầu đặc kết hợp nước tương và vị chua ngọt tự nhiên của cà chua chín, giúp từng lát nấm dai giòn và miếng đậu phụ mềm béo thấm trọn gia vị.', 'Múc nấm và đậu phụ kho tương ra đĩa sâu lòng, rưới đều nước sốt sánh bóng lên trên rồi rắc hành lá, tiêu đen và ớt lát; ăn nóng cùng cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ 4–5 phút và thêm chút nước lọc nếu sốt quá đặc.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món kho","Nấm đùi gà","Đậu phụ","Ngày rằm"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["soybean","wheat"]', 236, 236.1, 987, 17.2, 13.1, 1.9, 18.1, 4.2, 9.7, 1932, 4.83, '["Dark Soy Sauce Label Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Monosodium Glutamate"]', 'f7d59a6e64ef3eed23730c619a716ca9d40e860ffb46ee9b0bb1626bc862d7cb', 'dbadf94ce37f14a350656598eb1ae2ac5b05071faf23dabe72168168c2b43f60', 4),
('imp-e771ef1a49b2aeed', 'bong-cai-xao-nam-chay', 134, 'Bông cải xanh xào nấm đùi gà chay', 'Bông cải xanh và cà rốt giữ độ giòn tươi, xào nhanh trên lửa lớn cùng nấm đùi gà trong lớp sốt nước tương sánh nhẹ', 'Đĩa rau xào chay đầy màu sắc với từng nhánh bông cải xanh mướt giòn sần sật, cà rốt ngọt thanh và nấm đùi gà thái lát dai giòn, được bao bọc bởi lớp nước sốt nước tương và bột bắp sánh mịn thơm mùi tỏi phi.', 'Dọn nóng ra đĩa ngay sau khi tắt bếp, rắc thêm tiêu xay và ớt thái lát; dùng kèm cơm trắng nóng hoặc chén nước tương ớt.', 'Món xào ngon nhất khi ăn ngay lúc vừa nấu xong để giữ độ giòn của bông cải; nếu bảo quản tủ mát tối đa 1 ngày, đảo nhanh lại trên chảo nóng 2 phút.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Bông cải xanh","Nấm đùi gà","Thanh đạm"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["soybean","wheat"]', 192, 191.6, 802, 6.7, 11, 1.6, 20.6, 5.2, 6.9, 1506, 3.77, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170106","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'da00eaa13c9f2816a0e0cd3777d97e2d1ba3b33d907c3fb8dd4e2f73657a3112', '9b91ca40e94c3b1b28386cf59ce4dec0174dd969b946421709f53d2cfded6329', 4),
('imp-43e806b28c7b8bb5', 'com-chien-tom-trung', 135, 'Cơm chiên tôm trứng', 'Cơm nguội rang tơi săn hạt cùng tôm tươi ngọt thịt, trứng gà béo thơm, cà rốt và giá đỗ giòn mát', 'Đĩa cơm chiên tôm trứng dân dã mà tròn vị với hạt cơm tơi rời bóng nhẹ, thịt tôm tươi săn ngọt đậm xì dầu nước mắm, trứng gà xốp vàng, cà rốt thái hạt lựu và giá đỗ giòn thanh giải ngấy.', 'Múc cơm chiên ra đĩa nóng, rắc tiêu đen xay và hành lá, ăn kèm dưa leo cắt lát cùng chén nước tương ớt xắt.', 'Thưởng thức ngay lúc nóng để giá đỗ giữ độ giòn và hạt cơm săn ngon. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và rang lại trên chảo nóng không dầu 3 phút.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm trứng","Ăn nhanh","Dưới 20 phút","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["crustaceans","egg","fish","shrimp","soybean","wheat"]', 434, 433.5, 1814, 21.7, 12.1, 2.4, 59, 2.5, 3.5, 1401, 3.5, '["USDA FDC 168878","USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '598f52aed342553ae6e459009e090bc7b590186ad88c41a160219b37408e2a3b', '54c9b902af1377cd062601800800567c16be7c190296670935dba93fa2cbedcd', 4),
('imp-f92a1c569c245541', 'mi-xao-bo-rau-cu', 136, 'Mì xào bò rau củ', 'Sợi mì tươi dai mượt áp chảo lửa lớn cùng thịt bò thăn mềm ngọt, bắp cải, cà rốt và hành tây đậm sốt xì dầu', 'Đĩa mì xào bò rau củ hài hòa dinh dưỡng với sợi mì vàng dai mềm không bết, thịt bò thăn xào tái mềm mọng nước quyện hương tỏi gừng và sốt xì dầu, dầu hào đậm đà, bắp cải, cà rốt cùng hành tây giòn ngọt.', 'Bày mì xào bò rau củ ra đĩa sâu lòng khi còn bốc khói, rắc tiêu đen xay và thưởng thức nóng kèm chén tương ớt hoặc nước tương ớt thái lát.', 'Ngon nhất khi ăn nóng ngay sau khi xào để rau củ còn giòn và thịt bò không bị dai. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ rồi làm nóng nhanh trên chảo lửa vừa.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 12, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Thịt bò","Rau củ","Ăn nhanh","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["beef","molluscs","soybean","wheat"]', 436, 436.1, 1825, 22.9, 17.8, 4.8, 46.5, 3.9, 6.1, 1125, 2.81, '["NIN VN Fresh Rice Noodle Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '8a13555392379fdb6d145855c7d9319a17961090fcaa137dcda4fdd7ec2a8675', 'd449bb965f083ca1aacfff5261ae0c98dc8740ba37ed56ec8e245e4847e81c3c', 4),
('imp-f4665d594d941e4a', 'chao-ga-gung-nong', 137, 'Cháo gà gừng nóng', 'Cháo gạo rang nấu nước luộc đùi gà ngọt thanh, thịt gà xé mềm quyện gừng sợi và hành lá ấm áp', 'Nồi cháo gà gừng nóng hổi với nước dùng ngọt tự nhiên từ đùi gà ta luộc cùng gừng hành tím, hạt gạo tẻ kết hợp gạo nếp nở bung sánh mịn, thịt đùi gà xé phay mềm ngọt và gừng tươi thái chỉ ấm bụng.', 'Múc cháo nóng ra tô, xếp thịt gà xé sợi lên trên cùng hành lá thái nhỏ, gừng thái chỉ, tiêu đen xay và vài giọt dầu mè; ăn kèm quẩy giòn hoặc chén nước mắm gừng.', 'Có thể bảo quản phần cháo và thịt gà xé riêng trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn chỉ cần đun sôi lại phần cháo với chút nước lọc rồi cho gà xé và gừng hành vào.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo gà","Gừng ấm","Ăn sáng","Bồi bổ","Cơm nhà"]', '["breakfast","dinner"]', '["boil","simmer"]', '["chicken","fish","sesame"]', 420, 419.9, 1757, 24.5, 12.4, 3.3, 50.2, 1.6, 1.3, 1311, 3.28, '["USDA FDC 168881","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd49ffb0085ed3db122a255613feaef3d072e6cbfddff7840e8d424519f6f58be', '6cf35f9128c35c80ccf4997a9fa925505d03fa4d5db58241e7b8628c0bcae3a9', 4),
('imp-35164fb31de89c5f', 'goi-ga-bap-cai-chanh', 138, 'Gỏi gà bắp cải chanh', 'Ức gà luộc xé phay mềm ngọt trộn bắp cải, cà rốt bào giòn cùng nước mắm chanh tỏi ớt chua ngọt', 'Đĩa gỏi gà bắp cải thanh mát với thịt ức gà ta luộc chín mềm không khô, sợi bắp cải trắng và cà rốt giòn sần sật, hành tây bớt hăng quyện cùng rau răm thơm nồng và nước mắm chanh tỏi ớt chua cay mặn ngọt.', 'Xếp gỏi gà bắp cải ra đĩa, rắc đậu phộng rang giã dập và ít tiêu xay lên mặt; ăn kèm bánh phồng tôm hoặc cơm nóng, cháo gà đều rất hợp.', 'Nên trộn gỏi ngay trước khi ăn để bắp cải giữ độ giòn rụm không bị chảy nước. Có thể sơ chế sẵn gà xé, rau củ cắt sợi và pha riêng nước mắm trộn bảo quản ngăn mát tối đa 24 giờ.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi gà","Thanh mát","Ít dầu mỡ","Khai vị","Nhanh gọn"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["chicken","fish","peanut"]', 233, 232.6, 973, 26.6, 6.5, 1.1, 17.9, 3.8, 11.1, 978, 2.45, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170931","USDA FDC 171477","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","VN Rau Ram Ref"]', 'ef34c129df5b08e456e7404d5164803cfa29d3626747248ae87d9654f76f8abf', 'cb52d2be92ec4d3ca11fb48904cab272e9ac1ecdaeee881476bd4ff03c77ec6d', 4),
('imp-368d91563cb1879b', 'lau-thai-tom-ca-mien-tay', 139, 'Lẩu Thái tôm cá miền Tây', 'Nước lẩu hầm xương đậm đà hòa quyện hương thơm sả, riềng, lá chanh và vị chua cay đặc trưng, nhúng tôm sú, cá diêu hồng và nấm tươi', 'Lẩu Thái tôm cá miền Tây là sự kết hợp hài hòa giữa vị chua cay nồng nàn kiểu Thái với nguyên liệu tươi ngon vùng sông nước Nam Bộ. Nước dùng ninh xương ống ngọt sâu, thơm dậy mùi sả, riềng, lá chanh và sa tế tôm, làm nổi bật vị ngọt của tôm sú, cá diêu hồng và nấm tươi.', 'Dọn nồi lẩu sôi lăn tăn giữa bàn, bày đĩa cá diêu hồng, tôm sú, nấm đùi gà, nấm rơm và rau muống xung quanh; nhúng chín tới và thưởng thức nóng kèm bún tươi cùng chén nước mắm ớt.', 'Nếu còn dư phần nước lẩu chưa nhúng cá tôm, để nguội rồi bảo quản ngăn mát tối đa 24 giờ; khi ăn đun sôi lại 3–5 phút và nhúng hải sản mới.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Lẩu Thái","Tôm cá","Miền Tây","Chua cay"]', '["lunch","dinner"]', '["simmer","boil"]', '["crustaceans","fish","pork","shrimp"]', 456, 456, 1907, 37.3, 12.2, 2.7, 51.7, 5.4, 9.4, 1507, 3.77, '["Chili Oil / Satay Ref","Citrus Leaf Culinary Ref","NIN VN Fresh Rice Noodle Ref","Pork Bone Stock Extraction Ref","Thai Tom Yum Paste Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169251","USDA FDC 169378","USDA FDC 169655","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'cca2d14219d2f4b561906d3731c656a01e5b930a8fdda714581875cdb7b86b10', 'f823e50b3914655037dce8e38510aec00914bed30a9cded8d67619af8751b40c', 4),
('imp-c52c790faf9281da', 'lau-nam-chay-dau-phu', 140, 'Lẩu nấm chay đậu phụ', 'Nước dùng chay thanh ngọt tự nhiên từ bắp ngọt, cà rốt và nhiều loại nấm tươi, nhúng đậu phụ chiên giòn, váng đậu và rau xanh', 'Lẩu nấm chay đậu phụ mang hương vị thanh tịnh và ngọt lành hoàn toàn từ rau củ và các loại nấm tươi. Nước lẩu thơm mùi hành boa-rô phi, ngọt dịu tự nhiên từ bắp ngọt và cà rốt, kết hợp đậu phụ trắng mềm, váng đậu giòn dai, bắp cải và nhiều loại nấm bổ dưỡng.', 'Dọn nồi lẩu nấm chay sôi nhẹ giữa bàn, nhúng nấm tươi, đậu phụ, váng đậu và bắp cải; ăn kèm bún khô chần mềm cùng chén nước tương ớt thái lát.', 'Nếu còn dư nước dùng chay chưa nhúng rau, để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi ăn đun sôi lại 3 phút với nấm mới.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'easy', 20, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Món chay","Lẩu nấm","Đậu phụ","Thanh đạm"]', '["lunch","dinner"]', '["simmer","boil"]', '["soybean","wheat"]', 497, 497.4, 2082, 22.4, 15.1, 2.3, 74.6, 8.7, 12.8, 1651, 4.13, '["USDA FDC 168580","USDA FDC 169246","USDA FDC 169251","USDA FDC 169253","USDA FDC 169745","USDA FDC 169975","USDA FDC 169998","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172472","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref","Vegetarian Seasoning Powder Ref"]', '22174aefb94d0e6d21a73f43dd9a3853f0e0fdd3f3032b96841f1fa252c7fb8a', '82ce520031970260d4a08361aac1a589ad9fb0bae0d908ed059db78194b631e0', 4),
('imp-e9678cfa1bc90074', 'tom-xao-trung-ca-chua', 141, 'Tôm xào trứng cà chua', 'Tôm tươi giòn ngọt kết hợp trứng gà chiên mềm xốp quyện trong sốt cà chua chua ngọt đậm vị cho bữa cơm nhanh gọn', 'Tôm xào trứng cà chua nâng tầm món trứng cà chua quen thuộc nhờ thịt tôm tươi săn giòn, kết hợp trứng gà đánh mềm xốp và phần sốt cà chua sóng sánh hài hòa vị chua ngọt mặn dịu.', 'Dọn nóng trên đĩa sâu lòng, rắc hành lá xanh thái nhỏ và thưởng thức ngay cùng cơm trắng nóng.', 'Món ăn ngon nhất khi dùng ngay trong bữa; nếu bảo quản tủ mát tối đa 24 giờ, làm nóng nhanh trên chảo lửa vừa trong 2 phút và tránh nấu quá lâu khiến tôm bị dai.', 'chinese', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Trung Hoa","Tôm trứng","Xào nhanh","Đưa cơm"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","egg","sesame","shrimp","soybean","wheat"]', 332, 331.7, 1388, 30, 17.5, 3.8, 14.5, 2.3, 8.8, 1130, 2.83, '["Shaoxing Wine Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170457","USDA FDC 170460","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'd757521b5d830c1c43962f9438321c52c903095a4801624b4cf5e3a4a9592b14', 'cc1a4de4864b1b5f69dd87b134402a1ca2dcedff277f47253287442a458de352', 4),
('imp-387c41fb3a0c2297', 'ga-kung-pao-tu-xuyen', 142, 'Gà Kung Pao Tứ Xuyên', 'Thịt đùi gà tẩm bột áo mềm mọng xào lửa lớn với ớt khô, hoa tiêu cay tê, đậu phộng giòn rụm và sốt giấm đen chua ngọt đậm vị', 'Gà Kung Pao Tứ Xuyên chinh phục vị giác nhờ sự cân bằng tinh tế giữa vị cay tê của ớt khô và hoa tiêu, vị chua ngọt dịu đặc trưng từ giấm đen Trấn Giang cùng miếng thịt đùi gà mềm mọng và đậu phộng rang giòn bùi.', 'Bày ngay ra đĩa khi sốt vừa áo bóng và đậu phộng còn giòn tan; ăn nóng kèm cơm trắng dẻo thơm.', 'Nếu cần bảo quản, cất hộp kín trong ngăn mát tối đa 2 ngày và để riêng phần đậu phộng rang nếu có thể; hâm lại nhanh trên chảo lửa vừa trong 2–3 phút rồi rắc đậu phộng.', 'chinese', 'mon_xao', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Kung Pao","Đậu phộng","Cay tê"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","peanut","soybean","wheat"]', 501, 501.1, 2097, 30.8, 33.3, 6.4, 19.9, 3.1, 9.1, 912, 2.28, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","Dark Soy Sauce Label Ref","Shaoxing Wine Ref","Spice Reference","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170933","USDA FDC 171413","USDA FDC 172385","USDA FDC 172430","USDA FDC 172883","USDA FDC 173468","USDA FDC 174277"]', 'f9837d1349409a7155308e250675fd65bdedc58ec472caf68024b19448b5a4be', 'a9f2190257dc75e26e3c73eec340235a0dfe18bc87d1e65a0aad20ce91986a8d', 4),
('imp-f5abd36e99d48d94', 'dau-phu-mapo-tu-xuyen', 143, 'Đậu phụ Mapo Tứ Xuyên', 'Đậu phụ non om trong lớp dầu ớt tự phi thơm nồng từ ớt tươi và ớt khô cùng thịt heo xay, tương đậu cay và hoa tiêu tê đầu lưỡi', 'Đậu phụ Mapo Tứ Xuyên phiên bản tự phi dầu ớt tươi và ớt khô trực tiếp tại bếp mang đến hương cay thơm bùng nổ, kết hợp thịt heo xay tơi đậm vị tương ớt đậu bản và đậu phụ non mềm tan.', 'Múc ra đĩa sâu lòng khi sốt đang sôi liu riu, rắc thêm bột hoa tiêu và hành lá xanh; món ăn sinh ra để ăn nóng với cơm trắng.', 'Dùng ngon nhất ngay sau khi nấu. Nếu bảo quản tủ mát tối đa 2 ngày, hâm lại nhẹ tay trên chảo lửa nhỏ cùng 1–2 muỗng canh nước dùng hoặc nước lọc.', 'chinese', 'mon_kho', NULL, 'medium', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry","braise"]', '["pork","sesame","soybean","wheat"]', 420, 420.4, 1759, 17, 34.3, 7.7, 11.5, 1.4, 2.7, 715, 1.79, '["Pixian Doubanjiang Ref","Spice Reference","USDA FDC 167902","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 172476","USDA FDC 172883","USDA FDC 173647"]', '0b6289ca7e53e45e179a8730a203545a43599bf926bb13e3e6a2f52fd6ad4e14', 'aec18eb9aceaab44ffef33245d8cfff033ea709f4de886b0c788b770671f27dd', 4),
('imp-242fd73cebd63651', 'suon-chua-ngot-quang-dong', 144, 'Sườn om chua ngọt Quảng Đông', 'Sườn non heo áp xém vàng om mềm trong sốt tương cà, giấm gạo, đường phèn và dứa cà chua sánh bóng đậm đà', 'Sườn om chua ngọt Quảng Đông là món mặn trứ danh với từng khúc sườn non mềm róc xương, quyện lớp sốt đỏ bóng chua thanh của giấm gạo và tương cà, hòa cùng vị ngọt tươi từ dứa chín và cà chua.', 'Bày sườn và dứa cà chua ra đĩa lớn, rưới nước sốt sánh keo lên trên; ăn nóng kèm cơm trắng dẻo thơm.', 'Bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng trên chảo lửa nhỏ đến vừa với 2 muỗng canh nước lọc trong 5 phút.', 'chinese', 'mon_kho', NULL, 'medium', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Chua ngọt","Sườn heo","Tiệc nhà"]', '["lunch","dinner"]', '["boil","pan_fry","braise"]', '["pork","soybean","wheat"]', 376, 376.1, 1574, 16.8, 26.2, 8.9, 17.5, 1.4, 13.1, 801, 2, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 167861","USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170457","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '8df6f265ce1c06e3b2e795cccbec62f961f6b3262a336faa16d08668b52db728', 'ff61b09a51b656b02cc77adcfff057eab33da2779d132862563bfebafb6d753e', 4),
('imp-34f3eb2438125614', 'bap-cai-xao-toi-quang-dong', 145, 'Bắp cải xào tỏi kiểu Quảng Đông', 'Bắp cải xanh xé miếng kết hợp cà rốt thái lát xào lửa lớn giữ trọn độ giòn ngọt, dậy mùi tỏi phi, rượu Thiệu Hưng và giấm đen', 'Bắp cải xào tỏi kiểu Quảng Đông nổi bật với từng lá bắp cải xé tay giòn sần sật, mép lá hơi xém cạnh thơm mùi chảo nóng, quyện vị mặn ngọt thanh nhẹ của xì dầu, rượu Thiệu Hưng và giấm đen Trấn Giang.', 'Trút ra đĩa và dùng nóng ngay với cơm trắng để cảm nhận trọn vẹn độ giòn ngọt tự nhiên của rau củ.', 'Món rau xào nên dùng hết trong bữa để giữ độ giòn tươi; nếu bảo quản tủ mát tối đa 24 giờ, đảo nóng nhanh trên chảo lửa lớn trong 1–2 phút.', 'chinese', 'mon_xao', NULL, 'easy', 10, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Bắp cải","Xào tỏi","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["pork","soybean","wheat"]', 268, 268.4, 1123, 5.8, 20.9, 6.2, 15.9, 4.8, 7.2, 782, 1.96, '["Chinkiang Black Vinegar Ref","Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '52efb7776902ccc550e2e7ddddf172a3dcc69a16412ccd93bd2ca230754c7447', 'a4d0192d3e34c28ffcf8f3aaf95a3b3ccd52ee02c382679dd7dd7311b5e6ac3d', 4),
('imp-2d508cd359edb61c', 'dau-phu-hap-tom-gung', 146, 'Đậu phụ trứng hấp tôm gừng', 'Những khoanh đậu phụ trứng mềm tan phủ chả tôm tươi băm nhuyễn quyện gừng hành hấp chín tới, rưới sốt dầu hào xì dầu sánh bóng', 'Đậu phụ trứng hấp tôm gừng mang phong vị dim sum tinh tế với phần đậu phụ trứng béo mịn nâng đỡ viên chả tôm giòn ngọt tự nhiên, hoàn thiện bằng lớp sốt xì dầu dầu hào trong mượt và hương thơm ấm nồng của gừng hành.', 'Dọn nóng nguyên đĩa ngay sau khi rưới sốt và rắc lá hành xanh; dùng làm món chính nhẹ bụng cùng cơm trắng hoặc món khai vị tiệc gia đình.', 'Ngon nhất khi ăn nóng ngay sau khi hấp; nếu bảo quản tủ mát tối đa 24 giờ, đậy kín màng bọc thực phẩm và hấp nóng lại khoảng 4–5 phút trước khi dùng.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Dim sum","Đậu phụ","Tôm tươi"]', '["lunch","dinner"]', '["steam","simmer"]', '["crustaceans","egg","molluscs","sesame","shrimp","soybean","wheat"]', 211, 211, 883, 21.7, 9.3, 2.1, 9.3, 0.8, 1.9, 816, 2.04, '["Asian Egg Tofu Ref","Shaoxing Wine Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '1cf7eaeed48e1dd0452678f47a45bc1f2f9edfbb31237148f3f73f9b1a151e6e', '0e08d58f6cee8917495c9cd92e6f1e47a0b9d6b8b98e21f55a7d78497de0b86f', 4),
('imp-6eaf6ed6d417c52c', 'muc-chien-muoi-ot', 147, 'Mực chiên giòn muối ớt kiểu Hồng Kông', 'Mực tươi áo hai lớp bột ướt và bột khô chiên vàng giòn rụm, xóc nhanh cùng tỏi gừng, ớt hiểm phi thơm và muối tiêu rang', 'Mực chiên giòn muối ớt kiểu Hồng Kông hấp dẫn với lớp vỏ ngoài xốp giòn vàng ruộm ôm trọn miếng mực tươi giòn ngọt bên trong, dậy mùi thơm bùng nổ của tỏi phi, gừng băm, ớt hiểm và hành lá.', 'Dọn nóng ngay khi vừa xóc gia vị để giữ độ giòn rụm; thưởng thức kèm tương ớt hoặc chanh tươi như món khai vị hoặc ăn cùng cơm trắng.', 'Món chiên ngon nhất khi dùng ngay lúc nóng giòn; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 3–4 phút.', 'chinese', 'mon_chien', NULL, 'medium', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Hồng Kông","Hải sản","Muối ớt"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["molluscs","squid","wheat"]', 423, 422.7, 1768, 23.7, 17.5, 2.8, 40.7, 1.6, 0.7, 586, 1.46, '["Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 169761","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 175039"]', '40d30ab8bfc0264f87b8f4c3814251e31ca02c8f2a0c43f7bf57b06a17f05950', '77cba96b653b12470e4f775a9223c0787c4b8c6b1974689393091a2fa50c8daf', 4),
('imp-d90dc5bbe2891a12', 'chao-thit-bam-gung', 148, 'Cháo thịt bằm gừng trứng kiểu Quảng Đông', 'Cháo gạo rang ninh sánh mịn kết hợp thịt heo bằm ướp đậm vị, vân trứng gà béo mượt, gừng sợi cay ấm và hành lá thơm nồng', 'Cháo thịt bằm gừng trứng kiểu Quảng Đông là món ăn bổ dưỡng, ấm bụng với hạt gạo rang trước giúp cháo nhanh nhừ sánh mịn, hòa quyện thịt heo bằm tơi mềm, vân trứng gà óng ả và gừng tươi thái sợi giải cảm.', 'Xếp gừng thái sợi vào đáy tô trước rồi chan cháo nóng hổi lên trên, rắc hành lá, tiêu đen xay và vài giọt dầu mè thơm; dùng nóng ngay.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi hâm lại trên bếp lửa nhỏ, thêm 50–100 ml nước lọc và khuấy đều tay để cháo không bị bén đáy nồi.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 15, 40, 3, '/frigo/illustrations/delicious-meal.png', '["Món cháo","Quảng Đông","Bữa sáng","Ấm bụng"]', '["breakfast","dinner"]', '["simmer"]', '["egg","pork","sesame","soybean","wheat"]', 529, 529, 2213, 21.1, 20.6, 6.8, 62.4, 1.7, 1.2, 1340, 3.35, '["USDA FDC 167902","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'd55b69accb07fd52218bb7131fbecbab0905a0260cf3faf9ff108cbf0bf1b528', 'ce40c62dada905484e449db2948047ecf9b84105e5c5f027ec40f63e5225b6be', 4),
('imp-b23ab24915e52866', 'com-chien-duong-chau', 149, 'Cơm chiên Dương Châu', 'Hạt cơm tơi vàng óng ánh áo lòng đỏ trứng, quyện tôm tươi, thịt bằm, lạp xưởng, trứng chiên cắt hạt lựu cùng cà rốt và đậu giòn ngọt', 'Cơm chiên Dương Châu chuẩn vị quán Quảng Đông nổi bật với hạt cơm săn tơi vàng ươm nhờ kỹ thuật trộn lòng đỏ trứng trước khi rang, kết hợp đầy đặn tôm tươi, thịt heo xay, lạp xưởng thơm béo và rau củ giòn ngọt.', 'Dọn nóng ra đĩa hoặc nén chén úp ngược đẹp mắt, rắc thêm tiêu xay và hành lá; ăn kèm dưa leo, cà chua lát và chút nước tương ớt.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; hâm nóng bằng cách đảo nhanh trên chảo chống dính lửa vừa trong 3–4 phút cho hạt cơm tơi nóng lại.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Dương Châu","Cơm chiên","Quảng Đông","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","egg","pork","shrimp","soybean","wheat"]', 676, 675.6, 2827, 31.2, 31.1, 8.5, 65.9, 2.1, 5.2, 1330, 3.33, '["USDA / Chinese Sausage Ref","USDA FDC 167902","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'c35d990700c82d41cb844659ec45096548eaa4adb202c8c8431e6cbb1b6ac49b', '2af45fce514d2c653dd40575895c456ecbc826c7553370b829e721fa44469ac4', 4),
('imp-e83f58ebb9b02fbd', 'mi-dan-dan-tu-xuyen', 150, 'Mì Đan Đan Tứ Xuyên', 'Mì sợi dai trộn sốt tương mè béo bùi, dầu ớt cay nồng, giấm đen và hoa tiêu Tứ Xuyên, phủ thịt heo băm xào giòn, cải thìa và đậu phộng', 'Mì Đan Đan Tứ Xuyên là món mì trộn đường phố trứ danh, quy tụ hài hòa vị béo bùi của tương mè, vị cay tê bùng nổ từ dầu ớt và hoa tiêu, hòa quyện cùng sợi mì dai mượt, cải thìa chần giòn và thịt heo băm xào khô thơm lừng.', 'Trình bày gọn đẹp trong tô vừa với lớp sốt dưới đáy, mì ở giữa, thịt xào, cải thìa, đậu phộng giã và hành lá trên cùng; trộn thật đều tay trước khi ăn nóng.', 'Món mì trộn ngon nhất khi ăn ngay lúc vừa chế biến. Nếu cần chuẩn bị trước, có thể bảo quản riêng phần thịt xào và nước sốt trong tủ mát tối đa 3 ngày, khi ăn chỉ cần luộc mì nóng rồi trộn.', 'chinese', 'mon_bun_pho', NULL, 'medium', 15, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Tứ Xuyên","Cay tê","Mì Đan Đan"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["egg","peanut","pork","sesame","soybean","wheat"]', 792, 792.1, 3314, 29.5, 39, 8.7, 80.9, 5.9, 5.6, 1682, 4.21, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","Dark Soy Sauce Label Ref","Five Spice USDA Ref","Shaoxing Wine Ref","Spice Reference","USDA / MEXT Wheat Noodle Ref","USDA FDC 167902","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170189","USDA FDC 170390","USDA FDC 171028","USDA FDC 171413","USDA FDC 172430","USDA FDC 173647","USDA FDC 174277"]', 'fdb7a50c1e90707e1eb47c1ea5eb5237c6944f62b52e6e681e4d9e562325566d', 'dd70c6cbb8fd9fe98dbd0b5526f0b6db908b0eaf5473683161a6e3cfd705c57a', 4),
('imp-04d477399e49fe8e', 'mi-xao-bo-quang-dong', 151, 'Mì xào bò Quảng Đông', 'Thịt bò thái lát ướp mềm kiểu Quảng Đông xào lửa lớn với mì trứng áp vàng, giá đỗ, đậu Hà Lan giòn ngọt và sốt xì dầu đậm vị', 'Mì xào bò Quảng Đông mang hương vị đặc trưng của món xào chảo nóng với sợi mì trứng tơi dai, thịt bò mềm mọng nhờ kỹ thuật ướp baking soda và bột bắp, hòa cùng giá đỗ, đậu giòn ngọt và nước sốt xì dầu bóng thơm.', 'Dọn nóng ngay ra đĩa lớn, dùng kèm tương ớt sa tế hoặc giấm ớt ngâm nếu thích vị cay kích thích.', 'Mì xào ngon nhất khi dùng ngay lúc nóng; nếu bảo quản tủ mát tối đa 24 giờ, làm nóng nhanh trên chảo lửa vừa với 1–2 muỗng canh nước lọc trong 2–3 phút.', 'chinese', 'mon_xao', NULL, 'easy', 20, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Quảng Đông","Mì xào","Thịt bò","Lửa lớn"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["beef","egg","molluscs","sesame","soybean","wheat"]', 706, 705.6, 2953, 35.9, 25.4, 6.5, 81.9, 4.5, 6.9, 1660, 4.15, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169961","USDA FDC 169963","USDA FDC 170005","USDA FDC 170187","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175039"]', 'd2cfc0333aa54019c4e49709e6a4716516624ecdbfcad37331519845767a658a', '9a2aa582646a85e94b8d23bd358c5a8829bd062e1c7112f4f4bf3186779f94a3', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-a22f9257b0fd7a46', 'ba-chi-kho-dong-pha', 152, 'Ba chỉ kho Đông Pha', 'Từng khối ba chỉ heo buộc dây lạt kho liu riu hàng giờ trong rượu Thiệu Hưng, xì dầu, đường phèn và lớp hành gừng thơm nồng đến mềm tan', 'Ba chỉ kho Đông Pha là tuyệt phẩm ẩm thực Giang Nam với từng khối thịt ba chỉ vuông vắn có lớp bì màu nâu hổ phách óng ả, phần mỡ trong mềm tan không ngấy nhờ được om chậm hàng giờ với rượu Thiệu Hưng, xì dầu và đường phèn.', 'Gắp từng khối thịt ra đĩa sâu lòng, cắt bỏ dây buộc, rưới phần nước kho sánh bóng lên mặt; dọn nóng cùng cơm trắng dẻo và cải thìa luộc xanh mướt.', 'Có thể bảo quản hộp kín trong ngăn mát tối đa 4 ngày (thịt kho càng hâm lại càng đậm đà). Khi ăn, hấp cách thủy hoặc đun liu riu lại với nước kho trên lửa nhỏ trong 10–15 phút.', 'chinese', 'mon_kho', NULL, 'hard', 20, 180, 5, '/frigo/illustrations/delicious-meal.png', '["Đông Pha nhục","Trung Hoa","Món kho","Tiệc nhà"]', '["lunch","dinner"]', '["boil","braise"]', '["pork","soybean","wheat"]', 665, 665.1, 2782, 12.8, 61.2, 22.3, 11.6, 0.8, 8.5, 1139, 2.85, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169231","USDA FDC 170005","USDA FDC 170917","USDA FDC 171316","USDA FDC 171320","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', '8bd61b0014aa4ba0a9f99bfe0f99a42a05be746490f0e6d9dbccbe9cae1e9439', '1b8eee68225532eff6a66aa6510eae1527c32b3b963629da1f9985b8949445be', 4),
('imp-5f8d0890bd6d0a76', 'vien-su-tu-dau-kho-cai', 153, 'Viên Sư Tử Đầu kho cải thảo', 'Những viên thịt heo lớn quết tay mềm xốp trộn củ năng giòn sần sật, chiên vàng định hình rồi kho mềm thấm trên nền cải thảo ngọt thanh', 'Viên Sư Tử Đầu kho cải thảo là món ăn truyền thống vùng Hoài Dương nổi bật với những viên thịt heo cỡ lớn mềm tơi mọng nước xen lẫn củ năng giòn sần sật, được kho liu riu trên lớp cải thảo ngọt thanh cùng sốt xì dầu dầu hào sánh bóng.', 'Xếp cải thảo kho mềm xuống đáy đĩa sâu lòng, đặt 4 viên thịt Sư Tử Đầu lên trên, rưới nước sốt sánh bóng và rắc hành lá xanh; ăn nóng với cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại cả thịt viên và nước kho trong nồi đậy nắp trên lửa nhỏ khoảng 8–10 phút.', 'chinese', 'mon_kho', NULL, 'hard', 25, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Sư tử đầu","Hoài Dương","Món kho","Tiệc nhà"]', '["lunch","dinner"]', '["deep_fry","braise"]', '["egg","molluscs","pork","sesame","soybean","wheat"]', 513, 513.2, 2147, 25.1, 35.8, 10.9, 21.3, 2.8, 6.9, 1334, 3.33, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","Panko / Batter Mix Ref","Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169231","USDA FDC 169294","USDA FDC 169698","USDA FDC 169977","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', 'd55b7318855e6227cb3ea22ed5a1ee1ecf5d932c059ecbc8cff8bc1f27d1bc19', 'b2f02830ddfbd574ee5d293e430060a7e421004c02c6e2e4c3253f663a3641e3', 4),
('imp-ece7da4660b63e9d', 'bo-xao-ca-chua-kieu-trung', 154, 'Bò xào cà chua kiểu Trung', 'Thịt bò thái lát mềm mọng xào cùng cà chua chín đỏ sốt chua ngọt sánh mịn, đậm vị cơm nhà Trung Hoa', 'Món bò xào cà chua kiểu Trung nổi bật với từng lát thịt bò được xử lý mềm mượt hòa quyện trong phần sốt cà chua chín đỏ sánh bóng, chua ngọt hài hòa.', 'Dọn nóng ngay ra đĩa sâu lòng, rắc hành lá thái khúc lên trên và thưởng thức cùng cơm trắng dẻo thơm hoặc rau cải chần.', 'Ngon nhất khi dùng ngay sau khi xào; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đảo nhanh trên chảo lửa lớn cùng 1 muỗng canh nước lọc khi hâm lại.', 'chinese', 'mon_xao', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Cà chua","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","sesame","soybean","wheat"]', 420, 420.3, 1759, 30.6, 25, 7, 18.2, 2.8, 9.3, 1074, 2.69, '["Shaoxing Wine Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170460","USDA FDC 170499","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175039"]', '99dc2aa12ae7c712b7de6903506314f6dbb28b48d0341ef34b222365db4f84a6', 'a2652bc891d63a1ac2e8a263c1dac134bce24e71514be862f41c599e8cf2f796', 4),
('imp-b9d222a8c523b8e4', 'dua-leo-dap-toi-tu-xuyen', 155, 'Dưa leo đập tỏi Tứ Xuyên', 'Dưa leo đập dập giòn sần thấm đẫm sốt giấm đen Trấn Giang, tỏi băm, dầu mè và dầu ớt tê cay đặc trưng', 'Món khai vị lạnh trứ danh của ẩm thực Tứ Xuyên với từng miếng dưa leo đập dập giòn rụm, thấm sâu hỗn hợp giấm đen Trấn Giang, tỏi tươi, dầu mè thơm lừng và sa tế dầu ớt.', 'Bày dưa leo ra đĩa sâu lòng, rưới phần sốt còn lại trong tô lên mặt, rắc mè trắng rang và ngò rí; ăn lạnh ngay để khai vị hoặc giải ngấy cùng các món thịt kho, đồ chiên.', 'Món trộn ăn liền ngon nhất trong vòng 30 phút sau khi trộn; nếu chuẩn bị trước, nên bảo quản riêng dưa đã vắt ráo và phần sốt trong ngăn mát tối đa 12 giờ rồi mới trộn trước khi ăn.', 'chinese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn","Tứ Xuyên","Khai vị","Dưa leo","Giải ngấy"]', '["lunch","dinner"]', '["toss_mix"]', '["sesame","soybean","wheat"]', 145, 144.9, 607, 2.7, 10, 1.5, 12.9, 1.5, 6.9, 751, 1.88, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","Spice Reference","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170106","USDA FDC 170150","USDA FDC 171028","USDA FDC 173468","USDA FDC 174277"]', '0108fd9b397054c86308bd2c11f5fd78780877ccdd9fc48a5affaf2bd694cfa9', '7706d3de617cd05bd4aa738524599b2b9ee5562dcbc81ee49574f5226731bf2c', 4),
('imp-51f6c12eefee914d', 'dau-phu-kho-bap-cai', 156, 'Đậu phụ kho bắp cải', 'Đậu phụ chiên vàng óng kho mềm cùng bắp cải ngọt và nấm kim châm trong nước tương đậm đà thanh đạm', 'Món kho bình dân kiểu gia đình Trung Hoa kết hợp đậu phụ chiên vàng giòn vỏ ngoài, bắp cải giòn ngọt và nấm kim châm dai mềm thấm đẫm sốt nước tương sánh nhẹ.', 'Dọn nóng ngay trong nồi đất hoặc đĩa sâu lòng, rắc hành lá và tiêu đen xay lên mặt; dùng kèm cơm trắng nóng rất bắt vị.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn, hâm nóng trên chảo lửa nhỏ 3–4 phút cho đậu phụ và bắp cải nóng đều.', 'chinese', 'mon_kho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Đậu phụ","Bắp cải","Thanh đạm","Trung Hoa"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 254, 253.8, 1062, 15.8, 16.1, 2.3, 16.7, 5.4, 7.3, 1428, 3.57, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169253","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', 'ca80a96598d41662040e7bcdec81dfc698b6711e5ce9436210446d7676b9e18e', '77cde94fa04560d42870a3a4793a02c21a17bc355a5fcd92d851effacc0dc87e', 4),
('imp-6d3fa354c64cf8b1', 'ca-kho-tuong-dam', 157, 'Cá kho tương đậm kiểu Trung', 'Cá nguyên con áp chảo vàng giòn da rồi kho sánh cùng rượu Thiệu Hưng, giấm đen Trấn Giang và xì dầu đậm đà', 'Món cá kho tàu trứ danh kiểu Trung Hoa không thêm nước mà om cá trực tiếp trong hỗn hợp rượu Thiệu Hưng, giấm đen Trấn Giang và xì dầu sánh bóng, giữ nguyên lớp da vàng giòn và thớ thịt trắng ngọt.', 'Đặt nguyên con cá lên đĩa bầu dục lớn, rưới đều phần sốt nâu đỏ sánh mịn lên mình cá và dùng nóng cùng cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn, cho cá cùng nước sốt vào chảo đậy nắp hâm trên lửa nhỏ 5–6 phút đến khi nóng kỹ.', 'chinese', 'mon_kho', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Cá nguyên con","Trung Hoa","Đậm đà","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["fish","soybean","wheat"]', 341, 340.8, 1425, 39.3, 12.5, 2.4, 12.6, 0.6, 7.7, 745, 1.86, '["Chinkiang Black Vinegar Ref","Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","USDA FDC 175176"]', 'a510891d8a2135a5405fd24108770af9fa9c1265ed38266e63d4eaa1dc03bbfa', 'd7f2b2197eee328041dc277d93bb25ea703fa8eb508391e6c53c54e1a23b194a', 4),
('imp-03577e7fa7667ab8', 'canh-chua-cay-trung-hoa', 158, 'Canh chua cay kiểu Trung Hoa', 'Nước súp sánh mượt nóng hổi hòa quyện vị chua thanh giấm đen, cay nồng tiêu trắng cùng đậu phụ, nấm và vân trứng gà', 'Món súp chua cay trứ danh của ẩm thực Trung Hoa với nước dùng gà sánh nhẹ, vân trứng gà tơ mềm, nấm đùi gà giòn ngọt, đậu phụ mềm mịn cùng vị chua thơm từ giấm đen và cay ấm của tiêu trắng.', 'Múc canh nóng hổi ra tô sứ sâu lòng, rắc hành lá thái nhỏ và ớt hiểm đỏ lên mặt; dùng làm món khai vị nóng trước bữa chính.', 'Ngon nhất khi ăn nóng ngay lúc vừa nấu; nếu còn dư, bảo quản ngăn mát tối đa 24 giờ và đun nóng lại trên lửa vừa, thêm chút giấm đen trước khi tắt bếp để giữ trọn hương thơm.', 'chinese', 'mon_canh', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Chua cay","Trung Hoa","Khai vị","Ấm bụng"]', '["lunch","dinner"]', '["simmer"]', '["egg","sesame","soybean","wheat"]', 212, 211.7, 886, 16.9, 9.2, 1.9, 17.4, 3, 5.1, 1401, 3.5, '["Chinkiang Black Vinegar Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 172475","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '7eec388f0e729514d24716c53fbb29e2da0840df00c282b811207f1d98ec0286', '6ef7535dd433bc5a23a67cfbdaead5b0bf6c9a0f2874da02e7a71fc1827f5933', 4),
('imp-62ebe8dd18b15b5e', 'muc-xao-gung-hanh', 159, 'Mực xào gừng hành', 'Mực ống khía hoa giòn ngọt chần nhanh rồi xào lửa lớn với gừng sợi, hành lá và sốt dầu hào thơm lừng', 'Món mực xào gừng hành kiểu Quảng Đông giữ được độ giòn sần sật tự nhiên của từng miếng mực khía hoa nhờ kỹ thuật chần nhanh với gừng và xào đảo tốc độ trên lửa lớn.', 'Trút ngay ra đĩa khi vừa tắt bếp để mực giữ độ giòn ngọt, rắc thêm chút tiêu xay và ăn nóng kèm cơm trắng.', 'Mực xào ngon nhất khi ăn ngay lúc nóng; nếu cần bảo quản ngăn mát tối đa 24 giờ, khi hâm lại chỉ đảo thật nhanh trên chảo nóng trong 30 giây để tránh mực bị dai.', 'chinese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Mực tươi","Quảng Đông","Nhanh gọn","Hải sản"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["molluscs","soybean","squid","wheat"]', 264, 263.9, 1104, 24.1, 10.5, 1.8, 16.6, 1.5, 4.9, 1335, 3.34, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '2708bd3ceb39a2a7ae6429c87b9b6ee7c18ca458e149ceb9b2ebc16985196a1e', 'a5e45bca6d64ea7a6fc3f6d715c78d94e1b88074792c2270188c09308d231278', 4);

