('imp-511a92d180408e0a_v4_ing_3', 'imp-511a92d180408e0a', 2, 'DRIED_SHIITAKE', 'Nấm hương khô (đông cô)', '20 g (khoảng 6–7 tai nấm)', 'ngâm nước ấm 20 phút cho nở mềm, cắt bỏ chân cứng rồi băm nhỏ', 'main', 20, 'g', 20, 1, 20, 0, 1),
