('imp-62ebe8dd18b15b5e_v4_ing_1', 'imp-62ebe8dd18b15b5e', 0, 'SQUID', 'Mực ống tươi', '500 g', 'rút bỏ đầu, nội tạng, mắt, răng và lột sạch lớp màng tím; khía hoa mặt trong rồi cắt miếng vừa ăn', 'main', 500, 'g', 500, 0.85, 425, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_2', 'imp-62ebe8dd18b15b5e', 1, 'GINGER', 'Gừng tươi', '30 g (1 nhánh vừa)', 'chia 10 g thái lát để thả vào nước chần mực khử tanh (bỏ bã sau chần), 20 g còn lại thái sợi mỏng để xào', 'aromatics', 30, 'g', 30, 0.65, 19.5, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_3', 'imp-62ebe8dd18b15b5e', 2, 'SCALLION', 'Hành lá tươi', '1 bó (khoảng 4 cây)', 'rửa sạch, cắt khúc 4 cm, tách riêng phần gốc trắng phi thơm và phần lá xanh cho vào cuối', 'aromatics', 1, 'bunch', 40, 1, 40, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_4', 'imp-62ebe8dd18b15b5e', 3, 'GARLIC', 'Tỏi khô', '1/2 củ (khoảng 3–4 tép)', 'bóc vỏ, đập dập rồi băm nhỏ', 'aromatics', 0.5, 'piece', 12.5, 0.9, 11.25, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_5', 'imp-62ebe8dd18b15b5e', 4, 'CARROT', 'Cà rốt tươi', '3/4 củ (khoảng 80 g)', 'tùy chọn gọt vỏ, thái sợi mỏng hoặc tỉa hoa tạo màu sắc hài hòa', 'main', 0.75, 'piece', 82.5, 0.89, 73.43, 1, 1),
('imp-62ebe8dd18b15b5e_v4_ing_6', 'imp-62ebe8dd18b15b5e', 5, 'SHAOXING_WINE', 'Rượu Thiệu Hưng', '22 ml (~1,5 muỗng canh)', 'hòa vào chén nước sốt giúp khử tanh mực và dậy hương thơm', 'sauce', 22, 'ml', 21.8, 0.7, 15.26, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_7', 'imp-62ebe8dd18b15b5e', 6, 'LIGHT_SOY_SAUCE', 'Xì dầu nhạt', '22 ml (~1,5 muỗng canh)', 'tạo vị mặn thanh cho sốt xào mực', 'sauce', 22, 'ml', 26, 1, 26, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_8', 'imp-62ebe8dd18b15b5e', 7, 'OYSTER_SAUCE', 'Dầu hào', '22 ml (~1,5 muỗng canh)', 'giúp nước sốt đậm vị umami và bóng đẹp', 'sauce', 22, 'ml', 26.8, 1, 26.8, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_9', 'imp-62ebe8dd18b15b5e', 8, 'DARK_SOY_SAUCE', 'Xì dầu đặc', '5 ml (~1 muỗng cà phê)', 'tạo màu nâu hổ phách nhẹ bám đều lên miếng mực', 'sauce', 5, 'ml', 6.2, 1, 6.2, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_10', 'imp-62ebe8dd18b15b5e', 9, 'SUGAR', 'Đường cát trắng', '6 g (~1,5 muỗng cà phê)', 'cân bằng vị mặn của xì dầu và dầu hào', 'sauce', 6, 'g', 6, 1, 6, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_11', 'imp-62ebe8dd18b15b5e', 10, 'BLACK_PEPPER', 'Tiêu đen xay', '2,3 g (~1 muỗng cà phê)', 'tạo vị cay ấm nổi bật cho món mực xào', 'sauce', 2.3, 'g', 2.3, 1, 2.3, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_12', 'imp-62ebe8dd18b15b5e', 11, 'CORNSTARCH', 'Bột bắp', '5 g (~1,5 muỗng cà phê)', 'hòa vào chén sốt để làm sánh nhanh khi đổ vào chảo nóng', 'sauce', 5, 'g', 5, 1, 5, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_13', 'imp-62ebe8dd18b15b5e', 12, 'COOKING_OIL', 'Dầu ăn thực vật', '30 ml (~2 muỗng canh)', 'dùng để phi thơm gừng tỏi và xào nhanh mực trên lửa lớn', 'aromatics', 30, 'ml', 27.6, 0.9, 24.84, 0, 1),
('imp-62ebe8dd18b15b5e_v4_ing_14', 'imp-62ebe8dd18b15b5e', 13, 'SEASONING_POWDER', 'Hạt nêm', '4 g (~1 muỗng cà phê)', 'tùy chọn thêm vào sốt để tăng vị ngọt đậm đà', 'sauce', 4, 'g', 4, 1, 4, 1, 1),
('imp-62ebe8dd18b15b5e_v4_ing_15', 'imp-62ebe8dd18b15b5e', 14, 'SALT', 'Muối ăn', '1,5 g (~1/4 muỗng cà phê)', 'tùy chọn nêm chỉnh lại nếu muốn vị đậm hơn', 'sauce', 1.5, 'g', 1.5, 1, 1.5, 1, 1),
('imp-62ebe8dd18b15b5e_v4_ing_16', 'imp-62ebe8dd18b15b5e', 15, 'COOKING_WATER', 'Nước lọc', '25 ml (~1,5 muỗng canh)', 'hòa tan bột bắp và các gia vị trong chén nước sốt', 'sauce', 25, 'ml', 25, 0.9, 22.5, 0, 0);

INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-511a92d180408e0a_v4_step_1', 'imp-511a92d180408e0a', 1, 'prep', 'Ngâm nấm hương và sơ chế hành tím, hành lá', 'Ngâm 20 g nấm hương khô trong nước ấm khoảng 20 phút cho nở mềm hoàn toàn, vớt ra vắt nhẹ nước, cắt bỏ chân nấm cứng rồi băm nhỏ. Bóc vỏ 15 g hành tím băm nhuyễn; rửa sạch hành lá thái nhỏ và để riêng 1/3 phần lá xanh dùng rắc mặt.', NULL, 20),
('imp-511a92d180408e0a_v4_step_2', 'imp-511a92d180408e0a', 2, 'marinate', 'Ướp thịt heo xay cùng nấm hương và gia vị', 'Cho 200 g thịt heo xay vào tô cùng nấm hương băm nhỏ, hành tím băm, 5 ml nước mắm, 2,5 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay. Trộn thật đều tay rồi để nghỉ 10 phút cho thịt ngấm vị và không bị vón cục khi hòa cùng trứng.', 'Ướp thịt heo xay trước khi trộn vào trứng giúp thịt tơi mềm, đậm đà và không bị nhạt vị so với phần trứng xung quanh.', 10),
('imp-511a92d180408e0a_v4_step_3', 'imp-511a92d180408e0a', 3, 'prep', 'Đánh tan trứng gà và lọc qua rây mịn', 'Đập 4 quả trứng gà vào tô lớn, thêm 120 ml nước lọc nguội, 10 ml nước mắm còn lại, 2,5 g hạt nêm và 3 g đường cát trắng. Dùng đũa khuấy nhẹ đều theo một chiều cho tan gia vị mà không tạo nhiều bọt khí, sau đó lọc hỗn hợp qua rây mịn vào tô sứ chịu nhiệt.', 'Khuấy nhẹ tay theo một chiều và lọc qua rây giúp loại bỏ lợn cợn lòng trắng và bọt khí, mặt trứng sau khi hấp sẽ láng mịn như gương.', NULL),
('imp-511a92d180408e0a_v4_step_4', 'imp-511a92d180408e0a', 4, 'prep', 'Trộn đều nhân thịt nấm và bọc kín miệng tô', 'Cho phần thịt heo xay đã ướp cùng 2/3 lượng hành lá thái nhỏ vào tô trứng đã lọc, khuấy nhẹ cho thịt tơi đều không lắng đọng cục ở đáy. Dùng màng bọc thực phẩm chịu nhiệt bọc kín miệng tô (hoặc đậy đĩa sứ vừa khít) để hơi nước không nhỏ giọt làm rỗ mặt trứng.', NULL, NULL),
('imp-511a92d180408e0a_v4_step_5', 'imp-511a92d180408e0a', 5, 'cook', 'Hấp cách thủy lửa nhỏ cho trứng đông mịn', 'Đun sôi 600 ml nước lọc trong nồi hấp, đặt tô trứng lên xửng rồi hạ xuống lửa nhỏ liu riu, đậy nắp và hấp cách thủy trong 20 phút. Nếu dùng nắp vung thường không bọc màng thực phẩm, nên lót thêm chiếc khăn sạch dưới nắp nồi để thấm hơi nước.', 'Luôn giữ lửa nhỏ liu riu trong suốt quá trình hấp; nhiệt quá mạnh sẽ làm nước sôi trào khiến trứng bị rỗ tổ ong và tách nước.', 20),
('imp-511a92d180408e0a_v4_step_6', 'imp-511a92d180408e0a', 6, 'finish', 'Kiểm tra độ chín và hoàn thiện tô trứng hấp', 'Mở màng bọc, dùng tăm xiên nhẹ vào chính giữa tô trứng, rút ra thấy tăm sạch không dính dịch trứng ướt và phần thịt bên trong đã chín trắng hoàn toàn là đạt. Rắc phần hành lá thái nhỏ và 1 g tiêu đen xay còn lại lên mặt, rưới thêm 5 ml dầu mè thơm và dùng nóng ngay với cơm.', NULL, NULL),
('imp-d02c9b83214f81be_v4_step_1', 'imp-d02c9b83214f81be', 1, 'cook', 'Luộc chín thịt ba chỉ và thái lát mỏng', 'Chà sạch thịt ba chỉ với chút muối rồi rửa lại, cho vào nồi với 500 ml nước lọc, 10 g hành tím đập dập và 3 g muối ăn. Đun sôi trên lửa lớn rồi hạ lửa vừa luộc khoảng 18 phút đến khi đũa xiên qua thịt không còn nước hồng. Vớt ra ngâm nước nguội cho thịt trắng săn, để ráo rồi thái lát mỏng vừa ăn.', NULL, 18),
('imp-d02c9b83214f81be_v4_step_2', 'imp-d02c9b83214f81be', 2, 'prep', 'Sơ chế dưa leo giòn mát không đắng', 'Rửa sạch dưa leo, cắt bỏ hai đầu và chà xát vòng tròn hai đầu quả đến khi ra bọt trắng để loại bỏ vị đắng, sau đó xả sạch. Bổ đôi dưa leo theo chiều dọc, nạo bỏ hết phần ruột hạt rồi thái lát vát mỏng, ngâm cùng cà rốt bào sợi vào thau nước đá lạnh pha 300 ml nước lọc và 3 g muối ăn trong 10 phút cho rau củ giòn cứng rồi vớt vắt ráo.', 'Loại bỏ hết phần ruột dưa leo và ngâm nước đá giúp gỏi giữ độ giòn lâu mà không bị chảy nhiều nước khi trộn.', 10),
('imp-d02c9b83214f81be_v4_step_3', 'imp-d02c9b83214f81be', 3, 'cook', 'Rim chín tôm giữ trọn vị ngọt', 'Rửa sạch tôm tươi, cắt bỏ râu chân và rút chỉ đen trên lưng. Làm nóng chảo trên lửa vừa, cho tôm cùng 2 g muối ăn vào rim đảo đều khoảng 4 phút đến khi tôm chuyển màu đỏ cam rực, thịt săn chín hoàn toàn và cạn ráo nước thì tắt bếp, để nguội rồi bóc vỏ và chẻ đôi.', 'Rim tôm trên chảo khô thay vì luộc ngập nước giúp thịt tôm săn giòn và giữ nguyên vị ngọt tự nhiên.', 4),
('imp-d02c9b83214f81be_v4_step_4', 'imp-d02c9b83214f81be', 4, 'sauce', 'Giã tỏi ớt pha nước mắm trộn gỏi', 'Cho 48 g đường cát trắng, tỏi khô và ớt sừng vào cối giã nhuyễn quyện đều. Trút ra bát, thêm 45 ml nước mắm ngon, 15 ml tương ớt và nước cốt 2 quả chanh tươi, khuấy kỹ cho đường tan hết thành hỗn hợp nước trộn sánh thơm.', NULL, NULL),
('imp-d02c9b83214f81be_v4_step_5', 'imp-d02c9b83214f81be', 5, 'prep', 'Phi hành tím và chuẩn bị đồ ăn kèm', 'Phi thơm vàng 10 g hành tím thái lát với 10 ml dầu ăn trên lửa nhỏ rồi vớt ráo dầu. Rang chín lạc trên lửa nhỏ, xát sạch vỏ và giã dập. Chuẩn bị sẵn đĩa bánh phồng tôm giòn và rửa sạch, cắt nhỏ rau húng lủi.', NULL, NULL),
('imp-d02c9b83214f81be_v4_step_6', 'imp-d02c9b83214f81be', 6, 'finish', 'Trộn gỏi theo hai lượt thấm đều vị', 'Cho dưa leo và cà rốt đã vắt ráo vào âu lớn, rưới một nửa nước mắm trộn vào đảo đều và để 3 phút cho rau củ thấm trước. Tiếp theo cho tôm rim và thịt ba chỉ vào, rưới nốt phần nước trộn còn lại đảo nhẹ tay, thêm rau húng lủi cắt nhỏ vào trộn đều lần cuối. Bày gỏi ra đĩa, rắc đậu phộng rang giã dập, hành phi và dọn ăn kèm bánh phồng tôm.', 'Trộn rau củ trước với một nửa nước trộn giúp dưa leo cà rốt đậm đà mà không làm tôm thịt bị mặn gắt.', NULL),
('imp-9ae951bec7fbf21b_v4_step_1', 'imp-9ae951bec7fbf21b', 1, 'prep', 'Ngâm và trụng hủ tiếu khô tơi sợi', 'Ngâm hủ tiếu khô trong nước lọc mát khoảng 8 phút cho sợi hơi mềm, sau đó đun nóng 1 lít nước lọc khoảng 80°C rồi trụng hủ tiếu nhanh 2 phút. Vớt ra rổ xóc ráo hoàn toàn, trộn ngay với 10 ml dầu ăn để sợi hủ tiếu tơi rời, không dính bết khi xào.', 'Không luộc hủ tiếu bằng nước sôi quá lâu vì sợi sẽ mềm nhão và dễ nát vụn khi đảo trên chảo.', 10),
('imp-9ae951bec7fbf21b_v4_step_2', 'imp-9ae951bec7fbf21b', 2, 'marinate', 'Sơ chế và ướp tôm tươi thấm vị', 'Tôm tươi bóc vỏ chừa đuôi, rút bỏ chỉ đen, rửa sạch thấm khô. Ướp tôm với 10 ml dầu hào, 2,5 g hạt nêm, 2,5 g đường cát trắng, 1 g tiêu đen xay cùng một nửa phần tỏi khô và hành tím khô băm nhuyễn, để ngấm 10 phút.', NULL, 10),
('imp-9ae951bec7fbf21b_v4_step_3', 'imp-9ae951bec7fbf21b', 3, 'prep', 'Chuẩn bị giá đỗ, hẹ lá và rau trang trí', 'Rửa sạch giá đỗ, để thật ráo nước để khi xào không ra nước; hẹ lá cắt khúc 3–4 cm; ngò rí rửa sạch và ớt tươi thái lát mỏng.', NULL, NULL),
('imp-9ae951bec7fbf21b_v4_step_4', 'imp-9ae951bec7fbf21b', 4, 'cook', 'Xào chín săn tôm tươi trên lửa lớn', 'Bắc chảo rộng lên bếp lửa lớn với 15 ml dầu ăn, phi thơm phần tỏi và hành tím băm còn lại rồi trút tôm đã ướp vào đảo nhanh tay khoảng 2–3 phút đến khi tôm chuyển màu hồng cam đậm, thịt săn chín hoàn toàn thì trút ra đĩa riêng.', 'Xào tôm riêng ở lửa lớn giúp tôm giữ độ giòn ngọt và không ra nước làm ướt sợi hủ tiếu.', 3),
('imp-9ae951bec7fbf21b_v4_step_5', 'imp-9ae951bec7fbf21b', 5, 'cook', 'Xào hủ tiếu thấm xì dầu với giá hẹ', 'Làm nóng chảo vừa dùng với 15 ml dầu ăn còn lại, thả giá đỗ và hẹ lá vào đảo nhanh 45 giây trên lửa lớn cho vừa chín tới. Trút sợi hủ tiếu đã trộn dầu vào, rưới đều 25 ml xì dầu, 10 ml dầu hào còn lại, 2,5 g hạt nêm và 2,5 g đường cát trắng, xóc đảo liên tục 2 phút cho sợi hủ tiếu ráo bóng, lên màu vàng nâu hấp dẫn.', 'Đảo nhanh tay trên lửa lớn giúp sợi hủ tiếu dậy mùi thơm áp chảo mà giá hẹ vẫn giòn xanh.', 3),
('imp-9ae951bec7fbf21b_v4_step_6', 'imp-9ae951bec7fbf21b', 6, 'finish', 'Trộn đều tôm và bày đĩa thưởng thức', 'Trút phần tôm đã xào vào chảo hủ tiếu, đảo đều thêm 30 giây cho quyện vị rồi tắt bếp. Bày ra 3 đĩa, rắc thêm 1 g tiêu đen xay còn lại, điểm ngò rí và ớt tươi thái lát để thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-5ab5c1053b7371f0_v4_step_1', 'imp-5ab5c1053b7371f0', 1, 'prep', 'Thấm ráo đậu phụ và băm nhuyễn sả, tỏi, ớt', 'Đậu phụ trắng rửa nhẹ, dùng khăn giấy thấm thật khô rồi cắt mỗi bìa thành 6–8 miếng vuông dày khoảng 2 cm. Sả tươi bóc bỏ lớp bẹ già bên ngoài, cắt bỏ gốc và băm thật nhuyễn; tỏi khô và ớt sừng bỏ hạt, băm nhuyễn để riêng.', 'Băm sả càng nhuyễn thì khi xào sả càng dễ dậy hương và bám kín đều lên bề mặt từng miếng đậu phụ.', NULL),
('imp-5ab5c1053b7371f0_v4_step_2', 'imp-5ab5c1053b7371f0', 2, 'cook', 'Chiên vàng giòn đều các mặt đậu phụ', 'Làm nóng chảo với 85 ml dầu ăn thực vật trên lửa vừa đến khi dầu nóng già, lần lượt thả từng miếng đậu phụ vào chiên khoảng 8 phút. Lật nhẹ các mặt đến khi vỏ đậu phồng vàng giòn đều thì gắp ra đĩa lót giấy thấm dầu.', 'Chờ dầu nóng già trước khi thả đậu và giữ khoảng cách giữa các miếng giúp đậu không bị dính sát và không vỡ khi trở mặt.', 8),
('imp-5ab5c1053b7371f0_v4_step_3', 'imp-5ab5c1053b7371f0', 3, 'cook', 'Phi thơm tỏi, sả băm và ớt trên lửa nhỏ', 'Chắt bớt dầu trong chảo ra, chỉ giữ lại khoảng 15 ml dầu ăn. Cho tỏi băm vào phi 30 giây trên lửa nhỏ cho vừa dậy hương, tiếp tục đổ toàn bộ sả băm và ớt băm vào đảo đều tay thêm 2 phút đến khi sả ngả vàng thơm nồng.', 'Giữ lửa nhỏ khi phi sả và tỏi để hỗn hợp chín vàng đều từ từ, tránh bị cháy đắng.', 2),
('imp-5ab5c1053b7371f0_v4_step_4', 'imp-5ab5c1053b7371f0', 4, 'cook', 'Nêm gia vị vào hỗn hợp sả ớt', 'Nêm trực tiếp vào chảo sả ớt 30 ml nước tương, 8 g đường cát trắng, 3 g muối ăn và 4 g hạt nêm chay. Đảo đều trên lửa nhỏ khoảng 1 phút cho đường tan hết và gia vị quyện sánh với sả ớt.', NULL, NULL),
('imp-5ab5c1053b7371f0_v4_step_5', 'imp-5ab5c1053b7371f0', 5, 'cook', 'Xóc đều đậu phụ chiên với sả ớt đậm đà', 'Trút toàn bộ phần đậu phụ đã chiên giòn trở lại chảo, dùng đũa hoặc xẻng gỗ đảo nhẹ và đều tay trong 3 phút trên lửa nhỏ để lớp sả ớt mặn ngọt bám kín quanh từng miếng đậu.', NULL, 3),
('imp-5ab5c1053b7371f0_v4_step_6', 'imp-5ab5c1053b7371f0', 6, 'finish', 'Rắc tiêu đen và trình bày ra đĩa nóng', 'Rắc 1 g tiêu đen xay vào chảo, đảo nhanh thêm 10 giây rồi tắt bếp. Gắp đậu phụ chiên sả ớt ra đĩa, gạt đều phần sả ớt phi vàng lên mặt và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-67054d03e5a5b011_v4_step_1', 'imp-67054d03e5a5b011', 1, 'prep', 'Vo gạo và sơ chế gừng, hành lá, đánh trứng', 'Vo sạch 100 g gạo tẻ qua 2 lần nước nhẹ tay rồi để ráo. Cạo vỏ 15 g gừng tươi, rửa sạch và thái sợi chỉ thật mảnh. Rửa sạch hành lá, thái nhuyễn. Đập 2 quả trứng gà vào chén, dùng đũa đánh tan nhẹ đến khi lòng trắng và lòng đỏ hòa đều.', 'Thái gừng thành sợi thật mảnh sẽ giúp gừng tiết tinh dầu ấm nhanh khi gặp cháo nóng mà không bị cay gắt lúc nhai.', NULL),
('imp-67054d03e5a5b011_v4_step_2', 'imp-67054d03e5a5b011', 2, 'cook', 'Nấu gạo nở mềm trên lửa nhỏ vừa', 'Cho gạo vào nồi cùng 1,2 lít nước lọc, đặt lên bếp đun sôi bùng trên lửa lớn rồi hạ ngay xuống lửa nhỏ. Đậy hé nắp và ninh khoảng 15 phút, thỉnh thoảng dùng vá khuấy sát đáy nồi để hạt gạo nở bung đều, nước cháo sánh mịn mà không bị bén đáy.', 'Đậy hé nắp khi ninh cháo giúp giữ nhiệt ổn định cho gạo nhanh nhừ mà không bị trào bọt ra bếp.', 15),
('imp-67054d03e5a5b011_v4_step_3', 'imp-67054d03e5a5b011', 3, 'cook', 'Nêm gia vị cho nồi cháo trắng', 'Khi hạt gạo đã nở nhừ sánh mịn, nêm 3 g muối ăn và 15 ml nước mắm ngon vào nồi, khuấy đều rồi nếm thử để điều chỉnh độ mặn thanh vừa miệng.', NULL, NULL),
('imp-67054d03e5a5b011_v4_step_4', 'imp-67054d03e5a5b011', 4, 'cook', 'Rót trứng gà tạo vân tơi mịn', 'Giữ nồi cháo sôi lăn tăn nhẹ trên lửa nhỏ, từ từ rót chén trứng gà đã đánh tan vào nồi theo dòng mảnh, đồng thời dùng đũa khuấy đều một chiều khoảng 1 phút để trứng kết thành những vân vàng mịn quyện đều trong cháo và chín hoàn toàn.', 'Rót trứng từ từ khi cháo đang sôi nhẹ giúp trứng chín ngay thành vân mượt mà không bị tanh hay vón cục lớn.', 1),
('imp-67054d03e5a5b011_v4_step_5', 'imp-67054d03e5a5b011', 5, 'cook', 'Hòa một phần gừng vào nồi cháo', 'Thả một nửa lượng gừng tươi thái sợi vào nồi cháo, khuấy nhẹ thêm 30 giây cho hương gừng lan tỏa đều trong nước cháo rồi tắt bếp.', NULL, NULL),
('imp-67054d03e5a5b011_v4_step_6', 'imp-67054d03e5a5b011', 6, 'finish', 'Chan cháo nóng lên hành lá và thưởng thức', 'Lót hành lá thái nhỏ và phần gừng tươi thái sợi còn lại dưới đáy 2 bát sứ. Múc cháo trứng nóng hổi chan lên trên để hành lá chín tái dậy mùi thơm, nhỏ đều 5 ml dầu mè và rắc 1,5 g tiêu đen xay rồi thưởng thức ngay.', NULL, NULL),
('imp-e375595daced53af_v4_step_1', 'imp-e375595daced53af', 1, 'prep', 'Thái mỏng và ướp nhẹ thịt thăn bò', 'Thấm thật khô 600 g thịt thăn bò, thái lát mỏng ngang thớ. Xếp thịt bò ra đĩa lớn, ướp nhẹ với 15 g gừng thái sợi, một nửa lượng tỏi băm, 1,5 g tiêu đen xay và 5 ml dầu ăn rồi trộn đều cho thịt thơm mềm và không bị thâm.', 'Chỉ ướp thịt bò với dầu ăn, gừng, tỏi và tiêu, không ướp muối hay nước mắm quá sớm để thịt không bị chảy nước đỏ.', NULL),
('imp-e375595daced53af_v4_step_2', 'imp-e375595daced53af', 2, 'prep', 'Sơ chế dứa, rau củ và chuẩn bị đồ cuốn', 'Thái lát mỏng 1/2 quả dứa chín để nấu lẩu, băm nhuyễn 1/4 quả còn lại để pha mắm nêm. Bổ múi cau 2 quả cà chua; 1/2 củ hành tây bổ múi cau, 1/2 củ thái lát mỏng xếp lên đĩa thịt bò. Đập dập 3 cây sả cắt khúc 5 cm; rửa sạch rau muống, xà lách, rau sống và bày bánh tráng cuốn, bún tươi ra bàn.', NULL, NULL),
('imp-e375595daced53af_v4_step_3', 'imp-e375595daced53af', 3, 'sauce', 'Pha mắm nêm dứa tỏi ớt đậm đà', 'Cho 45 ml mắm nêm vào chén cùng 8 g đường phèn giã nhỏ, phần dứa băm nhuyễn, phần tỏi băm còn lại và 1 quả ớt hiểm băm. Khuấy đều cho đường tan hoàn toàn và các gia vị hòa quyện sánh thơm.', 'Băm nhuyễn dứa chín trộn vào mắm nêm giúp làm dịu độ mặn gắt tự nhiên của mắm cá cơm và tạo vị chua ngọt thanh rất bắt miệng.', NULL),
('imp-e375595daced53af_v4_step_4', 'imp-e375595daced53af', 4, 'cook', 'Phi thơm hành tím và xào sơ dứa, cà chua', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn còn lại, phi thơm 20 g hành tím băm và 3 cây sả đập dập trong 1 phút. Cho phần dứa thái lát và cà chua bổ múi cau vào đảo nhẹ 3 phút cho cà chua mềm và dứa tiết nước ngọt.', NULL, 4),
('imp-e375595daced53af_v4_step_5', 'imp-e375595daced53af', 5, 'cook', 'Nấu nước lẩu dừa dứa chua thanh', 'Đổ 500 ml nước dừa tươi và 1200 ml nước lọc vào nồi, thêm 1/2 củ hành tây bổ múi cau rồi đun sôi bùng và hớt sạch bọt. Hạ lửa vừa nấu 10 phút cho nước ngọt thanh, sau đó cho 80 ml giấm gạo, 15 ml nước mắm ngon, 12 g đường phèn, 3 g muối ăn và 1 quả ớt thái lát vào nếm lại vị chua ngọt dịu nhẹ.', 'Cho giấm gạo vào ở giai đoạn cuối trước khi dọn bàn để giữ độ chua thanh dịu mà không bị bay hơi mất mùi thơm.', 10),
('imp-e375595daced53af_v4_step_6', 'imp-e375595daced53af', 6, 'finish', 'Nhúng bò chín tới và cuốn bánh tráng chấm mắm nêm', 'Chuyển nồi lẩu ra bếp giữa bàn giữ sôi lăn tăn. Khi ăn, gắp từng lát thịt bò cùng hành tây thái lát nhúng vào nước lẩu khoảng 15–20 giây cho thịt vừa chín tái hồng mềm ngọt, nhúng thêm rau muống. Trải bánh tráng, xếp rau sống, bún tươi và thịt bò nóng hổi vào cuốn tròn rồi chấm cùng mắm nêm dứa ớt.', NULL, NULL),
('imp-9b4ea97916a44e67_v4_step_1', 'imp-9b4ea97916a44e67', 1, 'prep', 'Nhặt và rửa sạch rau muống non', 'Nhặt bỏ phần cọng già và lá úa của 1,5 bó rau muống, cắt khúc dài khoảng 5 cm. Ngâm rau vào chậu nước sạch pha 3 g muối ăn trong 7 phút cho sạch bụi bẩn, sau đó rửa lại 2–3 lần nước lạnh rồi vớt ra rổ để thật ráo.', NULL, 7),
('imp-9b4ea97916a44e67_v4_step_2', 'imp-9b4ea97916a44e67', 2, 'prep', 'Sơ chế tôm giã nhuyễn và đập dập', 'Lột vỏ 250 g tôm tươi, bỏ đầu, rút sạch chỉ đen dọc lưng, rửa qua nước lạnh rồi thấm ráo. Chia 1/3 lượng tôm cho vào cối giã thật nhuyễn để tạo độ ngọt tự nhiên cho nước canh; 2/3 phần tôm còn lại dùng sống dao đập dập nhẹ cho thịt tôm giữ độ sần sật. Băm nhỏ 20 g hành tím, cắt khúc hành lá và ngò rí.', 'Kết hợp giã nhuyễn 1/3 tôm và đập dập 2/3 tôm giúp nước dùng vừa ngọt đậm đà vừa còn miếng thịt tôm ăn rất đã miệng.', NULL),
('imp-9b4ea97916a44e67_v4_step_3', 'imp-9b4ea97916a44e67', 3, 'cook', 'Phi thơm hành tím và xào chín thơm tôm', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm vào phi đến khi dậy mùi thơm vàng nhẹ. Trút cả phần tôm giã nhuyễn và tôm đập dập vào đảo đều 2–3 phút đến khi tôm săn lại, chuyển màu cam hồng hấp dẫn và chín đều.', NULL, 3),
('imp-9b4ea97916a44e67_v4_step_4', 'imp-9b4ea97916a44e67', 4, 'cook', 'Nấu nước dùng tôm ngọt trong', 'Đổ 900 ml nước lọc vào nồi tôm, bật lửa lớn đun sôi bùng, dùng vá hớt sạch phần bọt nổi trên mặt rồi hạ xuống lửa vừa nấu tiếp 5 phút để thịt tôm tiết hết vị ngọt vào nước canh.', 'Hớt sạch bọt ngay khi nước vừa sôi giúp nồi canh rau muống giữ được độ trong thanh và không bị đục.', 5),
('imp-9b4ea97916a44e67_v4_step_5', 'imp-9b4ea97916a44e67', 5, 'cook', 'Nêm gia vị và thả rau muống nấu mở vung', 'Nêm 8 g hạt nêm, 5 g muối ăn còn lại, 10 ml nước mắm và 4 g đường vào nồi, khuấy tan rồi nếm lại vị thanh ngọt hài hòa. Khi nước sôi bùng trở lại trên lửa lớn, thả rau muống vào và dùng vá nhấn nhẹ cho rau ngập nước, nấu mở vung đúng 3 phút đến khi cọng rau vừa chín tới, xanh mướt và vẫn giữ độ giòn.', 'Nấu rau muống ở lửa lớn và tuyệt đối không đậy nắp giúp giữ màu xanh tươi tự nhiên mà không bị thâm sẫm.', 3),
('imp-9b4ea97916a44e67_v4_step_6', 'imp-9b4ea97916a44e67', 6, 'finish', 'Hoàn thiện với hành lá và ngò rí', 'Tắt bếp ngay sau khi rau chín tới, thả hành lá và ngò rí cắt khúc vào đảo nhẹ một lượt cho dậy hương thơm rồi múc canh ra tô dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-6d7fc503ade5df6e_v4_step_1', 'imp-6d7fc503ade5df6e', 1, 'prep', 'Sơ chế thịt ba chỉ và băm nhuyễn sả ớt', 'Rửa sạch thịt ba chỉ heo, dùng khăn giấy thấm thật khô rồi thái thành từng lát mỏng vừa ăn dày khoảng 0,4 cm. Sả tươi bóc bỏ bẹ già, đập dập và băm thật nhuyễn; tỏi khô và ớt hiểm đỏ tươi băm nhỏ; hành lá rửa sạch thái nhỏ.', 'Thấm khô thịt ba chỉ trước khi cho lên chảo giúp thịt nhanh săn xém cạnh mà không bị bắn dầu.', NULL),
('imp-6d7fc503ade5df6e_v4_step_2', 'imp-6d7fc503ade5df6e', 2, 'cook', 'Áp chảo thịt ba chỉ ra bớt mỡ và săn xém', 'Đặt chảo khô lên bếp lửa vừa (thêm tối đa 10 ml dầu ăn nếu thịt ít mỡ). Cho toàn bộ thịt ba chỉ vào dàn đều, đảo khoảng 3–4 phút cho thịt tiết bớt mỡ thừa, săn chắc và chín kỹ đều hai mặt không còn sắc hồng thì gắp riêng ra đĩa.', 'Áp chảo trước giúp phần mỡ ba chỉ tan bớt, miếng thịt khi xào xong ăn giòn ngậy mà không bị ngán.', 4),
('imp-6d7fc503ade5df6e_v4_step_3', 'imp-6d7fc503ade5df6e', 3, 'cook', 'Phi thơm vàng tỏi, sả và ớt băm', 'Chắt bớt phần mỡ heo dư nếu quá nhiều, chỉ giữ lại khoảng 1,5 muỗng canh mỡ nóng trong chảo. Cho tỏi băm, sả băm và ớt hiểm đỏ băm vào phi đều tay trên lửa vừa khoảng 2 phút cho đến khi sả ngả vàng nhẹ và dậy mùi thơm nồng.', 'Giữ lửa vừa khi phi sả để tinh dầu sả tỏa thơm mà không bị cháy khét gây đắng.', 2),
('imp-6d7fc503ade5df6e_v4_step_4', 'imp-6d7fc503ade5df6e', 4, 'cook', 'Xào thấm gia vị đậm đà kiểu miền Trung', 'Trút toàn bộ thịt ba chỉ vào lại chảo sả ớt, nêm 15 ml nước mắm ngon, 8 g đường cát trắng và 5 g hạt nêm. Hạ lửa vừa-nhỏ và đảo liên tục khoảng 3–4 phút để gia vị keo nhẹ bám đều quanh miếng thịt, bề mặt thịt vàng xém cạnh và chín kỹ hoàn toàn.', NULL, 4),
('imp-6d7fc503ade5df6e_v4_step_5', 'imp-6d7fc503ade5df6e', 5, 'cook', 'Thêm hành lá và tiêu đen xay', 'Nêm nếm lại cho vừa khẩu vị mặn cay đậm đà. Cho hành lá thái nhỏ và 2 g tiêu đen xay vào đảo nhanh tay thêm 20 giây cho hành chín xanh rồi tắt bếp.', NULL, NULL),
('imp-6d7fc503ade5df6e_v4_step_6', 'imp-6d7fc503ade5df6e', 6, 'finish', 'Trình bày và dùng nóng với cơm', 'Múc thịt ba chỉ xào sả ớt cùng phần sả phi vàng thơm ra đĩa, thưởng thức nóng ngay với cơm trắng.', NULL, NULL),
('imp-364497296cfcf033_v4_step_1', 'imp-364497296cfcf033', 1, 'prep', 'Làm sạch ống mực và ngâm mềm nấm hương', 'Nắm phần đầu mực kéo nhẹ tách khỏi thân, rút bỏ túi mực, nang cứng và nội tạng, cắt bỏ mắt cùng răng mực rồi lột bỏ lớp da tím bên ngoài. Rửa mực với 2 g muối ăn rồi xả sạch lại nước mát, giữ nguyên ống thân không bị thủng rách và để thật ráo. Ngâm 15 g nấm hương khô trong nước ấm 20 phút cho nở mềm rồi băm nhuyễn.', NULL, 20),
('imp-364497296cfcf033_v4_step_2', 'imp-364497296cfcf033', 2, 'marinate', 'Quết dẻo nhân thịt heo xay với nấm và gia vị', 'Cho 250 g thịt heo xay vào tô lớn cùng nấm hương băm nhuyễn, 10 g gừng băm, 15 g hành tím băm, tỏi băm nhuyễn và một nửa lượng hành lá thái nhỏ. Nêm 15 ml nước mắm, 4 g hạt nêm, 4 g đường cát trắng, 2 g muối ăn và 2 g tiêu đen xay, dùng thìa quết mạnh tay 2 phút cho nhân dẻo mịn rồi để nghỉ 10 phút.', 'Quết nhân kỹ cho dẻo kết dính giúp phần thịt bên trong không bị rời rạc hay rỗng ruột khi cắt khoanh.', 10),
('imp-364497296cfcf033_v4_step_3', 'imp-364497296cfcf033', 3, 'prep', 'Nhồi nhân vào thân mực và cố định bằng tăm', 'Dùng thìa nhỏ múc từng phần nhân thịt nhồi vào ống thân mực, ấn nhẹ cho nhân chặt đều nhưng chỉ nhồi khoảng 80% độ dài thân mực để trừ hao độ co khi chín. Đặt đầu mực trở lại miệng ống và dùng tăm tre ghim chéo cố định chắc chắn, có thể chích vài lỗ tăm nhỏ dọc thân mực để thoát khí.', 'Chỉ nhồi đầy khoảng 80% thân mực và chích 2–3 lỗ tăm nhỏ giúp vỏ mực không bị nứt vỡ khi hấp nóng.', NULL),
('imp-364497296cfcf033_v4_step_4', 'imp-364497296cfcf033', 4, 'cook', 'Hấp cách thủy mực nhồi thịt chín đều', 'Đun sôi 600 ml nước lọc trong nồi hấp. Xếp mực đã nhồi vào đĩa sâu lòng chịu nhiệt, rải đều 15 g gừng thái sợi và phần hành lá cắt khúc còn lại lên trên. Đặt đĩa vào xửng, đậy kín nắp và hấp trên lửa vừa khoảng 18 phút đến khi thân mực chuyển trắng đục và xiên tăm vào giữa thấy nhân thịt chín săn, nước tiết ra trong suốt.', 'Duy trì lửa vừa ổn định khi hấp giúp nhân thịt bên trong chín đều tới tâm mà lớp mực bên ngoài không bị co rút hay nứt vỡ.', 18),
('imp-364497296cfcf033_v4_step_5', 'imp-364497296cfcf033', 5, 'sauce', 'Pha muối tiêu chanh ớt chấm mực hấp', 'Trộn đều 3 g muối ăn còn lại với 1 g tiêu đen xay trong chén nhỏ, vắt nước cốt 1/2 quả chanh tươi vào khuấy nhẹ rồi thả vài lát ớt tươi lên trên.', NULL, NULL),
('imp-364497296cfcf033_v4_step_6', 'imp-364497296cfcf033', 6, 'finish', 'Cắt khoanh mực nhồi thịt và trình bày nóng', 'Nhấc đĩa mực ra khỏi xửng, chờ nguội bớt khoảng 3 phút cho nhân săn chắc rồi rút bỏ tăm tre. Dùng dao bản mỏng thật sắc thái mực thành từng khoanh tròn dày 1,5 cm, xếp ngay ngắn ra đĩa cùng phần gừng hành hấp và rưới nhẹ ít nước ngọt tiết ra, dọn nóng chấm muối tiêu chanh.', NULL, NULL),
('imp-806780abda4b5205_v4_step_1', 'imp-806780abda4b5205', 1, 'marinate', 'Sơ chế và ướp tôm tươi cùng mực ống', 'Lột vỏ tôm tươi, rút sạch chỉ lưng rồi cắt miếng vừa ăn; làm sạch mực ống, thái miếng vuông 1 cm. Cho tôm mực vào tô ướp với 5 ml nước mắm ngon, 2 g hạt nêm, một nửa lượng tiêu đen xay và một phần nhỏ hành tím băm trong 10 phút cho thấm vị.', NULL, 10),
('imp-806780abda4b5205_v4_step_2', 'imp-806780abda4b5205', 2, 'prep', 'Sơ chế dứa chín, rau củ và đánh tơi cơm nguội', 'Khoét lấy phần thịt dứa từ 1/2 quả dứa chín (giữ lại vỏ làm bát đựng nếu thích), bỏ lõi cứng, cắt hạt lựu nhỏ rồi ép nhẹ cho ráo bớt nước. Thái hạt lựu nhỏ cà rốt và đậu cô ve; băm nhỏ tỏi, phần hành tím còn lại và thái nhỏ hành lá. Đánh tơi 540 g cơm nguội với 3 g bột cà ri để cơm lên màu vàng đều.', 'Vắt nhẹ phần dứa cắt hạt lựu cho ráo nước giúp cơm khi rang luôn tơi khô mà không bị nhão.', NULL),
('imp-806780abda4b5205_v4_step_3', 'imp-806780abda4b5205', 3, 'cook', 'Xào nhanh tôm mực chín săn và rau củ giòn ngọt', 'Làm nóng 10 ml dầu ăn trên lửa lớn, phi thơm một nửa lượng tỏi và hành tím băm. Cho tôm và mực vào đảo nhanh khoảng 2 phút đến khi tôm chuyển màu đỏ hồng, thịt mực săn trắng chín hoàn toàn thì trút riêng ra đĩa. Tận dụng chảo nóng đảo nhanh cà rốt và đậu cô ve thêm 2 phút cho chín tới rồi cho ra đĩa cùng hải sản.', 'Xào hải sản trên lửa lớn và vớt ra sớm giúp tôm mực giữ độ giòn ngọt tự nhiên, không bị ra nước và dai.', 4),
('imp-806780abda4b5205_v4_step_4', 'imp-806780abda4b5205', 4, 'cook', 'Chiên trứng và rang tơi cơm nguội với bột cà ri', 'Cho 15 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi và hành tím băm còn lại. Đập 2 quả trứng gà vào khuấy tơi trên lửa vừa, ngay khi trứng vừa sệt lại thì trút toàn bộ cơm nguội đã trộn bột cà ri vào. Vặn lửa lớn, đảo đều liên tục khoảng 4 phút cho từng hạt cơm săn tơi và quyện đều trứng.', NULL, 4),
('imp-806780abda4b5205_v4_step_5', 'imp-806780abda4b5205', 5, 'cook', 'Trộn dứa chín, hải sản và nêm vị đậm đà', 'Cho phần thịt dứa cắt hạt lựu vào chảo cơm đảo đều 1 phút, nêm 15 ml nước mắm ngon, 4 g đường cát trắng và 2 g hạt nêm còn lại. Tiếp tục trút đĩa tôm mực cùng cà rốt, đậu cô ve vào đảo nhanh trên lửa lớn 2 phút cho mọi nguyên liệu quyện đều và nóng hổi.', 'Cho dứa vào gần cuối giúp miếng dứa giữ được độ mọng giòn và vị chua ngọt tươi mát.', 2),
('imp-806780abda4b5205_v4_step_6', 'imp-806780abda4b5205', 6, 'finish', 'Rắc hành lá, hạt điều rang và trình bày', 'Tắt bếp, rắc hành lá thái nhỏ và phần tiêu đen xay còn lại vào đảo đều một lượt. Múc cơm chiên dứa hải sản vào lòng quả dứa hoặc ra đĩa lớn, rắc hạt điều rang chín giã dập lên trên và thưởng thức nóng.', NULL, NULL),
('imp-a48b19224e397cea_v4_step_1', 'imp-a48b19224e397cea', 1, 'prep', 'Sơ chế thịt bò thái mỏng, hành tây và gừng', 'Thái 250 g thịt bò thành lát thật mỏng dày khoảng 1,5 mm rồi cắt đoạn dài 4–5 cm; thái múi mỏng 1 củ hành tây theo chiều dọc; mài nhuyễn 8 g gừng tươi và thái khoanh mỏng 1/2 bó hành lá. Giữ ấm sẵn 360 g cơm gạo Nhật nấu chín.', 'Nếu tự thái thịt bò tại nhà, đặt khối thịt vào ngăn đá 30 phút cho hơi se cứng lại sẽ giúp cắt được những lát thịt mỏng đều dễ dàng.', NULL),
('imp-a48b19224e397cea_v4_step_2', 'imp-a48b19224e397cea', 2, 'cook', 'Luộc nhanh trứng lòng đào ăn kèm (tùy chọn)', 'Nếu dùng trứng ăn kèm, đun sôi nhẹ nồi nước nhỏ, nhẹ nhàng thả 2 quả trứng gà lạnh vào luộc đúng 6 phút trên lửa vừa, sau đó vớt ngay sang bát nước đá ngâm 5 phút cho nguội hẳn rồi bóc sạch vỏ.', NULL, 6),
('imp-a48b19224e397cea_v4_step_3', 'imp-a48b19224e397cea', 3, 'sauce', 'Đun sôi nước sốt và nấu mềm ngọt hành tây', 'Cho 120 ml nước dùng Dashi, 45 ml rượu Sake nấu ăn, 35 ml nước tương Nhật, 15 ml rượu ngọt Mirin và 12 g đường cát trắng vào chảo sâu lòng trên lửa vừa, khuấy tan đường. Khi nước sốt sôi nhẹ, thả toàn bộ hành tây vào nấu khoảng 5 phút cho đến khi hành mềm trong và ngấm vị.', 'Nấu mềm hành tây trước giúp hành tiết trọn vị ngọt vào nước dùng mà không cần đun thịt bò quá lâu.', 5),
('imp-a48b19224e397cea_v4_step_4', 'imp-a48b19224e397cea', 4, 'cook', 'Om nhanh thịt bò thái mỏng đến vừa chín tới', 'Dàn đều các lát thịt bò vào chảo nước sốt đang sôi lăn tăn trên lửa vừa, dùng đũa tách tơi các lát thịt để chín đều. Nấu khoảng 3–4 phút, thường xuyên hớt sạch bọt nổi lên mặt nước để nước sốt trong đẹp và thịt vừa chín tới không còn màu đỏ tái.', 'Thịt bò thái mỏng rất nhanh chín; tránh đun quá 5 phút khiến thịt bị co cứng, dai và mất nước ngọt.', 4),
('imp-a48b19224e397cea_v4_step_5', 'imp-a48b19224e397cea', 5, 'cook', 'Thêm gừng mài nhuyễn dậy hương thơm', 'Cho 8 g gừng tươi mài nhuyễn vào chảo thịt bò, đảo nhẹ cho hòa quyện vào nước sốt và nấu thêm 1 phút trên lửa nhỏ để gừng tỏa hương thơm dịu mà không bị nồng gắt rồi tắt bếp.', NULL, 1),
('imp-a48b19224e397cea_v4_step_6', 'imp-a48b19224e397cea', 6, 'finish', 'Bày tô cơm Gyudon nóng và thưởng thức', 'Xới 360 g cơm gạo Nhật vào hai tô sâu lòng, gắp thịt bò cùng hành tây xếp phủ đều lên cơm, chan thêm vài muỗng nước sốt om cho thấm vị. Rắc hành lá thái khoanh lên trên và đặt thêm nửa quả trứng lòng đào nếu thích, dọn ăn ngay khi còn nóng.', NULL, NULL),
('imp-79819e1b0c75f4da_v4_step_1', 'imp-79819e1b0c75f4da', 1, 'prep', 'Sơ chế rau củ, thịt ba chỉ và pha hỗn hợp sốt', 'Thái lát mỏng 160 g thịt ba chỉ heo cắt đoạn 3 cm; cắt 1/4 bắp cải xanh thành miếng vuông 2,5 cm; thái múi 1/2 củ hành tây; thái sợi 1/2 củ cà rốt; thái lát 40 g nấm hương tươi và cắt khúc 1 bó hành lá. Khuấy đều 30 ml nước tương Nhật, 15 ml rượu Sake nấu ăn và 10 ml rượu ngọt Mirin trong bát nhỏ.', NULL, NULL),
('imp-79819e1b0c75f4da_v4_step_2', 'imp-79819e1b0c75f4da', 2, 'prep', 'Chần nhanh sợi mì Udon cho tơi mềm', 'Đun sôi nồi nước trên lửa lớn, thả 2 gói mì Udon tươi vào chần nhanh khoảng 40 giây đến 1 phút vừa đủ để các sợi mì tách tơi ra, lập tức vớt ra rổ để thật ráo nước.', 'Mì udon tươi đã chín sẵn nên chỉ cần chần thoáng dưới 1 phút; chần quá lâu sợi mì sẽ bị bở và đứt gãy khi xào.', 1),
('imp-79819e1b0c75f4da_v4_step_3', 'imp-79819e1b0c75f4da', 3, 'cook', 'Xào thịt ba chỉ vàng xém cạnh', 'Làm nóng chảo sâu lòng trên lửa vừa với 15 ml dầu ăn thực vật. Cho thịt ba chỉ vào xào, rắc 1 g muối ăn và 1 g tiêu đen xay, đảo đều khoảng 4 phút đến khi thịt ra bớt mỡ, xém vàng nhẹ các mép và chín kỹ hoàn toàn.', 'Xào cho thịt ba chỉ hơi xém vàng giúp mỡ thừa tiết ra làm nền xào rau củ thơm béo đậm đà.', 4),
('imp-79819e1b0c75f4da_v4_step_4', 'imp-79819e1b0c75f4da', 4, 'cook', 'Xào và om chín mềm bắp cải cùng rau củ', 'Cho hành tây vào chảo đảo 1 phút cho dậy mùi, tiếp tục thả bắp cải xanh, cà rốt, nấm hương tươi và phần đầu hành lá vào đảo đều tay cho thấm mỡ thịt. Đậy nắp chảo và hạ lửa vừa nhỏ hấp nhẹ trong 3 phút để rau củ chín mềm mà vẫn giữ được độ giòn ngọt.', NULL, 3),
('imp-79819e1b0c75f4da_v4_step_5', 'imp-79819e1b0c75f4da', 5, 'cook', 'Xào mì Udon trên lửa lớn và rưới sốt áp thành chảo', 'Mở nắp, tăng lên lửa vừa lớn, trút mì Udon đã chần vào chảo và dùng kẹp gắp nâng đảo đều tay trong 2 phút. Rưới hỗn hợp nước sốt nước tương Nhật men theo thành chảo nóng, đảo thêm 2 phút cùng phần lá hành xanh đến khi sốt rút quyện bóng đều từng sợi mì rồi tắt bếp.', 'Dùng kẹp gắp thay vì đũa và rót nước tương dọc thành chảo nóng giúp sợi udon không bị đứt vụn mà lại dậy mùi thơm khói nhẹ đặc trưng.', 4),
('imp-79819e1b0c75f4da_v4_step_6', 'imp-79819e1b0c75f4da', 6, 'finish', 'Bày đĩa mì và rắc cá bào Katsuobushi', 'Gắp mì Yaki Udon nóng hổi chia đều ra hai đĩa, rắc thêm cá bào khô Katsuobushi lên trên để tăng độ đậm đà và dùng nóng ngay.', NULL, NULL),
('imp-ac255bcc36d1324e_v4_step_1', 'imp-ac255bcc36d1324e', 1, 'sauce', 'Pha hỗn hợp sốt Teriyaki hương gừng tỏi', 'Trong bát chịu nhiệt, cho 60 ml nước tương Nhật, 30 ml rượu Sake nấu ăn (một nửa lượng chuẩn bị), 30 ml rượu ngọt Mirin, 24 g đường cát trắng cùng 10 g gừng tươi băm và 1/2 củ tỏi băm nhuyễn. Khuấy đều cho đường tan hoàn toàn hoặc làm ấm nhẹ 30 giây để gia vị hòa quyện.', NULL, NULL),
('imp-ac255bcc36d1324e_v4_step_2', 'imp-ac255bcc36d1324e', 2, 'prep', 'Thấm khô, ướp muối tiêu và áo bột mì cho cá hồi', 'Dùng khăn giấy thấm thật khô bề mặt 600 g phi lê cá hồi còn da, rắc đều 2 g muối ăn và 1 g tiêu đen xay lên cả hai mặt. Tiếp theo rắc đều 16 g bột mì đa dụng phủ mỏng hai mặt cá, vỗ nhẹ cho bột bám sát rồi giũ bỏ phần bột thừa.', 'Lớp bột mì mỏng đóng vai trò khóa nước ngọt trong thịt cá hồi, đồng thời giúp sốt Teriyaki tự sánh quyện mà không cần pha thêm bột năng.', NULL),
('imp-ac255bcc36d1324e_v4_step_3', 'imp-ac255bcc36d1324e', 3, 'cook', 'Áp chảo mặt da cá hồi vàng giòn với dầu và bơ', 'Làm nóng chảo chống dính lớn trên lửa vừa với 15 ml dầu ăn trung tính và 25 g bơ lạt. Khi bơ vừa tan sủi bọt, đặt từng miếng cá hồi mặt da úp xuống chảo, dùng xẻng ép nhẹ 15 giây cho mặt da áp sát đáy chảo rồi chiên khoảng 3 phút đến khi da cá vàng giòn và phần thịt chín dần lên quá nửa thân cá thì lật mặt.', NULL, 3),
('imp-ac255bcc36d1324e_v4_step_4', 'imp-ac255bcc36d1324e', 4, 'cook', 'Rưới rượu Sake hấp chín mềm lõi cá hồi', 'Rưới 30 ml rượu Sake nấu ăn còn lại vào chảo, đậy kín vung và hạ xuống lửa nhỏ hấp thêm 3–4 phút cho đến khi thịt cá hồi chuyển màu hồng nhạt đục đều và chín tới mềm ẩm. Nhẹ nhàng gắp cá ra đĩa riêng và lau sạch phần mỡ cháy thừa trong chảo.', 'Không đậy vung hấp quá lâu khiến cá hồi bị khô xác; thịt cá vừa chuyển đục và tách thớ nhẹ khi ấn là đạt.', 4),
('imp-ac255bcc36d1324e_v4_step_5', 'imp-ac255bcc36d1324e', 5, 'cook', 'Cô sánh sốt Teriyaki và áo bóng lên cá hồi', 'Đổ toàn bộ bát sốt Teriyaki vào chảo nóng trên lửa vừa, khi sốt bắt đầu sôi sủi bọt đều thì đặt cá hồi trở lại chảo. Nghiêng chảo và liên tục múc sốt rưới lên từng miếng cá khoảng 2 phút cho đến khi sốt cô sánh lại thành lớp men nâu bóng bám đẹp quanh miếng cá rồi tắt bếp.', 'Tắt bếp ngay khi sốt vừa sánh nhẹ vì khi nguội bớt sốt Teriyaki sẽ tiếp tục cô đặc và bám bóng đẹp hơn.', 2),
('imp-ac255bcc36d1324e_v4_step_6', 'imp-ac255bcc36d1324e', 6, 'finish', 'Trình bày cá hồi sốt Teriyaki và dùng nóng', 'Xếp các miếng cá hồi ra đĩa lớn với mặt da giòn quay lên trên, rưới nốt phần sốt Teriyaki sánh bóng trong chảo lên mặt cá, rắc hành lá thái nhỏ và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-bb07db73fb381724_v4_step_1', 'imp-bb07db73fb381724', 1, 'prep', 'Làm lạnh sâu và thấm nhẹ nước cho đậu phụ non', 'Giữ 350 g đậu phụ non trong ngăn mát tủ lạnh đến sát giờ chế biến. Nhẹ nhàng lấy khối đậu ra khỏi hộp, gói lỏng trong hai lớp khăn giấy sạch đặt lên đĩa khoảng 5 phút để thấm bớt phần nước đọng bề mặt mà không làm nát đậu.', 'Tuyệt đối không dùng vật nặng ép đậu phụ non vì sẽ làm vỡ cấu trúc mềm mịn đặc trưng của món Hiyayakko.', 5),
('imp-bb07db73fb381724_v4_step_2', 'imp-bb07db73fb381724', 2, 'prep', 'Mài nhuyễn gừng tươi và chuẩn bị rau gia vị', 'Gọt sạch vỏ 15 g gừng tươi, dùng bàn mài nhuyễn mịn và giữ lại cả phần nước gừng tiết ra. Rửa sạch 1/2 bó hành lá tươi, vẩy ráo nước rồi thái khoanh thật mỏng; nếu dùng rong biển khô Nori thì cắt thành sợi nhỏ.', NULL, NULL),
('imp-bb07db73fb381724_v4_step_3', 'imp-bb07db73fb381724', 3, 'sauce', 'Pha hỗn hợp nước tương dầu mè', 'Trong chén nhỏ, khuấy đều 20 ml nước tương Nhật cùng 5 ml dầu mè rang đến khi hòa quyện hoàn toàn, giữ sẵn để rưới trực tiếp trước lúc ăn.', NULL, NULL),
('imp-bb07db73fb381724_v4_step_4', 'imp-bb07db73fb381724', 4, 'prep', 'Cắt khối đậu phụ và xếp ra đĩa sâu lòng', 'Gỡ bỏ khăn giấy, nhúng lưỡi dao mỏng qua nước lọc cho trơn rồi cắt khối đậu phụ non thành 6 hoặc 8 miếng vuông vừa ăn. Dùng xẻng rộng bản nhẹ tay nhấc từng khối đậu xếp vào hai đĩa sâu lòng hoặc bát nhỏ.', 'Nhúng ướt dao trước khi cắt giúp lát cắt đậu phụ sắc nét, bóng mịn và không dính mặt dao.', NULL),
('imp-bb07db73fb381724_v4_step_5', 'imp-bb07db73fb381724', 5, 'finish', 'Phủ gia vị lên mặt đậu và ướp lạnh nhẹ', 'Nghiêng nhẹ đĩa đổ bỏ phần nước vừa tiết thêm từ đậu phụ trong 2 phút chờ. Lần lượt đặt gừng tươi mài nhuyễn, hành lá thái mỏng lên chính giữa từng miếng đậu, rắc cá bào khô Katsuobushi, hạt mè trắng rang và rong biển khô Nori lên trên.', NULL, 2),
('imp-bb07db73fb381724_v4_step_6', 'imp-bb07db73fb381724', 6, 'finish', 'Rưới sốt nước tương ngay tại bàn và thưởng thức', 'Rưới đều hỗn hợp nước tương Nhật và dầu mè rang quanh các miếng đậu phụ ngay trước khi ăn để giữ đậu luôn mát lạnh, không bị ngấm mặn quá sớm.', 'Nghiêng nhẹ đĩa chắt bỏ nước đậu thừa một lần nữa ngay trước lúc rưới sốt giúp hương vị đậm đà không bị loãng.', NULL),
('imp-a9398d96945ba6f7_v4_step_1', 'imp-a9398d96945ba6f7', 1, 'prep', 'Sơ chế kim chi, thịt ba chỉ và rau nấm', 'Cắt 450 g kim chi cải thảo ủ chua thành khúc dài 3–4 cm, giữ lại phần nước kim chi. Thái thịt ba chỉ heo thành miếng dày 0,5 cm rồi ướp nhẹ với 15 ml rượu ngọt Mirin và 1 g tiêu đen xay trong 10 phút. Thái lát hành tây, nấm đùi gà tươi, đậu phụ trắng mềm và cắt khúc hành lá tươi.', NULL, 10),
('imp-a9398d96945ba6f7_v4_step_2', 'imp-a9398d96945ba6f7', 2, 'cook', 'Xào thịt ba chỉ và kim chi cho săn thơm', 'Làm nóng nồi đáy dày hoặc nồi đất trên lửa vừa với 5 ml dầu mè rang, cho thịt ba chỉ heo vào đảo 3 phút đến khi thịt săn chín mặt và tươm mỡ nhẹ. Thêm tỏi khô băm nhỏ, hành tây và kim chi cải thảo vào xào chung 4 phút cho kim chi mềm dịu và thấm mỡ thịt.', 'Xào kỹ kim chi trước khi đổ nước dùng giúp vị chua gắt dịu xuống và nước canh thơm sâu hơn.', NULL),
('imp-a9398d96945ba6f7_v4_step_3', 'imp-a9398d96945ba6f7', 3, 'cook', 'Nấu nước dùng và hòa gia vị cay đậm', 'Cho 6 g ớt bột Hàn Quốc (Gochugaru), 15 g tương ớt Hàn Quốc (Gochujang), 15 ml nước tương, 8 g đường cát trắng và phần nước kim chi vào nồi đảo nhanh 30 giây, sau đó rót 600 ml nước dùng cá cơm tảo bẹ vào đun sôi trên lửa lớn.', NULL, 5),
('imp-a9398d96945ba6f7_v4_step_4', 'imp-a9398d96945ba6f7', 4, 'cook', 'Hầm liu riu cho thịt mềm và thấm vị', 'Khi nồi canh sôi bùng, hớt bớt bọt nổi rồi hạ xuống lửa vừa-nhỏ, đậy hé nắp hầm khoảng 12 phút để thịt ba chỉ chín mềm hoàn toàn và vị ngọt của kim chi hòa quyện vào nước canh. Nêm thêm 3 g muối ăn và điều chỉnh lại theo khẩu vị.', NULL, 12),
('imp-a9398d96945ba6f7_v4_step_5', 'imp-a9398d96945ba6f7', 5, 'cook', 'Thả nấm đùi gà và đậu phụ trắng', 'Cho nấm đùi gà tươi và xếp nhẹ từng lát đậu phụ trắng mềm lên mặt nồi canh, nấu thêm 4 phút trên lửa vừa để nấm chín ngọt và đậu phụ nóng ấm mà không bị nát vụn.', 'Không khuấy mạnh tay sau khi đã thả đậu phụ để giữ nguyên dáng miếng đậu vuông đẹp mắt.', 4),
('imp-a9398d96945ba6f7_v4_step_6', 'imp-a9398d96945ba6f7', 6, 'finish', 'Rắc hành lá, rưới dầu mè và dọn nóng', 'Thả hành lá tươi cắt khúc vào nồi nấu thêm 30 giây, tắt bếp rồi rưới 5 ml dầu mè rang còn lại lên trên và dọn nóng ngay cùng cơm trắng.', 'Chỉ rưới phần dầu mè rang còn lại sau khi tắt bếp để giữ nguyên hương thơm nồng nàn đặc trưng.', NULL),
('imp-af8a9cdb17d5e9fd_v4_step_1', 'imp-af8a9cdb17d5e9fd', 1, 'prep', 'Sơ chế rau củ và thái mỏng thịt bò', 'Thái 420 g thịt bò thăn thành lát thật mỏng khoảng 2–3 mm theo chiều ngang thớ. Bóc vỏ hành tây thái múi cau mỏng, gọt vỏ cà rốt thái lát vát mỏng 0,3 cm, rửa sạch hành lá tươi và cắt khúc 4 cm.', 'Để miếng thịt bò vào ngăn đá khoảng 20 phút cho hơi cứng mặt sẽ giúp bạn thái lát cực mỏng và đều tay.', NULL),
('imp-af8a9cdb17d5e9fd_v4_step_2', 'imp-af8a9cdb17d5e9fd', 2, 'marinate', 'Ướp thịt bò với sốt Bulgogi', 'Trong tô lớn, trộn tan 36 ml nước tương, 22 g đường nâu, 15 ml rượu ngọt Mirin, 10 ml dầu mè rang, tỏi khô băm nhuyễn, gừng tươi băm nhuyễn và 1 g tiêu đen xay. Cho thịt bò thái lát cùng một nửa lượng hành tây vào bóp nhẹ cho thấm đều gia vị, bọc kín ướp tối thiểu 20 phút.', 'Ướp cùng một phần hành tây và gừng giúp enzyme tự nhiên làm thịt bò mềm ngọt hơn khi xào.', 20),
('imp-af8a9cdb17d5e9fd_v4_step_3', 'imp-af8a9cdb17d5e9fd', 3, 'cook', 'Xào sơ cà rốt và hành tây giữ độ giòn', 'Làm nóng chảo rộng trên lửa lớn với 7 ml dầu thực vật, cho cà rốt và phần hành tây còn lại vào đảo nhanh tay 2 phút đến khi cà rốt vừa chín tới và hành tây thơm ngọt rồi trút tạm ra đĩa.', NULL, 2),
('imp-af8a9cdb17d5e9fd_v4_step_4', 'imp-af8a9cdb17d5e9fd', 4, 'cook', 'Áp chảo thịt bò Bulgogi trên lửa lớn', 'Thêm 8 ml dầu thực vật còn lại vào chảo đang nóng già, trải đều thịt bò đã ướp lên mặt chảo trên lửa lớn để thịt xém cạnh nhanh mà không bị tiết nhiều nước. Đảo đều tay khoảng 3–4 phút cho đến khi thịt chín đều chuyển màu nâu bóng hấp dẫn.', 'Không cho quá nhiều thịt cùng lúc nếu chảo nhỏ; có thể chia làm 2 mẻ xào để thịt giữ được độ săn và mùi thơm áp chảo.', 4),
('imp-af8a9cdb17d5e9fd_v4_step_5', 'imp-af8a9cdb17d5e9fd', 5, 'cook', 'Đảo chung rau củ và hành lá', 'Trút đĩa cà rốt, hành tây đã xào sơ cùng hành lá tươi cắt khúc vào chảo thịt bò, đảo nhanh tay thêm 1 phút trên lửa lớn cho toàn bộ nguyên liệu quyện đều phần nước sốt Bulgogi sánh nhẹ dưới đáy chảo.', NULL, NULL),
('imp-af8a9cdb17d5e9fd_v4_step_6', 'imp-af8a9cdb17d5e9fd', 6, 'finish', 'Hoàn thiện với dầu mè và hạt mè rang', 'Tắt bếp, rưới 5 ml dầu mè rang còn lại và rắc 8 g hạt mè trắng rang lên khắp mặt chảo, đảo nhẹ một lượt rồi trút ra đĩa thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-d3d0c59e0cfa845d_v4_step_1', 'imp-d3d0c59e0cfa845d', 1, 'prep', 'Thái kim chi và pha nước chấm xì dầu giấm', 'Vắt nhẹ 180 g kim chi cải thảo chín lấy khoảng 45 ml nước kim chi để riêng, phần cái thái nhỏ cỡ 1 cm. Thái mỏng hành tây và cắt khúc 3 cm hành lá tươi. Trong chén nhỏ, khuấy tan 20 ml nước tương, 10 ml giấm gạo, 3 g đường cát trắng và 3 g hạt mè trắng rang làm nước chấm.', 'Dùng kim chi đã ủ chua kỹ sẽ cho hương vị đậm đà và độ giòn sần sật hấp dẫn nhất khi chiên.', NULL),
('imp-d3d0c59e0cfa845d_v4_step_2', 'imp-d3d0c59e0cfa845d', 2, 'sauce', 'Trộn bột bánh với nước lạnh và kim chi', 'Trộn đều 140 g bột mì đa dụng, 20 g bột bắp và 3 g ớt bột Hàn Quốc (Gochugaru) trong tô lớn. Rót từ từ 220 ml nước lọc lạnh cùng 45 ml nước kim chi vào, đánh nhẹ vừa đủ tan hết bột khô rồi cho 1 quả trứng gà tươi, kim chi thái nhỏ, hành tây và hành lá vào trộn đều thành hỗn hợp bột hơi sánh.', 'Dùng nước lọc thật lạnh và không khuấy bột quá kỹ giúp bánh chiên lên giòn xốp, không bị dai.', NULL),
('imp-d3d0c59e0cfa845d_v4_step_3', 'imp-d3d0c59e0cfa845d', 3, 'cook', 'Chiên bánh mẻ thứ nhất đến khi giòn cạnh', 'Làm nóng chảo chống dính đường kính 22–24 cm trên lửa vừa-lớn với 22 ml dầu thực vật, múc một nửa lượng bột dàn thành lớp mỏng đều khắp mặt chảo. Chiên khoảng 4 phút đến khi phần viền vàng giòn rụm và mặt bột bên trên se lại.', NULL, 4),
('imp-d3d0c59e0cfa845d_v4_step_4', 'imp-d3d0c59e0cfa845d', 4, 'cook', 'Lật mặt và chiên vàng giòn hoàn toàn', 'Lật khéo chiếc bánh lại, ấn nhẹ bằng xẻng chiên cho bánh áp sát mặt chảo và chiên tiếp 3 phút trên lửa vừa đến khi cả hai mặt vàng ruộm, dậy mùi thơm lừng rồi gắp ra đĩa lót giấy thấm dầu.', 'Ấn nhẹ mặt bánh sau khi lật giúp hơi nước thoát nhanh, mặt bánh phẳng và giòn đều từ tâm ra viền.', 3),
('imp-d3d0c59e0cfa845d_v4_step_5', 'imp-d3d0c59e0cfa845d', 5, 'cook', 'Chiên nốt mẻ bánh kim chi thứ hai', 'Cho 23 ml dầu thực vật còn lại vào chảo, trút hết phần bột kim chi còn lại dàn mỏng đều và lặp lại quy trình chiên mỗi mặt 3–4 phút cho đến khi bánh chín vàng giòn đều hai mặt.', NULL, 7),
('imp-d3d0c59e0cfa845d_v4_step_6', 'imp-d3d0c59e0cfa845d', 6, 'finish', 'Cắt miếng tam giác và thưởng thức nóng', 'Đặt bánh kim chi chiên giòn lên thớt sạch, cắt thành từng miếng tam giác hoặc ô vuông vừa ăn, xếp ra đĩa và dọn nóng kèm chén nước chấm xì dầu giấm gạo mè rang.', NULL, NULL),
('imp-262caf09e6f38c59_v4_step_1', 'imp-262caf09e6f38c59', 1, 'prep', 'Sơ chế bông cải xanh và hương liệu', 'Tách 1,5 bông cải xanh thành các nhánh hoa cỡ vừa đồng đều để khi nấu chín cùng lúc; gọt bỏ lớp xơ cứng ở phần thân cọng rồi rửa sạch và để ráo. Tỏi khô băm nhỏ, gừng tươi băm thật nhuyễn.', 'Cắt các nhánh bông cải có kích thước tương đương nhau giúp rau chín đều, không bị chỗ sượng chỗ mềm nhũn.', NULL),
('imp-262caf09e6f38c59_v4_step_2', 'imp-262caf09e6f38c59', 2, 'sauce', 'Pha chén sốt xì dầu bột bắp', 'Cho vào chén nhỏ 30 ml nước lọc, 22 ml xì dầu nhạt, 3 ml xì dầu đặc, 4 g đường cát trắng, 4 g bột bắp và 1 g muối ăn (tùy khẩu vị). Khuấy đều tay đến khi đường và bột bắp tan hoàn toàn, để sẵn cạnh bếp.', 'Luôn khuấy lại chén sốt ngay trước khi rót vào chảo vì bột bắp rất nhanh lắng xuống đáy.', NULL),
('imp-262caf09e6f38c59_v4_step_3', 'imp-262caf09e6f38c59', 3, 'cook', 'Chần bông cải xanh giữ màu giòn mướt', 'Đun sôi mạnh 1000 ml nước lọc với 2 g muối ăn và 5 ml dầu ăn thực vật trong nồi lớn. Thả toàn bộ bông cải xanh vào chần đúng 1 phút trên lửa lớn cho rau vừa chuyển màu xanh ngọc rực rỡ, lập tức vớt ra rổ thưa xóc thật ráo nước.', 'Một chút dầu ăn và muối trong nước sôi giúp khóa màu xanh mướt cho bông cải và rút ngắn tối đa thời gian xào trên chảo.', 1),
('imp-262caf09e6f38c59_v4_step_4', 'imp-262caf09e6f38c59', 4, 'cook', 'Phi thơm tỏi gừng trên chảo nóng', 'Đặt chảo sâu lòng lên lửa vừa lớn, làm nóng 20 ml dầu ăn thực vật còn lại. Cho gừng băm và tỏi băm vào đảo nhanh khoảng 30 giây đến khi dậy mùi thơm dịu và tỏi vừa chuyển vàng nhẹ, tuyệt đối không để tỏi cháy sậm.', NULL, NULL),
('imp-262caf09e6f38c59_v4_step_5', 'imp-262caf09e6f38c59', 5, 'cook', 'Xào bông cải với sốt lửa lớn', 'Trút bông cải xanh đã ráo nước vào chảo, tăng lửa lớn và đảo nhanh tay trong 1 phút. Khuấy đều chén sốt đã pha rồi rót vòng quanh chảo, tiếp tục xóc đảo liên tục thêm 1 phút cho đến khi sốt sôi sệt, trong bóng và bám đều quanh từng nhánh bông cải.', NULL, 2),
('imp-262caf09e6f38c59_v4_step_6', 'imp-262caf09e6f38c59', 6, 'finish', 'Rưới dầu mè và hoàn thiện', 'Tắt bếp ngay khi sốt vừa áo bóng, rưới 5 ml dầu mè thơm lên trên rồi đảo đều một lượt cuối cùng. Gắp bông cải ra đĩa và dùng nóng ngay để cảm nhận trọn vẹn độ giòn ngọt.', NULL, NULL),
('imp-352999f711c710d9_v4_step_1', 'imp-352999f711c710d9', 1, 'prep', 'Sơ chế hương liệu và thái thịt đùi gà', 'Thấm khô 500 g thịt đùi gà lọc xương rồi thái miếng vuông đều 2,5 cm. Gọt vỏ 45 g gừng tươi già: bào nhuyễn 5 g để ướp thịt, 40 g còn lại thái lát mỏng. Hành lá tươi cắt khúc 5 cm tách riêng đầu hành trắng đập dập và phần lá xanh; đập dập 4 tép tỏi khô và 2 củ hành tím khô; thái lát vát 1 quả ớt sừng đỏ (nếu dùng).', NULL, NULL),
('imp-352999f711c710d9_v4_step_2', 'imp-352999f711c710d9', 2, 'marinate', 'Ướp thịt gà giữ ẩm với bột bắp', 'Cho thịt đùi gà vào tô cùng 15 ml rượu Thiệu Hưng, 10 ml xì dầu nhạt, 1,5 g muối ăn và 5 g gừng bào nhuyễn, bóp trộn đều đến khi thịt thấm hết phần nước gia vị rồi mới cho 12 g bột bắp vào trộn áo đều từng miếng. Ướp thịt trong 15 phút.', 'Trộn cho thịt ngậm hết nước gia vị trước rồi mới áo bột bắp giúp miếng gà khi áp chảo mềm mọng bên trong mà bề mặt vẫn xém đẹp.', 15),
('imp-352999f711c710d9_v4_step_3', 'imp-352999f711c710d9', 3, 'sauce', 'Pha chén sốt xì dầu dầu hào', 'Khuấy đều trong chén nhỏ 60 ml nước dùng gà, 20 ml xì dầu nhạt còn lại, 5 ml xì dầu đặc, 15 ml dầu hào, 4 g đường cát trắng, 4 g bột bắp còn lại và 1 g tiêu trắng xay đến khi tan mịn hoàn toàn.', 'Khuấy lại chén sốt ngay trước khi đổ vào chảo để bột bắp không bị lắng xuống đáy chén.', NULL),
('imp-352999f711c710d9_v4_step_4', 'imp-352999f711c710d9', 4, 'cook', 'Phi thơm gừng, tỏi và hành tím', 'Đun nóng chảo sâu lòng trên lửa vừa lớn đến khi hơi bốc khói, rót 20 ml dầu ăn thực vật tráng đều. Cho gừng thái lát vào đảo khoảng 1 phút đến khi cạnh gừng hơi xém vàng thơm nồng, tiếp tục cho tỏi khô, hành tím khô và đầu hành trắng đập dập vào đảo nhanh 20 giây.', NULL, 1),
('imp-352999f711c710d9_v4_step_5', 'imp-352999f711c710d9', 5, 'cook', 'Áp chảo gà chín xém hai mặt', 'Dàn đều thịt gà đã ướp thành một lớp mỏng trong chảo, giữ nguyên không đảo trong 2 phút để mặt dưới vàng xém đẹp rồi lật mặt áp tiếp 1–2 phút nữa đến khi thịt gà săn chắc hoàn toàn và không còn màu hồng bên trong. Rưới 25 ml rượu Thiệu Hưng còn lại quanh mép chảo, đảo nhanh tay cho hơi rượu bốc lên làm bong lớp cháy thơm đáy chảo.', 'Không xếp chồng miếng gà lên nhau khi áp chảo vì hơi nước sẽ làm thịt bị hấp mềm thay vì xém vàng thơm.', 4),
('imp-352999f711c710d9_v4_step_6', 'imp-352999f711c710d9', 6, 'finish', 'Quyện sốt sánh, thêm hành lá và hoàn thiện', 'Thả phần lá hành xanh và ớt sừng thái lát vào đảo 30 giây cho hành vừa mềm vẫn giữ sắc xanh. Khuấy lại chén sốt rồi rót đều vào chảo, đảo liên tục 30–45 giây trên lửa lớn đến khi sốt sánh bóng bám đều từng miếng gà. Tắt bếp, rưới 5 ml dầu mè thơm, đảo một lượt cuối và dọn nóng ăn kèm cơm trắng.', NULL, NULL),
('imp-b3f99919ea9f17f8_v4_step_1', 'imp-b3f99919ea9f17f8', 1, 'prep', 'Sơ chế bí đao và rau thơm', 'Gọt sạch vỏ xanh của bí đao tươi, nạo bỏ phần ruột xốp và hạt, rửa sạch rồi cắt thành từng miếng con chì dày khoảng 0,6 cm đều nhau để bí chín tới cùng lúc. Gừng tươi băm nhuyễn; hành lá tươi tách phần băm trộn thịt, phần đầu hành trắng để phi và lá xanh thái nhỏ; ngò rí tươi cắt khúc ngắn.', NULL, NULL),
('imp-b3f99919ea9f17f8_v4_step_2', 'imp-b3f99919ea9f17f8', 2, 'marinate', 'Ướp và quết thịt heo viên dai giòn', 'Cho 300 g thịt heo xay vào tô lớn cùng 25 ml xì dầu nhạt, 20 ml rượu Thiệu Hưng, 3 ml dầu mè thơm, 2/3 lượng tiêu trắng xay, 2 g đường cát trắng, 1,5 g muối ăn, lòng trắng của 1 quả trứng gà, 10 g gừng băm, 1/2 phần hành lá băm và 20 ml nước lọc. Dùng đũa quết mạnh tay theo đúng một chiều trong 8–10 phút đến khi thịt dẻo quánh, bám dính thành khối.', 'Quết thịt theo một chiều và thêm chút nước lọc giúp sợi thịt ngậm nước và liên kết đàn hồi, cho viên thịt mềm mọng mà vẫn giòn dai.', 8),
('imp-b3f99919ea9f17f8_v4_step_3', 'imp-b3f99919ea9f17f8', 3, 'prep', 'Vo viên thịt gọn đẹp', 'Thoa một lớp dầu mỏng vào lòng bàn tay hoặc dùng muỗng nhúng dầu, chia hỗn hợp thịt thành 12–16 viên tròn đường kính khoảng 2,5–3 cm rồi xếp lên đĩa phẳng, giữ mát trong khi nấu nước dùng để viên thịt giữ dáng chắc đẹp.', NULL, NULL),
('imp-b3f99919ea9f17f8_v4_step_4', 'imp-b3f99919ea9f17f8', 4, 'cook', 'Phi thơm đầu hành và nấu mềm bí đao', 'Làm nóng 10 ml dầu ăn thực vật trong nồi canh trên lửa vừa, thả phần đầu hành trắng vào xào thơm 1 phút cho dậy mùi. Đổ 650 ml nước dùng gà và 350 ml nước lọc vào nồi, thả bí đao vào đun sôi rồi hạ lửa vừa, nấu liu riu 8–10 phút đến khi miếng bí đao bắt đầu chuyển trong.', NULL, 9),
('imp-b3f99919ea9f17f8_v4_step_5', 'imp-b3f99919ea9f17f8', 5, 'cook', 'Thả thịt viên và nấu chín tới', 'Khi nước canh đang sôi nhẹ, nhẹ nhàng thả từng viên thịt vào nồi để viên thịt se mặt ngay và không bị vỡ nát. Hớt sạch bọt nổi trên mặt nước, đun liu riu thêm 4 phút đến khi toàn bộ thịt viên nổi hẳn lên mặt nước và chín chắc hoàn toàn bên trong, bí đao vừa trong mướt mà không bị nát bở.', 'Giữ lửa ở mức sôi lăn tăn sau khi thả viên giúp nước canh trong veo và viên thịt chín đều từ ngoài vào trong.', 4),
('imp-b3f99919ea9f17f8_v4_step_6', 'imp-b3f99919ea9f17f8', 6, 'finish', 'Nêm gia vị và hoàn thiện tô canh', 'Nêm vào nồi canh 3,5 g muối ăn còn lại (điều chỉnh theo độ mặn nước dùng), 1/3 lượng tiêu trắng xay còn lại và 2 ml dầu mè thơm, khuấy nhẹ rồi tắt bếp. Múc canh ra tô lớn, rắc lá hành xanh và ngò rí tươi lên mặt, dùng nóng ngay.', 'Rưới dầu mè thơm và tiêu trắng sau khi tắt bếp giúp giữ trọn hương thơm dịu mà không bị đắng.', NULL),
('imp-b6dae711698259d6_v4_step_1', 'imp-b6dae711698259d6', 1, 'prep', 'Sơ chế tôm sú và nhóm thảo mộc Thái', 'Rửa sạch 450 g tôm sú, tách riêng phần đầu và vỏ tôm để nấu nước dùng; phần thịt tôm chẻ dọc sống lưng rút sạch chỉ đen rồi để ráo trong ngăn mát. Đập dập 3 cây sả cắt khúc 4–5 cm, thái lát mỏng 35 g củ riềng tươi, xé bỏ gân 6 g lá chanh Thái, đập dập 3 quả ớt hiểm, bổ đôi 200 g nấm và cắt múi cau 2 quả cà chua.', 'Giữ lại đầu và vỏ tôm để xào gạch sẽ giúp nước dùng Tom Yum ngọt tự nhiên và có sắc cam óng mà không cần bột nêm.', NULL),
('imp-b6dae711698259d6_v4_step_2', 'imp-b6dae711698259d6', 2, 'cook', 'Phi vỏ đầu tôm và ninh nước dùng ngọt thanh', 'Làm nóng nồi trên lửa vừa lớn với 15 ml dầu ăn, trút toàn bộ đầu và vỏ tôm vào xào khoảng 3 phút, dùng muôi ấn nhẹ đầu tôm cho gạch tiết ra và vỏ chuyển đỏ au thơm lừng. Đổ 1200 ml nước lọc vào đun sôi rồi hạ lửa vừa, nấu liu riu 8 phút và hớt sạch bọt, sau đó vớt bỏ toàn bộ xác vỏ đầu tôm.', NULL, 8),
('imp-b6dae711698259d6_v4_step_3', 'imp-b6dae711698259d6', 3, 'cook', 'Hầm thảo mộc dậy hương thơm đặc trưng', 'Cho sả, riềng, lá chanh Thái và ớt hiểm đập dập vào nồi nước dùng tôm, đun sôi lăn tăn trên lửa nhỏ 5 phút để các loại thảo mộc tiết hết tinh dầu thơm nồng vào nước dùng.', 'Đun sôi nhẹ thay vì lửa quá lớn để giữ nước dùng trong thơm và thảo mộc không bị nồng gắt.', 5);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-b6dae711698259d6_v4_step_4', 'imp-b6dae711698259d6', 4, 'cook', 'Nấu nấm, cà chua và hòa sốt Tom Yum', 'Múc một vá nước dùng nóng ra chén hòa tan 45 g sốt Tom Yum rồi đổ ngược lại vào nồi, nêm thêm 40 ml nước mắm ngon và 6 g đường cát trắng. Thả 200 g nấm cùng 2 quả cà chua bổ múi cau vào nấu thêm 3 phút trên lửa vừa đến khi nấm chín mềm và cà chua vừa tiết vị chua dịu.', NULL, 3),
('imp-b6dae711698259d6_v4_step_5', 'imp-b6dae711698259d6', 5, 'cook', 'Nấu tôm chín hồng vừa tới giữ độ giòn ngọt', 'Tăng lửa cho nồi canh sôi đều trở lại, thả phần thịt tôm đã sơ chế vào nấu nhanh khoảng 2 phút đến khi tôm cuộn cong, vỏ đuôi đỏ au và thịt tôm chuyển đục săn chắc chín hoàn toàn thì tắt bếp ngay.', 'Nấu tôm vừa chín tới rồi tắt bếp ngay để thịt tôm giữ được độ giòn mọng tự nhiên, không bị khô xác.', 2),
('imp-b6dae711698259d6_v4_step_6', 'imp-b6dae711698259d6', 6, 'finish', 'Vắt chanh tươi, rắc ngò rí và hoàn thiện tô canh', 'Chờ nồi canh hết sôi hẳn mới rót nước cốt từ 2 quả chanh tươi vào khuấy nhẹ để giữ trọn hương thơm và không bị đắng. Nếm lại cho đạt vị chua thanh dẫn đầu, mặn cay hài hòa rồi múc ra tô, rắc 20 g ngò rí thái khúc lên trên và dọn nóng.', NULL, NULL),
('imp-f729957329cd75f5_v4_step_1', 'imp-f729957329cd75f5', 1, 'prep', 'Ngâm bánh phở và chuẩn bị nguyên liệu', 'Ngâm 240 g bánh phở khô trong nước nguội 45 phút đến khi sợi mềm dẻo nhưng vẫn còn độ dai nhẹ khi bẻ cong, vớt ra để thật ráo nước rồi cắt đôi cho dễ đảo. Ngâm 70 g me chín với 100 ml nước ấm rồi dằm lọc bỏ hạt lấy nước cốt. Băm nhỏ 15 g tôm khô, 50 g hành tím, 1/2 củ tỏi; cắt hạt lựu 1,5 miếng đậu phụ; cắt khúc 4 cm phần 80 g hẹ lá; giã thô 60 g đậu phộng rang và bổ múi cau 2 quả chanh tươi.', 'Ngâm bánh phở bằng nước nguội thay vì luộc nước sôi giúp sợi mì giữ độ dai bóng và không bị bết nát khi xào.', 45),
('imp-f729957329cd75f5_v4_step_2', 'imp-f729957329cd75f5', 2, 'sauce', 'Nấu sốt me đường thốt nốt chua ngọt', 'Cho 60 g đường thốt nốt băm nhỏ vào nồi nhỏ đun lửa vừa, khuấy liên tục đến khi đường tan chảy và hơi chuyển màu nâu caramen thơm dịu. Tắt bếp rồi rót nước cốt me đã lọc cùng 45 ml nước mắm ngon vào khuấy tan đều thành hỗn hợp sốt sánh mượt màu hổ phách.', 'Thắng nhẹ đường thốt nốt trước khi cho nước cốt me giúp sốt Pad Thai có mùi thơm sâu và màu hổ phách bóng đẹp.', 4),
('imp-f729957329cd75f5_v4_step_3', 'imp-f729957329cd75f5', 3, 'cook', 'Áp chảo tôm chín săn và giữ riêng', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, xếp 350 g tôm tươi vào áp chảo mỗi mặt khoảng 1 phút đến khi tôm chuyển màu hồng cam, cong săn và chín hoàn toàn bên trong thì gắp ra đĩa riêng, giữ lại dầu thơm trong chảo.', NULL, 2),
('imp-f729957329cd75f5_v4_step_4', 'imp-f729957329cd75f5', 4, 'cook', 'Xào vàng đậu phụ và hương liệu', 'Vẫn chiếc chảo đó trên lửa vừa, thêm 25 ml dầu ăn rồi cho đậu phụ cắt hạt lựu, hành tím băm, tỏi băm, tôm khô băm và 2 g ớt khô vảy vào đảo đều 3 phút đến khi đậu phụ vàng cạnh và dậy mùi thơm.', NULL, 3),
('imp-f729957329cd75f5_v4_step_5', 'imp-f729957329cd75f5', 5, 'cook', 'Xào bánh phở ngấm sốt và đánh tơi trứng', 'Tăng lửa lớn, trút bánh phở đã ráo và toàn bộ nước sốt me vào chảo, đảo liên tục 3 phút cho sợi mì hút trọn nước sốt và tơi bóng (nếu mì còn hơi cứng có thể rưới thêm 1–2 muỗng canh nước lọc). Gạt mì sang một bên chảo, thêm 10 ml dầu ăn còn lại vào khoảng trống, đập 3 quả trứng gà vào đánh vỡ lòng đỏ rồi phủ mì lên chờ 20 giây cho trứng se chín, sau đó đảo tơi quyện đều.', 'Pad Thai chuẩn phải ráo bóng, từng sợi mì áo đều sốt mà không đọng nước ở đáy chảo.', 3),
('imp-f729957329cd75f5_v4_step_6', 'imp-f729957329cd75f5', 6, 'finish', 'Trộn giá đỗ, hẹ và dọn Pad Thai nóng', 'Tắt bếp, trút tôm áp chảo trở lại chảo cùng 2/3 lượng giá đỗ (khoảng 130 g), phần lớn hẹ cắt khúc và một nửa lượng đậu phộng rang giã dập, đảo nhanh tay 20 giây để giá hẹ vừa chín tái giữ độ giòn tươi. Gắp mì ra đĩa, rắc phần đậu phộng còn lại lên trên và dọn kèm giá sống, hẹ tươi cùng múi chanh.', NULL, NULL),
('imp-04d0b94d17ce080c_v4_step_1', 'imp-04d0b94d17ce080c', 1, 'marinate', 'Thái lát và ướp mềm ức gà', 'Thái 380 g ức gà phi lê thành từng lát mỏng dày 0,5 cm để thịt chín nhanh mà không bị khô. Trộn đều thịt gà với 12 ml xì dầu trong tô sạch, ướp nghỉ 10 phút trong lúc sơ chế rau củ.', NULL, 10),
('imp-04d0b94d17ce080c_v4_step_2', 'imp-04d0b94d17ce080c', 2, 'prep', 'Sơ chế gừng sợi, nấm, hành tây và pha sốt', 'Cạo vỏ 80 g gừng tươi và thái sợi chỉ thật mảnh, thái lát 150 g nấm hương tươi, bổ múi cau mỏng 3/4 củ hành tây, băm nhỏ 1/2 củ tỏi, thái lát xéo 2 quả ớt sừng đỏ và cắt khúc 3–4 cm hành lá (để riêng đầu hành trắng và lá xanh). Pha sẵn chén sốt gồm 20 ml dầu hào, 13 ml xì dầu còn lại, 5 ml nước mắm, 5 g đường và 45 ml nước lọc.', 'Thái gừng thành sợi chỉ mỏng đều giúp gừng chín mềm thơm dịu và dễ ăn hòa quyện cùng thịt gà.', NULL),
('imp-04d0b94d17ce080c_v4_step_3', 'imp-04d0b94d17ce080c', 3, 'cook', 'Áp chảo xào săn thịt ức gà', 'Đun nóng chảo sâu lòng trên lửa lớn với 10 ml dầu ăn, cho toàn bộ ức gà đã ướp vào trải đều và xào nhanh tay khoảng 2 phút đến khi bề mặt gà săn trắng và chín khoảng 80% thì trút ngay ra đĩa riêng.', 'Xào gà riêng trước rồi lấy ra giúp thịt ức gà giữ độ mọng nước và không bị dai trong lúc xào rau.', 2),
('imp-04d0b94d17ce080c_v4_step_4', 'imp-04d0b94d17ce080c', 4, 'cook', 'Xào thơm gừng sợi, hành tây và nấm tươi', 'Dùng lại chảo đó trên lửa vừa lớn với 10 ml dầu ăn còn lại, cho tỏi băm, gừng thái sợi, hành tây và phần đầu hành trắng vào đảo đều 3 phút đến khi gừng dậy hương thơm nồng và hành tây hơi trong. Tiếp tục cho nấm hương thái lát vào xào thêm 2 phút đến khi nấm mềm săn.', NULL, 5),
('imp-04d0b94d17ce080c_v4_step_5', 'imp-04d0b94d17ce080c', 5, 'cook', 'Đảo gà với sốt dầu hào cho sánh quyện', 'Trút phần ức gà cùng nước tiết ra vào chảo, khuấy lại chén sốt đã pha rồi rưới đều vào. Đảo nhanh tay trên lửa lớn khoảng 2 phút đến khi thịt gà chín trắng hoàn toàn bên trong, nước sốt sôi sệt lại và bám bóng đều quanh từng lát gà, gừng và nấm.', 'Đảo nhanh trên lửa lớn ở bước cuối để nước sốt cô sánh bám vào gà mà nấm và hành tây không bị ra nước loãng.', 2),
('imp-04d0b94d17ce080c_v4_step_6', 'imp-04d0b94d17ce080c', 6, 'finish', 'Thêm hành lá, ớt sừng và hoàn thiện đĩa gà xào', 'Tắt bếp ngay rồi cho phần lá xanh của hành lá cùng ớt sừng đỏ thái lát vào đảo đều 10 giây cho hành vừa héo xanh mướt, nếm lại vừa miệng rồi trút ra đĩa thưởng thức nóng.', NULL, NULL),
('imp-b01569fd0df22f66_v4_step_1', 'imp-b01569fd0df22f66', 1, 'prep', 'Sơ chế tỏi lát, ớt tươi và ngò tây', 'Bóc vỏ 3 tép tỏi tươi, bổ dọc lấy bỏ phần lõi xanh ở giữa rồi thái thành những lát mỏng đều nhau để chín cùng lúc. Rửa sạch 1 quả ớt sừng đỏ tươi, bỏ hạt nếu ăn cay nhẹ rồi thái khoanh mỏng. Nhặt lá 6 g ngò tây tươi, rửa sạch, thấm khô và băm nhỏ.', 'Thái tỏi lát đều tay giúp tỏi vàng đồng loạt trong dầu mà không bị miếng cháy miếng sống.', NULL),
('imp-b01569fd0df22f66_v4_step_2', 'imp-b01569fd0df22f66', 2, 'cook', 'Đun nước muối và luộc mì Ý al dente', 'Đun sôi mạnh nồi với 2 lít nước lọc, cho 10 g muối hạt vào khuấy tan rồi thả 180 g mì Ý Spaghetti khô vào luộc khoảng 7–8 phút (bớt 2 phút so với hướng dẫn bao bì) để mì chín tiếp trong chảo sốt. Trước khi vớt, múc giữ lại 120 ml nước luộc mì.', NULL, 8),
('imp-b01569fd0df22f66_v4_step_3', 'imp-b01569fd0df22f66', 3, 'sauce', 'Phi thơm tỏi ớt trên lửa nhỏ với dầu ô liu', 'Đổ 35 ml dầu ô liu nguyên chất vào chảo lớn, đặt lên bếp lửa thật nhỏ. Khi dầu vừa ấm, cho tỏi thái lát và ớt sừng vào phi nhẹ nhàng 2–3 phút đến khi tỏi dậy mùi thơm và vừa chuyển màu vàng nhạt thì lập tức nhấc chảo khỏi bếp để giữ màu đẹp.', 'Chỉ cần tỏi hơi ngả vàng nhạt là đạt, tuyệt đối không để tỏi chuyển nâu vì sẽ gây vị đắng gắt.', 3),
('imp-b01569fd0df22f66_v4_step_4', 'imp-b01569fd0df22f66', 4, 'cook', 'Nhũ tương hóa dầu tỏi với nước luộc mì', 'Đặt chảo dầu tỏi ớt lại lên bếp ở lửa vừa, múc khoảng 60 ml nước luộc mì giàu tinh bột vào chảo và khuấy nhẹ cho hỗn hợp sủi lăn tăn, tạo thành lớp nền hơi sệt.', NULL, NULL),
('imp-b01569fd0df22f66_v4_step_5', 'imp-b01569fd0df22f66', 5, 'cook', 'Xóc mì Ý quyện sốt óng mượt', 'Gắp mì Ý Spaghetti từ nồi thả thẳng vào chảo, đảo và xóc đều tay liên tục khoảng 2 phút trên lửa vừa. Thêm từng chút nước luộc mì còn lại nếu cần cho đến khi tinh bột hòa với dầu ô liu thành lớp sốt bóng mượt ôm trọn sợi mì.', 'Xóc chảo liên tục giúp dầu ô liu và nước tinh bột tạo nhũ tương mượt thay vì tách dầu đọng ở đáy chảo.', 2),
('imp-b01569fd0df22f66_v4_step_6', 'imp-b01569fd0df22f66', 6, 'finish', 'Chỉnh muối, rắc ngò tây và dọn nóng', 'Nếm thử và rắc thêm chút muối hạt (khoảng 2 g nếu nhạt), tắt bếp rồi rắc ngò tây tươi băm nhỏ vào đảo nhẹ lần cuối. Chia mì ra 2 đĩa sâu lòng, rưới phần dầu tỏi ớt còn lại lên trên và thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-d463228be1e6e7c0_v4_step_1', 'imp-d463228be1e6e7c0', 1, 'prep', 'Giữ nóng nước dùng và sơ chế nấm rau củ', 'Đun 800 ml nước dùng rau củ trong nồi riêng ở lửa nhỏ cho luôn sôi lăn tăn. Lau sạch 300 g nấm đùi gà và nấm bào ngư bằng khăn ẩm (không ngâm nước), thái lát dày 0,5 cm. Băm nhỏ hành tây, tỏi tươi và ngò tây để riêng; cắt 23 g bơ lạt vào ngăn mát giữ lạnh.', 'Nước dùng phải luôn nóng để không làm hạt gạo bị sốc nhiệt và sượng lõi khi om.', NULL),
('imp-d463228be1e6e7c0_v4_step_2', 'imp-d463228be1e6e7c0', 2, 'cook', 'Áp chảo nấm vàng thơm với bơ và tỏi', 'Làm nóng chảo lớn trên lửa vừa-cao với 12 ml dầu ô liu nguyên chất và 22 g bơ lạt. Phi thơm tỏi băm 30 giây rồi trút nấm vào dàn đều một lớp, xào 5 phút đến khi nấm cạn nước và vàng xém nhẹ. Nêm 2 g muối ăn và 1 g tiêu đen xay, trút ra đĩa giữ ấm.', 'Dàn nấm thành một lớp mỏng và hạn chế đảo sớm giúp nấm xém vàng thơm thay vì ra nhiều nước.', 5),
('imp-d463228be1e6e7c0_v4_step_3', 'imp-d463228be1e6e7c0', 3, 'cook', 'Xào hành tây và rang hạt gạo Arborio', 'Bắc nồi đáy dày lên bếp ở lửa vừa, thêm 8 ml dầu ô liu còn lại vào xào hành tây băm khoảng 4 phút đến khi hành mềm trong suốt (không để vàng cháy). Đổ 240 g gạo Ý Arborio vào đảo đều 3 phút cho đến khi viền hạt gạo trở nên trong mờ.', NULL, 7),
('imp-d463228be1e6e7c0_v4_step_4', 'imp-d463228be1e6e7c0', 4, 'cook', 'Om gạo từng vá nước dùng nóng với nấm', 'Rót 60 ml rượu vang trắng khô vào nồi gạo (nếu dùng), đảo 2 phút cho bay hơi hết mùi cồn. Múc từng vá nước dùng rau củ nóng (~120 ml) vào ngập mặt gạo, khuấy đều tay; khi nước rút gần cạn mới thêm vá tiếp theo. Sau 8 phút, trút 2/3 lượng nấm xào vào om cùng đến phút thứ 18 khi hạt gạo mềm béo bên ngoài và hơi sật nhẹ ở lõi.', 'Thêm nước dùng nóng từng vá một và khuấy đều giúp tinh bột gạo tiết ra tự nhiên tạo độ sánh như kem.', 18),
('imp-d463228be1e6e7c0_v4_step_5', 'imp-d463228be1e6e7c0', 5, 'finish', 'Đánh bóng Risotto với bơ lạnh và phô mai', 'Khi cơm đạt độ sánh sóng sánh nhẹ, tắt bếp ngay. Cho 23 g bơ lạt lạnh cắt nhỏ cùng 40 g phô mai Parmesan bào mịn vào nồi, đánh nhanh và đều tay khoảng 2 phút đến khi cơm bóng mượt và quyện kem mịn.', 'Tắt bếp rồi mới cho bơ lạnh và phô mai vào đánh giúp tạo nhũ tương béo mượt mà không bị tách dầu.', 2),
('imp-d463228be1e6e7c0_v4_step_6', 'imp-d463228be1e6e7c0', 6, 'finish', 'Nêm lại gia vị và trình bày đĩa nóng', 'Trộn 8 g ngò tây tươi băm, nêm nếm lại phần muối ăn (khoảng 3 g) và 0,5 g tiêu đen xay còn lại cho vừa miệng, để nghỉ 1 phút. Múc cơm Risotto ra 3 đĩa sâu lòng, xếp 1/3 lượng nấm còn lại lên trên và dùng nóng ngay.', NULL, NULL),
('imp-9d575ec5c01896f0_v4_step_1', 'imp-9d575ec5c01896f0', 1, 'prep', 'Sơ chế cá hồi và rau củ gia vị', 'Thấm thật khô 300 g phi lê cá hồi tươi bằng giấy bếp rồi cắt miếng vuông 3–4 cm, ướp đều với 1 g muối ăn, 1 g tiêu đen xay và vài giọt nước cốt chanh vàng. Thái hạt lựu hành tây, băm nhuyễn tỏi tươi, rửa sạch để ráo rau bina, bào vỏ vàng chanh và thái nhỏ ngò tây.', 'Thấm thật khô bề mặt cá hồi trước khi áp chảo giúp miếng cá vàng giòn mà không bị bắn dầu hay nát thịt.', NULL),
('imp-9d575ec5c01896f0_v4_step_2', 'imp-9d575ec5c01896f0', 2, 'cook', 'Luộc mì Ý Spaghetti giữ nước tinh bột', 'Đun sôi nồi lớn với 2,5 lít nước lọc cùng 9 g muối ăn, cho 270 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút đến khi vừa chín tới (al dente). Trước khi vớt mì ra rổ, múc giữ lại 100 ml nước luộc mì.', NULL, 9),
('imp-9d575ec5c01896f0_v4_step_3', 'imp-9d575ec5c01896f0', 3, 'cook', 'Áp chảo cá hồi chín vàng đều các mặt', 'Đun nóng chảo lớn trên lửa vừa-cao với 15 ml dầu ô liu. Xếp các miếng cá hồi vào chảo không chồng lên nhau, áp chảo khoảng 3–4 phút mỗi mặt đến khi vàng đều và thịt cá chín chắc hoàn toàn bên trong rồi gắp ra đĩa riêng.', 'Không áp chảo cá hồi quá lâu để tránh thịt cá bị khô; cá sẽ được đảo nhẹ lại cùng sốt ở bước cuối.', 7),
('imp-9d575ec5c01896f0_v4_step_4', 'imp-9d575ec5c01896f0', 4, 'sauce', 'Xào thơm hành tỏi và làm xẹp rau bina', 'Hạ chảo vừa áp chảo cá xuống lửa vừa, cho 15 g bơ lạt vào đun tan. Cho hành tây vào xào 3 phút cho mềm trong rồi thêm tỏi băm phi thơm 30 giây. Thả toàn bộ 150 g rau bina tươi vào đảo nhanh 1–2 phút đến khi lá vừa héo mềm.', NULL, 4),
('imp-9d575ec5c01896f0_v4_step_5', 'imp-9d575ec5c01896f0', 5, 'sauce', 'Nấu sốt kem tươi và phô mai Parmesan', 'Rót 150 ml kem tươi vào chảo, khuấy đều và đun liu riu 3 phút trên lửa nhỏ cho sốt hơi sánh lại (không để sôi bùng). Hạ lửa thật nhỏ, cho 45 g phô mai Parmesan bào vào khuấy tan hoàn toàn cùng vỏ chanh bào, phần nước cốt chanh vàng còn lại, ớt vảy khô (nếu dùng), 2 g muối ăn và 1 g tiêu đen xay.', 'Vỏ và nước cốt chanh vàng giúp cân bằng độ béo ngậy của kem tươi và cá hồi rất hiệu quả.', 3),
('imp-9d575ec5c01896f0_v4_step_6', 'imp-9d575ec5c01896f0', 6, 'finish', 'Trộn mì Ý với cá hồi và trình bày nóng', 'Cho mì Ý Spaghetti vào chảo sốt đảo đều tay 1 phút, thêm từng chút nước luộc mì nếu sốt đặc. Thả cá hồi áp chảo vào đảo thật nhẹ để miếng cá không nát, tắt bếp, dọn ra 3 đĩa sâu lòng và rắc ngò tây tươi lên trên.', NULL, NULL),
('imp-810c132a4d2cd4e0_v4_step_1', 'imp-810c132a4d2cd4e0', 1, 'prep', 'Sơ chế và ướp tôm sú tươi', 'Lột vỏ 350 g tôm sú (có thể giữ phần chóp đuôi cho đẹp), rút sạch chỉ đen dọc sống lưng, rửa sạch và để thật ráo nước. Ướp tôm với 6 ml nước mắm và 2 g muối ăn trong 10 phút để thịt tôm săn chắc và đậm vị.', NULL, 10),
('imp-810c132a4d2cd4e0_v4_step_2', 'imp-810c132a4d2cd4e0', 2, 'prep', 'Dằm lọc nước cốt me và sơ chế rau củ', 'Ngâm 25 g cơm me chín với 80 ml nước lọc nóng, dằm nhuyễn rồi lọc qua rây bỏ hạt lấy nước cốt. Đeo găng tay tước bỏ vỏ xơ dọc mùng, thái lát xéo dày 0,5 cm, bóp nhẹ với 3 g muối ăn rồi rửa sạch nhiều lần và vắt ráo. Bổ múi cau cà chua, cắt lát dứa, rửa sạch giá đỗ, băm tỏi, cắt khúc hành lá, ngò gai, rau ngổ và thái lát ớt sừng; sát lúc nấu mới thái vát đậu bắp.', 'Chỉ thái đậu bắp ngay trước khi thả vào nồi để đậu bắp giữ màu xanh mướt và hạn chế tiết nhớt ra nước canh.', NULL),
('imp-810c132a4d2cd4e0_v4_step_3', 'imp-810c132a4d2cd4e0', 3, 'cook', 'Phi thơm tỏi và xào sơ tôm trước', 'Làm nóng nồi với 20 ml dầu ăn trên lửa vừa, cho tỏi băm vào phi thơm vàng nhạt rồi trút tôm đã ướp vào đảo nhanh 2 phút đến khi tôm vừa chuyển màu đỏ au thì vớt riêng ra chén.', 'Xào sơ tôm rồi vớt ra và thả lại vào cuối bước nấu giúp thịt tôm giữ nguyên độ giòn ngọt, không bị teo dai.', 2),
('imp-810c132a4d2cd4e0_v4_step_4', 'imp-810c132a4d2cd4e0', 4, 'cook', 'Xào nền cà chua dứa và nấu nước dùng me', 'Dùng lại nồi có dầu thơm, cho một nửa cà chua bổ múi cau và toàn bộ dứa vào xào 3 phút trên lửa vừa cùng 3 g muối ăn còn lại cho cà chua mềm tiết màu đỏ cam. Đổ 1,42 lít nước lọc còn lại vào đun lửa lớn đến khi sôi bùng, sau đó cho nước cốt me, 25 g đường, 8 g hạt nêm và 14 ml nước mắm còn lại vào khuấy tan, nấu 4 phút cho nước dùng dậy vị chua ngọt hài hòa.', 'Cho nước cốt me vào từ từ và nếm chỉnh với đường để đạt vị chua thanh ngọt dịu đặc trưng miền Nam.', 7),
('imp-810c132a4d2cd4e0_v4_step_5', 'imp-810c132a4d2cd4e0', 5, 'cook', 'Chần chín rau củ và nấu chín kỹ tôm', 'Thả đậu bắp thái vát và phần cà chua còn lại vào nồi nấu 2 phút trên lửa vừa, tiếp theo cho dọc mùng vào nấu thêm 1 phút. Trút lại phần tôm đã xào vào nồi, đun sôi lăn tăn thêm 2 phút cho tôm chín kỹ hoàn toàn từ trong ra ngoài.', NULL, 5),
('imp-810c132a4d2cd4e0_v4_step_6', 'imp-810c132a4d2cd4e0', 6, 'finish', 'Thả giá đỗ và rau thơm hoàn thiện tô canh', 'Cuối cùng thả giá đỗ vào nồi, đợi nước vừa sôi trở lại khoảng 15 giây thì tắt bếp ngay để giá vẫn giữ được độ giòn mát. Múc canh ra tô lớn, rắc hành lá, ngò gai, rau ngổ và ớt sừng thái lát lên mặt rồi dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-59015074541ba061_v4_step_1', 'imp-59015074541ba061', 1, 'prep', 'Ngâm nấm hương và chần khổ qua giảm đắng', 'Ngâm 15 g nấm hương khô trong nước ấm 20 phút cho nở mềm hoàn toàn, rửa sạch, bỏ chân cứng rồi băm nhỏ. Rửa sạch 4 trái khổ qua, cắt khoanh tròn dày khoảng 3 cm, dùng cán muỗng nạo thật sạch ruột và lớp màng trắng. Đun sôi nồi nước pha 4 g muối ăn, chần sơ các khoanh khổ qua 2 phút rồi vớt ngay vào nước lạnh, để ráo.', 'Nạo sạch màng trắng và chần sơ qua nước muối rồi ngâm lạnh giúp khoanh khổ qua bớt hẳn vị đắng gắt mà vẫn xanh giòn.', 20),
('imp-59015074541ba061_v4_step_2', 'imp-59015074541ba061', 2, 'prep', 'Băm tôm, cà rốt và chuẩn bị hành lá', 'Lột vỏ 250 g tôm sú và rút sạch chỉ đen. Giữ lại 8 con chừa phần chóp đuôi để cắm trang trí; 180 g tôm còn lại băm hoặc quết nhuyễn. Cà rốt gọt vỏ, băm nhỏ một nửa để trộn nhân và thái lát hoa một nửa. Băm nhuyễn 25 g hành tím cùng đầu trắng của hành lá; phần lá hành xanh cắt khúc 2 cm.', NULL, NULL),
('imp-59015074541ba061_v4_step_3', 'imp-59015074541ba061', 3, 'marinate', 'Quết dẻo và ướp nhân tôm thịt', 'Trộn đều tôm băm nhuyễn, 200 g thịt heo xay, nấm hương băm, cà rốt băm, hành tím và đầu hành lá băm trong tô lớn cùng 6 ml nước mắm, 5 g hạt nêm, 5 g đường và 1 g tiêu đen xay. Quết liên tục theo một chiều 2 phút cho khối nhân dẻo dai rồi ướp 15 phút cho thấm gia vị.', 'Quết nhân kỹ giúp thịt heo và tôm kết dính chặt chẽ, không bị rời rạc hay rã nhân trong nước canh.', 15),
('imp-59015074541ba061_v4_step_4', 'imp-59015074541ba061', 4, 'prep', 'Nhồi nhân vào khoanh khổ qua và gắn đuôi tôm', 'Múc từng lượng nhân tôm thịt nhồi vừa khít vào lòng từng khoanh khổ qua, ấn nhẹ cho mặt nhân phẳng mịn nhưng không nén quá chặt để chừa chỗ nhân nở khi chín. Cắm nhẹ một con tôm nguyên chừa đuôi lên giữa mặt mỗi khoanh khổ qua cho đẹp mắt.', NULL, NULL),
('imp-59015074541ba061_v4_step_5', 'imp-59015074541ba061', 5, 'cook', 'Hầm khổ qua nhồi tôm thịt mở nắp cho nước trong', 'Đun sôi 1,5 lít nước lọc trong nồi rộng đáy, nêm 14 ml nước mắm còn lại, 5 g hạt nêm và 2 g muối ăn. Khi nước sôi đều, nhẹ nhàng xếp từng khoanh khổ qua nhồi và cà rốt thái hoa vào nồi, hạ xuống lửa vừa và nấu mở nắp hoàn toàn trong 20 phút, thỉnh thoảng hớt bọt nổi cho đến khi khổ qua chín mềm và nhân tôm thịt chín chắc hoàn toàn.', 'Không đậy nắp nồi trong suốt lúc hầm để giữ màu xanh tươi cho vỏ khổ qua và giúp nước canh trong vắt.', 20),
('imp-59015074541ba061_v4_step_6', 'imp-59015074541ba061', 6, 'finish', 'Hoàn thiện tô canh khổ qua nhồi tôm', 'Nếm lại nước canh cho vừa miệng rồi tắt bếp, thả hành lá cắt khúc vào. Nhẹ nhàng gắp các khoanh khổ qua nhồi tôm và cà rốt xếp vào tô, chan nước dùng nóng hổi lên trên, rắc 1 g tiêu đen xay còn lại và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-9c678f92a5cb0812_v4_step_1', 'imp-9c678f92a5cb0812', 1, 'prep', 'Sơ chế bí đao sạch nhựa và cắt miếng', 'Gọt sạch lớp vỏ xanh bên ngoài 1 quả bí đao, bổ dọc thân rồi nạo bỏ toàn bộ phần ruột xốp và hạt. Rửa lại bí thật kỹ qua 2 lượt nước cho hết nhựa nhớt, sau đó cắt miếng vừa ăn dày khoảng 1 cm.', 'Rửa sạch lớp nhựa trên miếng bí sau khi gọt sẽ giúp nước canh thành phẩm trong veo và không có vị chát nhẹ.', NULL),
('imp-9c678f92a5cb0812_v4_step_2', 'imp-9c678f92a5cb0812', 2, 'marinate', 'Làm sạch, băm nhỏ và ướp tôm tươi', 'Lột vỏ 250 g tôm tươi, bỏ đầu, rút sạch chỉ đen dọc sống lưng, rửa qua nước muối loãng rồi để ráo. Giữ lại khoảng 4–5 con nguyên để cho đẹp mắt, phần còn lại băm nhỏ vừa phải. Ướp tôm với 5 ml nước mắm, 4 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay trong 15 phút. Băm nhỏ 20 g hành tím, thái nhỏ hành lá và ngò rí.', NULL, 15),
('imp-9c678f92a5cb0812_v4_step_3', 'imp-9c678f92a5cb0812', 3, 'cook', 'Phi thơm hành tím và xào săn tôm', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm vào phi thơm vàng nhẹ rồi thả toàn bộ tôm đã ướp vào đảo nhanh khoảng 2 phút đến khi tôm săn lại và chuyển màu đỏ cam đều.', NULL, 2),
('imp-9c678f92a5cb0812_v4_step_4', 'imp-9c678f92a5cb0812', 4, 'cook', 'Đun sôi nước dùng tôm và hớt sạch bọt', 'Đổ 1,1 lít nước lọc vào nồi tôm, bật lửa lớn đun sôi bùng rồi dùng vá hớt bỏ sạch phần bọt nổi trên mặt để nước canh trong vắt.', 'Hớt bọt ngay khi nước vừa sôi mạnh giúp nước dùng tôm giữ được độ trong sáng và thơm thanh.', 4),
('imp-9c678f92a5cb0812_v4_step_5', 'imp-9c678f92a5cb0812', 5, 'cook', 'Nấu bí đao chín tới và nêm nếm hài hòa', 'Nêm 4 g muối còn lại và 4 g hạt nêm vào nồi, thả toàn bộ bí đao cắt miếng vào và dùng vá ấn nhẹ cho bí ngập nước. Nấu trên lửa vừa khoảng 4–5 phút đến khi miếng bí chuyển màu trong nhẹ, xiên đũa thấy vừa mềm nhưng vẫn giữ độ giòn ngọt và tôm chín kỹ hoàn toàn. Nêm thêm 10 ml nước mắm còn lại rồi tắt bếp.', 'Không nên cho nước mắm quá sớm hoặc nấu bí quá lâu kẻo bí bị nhũn nát và mất đi mùi thơm thanh mát.', 5),
('imp-9c678f92a5cb0812_v4_step_6', 'imp-9c678f92a5cb0812', 6, 'finish', 'Rắc hành ngò và tiêu xay hoàn thiện', 'Thả hành lá và ngò rí thái nhỏ vào nồi canh đang nóng, rắc 1 g tiêu đen xay còn lại rồi múc ra tô lớn thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-80ce5736becc08da_v4_step_1', 'imp-80ce5736becc08da', 1, 'prep', 'Sơ chế cà chua, hành tỏi và đánh tan trứng gà', 'Rửa sạch 3 quả cà chua chín, bỏ cuống và bổ múi cau vừa ăn. Băm nhỏ 15 g hành tím khô và 7,5 g tỏi khô; rửa sạch hành lá và ngò rí rồi thái nhỏ, để riêng phần đầu hành. Đập 3 quả trứng gà vào chén cùng 1 g muối ăn, dùng đũa đánh tan thật đều lòng đỏ và lòng trắng.', 'Đánh tan trứng với một nhúm nhỏ muối trước giúp vân trứng đậm đà và khi rót vào nồi không bị tanh.', NULL),
('imp-80ce5736becc08da_v4_step_2', 'imp-80ce5736becc08da', 2, 'cook', 'Phi thơm hành tỏi và xào mềm cà chua tạo màu', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm, tỏi băm và đầu hành lá vào phi thơm 30 giây. Trút cà chua bổ múi cau vào cùng 15 ml nước mắm ngon, xào đảo đều khoảng 2–3 phút cho cà chua mềm nhũn nhẹ và tiết màu đỏ cam bắt mắt.', 'Xào cà chua trực tiếp với chút nước mắm giúp cà chua nhanh mềm và nước canh lên màu đỏ tự nhiên rất đẹp.', 3),
('imp-80ce5736becc08da_v4_step_3', 'imp-80ce5736becc08da', 3, 'cook', 'Nấu sôi nước dùng chua dịu hài hòa', 'Đổ 1,1 lít nước lọc vào nồi cà chua, tăng lên lửa lớn đun sôi bùng rồi nêm 3 g muối ăn còn lại, 6 g hạt nêm và 5 g đường cát trắng. Khuấy tan và nấu thêm 2 phút cho nước canh ngấm vị chua ngọt dịu nhẹ, hớt bọt nếu có.', NULL, 4),
('imp-80ce5736becc08da_v4_step_4', 'imp-80ce5736becc08da', 4, 'cook', 'Rưới trứng tạo vân mây vàng óng bồng bềnh', 'Hạ xuống lửa nhỏ để nước canh chỉ sôi lăn tăn nhẹ. Cầm chén trứng đã đánh tan rưới thật chậm theo dòng mảnh vòng quanh nồi, chờ khoảng 5 giây cho lớp trứng hơi se mặt rồi dùng đũa khuấy nhẹ nhàng theo một chiều để tạo thành những dải vân trứng mịn màng.', 'Không đổ trứng khi nước đang sôi sùng sục và không khuấy mạnh tay để tránh vân trứng bị nát vụn làm đục nước.', 2),
('imp-80ce5736becc08da_v4_step_5', 'imp-80ce5736becc08da', 5, 'cook', 'Nấu chín kỹ trứng gà vừa tới', 'Giữ lửa nhỏ đun thêm đúng 1 phút cho các dải trứng nổi đều và chín hoàn toàn bên trong, nếm lại gia vị lần cuối cho vừa miệng rồi tắt bếp ngay để trứng không bị dai cứng.', NULL, 1),
('imp-80ce5736becc08da_v4_step_6', 'imp-80ce5736becc08da', 6, 'finish', 'Rắc rau thơm và tiêu xay hoàn thiện', 'Thả hành lá và ngò rí thái nhỏ vào nồi canh nóng, rắc thêm 1 g tiêu đen xay rồi múc ra tô lớn thưởng thức ngay cùng cơm trắng.', NULL, NULL),
('imp-9473faeacd64d970_v4_step_1', 'imp-9473faeacd64d970', 1, 'marinate', 'Sơ chế và ướp ức gà thấm gia vị', 'Rửa sạch 400 g ức gà phi lê, thấm ráo nước và giữ nguyên miếng để luộc không bị khô. Ướp ức gà với 1/3 chỗ hành tím băm, 5 ml nước mắm, 4 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay trong 15 phút cho thịt gà đậm đà từ bên trong.', NULL, 15),
('imp-9473faeacd64d970_v4_step_2', 'imp-9473faeacd64d970', 2, 'prep', 'Thái sợi nấm đùi gà, cà rốt và rau thơm', 'Cắt bỏ phần gốc cứng của 250 g nấm đùi gà, rửa nhanh dưới vòi nước lạnh cho sạch rồi để ráo, sau đó xé hoặc thái sợi dọc dày 0,5 cm. Gọt vỏ 1 củ cà rốt, thái lát mỏng hoặc thái sợi. Thái lát gừng, băm nhỏ phần hành tím còn lại, cắt khúc đầu hành lá và thái nhỏ lá hành cùng ngò rí.', 'Không ngâm nấm đùi gà quá lâu trong nước vì nấm hút nước sẽ bị nhạt vị và mất độ giòn ngọt đặc trưng.', NULL),
('imp-9473faeacd64d970_v4_step_3', 'imp-9473faeacd64d970', 3, 'cook', 'Áp săn ức gà và luộc chín lấy nước dùng trong', 'Làm nóng nồi với 10 ml dầu ăn trên lửa vừa, phi thơm phần hành tím băm còn lại rồi cho miếng ức gà đã ướp vào áp chảo săn hai mặt khoảng 3 phút. Đổ 1,1 lít nước lọc và gừng lát vào nồi, đun sôi bùng rồi hạ lửa vừa luộc thêm 12 phút đến khi thịt gà chín hoàn toàn bên trong (không còn lõi hồng), đồng thời hớt sạch bọt nổi.', 'Áp săn ức gà trước khi đổ nước giúp bề mặt thịt se thơm và nước dùng luộc gà trong veo không bị đục.', 15),
('imp-9473faeacd64d970_v4_step_4', 'imp-9473faeacd64d970', 4, 'prep', 'Vớt ức gà ra để nguội bớt và xé sợi', 'Vớt miếng ức gà ra đĩa cho nguội bớt khoảng 3–4 phút rồi dùng tay xé dọc theo thớ thịt thành từng sợi vừa ăn; giữ lại toàn bộ nồi nước luộc gà trên bếp.', 'Xé thịt khi ức gà còn hơi ấm theo đúng thớ dọc giúp sợi gà mềm tơi và không bị bở nát.', NULL),
('imp-9473faeacd64d970_v4_step_5', 'imp-9473faeacd64d970', 5, 'cook', 'Nấu cà rốt, nấm đùi gà và thả gà xé vào nồi', 'Đun sôi lại nồi nước luộc gà, thả cà rốt vào nấu 2 phút trước, sau đó cho nấm đùi gà thái sợi vào nấu thêm 3 phút trên lửa vừa cho nấm vừa chín tới vẫn còn độ giòn ngọt. Trút toàn bộ thịt ức gà xé sợi trở lại nồi, nêm 8 g hạt nêm còn lại, 10 ml nước mắm, 2 g muối và 4 g đường cát trắng, đun sôi nhẹ thêm 1–2 phút cho hòa quyện.', NULL, 7),
('imp-9473faeacd64d970_v4_step_6', 'imp-9473faeacd64d970', 6, 'finish', 'Thêm đầu hành, rau thơm và tiêu xay hoàn thiện', 'Thả đầu hành lá cắt khúc và lá hành thái nhỏ vào nồi, khuấy đều rồi tắt bếp. Múc canh ra tô lớn, rắc ngò rí và 1 g tiêu đen xay lên mặt, dùng nóng với cơm trắng.', NULL, NULL),
('imp-9ab5767266722397_v4_step_1', 'imp-9ab5767266722397', 1, 'prep', 'Làm sạch mực ống và khử mùi tanh', 'Rút bỏ đầu, ruột, túi mực và sống lưng cứng của 350 g mực ống tươi; lột bỏ lớp màng da bên ngoài nếu thích nước canh thật trong. Chà xát nhanh mực với 2 g muối ăn rồi rửa sạch nhiều lần bằng nước lạnh, để thật ráo và cắt khoanh tròn dày 1,5–2 cm.', 'Bóp rửa nhanh mực với chút muối rồi để thật ráo nước giúp mực hết nhớt và giữ độ giòn sần sật khi nấu.', NULL),
('imp-9ab5767266722397_v4_step_2', 'imp-9ab5767266722397', 2, 'marinate', 'Ướp mực và sơ chế cà chua, gừng, hành', 'Ướp mực cắt khoanh với 6 ml nước mắm, 3 g hạt nêm và 1 g tiêu đen xay trong 10 phút cho thấm vị. Trong lúc chờ, bổ múi cau 2,5 quả cà chua, băm nhỏ 25 g hành tím, thái lát một nửa lượng gừng và thái sợi phần gừng còn lại; cắt khúc hành lá và ngò rí.', NULL, 10),
('imp-9ab5767266722397_v4_step_3', 'imp-9ab5767266722397', 3, 'cook', 'Phi thơm hành gừng và xào cà chua lên màu', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và gừng thái lát vào phi thơm khoảng 1 phút cho dậy mùi ấm nồng. Trút cà chua bổ múi cau vào cùng 2 g muối ăn còn lại, xào đảo khoảng 2–3 phút đến khi cà chua mềm nhẹ và ra màu đỏ cam đẹp mắt.', 'Phi thơm hành tím cùng gừng lát trước khi xào cà chua là bước khử mùi tanh đặc trưng giúp canh mực thơm dịu hơn.', 3),
('imp-9ab5767266722397_v4_step_4', 'imp-9ab5767266722397', 4, 'cook', 'Nấu sôi nước dùng chua ngọt thanh nhẹ', 'Đổ 1,1 lít nước lọc vào nồi cà chua, bật lửa lớn đun sôi bùng rồi nêm 14 ml nước mắm còn lại, 5 g hạt nêm và 5 g đường cát trắng, nấu sôi 3 phút cho gia vị tan đều và cà chua tiết vị chua dịu.', NULL, 3),
('imp-9ab5767266722397_v4_step_5', 'imp-9ab5767266722397', 5, 'cook', 'Thả mực vào nấu chín tới giữ độ giòn ngọt', 'Khi nước đang sôi đều trên lửa lớn vừa, thả toàn bộ mực đã ướp và gừng thái sợi vào nồi. Nấu đúng 2–3 phút cho nước sôi lại, khoanh mực cong tròn, chuyển màu trắng đục săn chắc và chín hoàn toàn bên trong rồi nêm nếm lại cho vừa miệng.', 'Chỉ thả mực khi nước đang sôi mạnh và nấu khoảng 2–3 phút để mực vừa chín tới, giữ trọn độ giòn ngọt mà không bị dai.', 3),
('imp-9ab5767266722397_v4_step_6', 'imp-9ab5767266722397', 6, 'finish', 'Hoàn thiện với chanh tươi và hành ngò', 'Tắt bếp ngay, thả hành lá và ngò rí cắt nhỏ vào đảo nhẹ. Múc canh ra tô, vắt thêm nước cốt của 0,5 quả chanh tươi tùy khẩu vị và rắc 1 g tiêu đen xay lên trên, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-61eac17e8f3042a9_v4_step_1', 'imp-61eac17e8f3042a9', 1, 'prep', 'Gọt su su sạch mủ và cắt miếng vừa ăn', 'Cắt bỏ hai đầu của 2 quả su su non, ngâm hoặc gọt vỏ trực tiếp dưới vòi nước lạnh chảy nhẹ để mủ su su trôi sạch không làm dính và rít da tay. Bổ đôi su su, khoét bỏ phần hạt non rồi thái lát vát dày khoảng 0,5 cm, rửa lại nước sạch và để ráo.', 'Gọt vỏ su su dưới nước hoặc ngâm qua nước muối loãng giúp loại bỏ hoàn toàn nhựa mủ và giữ miếng su su trắng xanh đẹp mắt.', NULL),
('imp-61eac17e8f3042a9_v4_step_2', 'imp-61eac17e8f3042a9', 2, 'marinate', 'Ướp thịt heo xay và băm hành tím, rau thơm', 'Băm nhuyễn 20 g hành tím khô, thái nhỏ hành lá và ngò rí. Cho 220 g thịt heo xay vào tô, ướp cùng một nửa lượng hành tím băm, 5 ml nước mắm, 4 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay, trộn đều để thấm gia vị trong 10 phút.', NULL, 10),
('imp-61eac17e8f3042a9_v4_step_3', 'imp-61eac17e8f3042a9', 3, 'cook', 'Phi thơm hành tím và xào tơi thịt heo băm', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho nửa phần hành tím băm còn lại vào phi thơm vàng nhạt. Trút thịt heo xay đã ướp vào đảo nhanh và dằm nhẹ cho thịt tơi rời, xào khoảng 3 phút cho thịt săn lại và chín đều.', 'Dùng đũa đảo tơi liên tục khi thịt mới vào nồi nóng giúp thịt băm rời đều và không bị vón thành từng cục lớn.', 3),
('imp-61eac17e8f3042a9_v4_step_4', 'imp-61eac17e8f3042a9', 4, 'cook', 'Đun sôi nước dùng và hớt sạch bọt', 'Đổ 1,2 lít nước lọc vào nồi thịt xào, tăng lên lửa lớn đun sôi bùng rồi dùng vá hớt sạch phần bọt nổi trên mặt để nước canh trong vắt.', NULL, 5),
('imp-61eac17e8f3042a9_v4_step_5', 'imp-61eac17e8f3042a9', 5, 'cook', 'Nấu su su chín tới và nêm nếm vị thanh ngọt', 'Thả toàn bộ su su thái lát vào nồi nước đang sôi, nấu trên lửa vừa khoảng 4–5 phút đến khi su su chuyển màu xanh trong nhẹ và vẫn còn độ giòn ngọt (tránh nấu nhũn). Nêm 3 g muối còn lại, 4 g hạt nêm và 10 ml nước mắm vào khuấy nhẹ rồi nếm lại vừa miệng.', 'Su su thái lát mỏng chín rất nhanh; tắt bếp ngay khi su su vừa chuyển trong sẽ giữ được độ giòn ngọt và màu xanh tươi.', 5),
('imp-61eac17e8f3042a9_v4_step_6', 'imp-61eac17e8f3042a9', 6, 'finish', 'Hoàn thiện với hành lá, ngò rí và tiêu xay', 'Tắt bếp, thả hành lá và ngò rí thái nhỏ vào nồi canh, rắc 1 g tiêu đen xay còn lại rồi múc ra tô dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-ad2b55ed85f0d109_v4_step_1', 'imp-ad2b55ed85f0d109', 1, 'prep', 'Thái sợi bắp cải, cà rốt và đánh tan trứng', 'Tách bỏ lá úa và phần cùi cứng của 0,75 bắp cải, thái sợi hoặc miếng vuông vừa ăn rồi rửa sạch qua 2–3 lần nước, để thật ráo. Gọt vỏ 0,5 củ cà rốt, thái lát mỏng. Băm nhỏ 20 g hành tím, thái nhỏ ngò rí và hành lá (để riêng phần đầu hành đập dập), thái lát ớt sừng. Đập 4 quả trứng gà vào tô, đánh tan đều tay.', 'Đánh đều tay cho lòng đỏ và lòng trắng hòa quyện hoàn toàn sẽ giúp vân trứng cuộn thành dải mảnh mịn đẹp mắt.', NULL),
('imp-ad2b55ed85f0d109_v4_step_2', 'imp-ad2b55ed85f0d109', 2, 'cook', 'Phi thơm hành và đun sôi nước dùng cà rốt', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và đầu hành lá vào phi thơm vàng nhẹ. Đổ 1,2 lít nước lọc vào nồi cùng cà rốt thái lát, nêm 6 g muối ăn, 10 g hạt nêm và 8 g đường cát trắng, đun sôi khoảng 4 phút cho cà rốt hơi mềm và gia vị tan đều.', NULL, 4),
('imp-ad2b55ed85f0d109_v4_step_3', 'imp-ad2b55ed85f0d109', 3, 'cook', 'Rưới trứng tạo vân cuộn vàng mềm mịn', 'Khi nước dùng đang sôi đều ở lửa vừa, từ từ rót phần trứng gà đã đánh tan vào nồi qua dòng chảy nhỏ, đồng thời dùng đũa khuấy nhẹ nhàng theo một vòng tròn để trứng kết thành những sợi cuộn mỏng bồng bềnh và không bị vón cục.', 'Giữ nước sôi vừa phải và khuấy thật nhẹ một chiều trong lúc rưới trứng để tạo vân cuộn tơi đẹp mà không làm đục nước.', 2),
('imp-ad2b55ed85f0d109_v4_step_4', 'imp-ad2b55ed85f0d109', 4, 'cook', 'Nấu bắp cải vừa chín tới giữ độ giòn ngọt', 'Thả toàn bộ bắp cải thái sợi vào nồi, đảo nhẹ cho ngập nước và nấu mở vung trên lửa vừa thêm 2 phút đến khi bắp cải vừa chín tới vẫn giữ màu xanh nhạt tươi tắn, độ giòn ngọt và trứng chín hoàn toàn bên trong.', 'Chỉ nấu bắp cải khoảng 2 phút mở vung để rau giữ được độ giòn ngọt tự nhiên và không bị nồng mùi.', 2),
('imp-ad2b55ed85f0d109_v4_step_5', 'imp-ad2b55ed85f0d109', 5, 'cook', 'Nêm nước mắm sau cùng giữ trọn hương thơm', 'Rưới 20 ml nước mắm ngon vào nồi canh, khuấy nhẹ đều một lượt rồi nếm lại vị thanh ngọt vừa miệng trước khi tắt bếp.', NULL, NULL),
('imp-ad2b55ed85f0d109_v4_step_6', 'imp-ad2b55ed85f0d109', 6, 'finish', 'Hoàn thiện với hành ngò, ớt lát và tiêu xay', 'Tắt bếp, rắc hành lá và ngò rí thái nhỏ cùng vài lát ớt sừng đỏ và 1 g tiêu đen xay lên mặt nồi. Múc canh ra tô lớn dùng nóng với cơm trắng.', NULL, NULL),
('imp-7cfc6a2e9d8bf8a3_v4_step_1', 'imp-7cfc6a2e9d8bf8a3', 1, 'prep', 'Nhặt rau muống và sơ chế cà chua, hành lá', 'Nhặt bỏ phần gốc già của 1,5 bó rau muống, ngắt lấy phần cọng non và lá xanh thành khúc dài khoảng 5 cm. Ngâm rau với nước pha 2 g muối ăn trong 5 phút rồi xả sạch nhiều lần, để thật ráo. Bổ múi cau 2 quả cà chua chín, băm nhỏ 20 g hành tím và cắt nhỏ hành lá.', NULL, 5),
('imp-7cfc6a2e9d8bf8a3_v4_step_2', 'imp-7cfc6a2e9d8bf8a3', 2, 'marinate', 'Giã thô và ướp tôm đồng cho ngọt nước', 'Lột vỏ 200 g tôm đồng, bỏ đầu, rút sạch chỉ đen dọc lưng và giữ lại phần gạch tôm nếu có. Cho tôm vào cối giã thô vừa phải để thịt tôm vẫn còn độ sần sật, sau đó ướp với 1 g muối ăn, 3 g hạt nêm, 4 g đường cát trắng và 1 g tiêu đen xay trong 10 phút cho ngấm vị.', 'Giã thô tôm đồng cùng chút gạch giúp thịt tôm tiết ra hết độ ngọt vào nước dùng và tạo màu cam hấp dẫn.', 10),
('imp-7cfc6a2e9d8bf8a3_v4_step_3', 'imp-7cfc6a2e9d8bf8a3', 3, 'cook', 'Phi thơm hành tím và xào chín tôm, cà chua', 'Làm nóng nồi với 20 ml dầu ăn trên lửa vừa, cho hành tím băm vào phi thơm vàng nhẹ rồi trút tôm đồng đã ướp vào đảo đều khoảng 2 phút đến khi tôm săn lại và chuyển màu hồng cam. Tiếp tục cho cà chua bổ múi cau vào xào chung thêm 3 phút cho cà chua mềm nhẹ và ra màu đỏ cam tự nhiên.', 'Xào chín tôm cùng cà chua trước khi đổ nước giúp nước canh có màu đỏ cam đẹp mắt và dậy mùi thơm đậm đà.', 5),
('imp-7cfc6a2e9d8bf8a3_v4_step_4', 'imp-7cfc6a2e9d8bf8a3', 4, 'cook', 'Đun sôi nước dùng và nêm gia vị hài hòa', 'Đổ 1,3 lít nước lọc vào nồi, bật lửa lớn đun sôi bùng và hớt sạch bọt nổi trên mặt. Nêm 3 g muối ăn còn lại, 5 g hạt nêm và 15 ml nước mắm ngon vào nồi, khuấy tan đều và nấu thêm 2 phút cho nước canh đậm vị chua thanh ngọt dịu.', NULL, 4),
('imp-7cfc6a2e9d8bf8a3_v4_step_5', 'imp-7cfc6a2e9d8bf8a3', 5, 'cook', 'Thả rau muống vào nấu mở vung giữ màu xanh', 'Khi nước đang sôi mạnh trên lửa lớn, thả toàn bộ rau muống vào nồi và dùng vá ấn nhẹ cho rau ngập đều trong nước dùng. Nấu mở nắp khoảng 2–3 phút đến khi cọng rau vừa chín tới, xanh mướt và vẫn giữ độ giòn.', 'Không đậy nắp nồi và nấu nhanh trên lửa lớn giúp rau muống giữ màu xanh tươi mướt mà không bị úa vàng.', 3),
('imp-7cfc6a2e9d8bf8a3_v4_step_6', 'imp-7cfc6a2e9d8bf8a3', 6, 'finish', 'Hoàn thiện với hành lá và dọn nóng', 'Nếm lại vị canh lần cuối cho vừa miệng, thả hành lá cắt nhỏ vào đảo nhẹ rồi tắt bếp ngay. Múc canh ra tô lớn dùng nóng với cơm trắng.', NULL, NULL),
('imp-24cdd0b61f9ed162_v4_step_1', 'imp-24cdd0b61f9ed162', 1, 'prep', 'Làm sạch cua đồng, khêu gạch và lọc nước cua', 'Ngâm rửa sạch 400 g cua đồng cho hết bùn đất, tách mai, bỏ yếm và khêu riêng phần gạch cua ra chén. Giã nhuyễn thân cua với 2 g muối ăn (hoặc dùng cua xay nhuyễn), hòa với 1,14 lít nước lọc, bóp kỹ rồi lọc gạn 2–3 lần qua rây mịn vào nồi nấu canh để loại bỏ hoàn toàn vỏ sạn. Ngâm dằm 25 g me chín với 60 ml nước nóng rồi lọc lấy nước cốt.', 'Lọc nước cua qua rây mịn 2 lần giúp thu hết thịt cua mà nước canh vẫn sạch hoàn toàn không bị lợn cợn vỏ cứng.', 10),
('imp-24cdd0b61f9ed162_v4_step_2', 'imp-24cdd0b61f9ed162', 2, 'prep', 'Rán vàng đậu phụ và phi giòn hành tím', 'Thấm khô 2 bìa đậu phụ, cắt miếng vuông vừa ăn khoảng 2,5 cm. Làm nóng chảo với 20 ml dầu ăn trên lửa vừa, thả đậu phụ vào rán vàng giòn các mặt rồi gắp ra đĩa giấy thấm dầu. Bổ múi cau 2,5 quả cà chua; thái nhỏ hành lá và rau răm; chia 25 g hành tím làm hai phần (một nửa thái lát mỏng, một nửa băm nhỏ) rồi dùng chảo nhỏ với 15 ml dầu ăn phi vàng giòn phần hành thái lát, vớt riêng ra chén.', NULL, 8),
('imp-24cdd0b61f9ed162_v4_step_3', 'imp-24cdd0b61f9ed162', 3, 'cook', 'Nấu nổi riêu cua đồng và vớt tảng riêu riêng', 'Hòa 10 g hạt nêm và 2 g muối ăn vào nồi nước lọc cua, khuấy nhẹ một chiều rồi bắc lên bếp đun ở lửa vừa. Khi nước nóng dần và thịt cua bắt đầu tách lớp nổi lên mặt, ngừng khuấy hoàn toàn và hạ nhỏ lửa để riêu kết lại thành từng mảng dày. Khi nước sôi nhẹ, dùng vá lỗ nhẹ nhàng vớt phần riêu cua ra bát riêng để không bị nát.', 'Ngừng khuấy ngay khi thịt cua bắt đầu kết mảng và vớt riêu ra trước khi cho cà chua giúp giữ trọn tảng riêu nguyên vẹn đẹp mắt.', 8),
('imp-24cdd0b61f9ed162_v4_step_4', 'imp-24cdd0b61f9ed162', 4, 'cook', 'Chưng gạch cua cùng cà chua tạo màu đỏ óng', 'Tận dụng chảo dầu vừa phi hành, cho phần hành tím băm vào phi thơm, thả cà chua bổ múi cau và 2 g muối ăn còn lại vào xào mềm khoảng 2 phút cho ra màu đỏ đẹp rồi trút chén gạch cua vào đảo nhanh tay 1 phút đến khi gạch chín thơm vàng óng.', 'Chưng gạch cua trên lửa vừa cùng hành phi và cà chua giúp gạch lên màu vàng cam óng ả và khử hoàn toàn mùi tanh.', 3),
('imp-24cdd0b61f9ed162_v4_step_5', 'imp-24cdd0b61f9ed162', 5, 'cook', 'Nấu nước riêu chua dịu và thả đậu phụ rán', 'Trút chảo cà chua chưng gạch vào nồi nước cua, đun sôi lại rồi từ từ rót nước cốt me vào cùng 15 ml nước mắm ngon, điều chỉnh độ chua thanh mặn ngọt hài hòa. Thả toàn bộ đậu phụ rán vàng vào nồi đun sôi liu riu thêm 3 phút cho đậu thấm vị canh.', NULL, 4),
('imp-24cdd0b61f9ed162_v4_step_6', 'imp-24cdd0b61f9ed162', 6, 'finish', 'Thả lại riêu cua, hành răm và rắc hành phi', 'Nhẹ nhàng đặt phần riêu cua trở lại mặt nồi canh, rắc hành lá và rau răm thái nhỏ rồi tắt bếp ngay. Múc canh ra bát tô, rắc phần hành tím phi vàng giòn lên trên và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-15155ec6cc7b7713_v4_step_1', 'imp-15155ec6cc7b7713', 1, 'prep', 'Làm sạch và thái dải thịt ba chỉ', 'Rửa sạch 500 g thịt ba chỉ với nước pha 4 g muối để khử mùi, rửa lại nước sạch và thấm thật khô. Thái thịt thành các dải dày 1–1,5 cm, dài khoảng 5–6 cm để khi nướng thịt chín đều mà vẫn giữ được độ mọng nước.', 'Thấm thật khô thịt trước khi ướp giúp gia vị bám chắc vào bề mặt và không bị chảy nước loãng.', NULL),
('imp-15155ec6cc7b7713_v4_step_2', 'imp-15155ec6cc7b7713', 2, 'prep', 'Băm nhuyễn sả, hành tím, tỏi, gừng và ớt', 'Đập dập rồi băm thật nhuyễn 4 cây sả tươi, 30 g hành tím, 15 g gừng, tỏi và ớt hiểm. Giữ lại 1/4 lượng tỏi và 1 quả ớt hiểm băm riêng để pha nước chấm, phần còn lại dùng để ướp thịt.', NULL, NULL),
('imp-15155ec6cc7b7713_v4_step_3', 'imp-15155ec6cc7b7713', 3, 'marinate', 'Trộn sốt ướp sả mật ong và ướp thịt', 'Trộn đều sả, hành tím, gừng, 3/4 tỏi và 1 quả ớt băm với 30 ml nước mắm, 30 ml mật ong, 15 ml dầu ăn, 5 g đường cát trắng, 2 g muối và 2 g tiêu đen xay. Xoa đều hỗn hợp lên từng dải thịt ba chỉ, bọc kín và ướp ít nhất 45 phút trong ngăn mát tủ lạnh.', 'Gạt bớt phần xác sả tỏi quá dày trên bề mặt thịt trước khi đặt lên vỉ để tránh bị cháy khét trong lúc nướng mật ong.', 45),
('imp-15155ec6cc7b7713_v4_step_4', 'imp-15155ec6cc7b7713', 4, 'sauce', 'Pha nước mắm chua ngọt tỏi ớt ăn kèm', 'Trong lúc chờ thịt ngấm, hòa tan 10 g đường cát trắng với 45 ml nước lọc ấm và 15 ml giấm gạo, sau đó cho 15 ml nước mắm ngon vào khuấy đều. Cuối cùng thả phần tỏi và ớt hiểm băm còn lại vào để tỏi ớt nổi đẹp trên mặt chén nước chấm.', NULL, NULL),
('imp-15155ec6cc7b7713_v4_step_5', 'imp-15155ec6cc7b7713', 5, 'cook', 'Làm nóng lò và nướng vàng mặt thứ nhất', 'Lấy thịt ra khỏi tủ lạnh trước 10 phút cho bớt lạnh. Làm nóng lò nướng (hoặc nồi chiên không dầu) ở 190°C trong 10 phút, xếp dải thịt lên vỉ có khay hứng mỡ bên dưới và nướng mặt đầu tiên trong 15 phút.', NULL, 15),
('imp-15155ec6cc7b7713_v4_step_6', 'imp-15155ec6cc7b7713', 6, 'cook', 'Lật mặt, phết nước ướp và nướng cháy cạnh', 'Lật mặt miếng thịt, phết thêm một lớp mỏng phần nước ướp còn dư rồi tiếp tục nướng thêm 12–15 phút ở 190°C đến khi hai mặt thịt vàng ruộm, xém cạnh thơm lừng và nước thịt chảy ra trong hoàn toàn không còn màu hồng.', 'Mật ong rất nhanh lên màu nên cần canh lửa vừa khoảng 180–190°C và quan sát ở 5 phút cuối để thịt vàng bóng mà không bị đắng.', 15),
('imp-15155ec6cc7b7713_v4_step_7', 'imp-15155ec6cc7b7713', 7, 'finish', 'Thái miếng, vắt chanh tươi và dọn thưởng thức', 'Gắp thịt ba chỉ nướng ra thớt để nghỉ 5 phút cho nước thịt ổn định, sau đó thái lát mỏng vừa ăn. Xếp ra đĩa, vắt vài giọt nước cốt chanh tươi lên trên để cân bằng vị béo và dùng nóng kèm nước mắm chua ngọt.', NULL, NULL),
('imp-363ca9ee2c5f7738_v4_step_1', 'imp-363ca9ee2c5f7738', 1, 'prep', 'Khử mùi thịt nạm bò và sơ chế rau thơm', 'Bóp đều 650 g thịt nạm bò với 6 g muối hạt và 15 ml rượu trắng trong 5 phút để khử mùi gây, rửa lại nhiều lần nước lạnh rồi thấm khô và thái khối vuông 3,5–4 cm. Cà rốt cắt khúc 2,5 cm; cà chua bỏ hạt băm nhỏ; sả đập dập 2 cây và băm nhỏ 1 cây; gừng, hành tím, tỏi băm nhỏ; hoa hồi và quế thanh rang khô thơm; húng quế, ngò gai rửa sạch.', NULL, 5),
('imp-363ca9ee2c5f7738_v4_step_2', 'imp-363ca9ee2c5f7738', 2, 'marinate', 'Ướp thịt bò với ngũ vị hương và gia vị', 'Cho thịt bò vào tô lớn, trộn đều cùng một nửa lượng sả băm, gừng, hành tím, tỏi băm, 5 g bột ngũ vị hương, 15 ml nước mắm, 15 g đường cát trắng và 2 g tiêu đen xay. Bọc kín và ướp ít nhất 45 phút trong ngăn mát để thịt thấm sâu hương vị.', 'Nếu có thời gian, ướp thịt qua đêm trong ngăn mát tủ lạnh sẽ giúp thớ thịt bò mềm hơn và đậm mùi ngũ vị hương hơn.', 45),
('imp-363ca9ee2c5f7738_v4_step_3', 'imp-363ca9ee2c5f7738', 3, 'cook', 'Phi thơm dầu điều, xào cà chua và thịt bò', 'Làm nóng nồi đáy dày với 15 ml dầu màu điều trên lửa vừa, phi thơm phần hành tím, tỏi, gừng và sả băm còn lại trong 1 phút. Cho cà chua băm vào xào nhuyễn 3 phút tạo nền màu đỏ sánh, rồi trút toàn bộ thịt bò đã ướp vào đảo săn trên lửa lớn trong 5 phút.', NULL, 8),
('imp-363ca9ee2c5f7738_v4_step_4', 'imp-363ca9ee2c5f7738', 4, 'cook', 'Hầm mềm thịt bò với nước dừa tươi và thảo mộc', 'Đổ 1 lít nước dừa tươi và 100 ml nước lọc vào nồi, thả 2 cây sả đập dập, hoa hồi, quế thanh và nguyên củ hành tây vào cùng. Đun sôi bùng, hớt sạch bọt rồi hạ lửa nhỏ đậy hé nắp hầm liu riu 40 phút cho thịt nạm bò chín mềm.', 'Thả nguyên củ hành tây vào hầm giúp nước bò kho có độ ngọt thanh tự nhiên mà không bị đục nước.', 40),
('imp-363ca9ee2c5f7738_v4_step_5', 'imp-363ca9ee2c5f7738', 5, 'cook', 'Hầm cà rốt chín mềm và nêm nước dùng', 'Vớt bỏ củ hành tây, hoa hồi, quế thanh và cọng sả ra khỏi nồi. Cho cà rốt cắt khúc vào nồi cùng 15 ml nước mắm còn lại, 10 g đường cát trắng, 6 g hạt nêm và 2 g muối, tiếp tục hầm lửa vừa nhỏ thêm 15 phút đến khi cà rốt chín mềm mà không bị bở nát.', NULL, 15),
('imp-363ca9ee2c5f7738_v4_step_6', 'imp-363ca9ee2c5f7738', 6, 'finish', 'Tạo độ sánh bằng bột năng và dọn kèm bánh mì', 'Khuấy tan 18 g bột năng với 150 ml nước lọc, vừa rót từ từ vào nồi bò kho đang sôi nhẹ vừa khuấy đều đến khi nước dùng sánh mịn mượt, đun thêm 2 phút cho chín bột rồi tắt bếp. Múc bò kho ra tô, rắc ngò gai thái nhỏ và húng quế lên trên, dọn nóng kèm 5 ổ bánh mì giòn.', 'Rót nước bột năng từ từ từng chút một để kiểm soát độ sánh vừa đủ chấm bánh mì mà không bị đặc vón cục.', NULL),
('imp-3ec27a2b8f5e4345_v4_step_1', 'imp-3ec27a2b8f5e4345', 1, 'prep', 'Làm sạch gà và sơ chế gừng, ớt hiểm', 'Chà xát 700 g đùi gà với 4 g muối hạt cho sạch nhớt và khử mùi tanh, rửa lại nước lạnh rồi để ráo, chặt miếng vừa ăn cỡ 3,5–4 cm. Gừng cạo vỏ, chia đôi một nửa thái sợi mỏng và một nửa thái lát; ớt hiểm bỏ cuống đập dập nhẹ; hành tím và tỏi băm nhỏ; hành lá cắt khúc 3 cm.', 'Đập dập nhẹ ớt hiểm giúp tinh dầu cay tỏa đều vào nước kho mà không làm vỡ nát quá nhiều hạt ớt.', NULL),
('imp-3ec27a2b8f5e4345_v4_step_2', 'imp-3ec27a2b8f5e4345', 2, 'marinate', 'Ướp đùi gà với gừng sợi và nước mắm', 'Ướp thịt gà trong tô lớn cùng phần gừng thái sợi, 25 ml nước mắm ngon, 8 g đường cát trắng, 3 g muối và 1 g tiêu đen xay. Trộn đều rồi ướp ít nhất 25 phút cho thịt ngấm đậm gia vị.', 'Dùng gừng già thái sợi mỏng ướp cùng thịt gà giúp hương thơm cay ấm thấm sâu vào từng thớ thịt.', 25),
('imp-3ec27a2b8f5e4345_v4_step_3', 'imp-3ec27a2b8f5e4345', 3, 'sauce', 'Thắng nước màu và phi thơm hành tỏi gừng', 'Làm nóng nồi đáy dày hoặc nồi đất với 25 ml dầu ăn và 12 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan và chuyển màu nâu cánh gián. Cho nhanh hành tím, tỏi băm và phần gừng thái lát vào phi thơm khoảng 1 phút.', 'Kho bằng nồi đất hoặc nồi gang giữ nhiệt ổn định giúp thịt gà mềm thấm và nước kho sánh bóng nhanh hơn.', NULL),
('imp-3ec27a2b8f5e4345_v4_step_4', 'imp-3ec27a2b8f5e4345', 4, 'cook', 'Xào săn thịt gà trên lửa lớn', 'Vặn lửa lớn, trút toàn bộ thịt gà đã ướp vào nồi đảo liên tục trong 5 phút cho đến khi da gà săn lại, bề mặt miếng thịt đổi màu vàng nâu óng ả và thấm đều hương gừng tỏi.', NULL, 5),
('imp-3ec27a2b8f5e4345_v4_step_5', 'imp-3ec27a2b8f5e4345', 5, 'cook', 'Kho nhỏ lửa với ớt hiểm cho thấm vị', 'Thêm 20 ml nước mắm còn lại, 4 quả ớt hiểm và 80 ml nước lọc ấm vào nồi, đảo đều rồi đợi nước sôi lại. Hạ lửa nhỏ, đậy nắp kho liu riu trong 20 phút và thỉnh thoảng trở mặt để thịt gà chín kỹ tận xương.', NULL, 20),
('imp-3ec27a2b8f5e4345_v4_step_6', 'imp-3ec27a2b8f5e4345', 6, 'finish', 'Sánh sốt và rắc hành lá hoàn thiện', 'Mở nắp, tăng lửa vừa kho thêm 3 phút cho nước sốt cạn sánh sệt bám quanh từng miếng thịt gà. Nêm lại vừa miệng, tắt bếp rồi rắc hành lá cắt khúc và 1 g tiêu đen xay còn lại lên trên, dọn dùng nóng.', NULL, NULL),
('imp-323aae415415eb28_v4_step_1', 'imp-323aae415415eb28', 1, 'prep', 'Làm sạch tôm với nước muối chanh loãng', 'Pha 4 g muối hạt và phần lớn nước cốt của 1/2 quả chanh tươi vào tô nước lạnh (chừa lại vài giọt chanh). Ngâm rửa nhanh 400 g tôm trong 1 phút cho hết mùi tanh, xả lại nước sạch rồi cắt bớt râu, rút chỉ đen trên lưng và để thật ráo nước.', NULL, NULL),
('imp-323aae415415eb28_v4_step_2', 'imp-323aae415415eb28', 2, 'prep', 'Sơ chế tiêu xanh và hành tỏi thơm', 'Rửa sạch 30 g tiêu xanh tươi, lấy một nửa số hạt đập dập nhẹ cho tiết tinh dầu, phần còn lại giữ nguyên nhánh. Băm nhỏ hành tím, tỏi khô và đầu hành lá; lá hành cắt khúc 2,5 cm; ớt hiểm thái lát mỏng.', 'Đập dập nhẹ một phần tiêu xanh khi ướp giúp vị cay thơm thấm vào thịt tôm, trong khi giữ nguyên chùm cho vào sau giúp món ăn bắt mắt.', NULL),
('imp-323aae415415eb28_v4_step_3', 'imp-323aae415415eb28', 3, 'marinate', 'Ướp tôm cùng tiêu xanh đập dập', 'Trộn đều tôm với một nửa hành tím và tỏi băm, đầu hành băm, phần tiêu xanh đập dập, 30 ml nước mắm, 8 g đường cát trắng và 4 g hạt nêm. Ướp trong 15 phút cho thịt tôm săn và đậm đà.', 'Tôm tươi chỉ cần ướp khoảng 15 phút là đủ ngấm vị, ướp quá lâu với muối mắm dễ làm thịt tôm bị bở.', 15),
('imp-323aae415415eb28_v4_step_4', 'imp-323aae415415eb28', 4, 'sauce', 'Thắng nước màu và xào săn tôm', 'Đun nóng nồi đất hoặc chảo với 25 ml dầu ăn và 10 g đường cát trắng còn lại trên lửa nhỏ đến khi đường chuyển màu nâu cánh gián. Trút phần hành tím, tỏi băm còn lại vào phi thơm 30 giây, rồi vặn lửa lớn cho tôm vào đảo nhanh 3 phút đến khi tôm cong đỏ đều.', NULL, 3),
('imp-323aae415415eb28_v4_step_5', 'imp-323aae415415eb28', 5, 'cook', 'Kho mở nắp với tiêu xanh nguyên chùm', 'Rót 100 ml nước lọc nóng vào nồi, thả các nhánh tiêu xanh nguyên chùm còn lại vào cùng. Hạ lửa vừa nhỏ, kho không đậy nắp trong 8 phút, đảo nhẹ vài lần cho tôm chín hồng hoàn toàn và nước sốt rút sánh bóng bám quanh vỏ tôm.', 'Không đậy nắp và không kho quá lâu để tôm giữ được độ giòn ngọt tự nhiên mà không bị bở thịt.', 8),
('imp-323aae415415eb28_v4_step_6', 'imp-323aae415415eb28', 6, 'finish', 'Hoàn thiện hương vị và bày đĩa', 'Thả hành lá cắt khúc và ớt hiểm thái lát vào đảo nhẹ, tắt bếp rồi rắc 1,5 g tiêu đen xay và vắt thêm vài giọt nước cốt chanh tươi còn lại cho dậy hương thanh nhẹ. Dọn nóng ngay với cơm trắng.', NULL, NULL),
('imp-3f1ad35e1f1ec87f_v4_step_1', 'imp-3f1ad35e1f1ec87f', 1, 'prep', 'Nướng thơm, đập mềm và xé sợi mực khô', 'Kẹp 280 g mực khô vào vỉ, nướng trên bếp lửa nhỏ hoặc nồi chiên không dầu ở 180°C khoảng 3–4 phút cho mực vừa cong thơm đều hai mặt, tránh nướng quá lâu làm mực khô cứng. Bọc mực nóng trong giấy sạch dùng chày đập nhẹ cho mềm tơi, rũ sạch vụn cháy rồi xé sợi bản rộng cỡ 1 cm.', 'Đập mềm mực ngay khi còn nóng giúp các thớ thịt tơi mềm và dễ thấm đều nước sốt dứa khi rim.', 4),
('imp-3f1ad35e1f1ec87f_v4_step_2', 'imp-3f1ad35e1f1ec87f', 2, 'prep', 'Vắt nước cốt dứa và rang vàng mè trắng', 'Gọt vỏ bỏ mắt 1/2 quả dứa chín, băm nhuyễn hoặc giã nát rồi vắt qua rây thu lấy phần nước cốt dứa thơm ngọt, bỏ bã. Rang khô 15 g hạt mè trắng trên chảo lửa nhỏ khoảng 2 phút đến khi vàng thơm rồi trút ra chén riêng.', NULL, 2),
('imp-3f1ad35e1f1ec87f_v4_step_3', 'imp-3f1ad35e1f1ec87f', 3, 'sauce', 'Pha hỗn hợp nước sốt dứa chua cay mặn ngọt', 'Cho toàn bộ nước cốt dứa vào tô lớn, thêm 25 ml nước mắm ngon, 20 ml dầu hào, 20 ml tương cà, 20 ml tương ớt, 20 g đường cát trắng, 40 ml nước lọc và 3 quả ớt hiểm băm nhỏ. Khuấy đều đến khi đường tan hoàn toàn.', NULL, NULL),
('imp-3f1ad35e1f1ec87f_v4_step_4', 'imp-3f1ad35e1f1ec87f', 4, 'cook', 'Phi thơm hành tỏi và đun sôi hỗn hợp sốt', 'Làm nóng chảo rộng với 25 ml dầu ăn trên lửa vừa, phi thơm hành tím và tỏi băm khoảng 1 phút đến khi vừa ngả vàng. Đổ chén nước sốt dứa vào chảo đun sôi nhẹ trong 2 phút cho sốt hòa quyện và nếm chỉnh độ chua cay ngọt vừa miệng.', 'Nêm nếm độ chua ngọt ngay khi sốt đang sôi nhẹ trước khi thả mực vào sẽ giúp điều chỉnh hương vị chuẩn xác hơn.', 2);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-3f1ad35e1f1ec87f_v4_step_5', 'imp-3f1ad35e1f1ec87f', 5, 'cook', 'Rim nhỏ lửa cho mực thấm kẹo nước sốt', 'Trút toàn bộ mực khô xé sợi vào chảo sốt, đảo đều rồi hạ lửa nhỏ nhất, rim liu riu trong 10 phút và đảo liên tục để từng sợi mực hút cạn nước sốt, chuyển màu đỏ nâu sánh bóng dẻo ngon.', 'Luôn giữ lửa nhỏ khi rim để đường và tương ớt không bị cháy khét đáy chảo trước khi mực kịp ngấm đều.', 10),
('imp-3f1ad35e1f1ec87f_v4_step_6', 'imp-3f1ad35e1f1ec87f', 6, 'finish', 'Trộn ớt bột, mè rang và hoàn thiện', 'Khi nước sốt đã keo đặc bám trọn quanh miếng mực, rắc 2 g ớt bột khô và 15 g mè trắng rang vàng vào đảo đều 30 giây rồi tắt bếp. Để mực nguội bớt trước khi gắp ra đĩa và rắc thêm 1,5 g tiêu đen xay lên trên.', NULL, NULL),
('imp-64e505d497388f4a_v4_step_1', 'imp-64e505d497388f4a', 1, 'marinate', 'Thấm khô và ướp cá hồi với muối tiêu chanh', 'Thấm thật khô 3 miếng cá hồi phi lê bằng khăn giấy sạch, xoa đều 2 g muối ăn, 2 g tiêu đen xay và 20 ml nước cốt chanh tươi lên các mặt miếng cá rồi để ướp 10 phút cho thịt cá săn và thơm.', 'Lau thật khô bề mặt da cá trước khi áp chảo giúp lớp da áp nhiệt trực tiếp nhanh chóng vàng giòn mà không bị dính chảo.', 10),
('imp-64e505d497388f4a_v4_step_2', 'imp-64e505d497388f4a', 2, 'prep', 'Chuẩn bị tỏi, hành tím, ớt và hành lá', 'Tỏi khô và hành tím bóc vỏ, băm nhỏ; ớt tươi băm nhỏ; hành lá thái nhuyễn. Cắt thêm vài lát chanh mỏng và thái lát quả cà chua tươi (nếu dùng) để ăn kèm.', NULL, NULL),
('imp-64e505d497388f4a_v4_step_3', 'imp-64e505d497388f4a', 3, 'cook', 'Áp chảo cá hồi da giòn trên lửa vừa', 'Đặt chảo chống dính lên bếp, đun nóng 20 ml dầu ăn trên lửa vừa, đặt mặt da cá hồi xuống trước và ấn nhẹ 15 giây cho da phẳng sát đáy chảo. Áp chảo yên mặt da trong 3 phút cho vàng giòn, rồi nhẹ nhàng trở mặt nấu thêm 2 phút cho hai bên chín vừa tới và thịt cá chuyển hồng nhạt mọng nước, gắp cá ra đĩa nghỉ.', 'Không di chuyển miếng cá liên tục trong lúc áp chảo và tránh nấu quá lâu khiến cá hồi bị khô xác.', 5),
('imp-64e505d497388f4a_v4_step_4', 'imp-64e505d497388f4a', 4, 'sauce', 'Nấu sốt bơ tỏi chanh nước mắm sánh thơm', 'Dùng chảo sạch trên lửa nhỏ, cho 15 g bơ lạt vào đun chảy rồi thêm tỏi băm, hành tím băm và ớt băm (nếu ăn cay) phi thơm khoảng 1 phút cho vừa dậy mùi. Rót 20 ml nước mắm ngon, 20 ml nước cốt chanh còn lại và 8 g đường cát trắng vào khuấy tan sôi lăn tăn trong 1 phút cho sốt hơi sánh.', 'Giữ lửa nhỏ khi đun chảy bơ lạt để bơ không bị cháy khét, đồng thời giúp tỏi hành dậy mùi thơm dịu.', 2),
('imp-64e505d497388f4a_v4_step_5', 'imp-64e505d497388f4a', 5, 'cook', 'Áo nhanh sốt tỏi chanh lên cá hồi', 'Đặt các miếng cá hồi vừa áp chảo trở lại chảo sốt, dùng thìa rưới liên tục phần sốt bơ tỏi chanh nóng lên mặt thịt cá khoảng 1 phút trên lửa nhỏ để hương vị ngấm đều mà vẫn giữ nguyên độ giòn của lớp da.', 'Rưới liên tục sốt bơ tỏi chanh lên mặt thịt cá thay vì nấu lâu trên bếp giúp cá hồi giữ trọn độ mọng mềm bên trong.', 1),
('imp-64e505d497388f4a_v4_step_6', 'imp-64e505d497388f4a', 6, 'finish', 'Bày đĩa cùng cà chua và dùng nóng', 'Gắp cá hồi ra đĩa, rưới toàn bộ phần sốt còn lại trong chảo lên trên, rắc hành lá thái nhỏ và 1 g tiêu đen xay còn lại, trang trí vài lát chanh và cà chua tươi bên cạnh rồi thưởng thức ngay khi nóng.', NULL, NULL),
('imp-6e4c264764981b8b_v4_step_1', 'imp-6e4c264764981b8b', 1, 'prep', 'Sơ chế thịt đùi gà và rau gia vị', 'Rửa sạch thịt đùi gà lọc xương, thấm khô rồi cắt miếng vuông vừa ăn khoảng 2,5–3 cm. Sả tươi đập dập băm nhuyễn; hành tím khô và tỏi khô băm nhỏ; ớt hiểm đỏ tươi thái lát mỏng; hành tây bóc vỏ bổ múi cau.', NULL, NULL),
('imp-6e4c264764981b8b_v4_step_2', 'imp-6e4c264764981b8b', 2, 'marinate', 'Ướp thịt đùi gà thấm vị nước mắm', 'Cho thịt đùi gà vào tô, trộn đều cùng 15 ml nước mắm ngon, 4 g hạt nêm và 1/3 lượng tỏi băm. Bọc kín và ướp trong 20 phút cho miếng gà ngấm đậm gia vị.', 'Ướp thịt gà trước với nước mắm giúp thớ thịt săn chắc, thơm nồng từ bên trong khi gặp lửa.', 20),
('imp-6e4c264764981b8b_v4_step_3', 'imp-6e4c264764981b8b', 3, 'cook', 'Phi thơm hành tím, tỏi, sả và ớt', 'Đặt chảo lên bếp lửa vừa, làm nóng 30 ml dầu ăn rồi cho hành tím băm và 2/3 phần tỏi băm còn lại vào phi thơm 30 giây. Tiếp tục thả sả băm và ớt hiểm thái lát vào đảo đều khoảng 1,5 phút đến khi sả ngả vàng nhẹ và dậy mùi thơm nồng.', 'Phi hành tỏi trước rồi mới cho sả vào giúp tất cả nguyên liệu thơm chín đều mà tỏi không bị cháy.', NULL),
('imp-6e4c264764981b8b_v4_step_4', 'imp-6e4c264764981b8b', 4, 'cook', 'Xào săn thịt gà trên lửa lớn', 'Tăng lên lửa lớn, trút toàn bộ thịt gà đã ướp vào chảo sả ớt và đảo đều tay khoảng 3 phút cho bề mặt thịt gà săn lại và áo đều sả băm thơm lừng.', NULL, 3),
('imp-6e4c264764981b8b_v4_step_5', 'imp-6e4c264764981b8b', 5, 'cook', 'Om thấm gia vị cho thịt gà chín hoàn toàn', 'Hạ xuống lửa vừa, thêm 8 g đường vàng, 4 g hạt nêm còn lại, 3 g muối ăn và 45 ml nước lọc vào chảo. Đảo đều rồi đậy nắp hờ, rim nhỏ lửa khoảng 8–10 phút cho thịt gà chín kỹ hoàn toàn từ trong ra ngoài (không còn màu hồng ở lõi) và phần nước sốt sánh sệt lại.', 'Rim gà với chút nước lọc giúp thịt đùi gà chín mềm mọng nước mà đường không bị cháy sậm.', 9),
('imp-6e4c264764981b8b_v4_step_6', 'imp-6e4c264764981b8b', 6, 'finish', 'Đảo hành tây giòn ngọt và dọn đĩa', 'Mở nắp, tăng lên lửa lớn và cho hành tây bổ múi cau vào đảo nhanh tay thêm 1,5 phút cho hành vừa chín tới vẫn giữ độ giòn ngọt. Nêm nếm lại cho vừa khẩu vị rồi tắt bếp, múc ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-53760c13ec1e452b_v4_step_1', 'imp-53760c13ec1e452b', 1, 'marinate', 'Làm sạch và ướp tôm tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch lưng rút bỏ chỉ đen rồi rửa sạch, thấm ráo nước. Cho tôm vào tô ướp với 2,5 g hạt nêm, 2 g muối ăn và một nửa lượng tiêu đen xay, trộn đều để thấm trong 10 phút.', NULL, 10),
('imp-53760c13ec1e452b_v4_step_2', 'imp-53760c13ec1e452b', 2, 'prep', 'Nhặt giá đỗ và chuẩn bị hành tỏi', 'Giá đỗ nhặt bỏ rễ và vỏ đậu nếu có, rửa nhẹ nhàng 2 lần nước rồi vẩy thật ráo để khi xào không ra nước. Hành tím khô và tỏi khô bóc vỏ băm nhỏ; hành lá rửa sạch cắt khúc dài 4 cm.', 'Để giá đỗ thật ráo nước trước khi cho vào chảo là yếu tố quyết định giúp món xào giòn khô, không bị sũng nước.', NULL),
('imp-53760c13ec1e452b_v4_step_3', 'imp-53760c13ec1e452b', 3, 'cook', 'Phi thơm hành tỏi và xào chín tôm', 'Làm nóng 20 ml dầu ăn trong chảo rộng trên lửa vừa-lớn, cho hành tím và tỏi băm vào phi thơm 30 giây. Tăng lên lửa lớn, trút tôm đã ướp vào đảo nhanh tay khoảng 2 phút đến khi tôm chuyển màu đỏ cam đều, thân cong săn chắc và chín hoàn toàn.', NULL, 2),
('imp-53760c13ec1e452b_v4_step_4', 'imp-53760c13ec1e452b', 4, 'cook', 'Xào nhanh giá đỗ lửa lớn giữ độ giòn', 'Giữ nguyên lửa lớn nhất, trút toàn bộ giá đỗ vào chảo tôm và đảo đều tay liên tục. Rưới 10 ml nước mắm ngon, thêm 2,5 g hạt nêm và 2 g muối ăn còn lại, xào nhanh trong khoảng 1,5 phút cho giá vừa chín tới mà vẫn giòn mọng.', 'Chỉ xào giá đỗ trong 1,5–2 phút trên lửa lớn để giá không bị nhũn mềm và mất nước.', NULL),
('imp-53760c13ec1e452b_v4_step_5', 'imp-53760c13ec1e452b', 5, 'cook', 'Thêm hành lá và tắt bếp ngay', 'Thả hành lá cắt khúc vào chảo, đảo nhanh tay thêm 15–20 giây cho hành vừa chín xanh và nêm nếm lại cho vừa khẩu vị rồi tắt bếp ngay.', 'Tắt bếp ngay sau khi cho hành lá vì nhiệt dư trong chảo vẫn tiếp tục làm giá chín thêm.', NULL),
('imp-53760c13ec1e452b_v4_step_6', 'imp-53760c13ec1e452b', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Gắp tôm xào giá đỗ ra đĩa, rắc phần tiêu đen xay còn lại lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-a47ef9289f5d0136_v4_step_1', 'imp-a47ef9289f5d0136', 1, 'prep', 'Thái sợi cà rốt và chuẩn bị ngò rí, hành lá', 'Cà rốt gọt vỏ, rửa sạch rồi cắt khúc dài 5 cm và thái sợi nhỏ đều nhau dày khoảng 0,3 cm. Ngò rí và hành lá rửa sạch, thái nhỏ; tách riêng phần đầu hành trắng băm nhỏ, còn ngò rí chia làm hai phần.', 'Thái sợi cà rốt đều tay giúp cà rốt chín đồng đều và dễ quyện bám lấy từng mảng trứng.', NULL),
('imp-a47ef9289f5d0136_v4_step_2', 'imp-a47ef9289f5d0136', 2, 'prep', 'Đánh tan trứng gà với gia vị', 'Đập 3 quả trứng gà ta vào tô lớn, thêm 5 ml nước mắm ngon, 3 g hạt nêm, 2 g bột ngọt, một nửa lượng tiêu đen xay và 1/2 phần ngò rí thái nhỏ. Dùng đũa đánh bông đều cho lòng đỏ và lòng trắng hòa quyện hoàn toàn.', NULL, NULL),
('imp-a47ef9289f5d0136_v4_step_3', 'imp-a47ef9289f5d0136', 3, 'cook', 'Xào chín mềm sợi cà rốt', 'Làm nóng 10 ml dầu ăn trên chảo lửa vừa, cho đầu hành lá băm vào phi thơm 20 giây. Trút cà rốt thái sợi vào đảo đều, thêm 2 g hạt nêm còn lại và 30 ml nước lọc rồi xào khoảng 4–5 phút đến khi nước cạn ráo và sợi cà rốt chín mềm ngọt thì múc ra tô riêng.', 'Xào riêng cà rốt với một chút nước giúp cà rốt chín mềm hoàn toàn và giải phóng vị ngọt tự nhiên.', 4),
('imp-a47ef9289f5d0136_v4_step_4', 'imp-a47ef9289f5d0136', 4, 'cook', 'Chiên đảo tơi trứng gà trên lửa vừa', 'Lau sạch chảo rồi đun nóng 10 ml dầu ăn còn lại ở lửa vừa-nhỏ. Rót tô trứng gà đã đánh vào chảo, chờ 20 giây cho mặt dưới hơi se lại rồi dùng đũa khuấy nhẹ tạo thành từng mảng trứng chín mềm ẩm khoảng 1,5–2 phút.', 'Giữ lửa vừa-nhỏ khi chiên trứng để trứng chín bông mềm, không bị khô xác.', 2),
('imp-a47ef9289f5d0136_v4_step_5', 'imp-a47ef9289f5d0136', 5, 'cook', 'Trộn đều cà rốt với trứng và hành lá', 'Trút toàn bộ cà rốt đã xào chín trở lại chảo trứng, đảo đều nhẹ tay khoảng 1 phút cho cà rốt và trứng quyện vào nhau đều màu. Cho phần hành lá thái nhỏ vào đảo thêm 15 giây rồi tắt bếp.', NULL, NULL),
('imp-a47ef9289f5d0136_v4_step_6', 'imp-a47ef9289f5d0136', 6, 'finish', 'Hoàn thiện hương ngò rí và dọn nóng', 'Bày cà rốt xào trứng gà ra đĩa, rắc phần ngò rí thái nhỏ và tiêu đen xay còn lại lên trên. Dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-abdcd797955a6d6a_v4_step_1', 'imp-abdcd797955a6d6a', 1, 'prep', 'Thấm khô đậu phụ và sơ chế cà chua bỏ vỏ', 'Đậu phụ rửa nhẹ dưới vòi nước, dùng khăn giấy thấm thật khô rồi cắt miếng vuông dày 1,5–2 cm. Cà chua chín khía nhẹ hình chữ thập ở đáy, chần nước sôi 1 phút rồi nhúng nước lạnh để bóc sạch vỏ, bỏ hạt và băm nhuyễn. Hành tím khô, tỏi khô và đầu hành trắng băm nhỏ; lá hành xanh và ngò rí thái nhỏ.', 'Thấm khô mặt đậu trước khi chiên giúp đậu không bị bắn dầu và dễ tạo lớp vỏ vàng giòn không nát.', NULL),
('imp-abdcd797955a6d6a_v4_step_2', 'imp-abdcd797955a6d6a', 2, 'cook', 'Áp chảo chiên vàng đều các mặt đậu phụ', 'Đun nóng 80 ml dầu ăn trong chảo chống dính trên lửa vừa. Nhẹ nhàng xếp từng miếng đậu phụ vào chiên khoảng 4–5 phút mỗi mặt cho đến khi các mặt chuyển màu vàng giòn nhẹ thì gắp ra đĩa lót giấy thấm dầu.', NULL, 5),
('imp-abdcd797955a6d6a_v4_step_3', 'imp-abdcd797955a6d6a', 3, 'sauce', 'Phi thơm hành tỏi và xào nhừ sốt cà chua', 'Chắt bớt dầu thừa ra chén, chỉ chừa lại khoảng 20 ml dầu ăn trong chảo. Cho hành tím, tỏi băm và đầu hành trắng vào phi thơm vàng nhẹ rồi trút toàn bộ cà chua băm nhuyễn vào đảo đều trên lửa vừa khoảng 4 phút đến khi cà chua nhừ ra sốt đỏ sánh.', 'Xào cà chua với chút muối ngay từ đầu giúp cà chua nhanh nhuyễn và tiết màu đỏ đẹp mắt.', 4),
('imp-abdcd797955a6d6a_v4_step_4', 'imp-abdcd797955a6d6a', 4, 'sauce', 'Nêm gia vị cân bằng sốt cà chua', 'Rót 60 ml nước lọc vào chảo cà chua, nêm 15 ml nước mắm ngon, 5 g đường cát trắng, 3 g muối ăn và 4 g hạt nêm. Khuấy đều và đun sôi liu riu khoảng 2 phút cho sốt hòa quyện đậm đà.', NULL, NULL),
('imp-abdcd797955a6d6a_v4_step_5', 'imp-abdcd797955a6d6a', 5, 'cook', 'Đảo đậu phụ thấm đều sốt cà chua', 'Nhẹ nhàng cho toàn bộ đậu phụ đã chiên vào chảo sốt cà chua, hạ lửa nhỏ và dùng đũa lật nhẹ tay để đậu áo đều sốt mà không bị vỡ nát. Đun liu riu thêm khoảng 4–5 phút cho đậu ngấm vị sốt chua ngọt.', 'Đảo nhẹ tay và đun lửa nhỏ giúp đậu phụ giữ nguyên hình khối đẹp mắt mà vẫn thấm sâu gia vị.', 5),
('imp-abdcd797955a6d6a_v4_step_6', 'imp-abdcd797955a6d6a', 6, 'finish', 'Thêm hành lá, ngò rí và dọn nóng', 'Cho hành lá thái khúc vào đảo nhẹ thêm 20 giây rồi tắt bếp. Múc đậu phụ xào cà chua ra đĩa sâu lòng, rắc ngò rí và 1,5 g tiêu đen xay lên trên, ăn nóng cùng cơm trắng.', NULL, NULL),
('imp-97f26ff4abe44f9b_v4_step_1', 'imp-97f26ff4abe44f9b', 1, 'prep', 'Ngâm nở nấm hương, mộc nhĩ và miến dong', 'Ngâm riêng 20 g nấm hương khô, 15 g mộc nhĩ khô và 70 g miến dong khô vào 350 ml nước lọc ấm trong khoảng 15 phút cho nở mềm vừa. Rửa sạch nấm hương và mộc nhĩ, cắt chân nấm, vắt thật kiệt nước rồi băm nhỏ; miến vớt ra để thật ráo rồi cắt khúc ngắn.', 'Ngâm riêng từng loại để hương nấm không lấn át nhau và bắt buộc phải vắt thật khô trước khi trộn nhân.', 15),
('imp-97f26ff4abe44f9b_v4_step_2', 'imp-97f26ff4abe44f9b', 2, 'prep', 'Bào sợi rau củ và chuẩn bị thịt cua', 'Cà rốt, củ đậu và khoai lang (nếu dùng) gọt vỏ, bào sợi thật mảnh và ngắn (giữ lại 20 g cà rốt thái lát mỏng cho nước chấm). Hành tây băm nhỏ; hành lá, rau mùi ta (nếu dùng) thái nhỏ. Kiểm tra kỹ 300 g thịt cua biển để loại bỏ hoàn toàn mảnh vỏ vụn.', 'Bào sợi mảnh giúp rau củ nhanh chín đều cùng thời gian chiên thịt cua mà vẫn giữ độ ngọt thanh.', NULL),
('imp-97f26ff4abe44f9b_v4_step_3', 'imp-97f26ff4abe44f9b', 3, 'prep', 'Trộn nhân thịt cua và lòng đỏ trứng gà', 'Trong âu lớn, trộn đều 350 g thịt nạc vai heo xay với nấm hương, mộc nhĩ, miến, cà rốt, củ đậu, khoai lang, hành tây, hành lá và rau mùi ta. Nêm 15 ml dầu ăn, 5 ml nước mắm ngon, 5 g hạt nêm và 3 g tiêu đen xay; ngay lúc chuẩn bị gói mới cho 2–3 lòng đỏ trứng gà vào trộn đều (giữ phần lòng trắng để dán mép), còn thịt cua để riêng.', NULL, NULL),
('imp-97f26ff4abe44f9b_v4_step_4', 'imp-97f26ff4abe44f9b', 4, 'prep', 'Thoa giấm loãng và gói nem cua bể hình vuông', 'Hòa 15 ml giấm gạo với 60 ml nước lọc, thoa nhẹ một lớp mỏng lên mặt bánh đa nem cho mềm dẻo rồi đặt thêm 1/4 lá vào giữa để chống vỡ. Múc 1,5 muỗng canh nhân thịt rau củ dàn thành hình vuông, đặt một phần thịt cua biển lên trên mặt nhân, gấp 4 góc bánh lại vuông vức và phết lòng trắng trứng dán kín mép.', 'Gói hơi lỏng tay một chút vì khi chiên nhân thịt và trứng sẽ nở phồng; đặt thịt cua lên trên giúp miếng nem cắt ra thấy rõ thớ cua ngon mắt.', NULL),
('imp-97f26ff4abe44f9b_v4_step_5', 'imp-97f26ff4abe44f9b', 5, 'cook', 'Rán nem ngập dầu hai lần lửa cho giòn lâu', 'Đun nóng 485 ml dầu ăn trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm. Thả nem vào rán lần 1 khoảng 7 phút cho vỏ se vàng nhạt và nhân chín khoảng 80% thì vớt ra để ráo nguội. Khi sắp dùng bữa, thả nem vào rán lại lần 2 ở lửa vừa-lớn thêm 3 phút đến khi vỏ vàng rộm giòn tan và nhân chín kỹ hoàn toàn, vớt ra giấy thấm dầu.', NULL, 10),
('imp-97f26ff4abe44f9b_v4_step_6', 'imp-97f26ff4abe44f9b', 6, 'finish', 'Pha nước chấm chua ngọt và dọn nem nóng', 'Khuấy tan 15 g đường cát trắng với 90 ml nước lọc ấm, thêm 45 ml nước mắm ngon và nước cốt của 1 quả chanh tươi cho vừa vị chua ngọt dịu, thả thêm tỏi băm, ớt băm và vài lát cà rốt mỏng vào. Cắt mỗi chiếc nem làm đôi hoặc làm tư, dọn nóng kèm rau sống và bún tươi.', NULL, NULL),
('imp-03cb4c492e643034_v4_step_1', 'imp-03cb4c492e643034', 1, 'marinate', 'Làm sạch tôm và ướp muối tiêu', 'Tôm tươi bỏ đầu, bóc vỏ, khía nhẹ dọc sống lưng để rút sạch chỉ đen rồi thấm thật ráo nước bằng khăn giấy. Ướp tôm với 1 g muối ăn và 0,5 g tiêu đen xay trong 5 phút cho thịt tôm săn và đậm đà.', NULL, 5),
('imp-03cb4c492e643034_v4_step_2', 'imp-03cb4c492e643034', 2, 'prep', 'Hòa bột bắp và đánh tan hỗn hợp trứng', 'Khuấy tan hoàn toàn 10 g bột bắp với 30 ml nước lọc trong chén nhỏ. Đập 4 quả trứng gà vào tô lớn, đổ nước bột bắp vào cùng 10 ml nước mắm ngon, 1 g muối ăn, 0,5 g tiêu đen xay, hành tím băm và hành lá thái nhỏ rồi đánh tan đều nhẹ tay.', 'Cho nước bột bắp vào trứng giúp cấu trúc trứng mềm mịn, bóng đẹp và không bị khô rách khi chiên lớp mỏng.', NULL),
('imp-03cb4c492e643034_v4_step_3', 'imp-03cb4c492e643034', 3, 'cook', 'Xào nhanh tôm tươi chín tới trên lửa lớn', 'Đun nóng 10 ml dầu ăn trong chảo chống dính trên lửa lớn, thả tôm đã ướp vào đảo nhanh tay khoảng 2 phút đến khi tôm chuyển màu đỏ hồng cong nhẹ và chín tới hoàn toàn, trút ngay ra đĩa để riêng.', 'Xào tôm nhanh ở lửa lớn giúp tôm chín săn, giữ trọn vị ngọt mà không ra nước vào trứng ở bước sau.', 2),
('imp-03cb4c492e643034_v4_step_4', 'imp-03cb4c492e643034', 4, 'cook', 'Tráng lớp trứng mỏng và xếp tôm lên mặt', 'Lau sạch chảo, đun nóng 20 ml dầu ăn còn lại trên lửa vừa rồi hạ lửa nhỏ. Đổ toàn bộ tô trứng vào, nghiêng chảo dàn đều thành lớp mỏng phủ khắp đáy chảo. Ngay khi viền và mặt trứng bắt đầu se lại nhưng mặt trên còn hơi ướt, xếp đều toàn bộ tôm đã xào lên trên mặt trứng.', NULL, NULL),
('imp-03cb4c492e643034_v4_step_5', 'imp-03cb4c492e643034', 5, 'cook', 'Đậy nắp chiên lửa nhỏ cho trứng chín đều', 'Đậy nắp chảo và chiên tiếp ở lửa nhỏ khoảng 3–4 phút cho đến khi mặt dưới vàng ươm và lớp trứng mặt trên chín đông hoàn toàn quanh từng con tôm mà không cần lật mặt.', 'Đậy nắp ở lửa nhỏ giúp hơi nhiệt tuần hoàn làm chín mặt trên của lớp trứng mỏng, tránh làm vỡ trứng khi lật.', 4),
('imp-03cb4c492e643034_v4_step_6', 'imp-03cb4c492e643034', 6, 'finish', 'Trượt trứng ra đĩa và cắt miếng thưởng thức', 'Tắt bếp, nhẹ nhàng trượt miếng trứng chiên tôm ra đĩa phẳng, cắt thành từng miếng vuông hoặc tam giác vừa ăn và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-c4a65718d5cd4b3c_v4_step_1', 'imp-c4a65718d5cd4b3c', 1, 'prep', 'Hấp chín đậu xanh, ngâm nấm và vắt ráo đậu phụ', 'Hấp chín 80 g đậu xanh cà vỏ đã ngâm mềm sao cho hạt chín bở tơi mà không nhão ướt, để nguội tán nhẹ. Ngâm 15 g mộc nhĩ khô và 40 g miến dong vào 220 ml nước ấm 12 phút cho nở mềm rồi vớt ráo, băm nhỏ mộc nhĩ và cắt ngắn miến. Chần nhanh 3 miếng đậu phụ trắng qua nước sôi, bọc khăn xô vắt thật kiệt nước rồi bóp vụn.', 'Vắt thật ráo đậu phụ và nấu đậu xanh khô tơi là bí quyết giúp nhân chả giò chay không bị chảy nước làm rách vỏ bánh.', 12),
('imp-c4a65718d5cd4b3c_v4_step_2', 'imp-c4a65718d5cd4b3c', 2, 'prep', 'Sơ chế nấm đùi gà, rau củ và xào khô nhân', 'Nấm đùi gà, khoai lang bào sợi mảnh ngắn; cà rốt bào sợi 70 g (chừa 12 g băm nhỏ cho nước chấm); củ đậu bào sợi bóp với 1 g muối ăn rồi vắt ráo; hành lá thái nhỏ. Làm nóng 20 ml dầu ăn trên lửa vừa, phi vàng hành tím (nếu dùng) vớt riêng, rồi cho đậu phụ và nấm đùi gà vào xào ráo 3 phút cùng 5 ml nước mắm chay và 2 g hạt nêm chay nấm hương.', NULL, 3),
('imp-c4a65718d5cd4b3c_v4_step_3', 'imp-c4a65718d5cd4b3c', 3, 'prep', 'Trộn hoàn chỉnh nhân và pha hồ dán mép', 'Trong âu lớn, trộn nhẹ tay đậu phụ nấm vừa xào nguội bớt cùng đậu xanh, mộc nhĩ, miến, khoai lang, củ đậu, cà rốt sợi, hành lá, hành phi, 3 g hạt nêm chay còn lại, 1 g muối ăn, 4 g đường và 2 g tiêu đen xay. Hòa 16 g bột mì đa dụng với 30 ml nước lọc thành hồ sệt để dán mép bánh.', NULL, NULL),
('imp-c4a65718d5cd4b3c_v4_step_4', 'imp-c4a65718d5cd4b3c', 4, 'prep', 'Cuốn chả giò chay chặt vừa tay', 'Trải từng lá bánh tráng lên mặt phẳng sạch (có thể lót thêm 1/2 lá vào giữa nếu vỏ mỏng), múc khoảng 1,5 muỗng canh nhân đặt vào đầu bánh, gấp hai mép bên rồi cuộn tròn đều tay thành khoảng 20 cuốn vừa ăn, phết hồ bột mì dán kín mép ngoài.', 'Cuốn chả giò có độ chặt vừa phải, kích thước đồng đều để khi thả vào chảo dầu chín vàng cùng lúc.', NULL),
('imp-c4a65718d5cd4b3c_v4_step_5', 'imp-c4a65718d5cd4b3c', 5, 'cook', 'Chiên chả giò ngập dầu hai lần lửa', 'Đun nóng 480 ml dầu ăn trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm. Thả chả giò vào chiên lần 1 khoảng 5 phút đến khi vỏ se vàng nhạt thì vớt ra giá để nguội. Trước khi ăn, chiên lại lần 2 ở lửa vừa-lớn thêm 3 phút cho đến khi vỏ vàng ruộm giòn rụm đều các mặt, vớt ra giấy thấm dầu.', 'Chiên ngập dầu hai lần lửa giúp vỏ bánh tráng giòn xốp lâu hơn hẳn và không bị ỉu khi chấm nước mắm chay.', 8),
('imp-c4a65718d5cd4b3c_v4_step_6', 'imp-c4a65718d5cd4b3c', 6, 'finish', 'Nấu nước mắm chay chua ngọt và dọn ăn nóng', 'Đun sôi nhẹ 50 ml nước mắm chay với 26 g đường cát trắng còn lại và 50 ml nước lọc cho tan sánh rồi tắt bếp để nguội hẳn. Khi nguội, khuấy vào nước cốt của 1 quả chanh tươi cùng cà rốt băm nhuyễn, tỏi băm và ớt băm (nếu dùng). Dọn chả giò chay nóng giòn ăn kèm rau sống và bún.', 'Luôn đợi nước mắm chay nguội hẳn mới khuấy nước cốt chanh vào để giữ vị chua thanh và không bị đắng.', NULL),
('imp-f3c2431be267b74d_v4_step_1', 'imp-f3c2431be267b74d', 1, 'prep', 'Làm sạch cá điêu hồng và khứa thân', 'Đánh sạch vảy, bỏ mang, moi ruột và cạo sạch màng đen dọc khoang bụng cá điêu hồng. Chà xát 10 g muối hạt đều khắp trong ngoài thân cá trong 2 phút để khử sạch nhớt tanh, xả lại dưới vòi nước lạnh rồi thấm thật khô, khứa 3 đường chéo nông trên mỗi mặt cá.', 'Thấm thật ráo nước trên thân cá sau khi rửa muối giúp sốt ướp bám chặt vào từng thớ thịt và cá giữ được độ săn ngọt.', NULL),
('imp-f3c2431be267b74d_v4_step_2', 'imp-f3c2431be267b74d', 2, 'prep', 'Sơ chế dứa chín, gừng, hành tây và rau thơm', 'Gọt vỏ nửa quả dứa chín, bỏ mắt và lõi cứng rồi thái lát mỏng dày 0,5 cm. Cạo vỏ gừng: 15 g thái lát mỏng, 25 g thái sợi chỉ. Hành tây bóc vỏ cắt múi cau mỏng; hành tím thái lát mỏng; ớt sừng bỏ hạt thái sợi; hành lá và thì là rửa sạch cắt khúc 4 cm.', NULL, NULL),
('imp-f3c2431be267b74d_v4_step_3', 'imp-f3c2431be267b74d', 3, 'marinate', 'Pha sốt và ướp cá điêu hồng thấm gia vị', 'Khuấy tan hỗn hợp gồm 30 ml nước mắm ngon, 15 ml xì dầu, 15 ml dầu hào, 8 g đường cát trắng, 4 g hạt nêm và 2 g tiêu đen xay. Thoa đều sốt lên khắp hai mặt thân cá và cả bên trong bụng cá, nhét phần gừng thái lát và hành tím thái lát vào bụng rồi ướp 20 phút cho ngấm.', 'Ướp cá đủ 20 phút và thoa sốt vào cả các đường khứa giúp thịt cá phía sát xương cũng đậm đà hương vị.', 20),
('imp-f3c2431be267b74d_v4_step_4', 'imp-f3c2431be267b74d', 4, 'cook', 'Xếp dứa lót đáy và hấp cá lửa lớn', 'Xếp một nửa số lát dứa chín và hành tây cắt múi xuống đáy đĩa sâu lòng chịu nhiệt, đặt cá đã ướp lên trên, rưới nốt phần sốt ướp còn thừa cùng phần dứa, hành tây, gừng sợi và ớt thái sợi phủ mặt cá. Đun sôi 700 ml nước lọc trong nồi hấp ở lửa lớn, đặt đĩa cá vào xửng đậy kín nắp và hấp 18 phút.', 'Lót dứa và hành tây dưới bụng cá vừa ngăn da cá bị dính đĩa, vừa giúp hơi nóng lưu thông đều và tiết nước ngọt tự nhiên.', 18),
('imp-f3c2431be267b74d_v4_step_5', 'imp-f3c2431be267b74d', 5, 'cook', 'Thêm hành lá, thì là hấp chín tới', 'Mở nắp xửng, xếp hành lá và thì là cắt khúc lên mặt cá, đậy nắp hấp tiếp thêm 3 phút trên lửa vừa đến khi mắt cá đục trắng, dùng đũa tách nhẹ thấy thịt cá trắng đục chín mềm và rau thơm vừa chín tới vẫn giữ màu xanh mướt.', NULL, 3),
('imp-f3c2431be267b74d_v4_step_6', 'imp-f3c2431be267b74d', 6, 'finish', 'Rưới dầu mè thơm và dọn thưởng thức nóng', 'Nhấc đĩa cá ra khỏi nồi hấp cẩn thận, rưới 5 ml dầu mè thơm đều lên thân cá cho dậy mùi hấp dẫn, chan nhẹ nước hấp dứa chua ngọt xung quanh và dùng nóng ngay với cơm trắng hoặc cuốn bánh tráng rau sống.', NULL, NULL),
('imp-6118e8aa010584af_v4_step_1', 'imp-6118e8aa010584af', 1, 'marinate', 'Làm sạch và ướp tôm tươi thái hạt lựu', 'Tôm tươi bóc sạch vỏ, bỏ đầu và rút chỉ đen dọc lưng, rửa qua nước muối loãng rồi thấm thật ráo. Thái tôm thành hạt lựu nhỏ (hoặc băm thô) để giữ độ giòn ngọt, ướp tôm với 4 ml nước mắm và 1 g tiêu đen xay trong 10 phút cho thấm vị.', NULL, 10),
('imp-6118e8aa010584af_v4_step_2', 'imp-6118e8aa010584af', 2, 'prep', 'Đánh nhẹ trứng gà với nước lọc theo tỉ lệ chuẩn', 'Đập 4 quả trứng gà vào tô sạch, thêm 240 ml nước lọc nguội, 6 ml nước mắm còn lại và 4 g hạt nêm. Dùng đũa khuấy thật nhẹ nhàng theo một chiều cho gia vị tan đều mà không đánh nổi bọt khí quá nhiều.', 'Tỉ lệ khoảng 1,5 phần nước nguội so với 1 phần ruột trứng là bí quyết giúp món trứng hấp mềm rung rinh như tàu hũ non.', NULL),
('imp-6118e8aa010584af_v4_step_3', 'imp-6118e8aa010584af', 3, 'prep', 'Lọc rây trứng và dàn tôm lên mặt tô', 'Rót hỗn hợp trứng qua rây lưới mịn vào đĩa sâu lòng hoặc tô sứ chịu nhiệt để loại bỏ lợn cợn và bọt khí, dùng thìa hớt sạch phần bọt nhỏ nếu còn sót trên bề mặt. Nhẹ nhàng rải đều phần tôm đã ướp lên mặt trứng rồi bọc kín miệng tô bằng màng bọc thực phẩm chịu nhiệt (hoặc đậy đĩa vừa khít).', 'Bọc kín miệng tô bằng màng bọc chịu nhiệt giúp hơi nước ngưng tụ từ nắp nồi không nhỏ giọt làm rỗ bề mặt trứng hấp.', NULL),
('imp-6118e8aa010584af_v4_step_4', 'imp-6118e8aa010584af', 4, 'cook', 'Hấp cách thủy lửa nhỏ cho trứng mịn mượt', 'Đun sôi 600 ml nước lọc trong nồi hấp rồi hạ ngay xuống lửa nhỏ liu riu, đặt tô trứng vào xửng và đậy nắp hấp khoảng 16 phút. Hơi nóng dịu nhẹ sẽ làm trứng đông mịn dần và thịt tôm chín đỏ au nổi đẹp trên bề mặt.', 'Không để nước sôi quá mạnh hoặc đậy nắp kín hoàn toàn không thoát hơi khi không dùng màng bọc, vì hơi nước mạnh sẽ làm mặt trứng bị rỗ.', 16),
('imp-6118e8aa010584af_v4_step_5', 'imp-6118e8aa010584af', 5, 'prep', 'Chẻ hành lá trang trí tạo độ tươi xanh', 'Trong lúc chờ trứng chín, rửa sạch hành lá tươi, thái nhỏ một nửa và chẻ sợi phần còn lại ngâm nhanh vào chén nước mát cho xoăn nhẹ rồi vớt ra để ráo.', NULL, NULL),
('imp-6118e8aa010584af_v4_step_6', 'imp-6118e8aa010584af', 6, 'finish', 'Kiểm tra độ chín và hoàn thiện món ăn', 'Thử xiên tăm vào giữa tô trứng thấy tăm khô sạch không dính dịch lỏng và tôm đã chuyển đỏ hoàn toàn là đạt. Nhấc tô trứng ra, rắc hành lá tươi, 1 g tiêu đen xay còn lại và rưới 5 ml dầu mè thơm lên trên rồi thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-4ced29ad30507f2c_v4_step_1', 'imp-4ced29ad30507f2c', 1, 'cook', 'Luộc chín thịt ba chỉ và ngâm mát giữ độ trắng giòn', 'Chà xát thịt ba chỉ với 2 g muối ăn rồi rửa sạch. Đun sôi 1080 ml nước lọc với 1 g muối ăn trên lửa lớn, thả thịt ba chỉ vào luộc ở lửa vừa khoảng 18 phút đến khi xiên đũa qua thịt không còn nước hồng. Vớt thịt ra ngâm ngay vào nước nguội sạch 10 phút cho thịt trắng săn rồi thái lát thật mỏng.', 'Ngâm thịt ba chỉ trong nước mát ngay sau khi luộc giúp thớ thịt săn chắc, phần mỡ trong giòn và dễ thái lát mỏng đẹp.', 18),
('imp-4ced29ad30507f2c_v4_step_2', 'imp-4ced29ad30507f2c', 2, 'cook', 'Luộc chín tôm tươi và chẻ đôi dọc lưng', 'Cho tôm tươi đã rửa sạch vào nồi nước luộc thịt đang sôi ở lửa vừa, đậy vung luộc khoảng 4 phút đến khi tôm chuyển màu đỏ cam đều và chín kỹ hoàn toàn. Vớt tôm ra để nguội, bóc bỏ vỏ, rút chỉ đen trên lưng rồi chẻ đôi theo chiều dọc.', NULL, 4),
('imp-4ced29ad30507f2c_v4_step_3', 'imp-4ced29ad30507f2c', 3, 'prep', 'Sơ chế rau sống, giá đỗ và dưa leo', 'Ngâm xà lách, rau húng quế, ngò gai, hẹ lá và giá đỗ với nước pha 3 g muối ăn trong 5 phút rồi xả sạch nhiều lần, vẩy thật ráo nước. Dưa leo rửa sạch, bỏ phần ruột mềm rồi thái thanh dài mỏng. Tách bún tươi thành từng lọn nhỏ vừa cuốn.', 'Rau sống phải được vẩy thật ráo nước trước khi cuốn để tránh làm ướt mềm quá mức khiến bánh tráng dễ bị rách.', NULL),
('imp-4ced29ad30507f2c_v4_step_4', 'imp-4ced29ad30507f2c', 4, 'sauce', 'Pha nước mắm chanh tỏi ớt nổi đẹp', 'Hòa tan 50 ml nước mắm ngon với 25 g đường cát trắng và 120 ml nước lọc đến khi đường tan hết. Thêm nước cốt 1 quả chanh tươi, tỏi băm nhuyễn và ớt hiểm băm nhỏ vào sau cùng để tỏi ớt nổi đều trên mặt chén nước chấm.', NULL, NULL),
('imp-4ced29ad30507f2c_v4_step_5', 'imp-4ced29ad30507f2c', 5, 'prep', 'Làm mềm bánh tráng và xếp lớp nhân', 'Nhúng nhanh từng lá bánh tráng mỏng qua nước ấm sạch cho vừa dẻo rồi trải phẳng lên thớt sạch. Xếp 1 lá xà lách, vài cọng rau húng quế, ngò gai, giá đỗ, dưa leo, một ít bún tươi và 2–3 lát thịt ba chỉ vào mép dưới bánh.', NULL, NULL),
('imp-4ced29ad30507f2c_v4_step_6', 'imp-4ced29ad30507f2c', 6, 'finish', 'Cuộn tròn chặt tay và trình bày ra đĩa', 'Gập hai mép bên bánh tráng vào trong, cuộn tròn từ dưới lên 1 vòng cho gọn chắc, tiếp tục đặt 2 nửa con tôm úp mặt đỏ xuống dưới cùng 2 cọng hẹ lá thò đầu ra ngoài rồi cuộn chặt đến hết lá bánh. Lặp lại cho đến hết nguyên liệu, xếp gỏi cuốn ra đĩa dùng ngay với nước mắm tỏi ớt.', 'Làm mềm từng lá bánh tráng ngay trước khi cuốn và xếp lượng nhân vừa phải để cuốn gỏi tròn đều, không bị phồng rách.', NULL),
('imp-3a06ac78b572f3ae_v4_step_1', 'imp-3a06ac78b572f3ae', 1, 'prep', 'Sơ chế dưa leo và cà rốt ngâm đá giòn', 'Rửa sạch dưa leo, cắt hai đầu và chà xát vòng tròn đến khi ra bọt trắng để khử vị đắng rồi rửa sạch. Bổ đôi dưa leo, nạo bỏ ruột, thái lát mỏng; cà rốt gọt vỏ bào sợi mảnh. Ngâm cả hai vào thau nước đá với 400 ml nước lọc và 4 g muối ăn trong 10 phút rồi vớt ra vắt ráo nước.', 'Ngâm dưa leo và cà rốt trong nước đá muối giúp sợi rau củ giòn lâu, giữ màu tươi sáng và hạn chế ra nước sau khi trộn.', 10),
('imp-3a06ac78b572f3ae_v4_step_2', 'imp-3a06ac78b572f3ae', 2, 'cook', 'Rim chín tôm tươi giữ độ ngọt giòn', 'Làm sạch tôm, rút bỏ chỉ đen trên sống lưng rồi để ráo. Làm nóng chảo trên lửa vừa, cho tôm và 2 g muối ăn vào rim đảo đều khoảng 5 phút đến khi tôm chuyển màu đỏ cam đều, chín săn hoàn toàn thì tắt bếp, để nguội bóc vỏ và chẻ đôi.', 'Rim tôm vừa chín tới trên lửa vừa giúp tôm không bị teo khô mà giữ trọn vị ngọt đậm tự nhiên.', 5),
('imp-3a06ac78b572f3ae_v4_step_3', 'imp-3a06ac78b572f3ae', 3, 'sauce', 'Giã tỏi ớt hiểm pha nước mắm chua cay', 'Cho 48 g đường cát trắng, tỏi khô và 3 quả ớt hiểm vào cối giã thật nhuyễn. Trút ra bát, hòa thêm 45 ml nước mắm ngon, 15 ml tương ớt và nước cốt 2 quả chanh tươi, khuấy tan hoàn toàn để tạo bát nước trộn sánh thơm.', NULL, NULL),
('imp-3a06ac78b572f3ae_v4_step_4', 'imp-3a06ac78b572f3ae', 4, 'prep', 'Rang đậu phộng và cắt nhỏ rau thơm', 'Rang chín vàng đậu phộng trên lửa nhỏ, để nguội xát sạch vỏ lụa rồi giã dập vừa. Nhặt rửa sạch rau húng lủi và húng quế, vẩy ráo nước rồi cắt nhỏ. Chuẩn bị sẵn bánh phồng tôm giòn ăn kèm.', NULL, NULL),
('imp-3a06ac78b572f3ae_v4_step_5', 'imp-3a06ac78b572f3ae', 5, 'prep', 'Trộn thấm dưa leo, cà rốt và tôm rim', 'Cho dưa leo, cà rốt đã vắt ráo và tôm rim vào tô lớn, rưới đều bát nước trộn mắm chanh ớt vào, đeo găng tay trộn nhẹ nhàng rồi để yên 8 phút cho các nguyên liệu ngấm vị chua cay mặn ngọt.', NULL, 8),
('imp-3a06ac78b572f3ae_v4_step_6', 'imp-3a06ac78b572f3ae', 6, 'finish', 'Trộn rau thơm, rắc đậu phộng và thưởng thức', 'Thêm rau húng lủi và húng quế cắt nhỏ vào tô nộm, đảo đều nhẹ tay lần cuối để rau giữ màu xanh tươi. Gắp nộm ra đĩa, rắc đậu phộng rang giã dập lên trên và dọn ăn ngay kèm bánh phồng tôm.', 'Chỉ cho rau thơm vào trộn ở bước cuối để lá rau không bị dập nát hay thâm màu.', NULL),
('imp-21f32dccd464c605_v4_step_1', 'imp-21f32dccd464c605', 1, 'prep', 'Làm sạch gà và nướng rang hương liệu', 'Xát 10 g muối ăn cùng 20 g gừng tươi đập dập lên khắp mình và trong bụng gà ta, để 5 phút rồi rửa thật sạch dưới vòi nước lạnh và để ráo. Nướng 1/2 củ hành tây, 40 g gừng tươi và hành tím khô đến khi sém vàng thơm, cạo sạch cháy. Rang hạt mùi khô (cùng quế thanh và hoa hồi nếu thích) trên chảo khô lửa nhỏ 2 phút đến khi thơm rồi bọc vào túi vải sạch.', NULL, 10),
('imp-21f32dccd464c605_v4_step_2', 'imp-21f32dccd464c605', 2, 'cook', 'Luộc gà ta chín tới giữ da vàng giòn', 'Cho gà ta và 3 lít nước lọc lạnh vào nồi lớn cùng 5 g muối ăn, đun lửa vừa cho nước nóng lên từ từ; khi nước sôi lăn tăn thì hớt sạch bọt, mở hé vung và hạ lửa nhỏ liu riu luộc khoảng 30–35 phút. Xiên đũa vào phần thịt dày nhất ở đùi thấy không chảy nước hồng là gà chín hoàn toàn.', 'Luộc gà ở nhiệt độ sôi lăn tăn và mở hé nắp giúp nước dùng trong veo, thịt gà mềm mọng không bị bã.', 35),
('imp-21f32dccd464c605_v4_step_3', 'imp-21f32dccd464c605', 3, 'cook', 'Ngâm nguội gà, lọc xương và ninh nước dùng', 'Vớt gà ra ngâm nhanh vào thau nước lọc nguội 5 phút cho da gà giòn săn rồi vớt ráo, lọc lấy toàn bộ phần thịt và giữ lại phần xương. Cho xương gà cùng túi thảo mộc, hành tây nướng, gừng nướng và hành tím nướng vào nồi nước luộc, tiếp tục ninh lửa nhỏ thêm 35 phút cho nước dùng ngọt sâu rồi vớt bỏ hết xương và túi gia vị, lọc qua rây cho thật trong.', 'Trả phần xương gà sau khi lọc vào ninh thêm giúp nước dùng phở gà đậm vị ngọt tự nhiên mà thịt gà vẫn mềm.', 35),
('imp-21f32dccd464c605_v4_step_4', 'imp-21f32dccd464c605', 4, 'cook', 'Nêm hoàn thiện nồi nước dùng phở gà', 'Nêm vào nồi nước dùng đã lọc 5 g muối ăn còn lại, 15 g đường phèn, 10 g hạt nêm và 30 ml nước mắm ngon, khuấy đều cho tan hết rồi đun sôi nhẹ lại, nếm vị thanh ngọt vừa miệng và giữ nóng trên bếp.', 'Cho nước mắm ngon vào bước cuối giúp giữ được mùi thơm đặc trưng và không làm chua nước dùng.', NULL),
('imp-21f32dccd464c605_v4_step_5', 'imp-21f32dccd464c605', 5, 'prep', 'Chuẩn bị bánh phở, xé gà và rau thơm', 'Ngâm bánh phở khô rồi chần qua nước sôi cho mềm tơi, xả nhanh nước nguội rồi tráng lại nước nóng cho ráo. Thái miếng hoặc xé sợi phần thịt gà đã nguội. Thái lát thật mỏng 1/2 củ hành tây còn lại ngâm nước đá cho giòn; chẻ đầu hành lá, thái nhỏ lá hành, ngò rí; thái chỉ lá chanh tươi; trụng sơ giá đỗ và cắt múi chanh tươi, thái lát ớt tươi.', NULL, NULL),
('imp-21f32dccd464c605_v4_step_6', 'imp-21f32dccd464c605', 6, 'finish', 'Xếp tô phở gà phố cổ và thưởng thức', 'Chia bánh phở vào 4 tô lớn, xếp thịt gà ta lên trên, điểm đầu hành chẻ, hành tây thái mỏng, hành lá, ngò rí và lá chanh thái chỉ. Chan ngập nước dùng đang sôi sùng sục vào từng tô và dọn nóng ngay kèm giá đỗ, chanh tươi và ớt tươi.', NULL, NULL),
('imp-ba737c5583985a50_v4_step_1', 'imp-ba737c5583985a50', 1, 'prep', 'Chần xương bò, rang hương liệu và sơ chế sả', 'Chần xương ống bò với 500 ml nước sôi và 3 g muối ăn trong 5 phút rồi xả sạch dưới vòi nước lạnh. Đập dập 5 cây sả tươi, băm nhuyễn 3 cây sả còn lại cùng ớt hiểm tươi và tỏi khô. Rang thơm 1/2 củ hành tây, gừng tươi đập dập và 25 g hành tím khô trên chảo khô.', NULL, 8),
('imp-ba737c5583985a50_v4_step_2', 'imp-ba737c5583985a50', 2, 'marinate', 'Ướp và xào săn thịt nạm bò', 'Ướp nguyên miếng thịt nạm bò với 1/3 lượng sả tỏi ớt băm, 3 g hạt nêm, 5 ml dầu màu điều và 1 g tiêu đen xay trong 20 phút. Làm nóng chảo với 10 ml dầu ăn trên lửa lớn, cho thịt nạm vào áp chảo xào săn đều các mặt cho dậy mùi thơm rồi gắp ra.', NULL, 20),
('imp-ba737c5583985a50_v4_step_3', 'imp-ba737c5583985a50', 3, 'cook', 'Hầm xương bò và nạm bò mềm ngọt', 'Cho xương ống bò, hành tây gừng hành tím đã rang cùng 5 cây sả đập dập vào nồi với 2,25 lít nước lọc, đun sôi rồi hạ lửa nhỏ hầm 60 phút và hớt bọt thường xuyên. Tiếp theo thả miếng nạm bò đã xào săn vào hầm chung thêm 50 phút đến khi nạm bò chín mềm vừa ăn thì vớt ra để nguội, thái lát mỏng.', 'Xào săn nạm bò trước khi hầm giúp thịt giữ vị ngọt đậm và bề mặt thơm mùi sả ớt hơn.', 110),
('imp-ba737c5583985a50_v4_step_4', 'imp-ba737c5583985a50', 4, 'sauce', 'Lọc mắm ruốc Huế và nấu sa tế sả ớt', 'Hòa 18 g mắm ruốc Huế với 250 ml nước lọc, để lắng 10 phút rồi gạn lấy phần nước trong cho vào nồi nước dùng, bỏ cặn. Đun nóng 30 ml dầu ăn và 10 ml dầu màu điều trên lửa vừa, phi thơm 25 g hành tím băm, phần tỏi băm và sả băm còn lại đến vàng thơm rồi hạ lửa nhỏ cho 10 g ớt bột khô vào đảo nhanh. Cho một nửa sa tế vào nồi nước dùng; nửa còn lại trộn thêm phần ớt hiểm tươi băm còn lại, 2 g muối ăn và 5 g đường phèn thành sa tế ăn kèm.', 'Lắng kỹ mắm ruốc chỉ lấy phần nước trong để nồi bún bò thơm đặc trưng mà không bị sạn đục.', NULL),
('imp-ba737c5583985a50_v4_step_5', 'imp-ba737c5583985a50', 5, 'cook', 'Nêm nước dùng và luộc viên thịt heo xay', 'Vớt bỏ xương ống bò và sả gừng khỏi nồi nước dùng, nêm 25 g đường phèn còn lại, 5 g hạt nêm, 3 g muối ăn và 25 ml nước mắm ngon cho vị đậm đà cay thơm hài hòa. Quết kỹ 200 g thịt heo xay với 5 ml nước mắm ngon và 1 g tiêu đen xay đến khi dẻo quánh, vo thành từng viên nhỏ thả vào nồi nước dùng đang sôi nhẹ khoảng 5 phút đến khi viên thịt nổi lên chín kỹ hoàn toàn.', 'Quết đều thịt heo xay giúp viên mọc dai giòn tự nhiên khi nấu chín trong nước dùng.', 6),
('imp-ba737c5583985a50_v4_step_6', 'imp-ba737c5583985a50', 6, 'finish', 'Trụng bún, sắp tô và dọn nóng', 'Trụng bún sợi to qua nước sôi cho nóng tơi rồi chia vào 4 tô. Xếp thịt nạm bò thái lát và viên giò sống lên trên, chan nước dùng nóng hổi ngập mặt bún, rắc hành lá, rau răm và 1/2 củ hành tây thái thật mỏng. Dọn kèm giá đỗ, chanh tươi và chén sa tế sả ớt.', NULL, NULL),
('imp-37a39eaa1edcd2e4_v4_step_1', 'imp-37a39eaa1edcd2e4', 1, 'prep', 'Chần xương heo và nướng khô mực', 'Rửa sạch xương ống heo rồi chần qua 500 ml nước sôi với 2 g muối ăn trong 4 phút để loại bỏ bọt bẩn, vớt ra rửa lại dưới vòi nước lạnh. Nướng khô mực trên lửa nhỏ khoảng 2 phút đến khi dậy mùi thơm và hơi xém cạnh thì xé làm bốn; rửa sạch tôm khô.', NULL, 6),
('imp-37a39eaa1edcd2e4_v4_step_2', 'imp-37a39eaa1edcd2e4', 2, 'cook', 'Ninh nước lèo xương heo cùng củ cải và mực khô', 'Cho xương ống heo vào nồi với 2,1 lít nước lọc lạnh, thêm tôm khô, khô mực nướng, củ cải trắng cắt khúc, cà rốt cắt khúc và đầu hành lá đập dập. Đun sôi nhẹ rồi hạ lửa vừa hầm khoảng 75 phút, thường xuyên hớt bọt để nước lèo thật trong. Vớt bỏ xương, củ cải, cà rốt và xác mực tôm khô rồi nêm 25 g đường phèn, 8 g muối ăn, 10 g hạt nêm và 25 ml nước mắm ngon.', 'Giữ nồi nước lèo sôi lăn tăn nhẹ thay vì sôi bùng mạnh để củ cải và xương tiết vị ngọt mà nước vẫn trong vắt.', 75),
('imp-37a39eaa1edcd2e4_v4_step_3', 'imp-37a39eaa1edcd2e4', 3, 'cook', 'Luộc thịt ba chỉ, tôm tươi và trứng cút', 'Luộc chín thịt ba chỉ heo với chút nước và 2 g muối ăn khoảng 20 phút đến khi thịt chín kỹ, vớt ra ngâm nước đá lạnh cho săn trắng rồi thái lát mỏng. Trong nồi nước sôi khác, luộc trứng cút 8 phút rồi bóc vỏ bổ đôi; tiếp tục trụng luộc tôm tươi khoảng 3 phút đến khi chuyển màu hồng cam chín đều thì vớt ra bóc vỏ chừa đuôi, bỏ chỉ lưng.', NULL, 20),
('imp-37a39eaa1edcd2e4_v4_step_4', 'imp-37a39eaa1edcd2e4', 4, 'cook', 'Phi tỏi vàng giòn và xào thịt heo xay', 'Đun nóng 40 ml dầu ăn trong chảo nhỏ ở lửa vừa, cho tỏi khô băm vào đảo đều tay đến khi vừa chuyển màu vàng nhạt thì tắt bếp và vớt ngay phần tỏi phi ra chén (giữ lại dầu tỏi). Chắt 1 muỗng canh dầu tỏi ra riêng, phần còn lại trên chảo phi thơm hành tím khô băm rồi cho thịt heo xay vào xào săn tơi khoảng 4 phút với 5 ml nước mắm ngon.', 'Vớt tỏi phi ngay khi vừa ngả vàng rơm để nhiệt dư làm tỏi giòn đều mà không bị cháy đắng.', NULL),
('imp-37a39eaa1edcd2e4_v4_step_5', 'imp-37a39eaa1edcd2e4', 5, 'prep', 'Trụng hủ tiếu khô và chuẩn bị rau ăn kèm', 'Trụng hủ tiếu khô qua nồi nước sôi khoảng 2–3 phút cho vừa mềm dai, vớt ra xả nhanh nước lạnh cho ráo rồi trộn ngay với 1 muỗng canh dầu tỏi phi để sợi tơi bóng. Rửa sạch giá đỗ, rau tần ô, cắt khúc hẹ lá, cần tây, hành lá và cắt múi chanh tươi.', 'Xả nhanh hủ tiếu qua nước lạnh rồi trộn dầu tỏi phi giúp sợi dai bóng và không bị vón cục khi chia tô.', NULL),
('imp-37a39eaa1edcd2e4_v4_step_6', 'imp-37a39eaa1edcd2e4', 6, 'finish', 'Xếp tô hủ tiếu Nam Vang và chan nước lèo', 'Chia hủ tiếu vào 4 tô, xếp thịt ba chỉ thái lát, thịt heo xay xào, tôm luộc và trứng cút bổ đôi lên trên. Chan nước lèo đang sôi sùng sục ngập mặt hủ tiếu, thêm chút tỏi phi thơm vào tô và rắc hành lá, hẹ lá, cần tây; dọn nóng ngay kèm giá đỗ, rau tần ô và chanh tươi.', NULL, NULL),
('imp-0efa407066cdc8dd_v4_step_1', 'imp-0efa407066cdc8dd', 1, 'marinate', 'Làm sạch nhớt và ướp cá lóc với nghệ', 'Đánh sạch vảy, bỏ mang và cạo sạch màng đen trong bụng cá lóc tươi. Chà xát mình cá với 4 g muối ăn trong 2 phút cho hết nhớt rồi rửa sạch dưới vòi nước lạnh, thấm ráo và cắt khúc dày 3 cm. Ướp cá nhẹ tay với 3 g bột nghệ, 15 ml nước mắm ngon và 2 g muối ăn trong 15 phút.', 'Thấm thật ráo khúc cá trước khi ướp và chiên giúp cá không bị bắn dầu và giữ được lớp da nguyên vẹn.', 15),
('imp-0efa407066cdc8dd_v4_step_2', 'imp-0efa407066cdc8dd', 2, 'prep', 'Sơ chế cà chua, dứa và rau thơm', 'Cà chua chín bổ múi cau; dứa cắt lát xéo vừa ăn; băm nhỏ hành tím khô và tỏi khô. Rửa sạch hành lá, thì là tươi và ngò rí rồi thái khúc 2 cm; thái lát mỏng ớt tươi.', NULL, NULL),
('imp-0efa407066cdc8dd_v4_step_3', 'imp-0efa407066cdc8dd', 3, 'cook', 'Chiên áp chảo sơ từng khúc cá lóc', 'Đun nóng 30 ml dầu ăn trên chảo chống dính ở lửa vừa, xếp các khúc cá lóc đã ướp vào áp chảo mỗi mặt khoảng 2 phút đến khi bề mặt cá se vàng nhẹ thì nhẹ nhàng gắp ra đĩa riêng.', 'Chiên áp chảo sơ qua giúp thịt cá săn chắc, không bị vỡ nát khi thả vào nồi nước dùng sôi.', 4),
('imp-0efa407066cdc8dd_v4_step_4', 'imp-0efa407066cdc8dd', 4, 'cook', 'Xào cà chua, dứa và nấu nước dùng', 'Trong nồi lớn, làm nóng 15 ml dầu ăn còn lại, phi thơm hành tím và tỏi băm trên lửa vừa rồi cho cà chua và dứa vào xào 4 phút đến khi cà chua mềm tiết màu đỏ cam đẹp mắt. Đổ 1,6 lít nước lọc vào đun lửa lớn đến khi sôi bùng.', NULL, 4),
('imp-0efa407066cdc8dd_v4_step_5', 'imp-0efa407066cdc8dd', 5, 'cook', 'Nấu chín cá và nêm nước dùng chua ngọt', 'Hạ lửa vừa, nhẹ nhàng thả các khúc cá đã chiên sơ vào nồi nước sôi, nấu liu riu khoảng 8–10 phút đến khi thịt cá chín trắng hoàn toàn và hớt sạch bọt. Vớt nhẹ cá ra đĩa để tránh nát, nêm nồi nước dùng với 20 ml nước mắm ngon, 2 g muối ăn còn lại và 6 g đường cát trắng cho vị chua thanh hài hòa.', 'Không khuấy đảo mạnh tay sau khi cho cá vào nồi để từng khúc cá giữ trọn hình dáng đẹp mắt.', 10),
('imp-0efa407066cdc8dd_v4_step_6', 'imp-0efa407066cdc8dd', 6, 'finish', 'Trụng bún tươi và chan nước dùng nóng', 'Trụng nhanh bún gạo tươi qua nồi nước sôi khác trong 1 phút cho mềm tơi rồi chia đều vào 4 tô. Xếp các khúc cá lóc lên mặt bún, chan ngập nước dùng cà chua dứa đang sôi, rắc hành lá, thì là tươi, ngò rí và ớt tươi thái lát rồi thưởng thức ngay khi nóng.', NULL, NULL),
('imp-b6aeb931b882e8a3_v4_step_1', 'imp-b6aeb931b882e8a3', 1, 'cook', 'Vo gạo và nấu chín cơm trắng dẻo', 'Vo nhẹ 450 g gạo tẻ thơm qua 2 lần nước sạch để giữ lớp cám dinh dưỡng, cho vào nồi cơm điện cùng 600 ml nước lọc rồi bật chế độ nấu khoảng 25 phút. Khi cơm chín, để chế độ giữ ấm thêm 5 phút rồi xới tơi.', 'Trong lúc chờ nồi cơm chín, tận dụng thời gian sơ chế và kho đậu nấm để món mặn vừa xong kịp bữa.', 25),
('imp-b6aeb931b882e8a3_v4_step_2', 'imp-b6aeb931b882e8a3', 2, 'prep', 'Sơ chế nấm đùi gà, đậu phụ và pha nước kho', 'Nấm đùi gà cắt bỏ gốc, rửa nhanh dưới vòi nước lạnh rồi để ráo, thái lát dày 0,8–1 cm. Đậu phụ trắng thấm khô, cắt miếng vuông cạnh 3 cm. Hành lá tách đầu trắng băm nhỏ, lá xanh thái khúc; ớt sừng thái lát. Khuấy tan trong chén 45 ml nước tương, 8 g đường, 8 g hạt nêm chay, 3 g muối và 150 ml nước lọc.', 'Nấm đùi gà chỉ nên rửa nhanh chứ không ngâm lâu để giữ nguyên độ giòn ngọt tự nhiên.', NULL),
('imp-b6aeb931b882e8a3_v4_step_3', 'imp-b6aeb931b882e8a3', 3, 'cook', 'Chiên vàng sơ các mặt đậu phụ', 'Đun nóng 20 ml dầu ăn thực vật trong chảo trên lửa vừa, thả các miếng đậu phụ vào chiên khoảng 6 phút, lật nhẹ cho đến khi hai mặt vàng đều thì gắp ra đĩa lót giấy thấm dầu.', NULL, 6),
('imp-b6aeb931b882e8a3_v4_step_4', 'imp-b6aeb931b882e8a3', 4, 'cook', 'Phi thơm đầu hành và xào săn nấm đùi gà', 'Cho 20 ml dầu ăn còn lại vào nồi kho, đun nóng trên lửa vừa rồi phi thơm phần đầu hành lá băm trong 30 giây. Trút nấm đùi gà vào đảo nhanh tay 2 phút trên lửa vừa đến khi nấm săn lại và dậy mùi thơm.', NULL, 2),
('imp-b6aeb931b882e8a3_v4_step_5', 'imp-b6aeb931b882e8a3', 5, 'cook', 'Kho liu riu đậu phụ cùng nấm thấm vị', 'Đổ chén nước kho đã pha vào nồi nấm, xếp nhẹ các miếng đậu phụ chiên vào. Đun sôi bùng trên lửa vừa rồi hạ xuống lửa nhỏ, kho liu riu trong 9 phút cho nước kho sánh sệt lại, thấm đượm vào từng miếng đậu và nấm.', 'Hạn chế dùng đũa đảo mạnh trong lúc kho mà thỉnh thoảng nghiêng nhẹ nồi cho nước kho phủ đều, giúp đậu không bị nát.', 9),
('imp-b6aeb931b882e8a3_v4_step_6', 'imp-b6aeb931b882e8a3', 6, 'finish', 'Hoàn thiện và dọn cơm chay đậu kho nấm', 'Nêm nếm lại nước kho cho vừa miệng ăn kèm cơm, rắc phần lá xanh hành lá, ớt sừng thái lát và 1,5 g tiêu đen xay vào rồi tắt bếp. Xới cơm trắng nóng ra chén, múc đậu phụ kho nấm ra đĩa rưới nước kho sánh lên trên và thưởng thức nóng.', NULL, NULL),
('imp-f0039d3d3f6299b3_v4_step_1', 'imp-f0039d3d3f6299b3', 1, 'prep', 'Sơ chế đậu phụ, nấm đùi gà và cà chua', 'Đậu phụ trắng rửa nhẹ, để thật ráo rồi cắt miếng vuông dày vừa ăn. Nấm đùi gà cắt bỏ gốc, rửa sạch, thái lát dọc dày 0,5 cm. Cà chua bỏ cuống bổ múi cau; tỏi khô băm nhuyễn; hành lá cắt khúc 2–3 cm; ớt sừng thái lát mỏng.', 'Cắt đậu phụ miếng hơi dày một chút để khi kho lâu đậu vẫn chắc miếng và không bị vỡ nát.', NULL),
('imp-f0039d3d3f6299b3_v4_step_2', 'imp-f0039d3d3f6299b3', 2, 'cook', 'Chiên vàng sơ các mặt đậu phụ', 'Làm nóng chảo với 15 ml dầu ăn trên lửa vừa, thả từng miếng đậu phụ vào chiên khoảng 6 phút đến khi hai mặt ngả vàng nhẹ thì gắp ra đĩa để ráo dầu.', NULL, 6),
('imp-f0039d3d3f6299b3_v4_step_3', 'imp-f0039d3d3f6299b3', 3, 'cook', 'Phi tỏi và xào săn nấm đùi gà', 'Cho 10 ml dầu ăn còn lại vào chảo, phi thơm tỏi băm trên lửa vừa trong 30 giây. Đổ nấm đùi gà vào xào nhanh tay 3 phút với 10 ml nước tương và 1 g tiêu đen xay cho đến khi nấm săn cạnh và ngấm hương thơm.', NULL, 3),
('imp-f0039d3d3f6299b3_v4_step_4', 'imp-f0039d3d3f6299b3', 4, 'sauce', 'Xếp tầng nguyên liệu và pha sốt tương kho', 'Xếp cà chua bổ múi cau lót dưới đáy nồi kho, phủ phần nấm đùi gà đã xào lên trên và xếp đậu phụ chiên lên lớp trên cùng. Khuấy đều trong tô 30 ml nước tương còn lại, 20 ml hắc xì dầu, 15 g đường cát trắng, 4 g muối ăn, 3 g bột ngọt và 300 ml nước lọc đến khi tan hết.', 'Lót cà chua dưới đáy nồi giúp cà chua tiết nước ngọt làm nền sốt, đồng thời giữ đậu phụ phía trên nguyên vẹn không bị nát.', NULL),
('imp-f0039d3d3f6299b3_v4_step_5', 'imp-f0039d3d3f6299b3', 5, 'cook', 'Kho liu riu đến khi nước tương sánh đậm', 'Rót tô nước sốt tương vào nồi sao cho xâm xấp mặt nguyên liệu, bật lửa lớn đun sôi rồi hạ xuống lửa nhỏ, đậy hé vung kho liu riu trong 15 phút. Thỉnh thoảng lắc nhẹ quai nồi cho gia vị ngấm đều đến khi nước kho cạn sánh lại.', 'Kho ở lửa nhỏ liu riu và mở hé vung giúp nước sốt rút sánh dần mà không bị trào hay cháy khét đáy nồi.', 15),
('imp-f0039d3d3f6299b3_v4_step_6', 'imp-f0039d3d3f6299b3', 6, 'finish', 'Hoàn thiện món nấm kho đậu phụ tương', 'Nêm nếm lại sốt kho cho vừa vị đậm đà, tắt bếp rồi rắc hành lá cắt khúc, ớt sừng thái lát và 0,5 g tiêu đen xay còn lại lên trên. Múc ra đĩa sâu lòng và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-e771ef1a49b2aeed_v4_step_1', 'imp-e771ef1a49b2aeed', 1, 'prep', 'Sơ chế bông cải xanh, nấm đùi gà và cà rốt', 'Tách bông cải xanh thành từng nhánh vừa ăn, rửa sạch rồi để ráo. Nấm đùi gà cắt bỏ gốc, rửa nhanh sạch đất rồi thái lát dày 0,5 cm. Cà rốt gọt vỏ, thái lát mỏng; tỏi khô băm nhỏ; ớt sừng thái lát mỏng. Hòa tan 4 g bột bắp với 50 ml nước lọc trong chén riêng.', 'Không ngâm nấm đùi gà quá lâu trong nước để tránh nấm hút nước làm nhũn và mất vị ngọt khi xào.', NULL),
('imp-e771ef1a49b2aeed_v4_step_2', 'imp-e771ef1a49b2aeed', 2, 'cook', 'Chần sơ bông cải xanh và cà rốt giữ độ giòn', 'Đun sôi nồi nước nhỏ trên bếp, thả bông cải xanh và cà rốt vào chần nhanh trong 1–2 phút rồi vớt ra ngâm ngay vào thau nước lạnh khoảng 1 phút, sau đó vớt ra rổ để thật ráo nước.', 'Chần sơ rồi ngâm nước lạnh giúp bông cải xanh chín đều, giữ màu xanh mướt và giòn ngọt khi xào nhanh trên lửa lớn.', 2),
('imp-e771ef1a49b2aeed_v4_step_3', 'imp-e771ef1a49b2aeed', 3, 'cook', 'Xào săn nấm đùi gà riêng trên lửa lớn', 'Làm nóng chảo với 15 ml dầu ăn trên lửa lớn, trút nấm đùi gà vào xào nhanh tay 3 phút cho đến khi nấm săn lại và hơi xém cạnh. Nêm 1 g muối ăn và 0,5 g tiêu đen xay, đảo đều rồi trút nấm ra đĩa riêng.', 'Xào riêng nấm trước giúp nấm rút bớt nước, giữ độ dai giòn thơm và không làm nhũn rau khi xào chung.', 3),
('imp-e771ef1a49b2aeed_v4_step_4', 'imp-e771ef1a49b2aeed', 4, 'cook', 'Phi thơm tỏi và xào nhanh bông cải, cà rốt', 'Dùng lại chảo, thêm 20 ml dầu ăn đun nóng rồi cho tỏi băm vào phi khoảng 30 giây đến khi thơm vàng nhẹ. Bật lửa lớn, cho bông cải xanh và cà rốt đã ráo nước vào đảo đều tay 2 phút; nêm 30 ml nước tương, 8 g đường cát trắng, 8 g hạt nêm chay và 2 g muối ăn còn lại.', NULL, 2),
('imp-e771ef1a49b2aeed_v4_step_5', 'imp-e771ef1a49b2aeed', 5, 'sauce', 'Trộn nấm và làm sánh nước sốt bột bắp', 'Trút phần nấm đùi gà đã xào vào lại chảo rau củ, đảo đều tay cho hòa quyện. Khuấy đều chén nước bột bắp rồi chế từ từ vào chảo, đảo nhanh khoảng 1 phút đến khi lớp sốt sánh nhẹ bao quanh đều các nguyên liệu thì tắt bếp.', NULL, NULL),
('imp-e771ef1a49b2aeed_v4_step_6', 'imp-e771ef1a49b2aeed', 6, 'finish', 'Trình bày đĩa rau nấm xào chay nóng hổi', 'Gắp bông cải xanh xào nấm đùi gà ra đĩa lớn, rắc 1 g tiêu đen xay còn lại cùng vài lát ớt sừng đỏ lên trên để tăng màu sắc và hương thơm. Dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-43e806b28c7b8bb5_v4_step_1', 'imp-43e806b28c7b8bb5', 1, 'marinate', 'Làm sạch và ướp tôm tươi đậm vị', 'Bóc vỏ 200 g tôm tươi, bỏ đầu, rút sạch chỉ đen rồi rửa nước muối loãng và thấm thật khô. Thái tôm thành miếng nhỏ vừa ăn, ướp với 1/2 lượng hành tím băm, 5 ml nước mắm ngon, 2 g hạt nêm và 1 g tiêu đen xay trong 10 phút cho săn ngọt.', NULL, 10),
('imp-43e806b28c7b8bb5_v4_step_2', 'imp-43e806b28c7b8bb5', 2, 'prep', 'Sơ chế cà rốt, giá đỗ và đánh tơi cơm nguội', 'Thái hạt lựu nhỏ 1/2 củ cà rốt; rửa sạch 100 g giá đỗ rồi để thật ráo nước. Băm nhỏ tỏi và phần hành tím còn lại; thái nhỏ hành lá. Bóp tơi 540 g cơm nguội với 2 g muối ăn; đánh tan 2 quả trứng gà trong chén.', 'Cà rốt thái hạt lựu thật đều và giá đỗ để thật ráo sẽ giúp chảo cơm không bị ra nước lúc xào nhanh.', NULL),
('imp-43e806b28c7b8bb5_v4_step_3', 'imp-43e806b28c7b8bb5', 3, 'cook', 'Xào chín tôm tươi và cà rốt hạt lựu', 'Đun nóng 10 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa lượng tỏi băm và hành tím băm. Cho tôm đã ướp cùng cà rốt hạt lựu vào xào nhanh khoảng 3 phút đến khi tôm chuyển màu cam hồng, chín săn hoàn toàn và cà rốt vừa mềm thì xúc riêng ra đĩa.', NULL, 3),
('imp-43e806b28c7b8bb5_v4_step_4', 'imp-43e806b28c7b8bb5', 4, 'cook', 'Chiên tơi trứng gà và rang cơm lửa lớn', 'Cho 20 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi và hành tím băm còn lại. Đổ chén trứng gà vào đảo đều 30 giây thành mảng xốp mềm rồi trút toàn bộ cơm nguội vào. Tăng lửa lớn, rang đảo liên tục trong 4 phút để hạt cơm tơi đều, săn bóng và bám đều trứng vàng.', 'Đảo cơm đều tay trên lửa lớn cho đến khi nghe tiếng hạt cơm nhảy tanh tách nhẹ là cơm đã đạt độ săn ngon.', 4),
('imp-43e806b28c7b8bb5_v4_step_5', 'imp-43e806b28c7b8bb5', 5, 'cook', 'Nêm xì dầu, nước mắm và trộn tôm, giá đỗ', 'Rưới 20 ml xì dầu và 5 ml nước mắm ngon còn lại dọc quanh thành chảo nóng, thêm 3 g hạt nêm còn lại rồi đảo đều 1 phút cho dậy mùi thơm. Trút đĩa tôm cà rốt và 100 g giá đỗ vào đảo nhanh tay trên lửa lớn khoảng 1 phút để giá đỗ vừa chín tới vẫn còn độ giòn ngọt.', 'Rưới xì dầu quanh thành chảo đang nóng sẽ tạo mùi thơm cháy cạnh đặc trưng và giúp hạt cơm không bị ướt sũng.', NULL),
('imp-43e806b28c7b8bb5_v4_step_6', 'imp-43e806b28c7b8bb5', 6, 'finish', 'Rắc hành lá, tiêu xay và dọn nóng', 'Tắt bếp, rắc hành lá thái nhỏ và 1 g tiêu đen xay còn lại vào đảo đều lần cuối. Múc cơm chiên tôm trứng ra đĩa và dùng nóng ngay.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-f92a1c569c245541_v4_step_1', 'imp-f92a1c569c245541', 1, 'marinate', 'Thái mỏng và ướp mềm thịt bò với tỏi gừng', 'Thấm khô 250 g thịt bò thăn, thái lát mỏng ngang thớ. Ướp bò với 10 ml xì dầu, 5 ml dầu hào, 2 g hạt nêm, 1/2 lượng tỏi băm, 10 g gừng băm, 1/2 lượng tiêu đen xay và 5 ml dầu ăn trong 15 phút để thịt thấm vị và giữ độ mềm mọng khi xào.', 'Ướp bò với chút gừng băm và dầu ăn giúp khử mùi nhẹ và tạo lớp màng giữ nước cho thịt bò luôn mềm ngọt.', 15),
('imp-f92a1c569c245541_v4_step_2', 'imp-f92a1c569c245541', 2, 'prep', 'Sơ chế rau củ và trụng tơi mì tươi', 'Thái sợi bản vừa 1/4 bắp cải, thái sợi mỏng cà rốt, thái múi cau mỏng hành tây và cắt khúc 4 cm hành lá. Đun sôi 1 lít nước lọc, thả 400 g mì tươi vào trụng nhanh khoảng 1 phút cho sợi mì vừa rời tơi, vớt ra xả ngay nước lạnh cho săn sợi, để thật ráo rồi trộn với 5 ml dầu ăn chống dính.', NULL, 1),
('imp-f92a1c569c245541_v4_step_3', 'imp-f92a1c569c245541', 3, 'cook', 'Xào nhanh thịt bò tái mềm trên lửa lớn', 'Làm nóng 10 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa phần tỏi băm còn lại. Trút thịt bò đã ướp vào đảo nhanh tay trong 2 phút đến khi miếng thịt vừa săn chuyển màu nâu hồng mềm ngọt thì xúc ngay ra đĩa riêng.', 'Xào riêng thịt bò trên lửa lớn giúp thịt chín tái mềm mà không bị ra nhiều nước làm nhũn sợi mì.', 2),
('imp-f92a1c569c245541_v4_step_4', 'imp-f92a1c569c245541', 4, 'cook', 'Xào rau củ giòn ngọt và nêm sốt xì dầu', 'Thêm 10 ml dầu ăn còn lại vào chảo nóng, phi thơm phần tỏi băm còn lại rồi cho cà rốt và hành tây vào đảo trước 1 phút trên lửa lớn. Tiếp tục cho bắp cải vào xào chung thêm 2 phút, nêm 3 g hạt nêm còn lại và 4 g đường cát trắng cho rau chín tới giòn ngọt.', NULL, 3),
('imp-f92a1c569c245541_v4_step_5', 'imp-f92a1c569c245541', 5, 'cook', 'Áp chảo sợi mì thấm đều gia vị', 'Gạt rau củ sang một bên hoặc trút trực tiếp 400 g mì đã trụng vào chảo, rưới đều 15 ml xì dầu và 15 ml dầu hào còn lại lên sợi mì. Đảo đều tay trên lửa lớn khoảng 2 phút cho sợi mì săn bóng, ngấm đều gia vị và hơi xém thơm.', 'Xào mì trên lửa lớn và đảo liên tục giúp sợi mì thấm sốt đậm đà mà vẫn khô ráo, không bị nhão bết.', NULL),
('imp-f92a1c569c245541_v4_step_6', 'imp-f92a1c569c245541', 6, 'finish', 'Trộn thịt bò, hành lá và hoàn thiện món mì', 'Đổ đĩa thịt bò xào cùng hành lá cắt khúc vào chảo mì rau củ, đảo nhanh tay thêm 30 giây trên lửa lớn cho hòa quyện đều rồi tắt bếp. Bày mì xào ra đĩa, rắc phần tiêu đen xay còn lại lên trên và thưởng thức nóng.', NULL, NULL),
('imp-f4665d594d941e4a_v4_step_1', 'imp-f4665d594d941e4a', 1, 'prep', 'Làm sạch đùi gà, vo gạo và sơ chế gừng hành', 'Chà xát 500 g đùi gà với 3 g muối ăn trong 2 phút cho sạch mùi rồi rửa kỹ nước lạnh, để ráo. Trộn 200 g gạo tẻ với 30 g gạo nếp, vo qua 2 nước rồi chắt ráo. Đập dập 25 g gừng tươi và 25 g hành tím khô; phần 20 g gừng còn lại cạo vỏ thái sợi chỉ; hành lá rửa sạch thái nhỏ.', NULL, NULL),
('imp-f4665d594d941e4a_v4_step_2', 'imp-f4665d594d941e4a', 2, 'cook', 'Luộc chín đùi gà lấy nước dùng ngọt thanh', 'Cho đùi gà vào nồi cùng 2 lít nước lọc, gừng đập dập, hành tím và 3 g muối ăn. Đun sôi trên lửa lớn rồi hạ lửa vừa hớt sạch bọt, luộc liu riu khoảng 20 phút đến khi xiên đũa vào phần thịt dày nhất không thấy nước hồng chảy ra. Vớt đùi gà ra đĩa để nguội bớt, lọc giữ lại toàn bộ nước dùng gà.', 'Không luộc gà sôi sục quá mạnh để thịt đùi gà chín mềm mọng, giữ được độ ngọt và nước dùng trong veo.', 20),
('imp-f4665d594d941e4a_v4_step_3', 'imp-f4665d594d941e4a', 3, 'cook', 'Rang thơm gạo tẻ và gạo nếp', 'Trong lúc luộc gà, làm nóng chảo khô không dầu trên lửa nhỏ, cho gạo tẻ và gạo nếp đã ráo nước vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy hương thơm dịu thì tắt bếp.', 'Rang gạo đến khi hạt gạo trắng đục và thơm nhẹ là vừa đạt; tránh rang cháy vàng đậm sẽ làm cháo bị sẫm màu.', 6),
('imp-f4665d594d941e4a_v4_step_4', 'imp-f4665d594d941e4a', 4, 'cook', 'Ninh cháo với nước luộc gà cho sánh nhừ', 'Trút toàn bộ gạo rang vào nồi nước luộc gà nóng, khuấy đều một lượt rồi đun sôi trở lại. Hạ lửa nhỏ ninh khoảng 20 phút, thỉnh thoảng khuấy nhẹ sát đáy nồi để hạt gạo nở bung sánh mịn và ngấm trọn vị ngọt thanh của nước gà.', 'Dùng nước luộc gà nóng để ninh gạo rang giúp hạt gạo nhanh nở mềm và bát cháo đậm vị ngọt tự nhiên.', 20),
('imp-f4665d594d941e4a_v4_step_5', 'imp-f4665d594d941e4a', 5, 'prep', 'Xé sợi đùi gà luộc và trộn gia vị nhẹ', 'Khi đùi gà đã nguội bớt, tách bỏ xương rồi xé thịt gà thành từng miếng sợi vừa ăn. Trộn nhẹ thịt gà xé với 2 g hạt nêm và 1 g tiêu đen xay cho đậm đà hơn.', NULL, NULL),
('imp-f4665d594d941e4a_v4_step_6', 'imp-f4665d594d941e4a', 6, 'finish', 'Nêm nồi cháo và hoàn thiện tô cháo gà gừng', 'Nêm 20 ml nước mắm ngon, 4 g hạt nêm còn lại và 2 g muối ăn vào nồi cháo nhừ, khuấy đều rồi nấu thêm 2 phút trên lửa nhỏ. Múc cháo nóng ra 4 tô, xếp thịt gà xé sợi lên trên, rắc hành lá thái nhỏ, gừng tươi thái chỉ, 1 g tiêu đen xay còn lại và nhỏ đều 5 ml dầu mè trước khi thưởng thức.', NULL, NULL),
('imp-35164fb31de89c5f_v4_step_1', 'imp-35164fb31de89c5f', 1, 'cook', 'Luộc chín mềm ức gà ta và xé sợi', 'Cho 400 g ức gà vào nồi với 1 lít nước lọc, phần đầu hành lá đập dập và 2 g muối ăn. Đun sôi trên lửa vừa rồi hạ lửa nhỏ luộc khoảng 12 phút đến khi thịt gà chín trắng hoàn toàn, tắt bếp đậy nắp ủ thêm 5 phút cho ngọt thịt. Vớt gà ngâm nước nguội 2 phút cho săn trắng rồi xé sợi dọc thớ, trộn nhẹ với 1,5 g tiêu đen xay.', 'Ủ thêm 5 phút sau khi tắt bếp giúp miếng ức gà chín đều tận lõi mà thớ thịt vẫn ẩm mềm, không bị khô bã.', 12),
('imp-35164fb31de89c5f_v4_step_2', 'imp-35164fb31de89c5f', 2, 'prep', 'Sơ chế bắp cải, cà rốt và hành tây giòn mát', 'Bào sợi thật mỏng 280 g bắp cải trắng và 110 g cà rốt, xóc nhẹ với 2 g muối ăn để 5 phút rồi rửa nhanh qua nước lọc lạnh và vắt thật ráo nước. Thái lát mỏng 70 g hành tây, ngâm vào tô nước đá lạnh pha 5 g đường cát trắng trong 10 phút cho hết hăng rồi vớt ra để thật ráo cùng hành lá chẻ sợi và rau răm thái rối.', 'Vắt thật ráo rau củ sau khi ngâm nước đá giúp đĩa gỏi khô ráo giòn ngon, nước sốt bám đều mà không bị loãng vị.', 10),
('imp-35164fb31de89c5f_v4_step_3', 'imp-35164fb31de89c5f', 3, 'sauce', 'Pha nước mắm chanh tỏi ớt chua ngọt', 'Vắt 1,5 quả chanh tươi lấy nước cốt bỏ hạt. Cho 30 ml nước mắm ngon, 20 g đường cát trắng còn lại và nước cốt chanh vào chén, khuấy tan hoàn toàn đường rồi mới cho tỏi băm nhuyễn và 1 quả ớt hiểm băm nhỏ vào để tỏi ớt nổi đẹp trên mặt sốt.', 'Khuấy tan hoàn toàn đường với nước mắm và chanh trước khi thả tỏi ớt băm giúp phần tỏi ớt nổi đẹp mà không chìm đáy.', NULL),
('imp-35164fb31de89c5f_v4_step_4', 'imp-35164fb31de89c5f', 4, 'cook', 'Trộn sơ gà xé với một phần nước sốt', 'Cho thịt ức gà xé sợi vào thau lớn, rưới 1/3 lượng nước mắm chanh tỏi ớt đã pha vào trộn nhẹ cho thịt gà ngấm trước vị chua ngọt đậm đà.', NULL, NULL),
('imp-35164fb31de89c5f_v4_step_5', 'imp-35164fb31de89c5f', 5, 'cook', 'Trộn đều bắp cải, cà rốt, hành tây và rau răm', 'Cho bắp cải, cà rốt bào sợi, hành tây ngâm ráo, rau răm và hành lá chẻ sợi vào thau thịt gà. Rưới phần nước mắm chanh còn lại lên trên rồi dùng tay sạch (đeo găng) trộn nhẹ nhàng từ dưới lên để các sợi rau không bị dập nát mà vẫn thấm đều gia vị.', NULL, NULL),
('imp-35164fb31de89c5f_v4_step_6', 'imp-35164fb31de89c5f', 6, 'finish', 'Bày đĩa gỏi gà và rắc đậu phộng rang', 'Gắp gỏi gà bắp cải xếp gọn gàng lên đĩa, trang trí thêm vài lát ớt hiểm đỏ và rắc toàn bộ 30 g đậu phộng rang giã dập lên trên cùng. Thưởng thức ngay khi rau còn giòn mát.', NULL, NULL),
('imp-368d91563cb1879b_v4_step_1', 'imp-368d91563cb1879b', 1, 'prep', 'Chần xương ống và ninh nước dùng ngọt thanh', 'Chặt nhỏ 600 g xương ống heo, chần nước sôi 3 phút với 1 g muối ăn rồi vớt ra rửa sạch bọt bẩn. Cho xương vào nồi cùng 2400 ml nước lọc và 2 g muối ăn, đun sôi bùng rồi hạ lửa nhỏ liu riu ninh 25 phút, hớt bọt thường xuyên để nước dùng thật trong ngọt.', NULL, 25),
('imp-368d91563cb1879b_v4_step_2', 'imp-368d91563cb1879b', 2, 'prep', 'Làm sạch cá diêu hồng, tôm tươi và rau nấm', 'Chà xát 400 g cá diêu hồng với 2 g muối ăn cho hết nhớt, rửa sạch để ráo rồi cắt khúc dày 2 cm. Rửa sạch 400 g tôm tươi, cắt râu và rút chỉ đen lưng. Cắt gốc và rửa sạch nấm đùi gà thái lát, nấm rơm bổ đôi, rau muống cắt khúc; băm nhỏ hành tím, tỏi khô, 1 cây sả; đập dập 3 cây sả còn lại, thái lát riềng, vò nhẹ lá chanh, bổ múi cau cà chua và vắt nước cốt 2 quả chanh tươi.', 'Chà muối khử nhớt cá diêu hồng rồi rửa lại thật sạch và thấm khô giúp cá săn chắc, không bị tanh khi nhúng lẩu.', NULL),
('imp-368d91563cb1879b_v4_step_3', 'imp-368d91563cb1879b', 3, 'cook', 'Phi thơm sả riềng và xào nền sốt lẩu Thái', 'Làm nóng chảo sâu lòng với 20 ml dầu ăn trên lửa vừa, phi thơm hành tím, tỏi băm, sả băm, sả cây đập dập và riềng thái lát khoảng 2 phút cho dậy mùi. Cho phần cà chua băm nhỏ, 15 ml sa tế tôm và 25 g sốt gia vị lẩu Thái vào đảo đều 3 phút đến khi cà chua mềm nhuyễn lên màu đỏ cam đẹp mắt.', NULL, 5),
('imp-368d91563cb1879b_v4_step_4', 'imp-368d91563cb1879b', 4, 'cook', 'Hòa nước hầm xương và nấu sôi nước dùng chua cay', 'Vớt bỏ xương ống từ nồi nước ninh (hoặc giữ lại tùy thích), trút hỗn hợp sốt sả riềng vừa xào vào nồi nước dùng cùng 2 quả cà chua bổ múi cau và 1 quả ớt hiểm đập dập. Đun sôi 5 phút trên lửa vừa rồi nêm 30 ml nước mắm ngon, 8 g hạt nêm, 20 g đường cát trắng và 1 g muối ăn còn lại.', 'Nêm gia vị trước khi thả lá chanh và nước cốt chanh sẽ giúp bạn kiểm soát vị mặn ngọt chuẩn xác mà không bị vị chua làm nhiễu.', 5),
('imp-368d91563cb1879b_v4_step_5', 'imp-368d91563cb1879b', 5, 'cook', 'Thả lá chanh và rưới nước cốt chanh tạo vị chua tươi', 'Tắt bếp hoặc hạ về mức lửa nhỏ nhất để nước không sôi sùng sục, thả lá chanh đã vò nhẹ vào nồi và từ từ rưới nước cốt chanh tươi vào khuấy đều, nếm lại sao cho nước dùng dậy vị chua cay ngọt hài hòa đúng điệu miền Tây.', 'Tắt bếp rồi mới vắt chanh và thả lá chanh giúp giữ trọn tinh dầu thơm mát và tránh làm nước lẩu bị đắng gắt.', NULL),
('imp-368d91563cb1879b_v4_step_6', 'imp-368d91563cb1879b', 6, 'finish', 'Bày nồi lẩu lên bàn và nhúng cá, tôm, nấm nóng hổi', 'Chuyển nồi lẩu sang bếp bàn đun sôi lăn tăn, thả nấm đùi gà, nấm rơm và cá diêu hồng vào nấu trước 5 phút cho cá chín chắc hoàn toàn. Tiếp tục nhúng tôm tươi khoảng 3 phút đến khi tôm chuyển màu đỏ cam săn giòn, nhúng rau muống ăn kèm bún tươi và 2 quả ớt thái lát chấm nước mắm.', NULL, NULL),
('imp-c52c790faf9281da_v4_step_1', 'imp-c52c790faf9281da', 1, 'prep', 'Sơ chế các loại nấm tươi, đậu phụ và rau củ', 'Cắt bỏ phần gốc bám đất của nấm đùi gà, nấm bào ngư, nấm kim châm, nấm rơm và nấm đông cô tươi; ngâm nhanh qua nước pha 2 g muối ăn rồi rửa sạch, để thật ráo và thái lát vừa ăn. Cắt khoanh 250 g bắp ngọt và 1 củ cà rốt; cắt khối vuông 2,5 cm 2,5 bìa đậu phụ trắng; cắt khúc bắp cải trắng và thái lát phần củ trắng hành boa-rô.', 'Vắt nhẹ hoặc để các loại nấm thật ráo nước trước khi bày đĩa giúp nấm giữ độ giòn ngọt và không làm loãng nước lẩu khi nhúng.', NULL),
('imp-c52c790faf9281da_v4_step_2', 'imp-c52c790faf9281da', 2, 'prep', 'Luộc chín mềm bún khô hoặc mì chay', 'Ngâm 200 g bún khô hoặc mì chay khô trong nước lạnh 5 phút cho mềm bớt rồi luộc trong nồi nước sôi 4 phút đến khi sợi chín dẻo vừa tới. Vớt ra xả lại nước đun sôi để nguội cho tơi sợi rồi xếp ra đĩa ăn kèm.', NULL, 4),
('imp-c52c790faf9281da_v4_step_3', 'imp-c52c790faf9281da', 3, 'cook', 'Phi thơm hành boa-rô và xào nấm tạo hương', 'Làm nóng nồi trên lửa vừa với 20 ml dầu ăn thực vật, cho phần củ trắng hành boa-rô thái lát vào phi thơm khoảng 1 phút đến khi hơi vàng. Trút một nửa lượng nấm đông cô tươi vào đảo nhanh 2 phút cho dậy hương thơm đặc trưng.', 'Xào sơ nấm đông cô cùng hành boa-rô phi sẽ giúp nước lẩu chay dậy mùi thơm ấm hấp dẫn không thua kém nước hầm xương.', 3),
('imp-c52c790faf9281da_v4_step_4', 'imp-c52c790faf9281da', 4, 'cook', 'Ninh bắp ngọt và cà rốt lấy nước lẩu thanh ngọt', 'Đổ 2200 ml nước lọc vào nồi, thả toàn bộ bắp ngọt cắt khoanh và cà rốt vào đun sôi bùng. Hạ lửa vừa ninh khoảng 15 phút để bắp ngọt và cà rốt tiết hết vị ngọt thanh tự nhiên vào nước dùng, hớt sạch bọt nếu có.', NULL, 15),
('imp-c52c790faf9281da_v4_step_5', 'imp-c52c790faf9281da', 5, 'cook', 'Nêm gia vị thuần chay hài hòa', 'Nêm 25 ml nước tương, 12 g hạt nêm chay nấm hương, 12 g đường phèn và 5 g muối ăn vào nồi nước dùng, khuấy tan đều và nấu thêm 2 phút cho nước lẩu thấm vị thanh ngọt dịu nhẹ.', 'Sử dụng đường phèn thay đường cát giúp nước lẩu chay có độ ngọt thanh mát tự nhiên, không bị ngọt gắt cổ.', NULL),
('imp-c52c790faf9281da_v4_step_6', 'imp-c52c790faf9281da', 6, 'finish', 'Chuyển nồi lẩu ra bàn và nhúng nấm, đậu phụ nóng hổi', 'Chuyển nồi lẩu lên bếp giữa bàn giữ sôi lăn tăn, thả phần lá xanh hành boa-rô cắt khúc, đậu phụ trắng và váng đậu vào nấu 3 phút. Lần lượt nhúng nấm đùi gà, nấm bào ngư, nấm rơm, nấm kim châm và bắp cải vừa chín tới rồi thưởng thức nóng cùng bún khô luộc và 10 ml nước tương pha ớt tươi thái lát.', NULL, NULL),
('imp-e9678cfa1bc90074_v4_step_1', 'imp-e9678cfa1bc90074', 1, 'marinate', 'Làm sạch tôm và ướp gia vị', 'Tôm tươi bóc vỏ, khứa dọc sống lưng lấy sạch chỉ đen rồi rửa lại và thấm thật khô. Ướp tôm với 5 ml xì dầu nhạt, 0,5 g muối ăn và một nửa lượng tiêu trắng xay trong 10 phút. Cà chua chín bổ múi cau; tỏi khô băm nhỏ; hành lá tươi tách riêng đầu trắng và lá xanh thái nhỏ.', NULL, 10),
('imp-e9678cfa1bc90074_v4_step_2', 'imp-e9678cfa1bc90074', 2, 'prep', 'Đánh trứng gà mềm mượt', 'Hòa tan 3 g bột năng với 15 ml nước lọc (nếu dùng). Đập 5 quả trứng gà vào tô cùng hỗn hợp bột năng, 1,5 g muối ăn, phần tiêu trắng xay còn lại, 2,5 ml dầu mè thơm và 5 ml rượu Thiệu Hưng; đánh đều tay trong 1 phút cho trứng hòa quyện.', 'Bột năng pha loãng giúp trứng giữ nước khi xào, tạo kết cấu mềm mượt mà không bị tách nước.', NULL),
('imp-e9678cfa1bc90074_v4_step_3', 'imp-e9678cfa1bc90074', 3, 'cook', 'Chần nhanh tôm và chiên xốp trứng', 'Đun sôi một nồi nước nhỏ, thả tôm đã ướp vào chần nhanh 30–40 giây đến khi thịt tôm vừa chuyển màu hồng cam thì vớt ra để ráo, giữ độ giòn ngọt. Sau đó, làm nóng 14 ml dầu ăn thực vật trong chảo trên lửa vừa, đổ trứng gà vào đảo nhẹ đến khi trứng chín khoảng 70% còn mềm ẩm thì trút ra đĩa.', 'Chần sơ tôm trước giúp tôm không tiết nước làm loãng sốt và giữ độ giòn sần sật khi đảo lại cùng cà chua.', 3),
('imp-e9678cfa1bc90074_v4_step_4', 'imp-e9678cfa1bc90074', 4, 'cook', 'Phi thơm tỏi hành và nấu sốt cà chua', 'Cho 14 ml dầu ăn thực vật còn lại vào chảo, phi thơm tỏi băm và đầu hành trắng khoảng 30 giây, thả cà chua vào xào lửa lớn 1 phút. Tiếp tục cho 15 ml tương cà chua, 15 g cà chua cô đặc, 10 ml xì dầu nhạt còn lại, 8 g đường cát trắng, 2 g muối ăn và 60 ml nước lọc vào, đậy nắp nấu lửa vừa 4 phút cho cà chua mềm nhừ thành sốt sệt.', NULL, 5),
('imp-e9678cfa1bc90074_v4_step_5', 'imp-e9678cfa1bc90074', 5, 'cook', 'Đảo quyện tôm và trứng vào sốt', 'Mở nắp, thả tôm đã chần vào đảo 1 phút cho tôm chín chắc hoàn toàn và ngấm sốt, rồi nhẹ tay trút phần trứng chiên mềm vào đảo quyện 30 giây để sốt cà chua bám đều từng miếng trứng và tôm.', 'Không đảo mạnh tay khi cho trứng vào để giữ các mảng trứng xốp mềm ngấm sốt mà không bị nát vụn.', 1),
('imp-e9678cfa1bc90074_v4_step_6', 'imp-e9678cfa1bc90074', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Rưới 2,5 ml dầu mè thơm còn lại, rắc phần lá hành xanh thái nhỏ lên trên, đảo nhẹ một lượt rồi tắt bếp ngay. Trút ra đĩa sâu lòng và thưởng thức khi còn nóng cùng cơm trắng.', NULL, NULL),
('imp-387c41fb3a0c2297_v4_step_1', 'imp-387c41fb3a0c2297', 1, 'marinate', 'Thái hạt lựu và ướp thịt đùi gà', 'Thái 500 g thịt đùi gà không xương thành khối hạt lựu đều cạnh 1,5 cm. Trộn đều gà với 15 ml xì dầu nhạt, 10 ml rượu Thiệu Hưng, 8 g bột bắp, 1 g muối ăn, 1 g tiêu trắng xay và 10 ml dầu ăn thực vật. Để ướp trong 15 phút cho thịt ngấm gia vị và mềm mượt.', 'Lớp bột bắp cùng một chút dầu ăn giúp khóa ẩm miếng gà và ngăn thịt dính vào nhau khi cho lên chảo nóng.', 15),
('imp-387c41fb3a0c2297_v4_step_2', 'imp-387c41fb3a0c2297', 2, 'sauce', 'Pha chén sốt Kung Pao chua ngọt', 'Trong chén nhỏ, khuấy đều 30 ml nước dùng gà, 30 ml giấm đen Trấn Giang, 15 ml rượu Thiệu Hưng còn lại, 10 ml xì dầu nhạt còn lại, 8 ml xì dầu đặc, 22 g đường cát trắng, 6 g bột bắp còn lại và 1 g muối ăn đến khi đường và bột bắp tan hoàn toàn. Chuẩn bị sẵn tỏi khô thái lát, gừng tươi thái sợi, ớt khô cắt khúc, hành lá cắt khúc và ớt chuông đỏ thái hạt lựu (nếu dùng).', NULL, NULL),
('imp-387c41fb3a0c2297_v4_step_3', 'imp-387c41fb3a0c2297', 3, 'cook', 'Xào săn thịt gà rồi trút ra đĩa', 'Làm nóng chảo sâu lòng trên lửa vừa lớn với 15 ml dầu ăn thực vật. Trút thịt gà đã ướp vào dàn đều một lớp, giữ yên 30 giây cho mặt dưới se vàng rồi đảo nhanh tay khoảng 2–3 phút đến khi mặt ngoài gà vừa chuyển trắng đục và chín khoảng 80%. Lập tức vớt gà ra đĩa riêng.', NULL, 3),
('imp-387c41fb3a0c2297_v4_step_4', 'imp-387c41fb3a0c2297', 4, 'cook', 'Phi thơm hoa tiêu, ớt khô và hương liệu', 'Hạ lửa nhỏ, cho 20 ml dầu ăn thực vật còn lại vào chảo rồi thả 2 g hoa tiêu Tứ Xuyên và 6 quả ớt khô đỏ Tứ Xuyên cắt khúc vào đảo đều khoảng 1 phút cho dậy hương cay tê mà không bị cháy đen. Tăng lửa vừa, thêm tỏi khô, gừng tươi, một nửa hành lá tươi và ớt chuông đỏ vào đảo thơm 1 phút.', 'Luôn giữ lửa nhỏ khi phi hoa tiêu và ớt khô để tránh bị cháy sém gây vị đắng cho món xào.', 2),
('imp-387c41fb3a0c2297_v4_step_5', 'imp-387c41fb3a0c2297', 5, 'cook', 'Đảo gà với sốt đến khi sánh bóng', 'Khuấy đều lại chén sốt rồi rót nhanh vào chảo, đảo đều tay 15 giây cho sốt bắt đầu sôi lăn tăn và sánh lại. Trút toàn bộ thịt gà trở lại chảo, bật lửa lớn đảo nhanh 1–2 phút đến khi thịt gà chín kỹ hoàn toàn, không còn màu hồng và nước sốt sánh bóng bám đều từng miếng.', NULL, 2),
('imp-387c41fb3a0c2297_v4_step_6', 'imp-387c41fb3a0c2297', 6, 'finish', 'Trộn đậu phộng rang và hoàn thiện', 'Thả 70 g đậu phộng rang giòn và phần hành lá tươi còn lại vào chảo, xóc nhanh tay 5 giây cho quyện đều rồi tắt bếp ngay. Bày ra đĩa, có thể rưới thêm 8 ml dầu ớt Tứ Xuyên lên mặt và dùng nóng cùng cơm trắng.', 'Chỉ cho đậu phộng rang vào ngay trước khi tắt bếp để giữ trọn độ giòn bùi, tránh bị ỉu do hơi ẩm.', NULL),
('imp-f5abd36e99d48d94_v4_step_1', 'imp-f5abd36e99d48d94', 1, 'prep', 'Sơ chế nguyên liệu và pha bột bắp', 'Cắt 350 g đậu phụ non thành từng khối vuông cạnh 2,5 cm thật gọn. Băm nhuyễn 20 g gừng tươi và 0,75 củ tỏi khô; thái nhỏ 0,5 bó hành lá tươi; cắt khúc ớt khô đỏ và thái lát mỏng ớt hiểm tươi. Hòa tan 5 g bột bắp với 45 ml nước lọc trong chén nhỏ; giữ riêng 1/2 muỗng cà phê bột hoa tiêu Tứ Xuyên để trang trí.', NULL, NULL),
('imp-f5abd36e99d48d94_v4_step_2', 'imp-f5abd36e99d48d94', 2, 'cook', 'Phi dầu ớt thơm từ ớt tươi và ớt khô', 'Đặt chảo sâu lòng lên lửa nhỏ, làm nóng 30 ml dầu ăn thực vật rồi cho hỗn hợp ớt hiểm tươi thái lát và ớt khô đỏ cắt khúc vào đảo đều trong 4–5 phút đến khi dầu thấm màu cam đỏ và dậy mùi cay thơm nhưng ớt tuyệt đối không bị cháy đen. Tắt bếp và trút toàn bộ dầu lẫn ớt ra chén riêng.', 'Phi dầu ớt trên lửa nhỏ giúp chiết xuất tinh dầu cay thơm mà không làm ớt bị khét đắng.', 5),
('imp-f5abd36e99d48d94_v4_step_3', 'imp-f5abd36e99d48d94', 3, 'cook', 'Phi gừng tỏi và xào săn thịt heo xay', 'Cho 30 ml dầu ăn thực vật còn lại vào chảo, bật lửa vừa, phi thơm gừng băm 1 phút rồi cho tỏi băm vào đảo thêm 1 phút. Tăng lửa lớn, trút 170 g thịt heo xay vào dùng sạn dằm tơi và xào đều khoảng 3 phút cho thịt săn ráo và chín hoàn toàn.', NULL, 5),
('imp-f5abd36e99d48d94_v4_step_4', 'imp-f5abd36e99d48d94', 4, 'cook', 'Xào hoa tiêu, tương đậu bản và nấu sốt', 'Hạ lửa vừa, cho phần bột hoa tiêu Tứ Xuyên còn lại vào đảo nhanh 20 giây cho dậy mùi tê thơm, rồi thêm 28 g tương ớt đậu bản Doubanjiang vào xào đều 1 phút đến khi thịt quyện màu đỏ đẹp. Đổ 120 ml nước dùng gà vào, khuấy đều và đun sôi liu riu 1 phút.', 'Cho bột hoa tiêu vào sau khi thịt đã chín săn giúp gia vị thơm nồng mà không bị cháy đắng.', 2),
('imp-f5abd36e99d48d94_v4_step_5', 'imp-f5abd36e99d48d94', 5, 'cook', 'Sánh sốt và om đậu phụ thấm dầu ớt', 'Khuấy lại chén bột bắp rồi rót vào chảo, đảo đều 1–2 phút đến khi sốt sánh mượt vừa phải để bám miếng đậu. Tiếp theo, trút phần dầu ớt đã phi cùng đậu phụ non vào chảo, dùng lưng sạn hất đẩy nhẹ nhàng để sốt bao đều từng khối đậu và om mở nắp 4 phút cho đậu ngấm đẫm gia vị.', 'Sốt cần đủ sánh để bám đều mặt đậu phụ non nhưng vẫn giữ chút nước sốt đỏ để chan cơm nóng.', 5),
('imp-f5abd36e99d48d94_v4_step_6', 'imp-f5abd36e99d48d94', 6, 'finish', 'Rưới dầu mè, hành lá và hoàn thiện', 'Thêm 3 ml dầu mè thơm, 2 g đường cát trắng (nếu dùng) và hành lá thái nhỏ vào, đẩy nhẹ 30 giây đến khi hành vừa héo xanh. Tắt bếp, trút ra đĩa sâu lòng, rắc phần bột hoa tiêu Tứ Xuyên giữ riêng lên mặt và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-242fd73cebd63651_v4_step_1', 'imp-242fd73cebd63651', 1, 'prep', 'Chần sạch sườn non heo và sơ chế rau quả', 'Đun sôi 800 ml nước lọc trong nồi, thả 600 g sườn non heo chặt khúc vào chần 6–8 phút cho tiết hết bọt bẩn, vớt ra xả sạch dưới vòi nước lạnh rồi để ráo. Dứa chín cắt miếng tam giác vừa ăn; cà chua chín bổ múi cau; tỏi khô đập dập; gừng tươi thái lát mỏng.', 'Chần sườn qua nước sôi và rửa sạch lại giúp nước sốt om trong bóng và loại bỏ hoàn toàn mùi hôi.', 7),
('imp-242fd73cebd63651_v4_step_2', 'imp-242fd73cebd63651', 2, 'sauce', 'Pha hỗn hợp sốt chua ngọt', 'Cho vào tô lớn 40 ml tương cà chua, 30 ml giấm gạo trắng, 20 g đường cát trắng, 15 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml rượu Thiệu Hưng và 300 ml nước lọc còn lại. Khuấy đều tay đến khi đường tan hết.', NULL, NULL),
('imp-242fd73cebd63651_v4_step_3', 'imp-242fd73cebd63651', 3, 'cook', 'Phi thơm gừng tỏi và áp xém sườn non', 'Đun nóng 15 ml dầu ăn thực vật trong nồi đáy dày hoặc chảo sâu lòng trên lửa vừa, cho tỏi đập dập và gừng thái lát vào phi thơm 30 giây. Trút sườn non đã ráo vào áp xém các mặt khoảng 5 phút cho bề mặt sườn săn vàng thơm.', 'Áp xém sườn trước khi om giúp miếng thịt giữ nước ngọt bên trong và dễ bám sốt đẹp mắt.', 5),
('imp-242fd73cebd63651_v4_step_4', 'imp-242fd73cebd63651', 4, 'cook', 'Om mềm sườn trong nước sốt', 'Đổ toàn bộ tô nước sốt chua ngọt đã pha vào nồi ngập sườn, đun sôi bùng trên lửa lớn rồi hạ lửa nhỏ nhất, đậy nắp kín om liu riu trong 25–30 phút đến khi thịt sườn mềm róc xương và ngấm vị; cứ mỗi 10 phút mở nắp đảo một lần cho đều màu.', NULL, 28),
('imp-242fd73cebd63651_v4_step_5', 'imp-242fd73cebd63651', 5, 'cook', 'Thả dứa cà chua và cô sánh nước sốt', 'Mở nắp nồi, cho dứa chín và cà chua bổ múi cau vào nấu trên lửa vừa 4 phút cho dứa cà vừa chín mềm mà vẫn giữ hình dáng. Tiếp tục tăng lửa lớn, mở nắp hoàn toàn và đảo liên tục khoảng 3 phút cho nước sốt cô cạn sánh keo, ôm bóng quanh từng khúc sườn.', 'Cho dứa và cà chua vào giai đoạn cuối giúp giữ độ tươi ngon và vị chua ngọt thanh sáng cho món ăn.', 7),
('imp-242fd73cebd63651_v4_step_6', 'imp-242fd73cebd63651', 6, 'finish', 'Nêm muối cân vị và hoàn thiện', 'Nêm thêm 3 g muối ăn (tùy khẩu vị) để cân bằng vị chua ngọt, đảo nhẹ một vòng cho đều vị rồi tắt bếp. Bày sườn cùng dứa cà chua ra đĩa lớn, rưới hết phần sốt keo bóng lên mặt và dùng nóng với cơm trắng.', NULL, NULL),
('imp-34f3eb2438125614_v4_step_1', 'imp-34f3eb2438125614', 1, 'prep', 'Xé tay bắp cải, thái cà rốt và để thật ráo', 'Tách rời từng lá bắp cải xanh, loại bỏ phần gân lá dày cứng rồi dùng tay xé thành miếng vừa ăn. Thái lát mỏng cà rốt tươi; rửa nhẹ cả hai loại rau rồi vẩy thật ráo nước. Đập dập cắt đôi tỏi khô, thái sợi gừng tươi, bỏ hạt cắt khúc ớt khô đỏ, cắt khúc 5 cm hành lá tươi và thái lát mỏng thịt ba chỉ heo (nếu dùng).', 'Rau phải thật ráo nước trước khi cho vào chảo nóng để tránh làm hạ nhiệt, khiến bắp cải bị ra nước và mất độ giòn.', NULL),
('imp-34f3eb2438125614_v4_step_2', 'imp-34f3eb2438125614', 2, 'cook', 'Áp chảo thịt ba chỉ lấy mỡ thơm', 'Làm nóng chảo sâu lòng trên lửa lớn đến khi hơi bốc khói, cho 22 ml dầu ăn thực vật tráng đều lòng chảo. Nếu dùng thịt ba chỉ heo, cho thịt vào áp chảo 2 phút cho hai mặt xém vàng và tiết bớt mỡ thơm rồi gạt sang mép chảo hoặc gắp ra riêng.', NULL, 2),
('imp-34f3eb2438125614_v4_step_3', 'imp-34f3eb2438125614', 3, 'cook', 'Phi thơm ớt khô, tỏi và gừng', 'Hạ lửa vừa, cho ớt khô đỏ cắt khúc vào đảo khoảng 20 giây cho dậy mùi cay nhẹ, tiếp tục thả tỏi khô và gừng tươi thái sợi vào phi thơm thêm 40 giây đến khi tỏi hơi ngả vàng thơm mà không bị cháy đắng.', 'Luôn để mắt tới tỏi phi ở lửa vừa vì tỏi cháy sẽ làm món rau xào bị đắng và sậm màu.', 1),
('imp-34f3eb2438125614_v4_step_4', 'imp-34f3eb2438125614', 4, 'cook', 'Xào lửa lớn bắp cải và cà rốt', 'Vặn lửa lớn nhất, trút toàn bộ bắp cải xanh và cà rốt vào chảo đảo nhanh tay trong 1 phút. Rưới 10 ml rượu Thiệu Hưng quanh thành chảo cho bốc hơi thơm, thêm 15 ml xì dầu nhạt, 2 g đường cát trắng và 15 ml nước lọc, đảo đều rồi đậy nắp om nhanh 1–2 phút cho bắp cải vừa chín tới.', NULL, 2),
('imp-34f3eb2438125614_v4_step_5', 'imp-34f3eb2438125614', 5, 'cook', 'Thêm giấm đen và nêm muối cân vị', 'Mở nắp, trút thịt ba chỉ heo trở lại chảo (nếu dùng), rưới 5 ml giấm đen Trấn Giang và nêm 3 g muối ăn, đảo nhanh tay 30 giây trên lửa lớn đến khi nước hơi cạn ráo và mép lá bắp cải xém nhẹ đẹp mắt.', 'Cho giấm đen vào công đoạn cuối giúp giữ nguyên vị chua thanh dịu và hương thơm đặc trưng mà không bị bay hơi hết.', NULL),
('imp-34f3eb2438125614_v4_step_6', 'imp-34f3eb2438125614', 6, 'finish', 'Thêm hành lá và hoàn thiện', 'Thả hành lá tươi cắt khúc vào đảo nhanh 20–30 giây cho hành vừa chín tái giữ màu xanh tươi rồi tắt bếp ngay. Múc ra đĩa và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-2d508cd359edb61c_v4_step_1', 'imp-2d508cd359edb61c', 1, 'prep', 'Thấm khô và băm nhuyễn chả tôm', 'Tôm tươi bóc vỏ rút sạch chỉ đen, dùng khăn giấy thấm thật khô từng con rồi dùng dao băm nhuyễn bằng tay để thịt tôm giữ được độ dai giòn tự nhiên, không bị bở nát. Gừng tươi băm nhuyễn; hành lá tươi tách phần đầu trắng thái lát mỏng và phần lá xanh thái nhỏ.', 'Thấm thật khô tôm và băm bằng dao thay vì xay máy sẽ giúp chả tôm dẻo quánh, giòn sần sật khi hấp.', NULL),
('imp-2d508cd359edb61c_v4_step_2', 'imp-2d508cd359edb61c', 2, 'marinate', 'Quết dẻo chả tôm với gừng hành', 'Cho thịt tôm băm vào tô cùng 8 ml rượu Thiệu Hưng, 2 g bột bắp, 4 ml dầu mè thơm, 1,5 g muối ăn và một nửa lượng tiêu trắng xay. Dùng muỗng quết mạnh tay theo một chiều trong 4 phút đến khi chả tôm dẻo dính có độ đàn hồi. Sau đó trộn thêm gừng băm, đầu hành trắng và lòng trắng trứng gà (nếu dùng) vào quyện đều.', NULL, 4),
('imp-2d508cd359edb61c_v4_step_3', 'imp-2d508cd359edb61c', 3, 'prep', 'Xếp đậu phụ trứng và tạo hình tôm hấp', 'Cắt ống đậu phụ trứng thành 12 khoanh tròn dày đều nhau khoảng 2 cm, xếp gọn lên đĩa sâu lòng chịu nhiệt. Dùng muỗng múc khoảng 1 muỗng canh chả tôm đắp lên bề mặt mỗi khoanh đậu phụ và ấn nhẹ ở giữa cho chả bám chắc vào miếng đậu.', NULL, NULL),
('imp-2d508cd359edb61c_v4_step_4', 'imp-2d508cd359edb61c', 4, 'cook', 'Hấp chín đậu phụ tôm trong xửng nóng', 'Đun sôi nước trong xửng hấp trên lửa lớn, đặt đĩa đậu phụ tôm vào xửng, đậy kín nắp và hấp liên tục trong 10 phút cho đến khi chả tôm chuyển màu hồng cam tươi, săn chắc chín hoàn toàn bên trong và đậu phụ trứng nóng đều.', 'Chỉ đặt đĩa vào khi nước trong xửng đã sôi mạnh để chả tôm se mặt nhanh, giữ trọn vị ngọt và tránh đọng quá nhiều nước.', 10),
('imp-2d508cd359edb61c_v4_step_5', 'imp-2d508cd359edb61c', 5, 'sauce', 'Nấu sốt xì dầu dầu hào sánh mượt', 'Trong lúc chờ hấp, khuấy đều trong chén nhỏ 120 ml nước lọc, 10 ml xì dầu nhạt, 6 ml dầu hào, 3 g bột bắp còn lại, 2 g đường cát trắng và phần tiêu trắng xay còn lại. Đổ hỗn hợp vào chảo nhỏ, đun lửa vừa và khuấy liên tục 2 phút đến khi sốt trong bóng, sánh nhẹ thì tắt bếp và khuấy thêm 4 ml dầu mè thơm.', NULL, 2),
('imp-2d508cd359edb61c_v4_step_6', 'imp-2d508cd359edb61c', 6, 'finish', 'Chắt nước hấp, rưới sốt và thưởng thức', 'Lấy đĩa đậu phụ hấp tôm ra khỏi xửng, nhẹ tay nghiêng đĩa chắt bỏ phần nước tiết ra khi hấp để món ăn không bị loãng vị. Rưới đều phần sốt nóng sánh bóng lên từng khoanh đậu phụ tôm, rắc lá hành xanh thái nhỏ lên mặt và dùng nóng ngay với cơm trắng.', 'Chắt sạch nước tiết ra sau khi hấp giúp lớp sốt rưới bám đậm đà và giữ trọn vị béo thơm của đậu phụ trứng.', NULL),
('imp-6eaf6ed6d417c52c_v4_step_1', 'imp-6eaf6ed6d417c52c', 1, 'prep', 'Sơ chế mực tươi và ướp khử tanh', 'Làm sạch 450 g mực ống tươi, cắt khoanh hoặc miếng vừa ăn và khía vằn nhẹ mặt trong. Có thể ướp mực với 15 ml rượu Thiệu Hưng trong 10 phút rồi dùng khăn giấy thấm thật khô ráo bề mặt mực. Băm nhuyễn tỏi khô, gừng tươi và ớt hiểm cùng ớt sừng đỏ; thái nhỏ hành lá tươi.', 'Thấm thật khô mực trước khi nhúng bột là yếu tố quyết định giúp lớp vỏ bám chắc và không bị bắn dầu khi chiên.', 10),
('imp-6eaf6ed6d417c52c_v4_step_2', 'imp-6eaf6ed6d417c52c', 2, 'prep', 'Pha bột ướt và trộn lớp bột khô', 'Trong tô vừa, khuấy tan 50 g bột mì đa dụng với 70 ml nước lọc, 2 g muối ăn và 1 g tiêu đen xay thành hỗn hợp bột ướt sánh mịn. Trong đĩa rộng khác, trộn đều 35 g bột mì đa dụng còn lại cùng 35 g bột bắp và 1,5 g bột nở Baking soda.', NULL, NULL),
('imp-6eaf6ed6d417c52c_v4_step_3', 'imp-6eaf6ed6d417c52c', 3, 'prep', 'Áo hai lớp bột cho từng miếng mực', 'Trút mực đã thấm khô vào tô bột ướt đảo đều cho bột áo mỏng khắp bề mặt, sau đó gắp từng miếng mực lăn kỹ qua đĩa bột khô để tạo lớp áo tơi mịn. Xếp thưa các miếng mực đã áo bột ra khay phẳng, tránh chồng lên nhau gây bết dính.', 'Áo bột từng mẻ và xếp thưa nhau giúp lớp bột khô tơi xốp khi tiếp xúc với dầu nóng.', NULL),
('imp-6eaf6ed6d417c52c_v4_step_4', 'imp-6eaf6ed6d417c52c', 4, 'cook', 'Chiên ngập dầu mực vàng giòn', 'Đun nóng 500 ml dầu ăn thực vật trong chảo sâu lòng đến khoảng 180°C (thả đầu đũa thấy sủi tăm mạnh). Chia mực thành 2–3 mẻ nhỏ rồi thả vào chiên lửa vừa lớn khoảng 2–3 phút mỗi mẻ đến khi lớp vỏ phồng vàng giòn và thịt mực chín trắng săn bên trong. Vớt mực ra giá lưới cho ráo dầu.', 'Không cho quá nhiều mực vào chiên cùng lúc để tránh làm tụt nhiệt độ dầu khiến lớp vỏ bị ngấm dầu và mềm ỉu.', 3),
('imp-6eaf6ed6d417c52c_v4_step_5', 'imp-6eaf6ed6d417c52c', 5, 'cook', 'Phi thơm tỏi, gừng và ớt băm', 'Chắt hết dầu chiên ra tô riêng, chỉ chừa lại khoảng 1 muỗng canh dầu nóng tráng mặt chảo. Hạ lửa vừa, cho tỏi băm, gừng băm và ớt băm vào đảo nhanh khoảng 1 phút cho dậy mùi thơm lừng mà không để tỏi cháy sậm.', NULL, 1),
('imp-6eaf6ed6d417c52c_v4_step_6', 'imp-6eaf6ed6d417c52c', 6, 'finish', 'Xóc mực với muối tiêu, hành lá và dọn nóng', 'Trút toàn bộ mực chiên giòn và hành lá tươi thái nhỏ vào chảo, rắc 1 g muối ăn và 1 g tiêu đen xay còn lại rồi xóc đảo nhanh tay trong 20–30 giây cho tỏi ớt và muối tiêu bám đều khắp miếng mực. Tắt bếp, bày ngay ra đĩa và dùng nóng giòn.', NULL, NULL),
('imp-d90dc5bbe2891a12_v4_step_1', 'imp-d90dc5bbe2891a12', 1, 'prep', 'Rang sơ gạo và sơ chế gừng hành', 'Vo sạch 220 g gạo tẻ thơm rồi để thật ráo nước. Cho gạo vào chảo khô rang trên lửa vừa khoảng 5 phút đến khi hạt gạo săn lại, đục đều và hơi thơm nhẹ. Trong lúc đó, gọt vỏ gừng tươi thái sợi chỉ mỏng, thái lát mỏng hành tím khô và thái nhỏ hành lá tươi.', 'Rang gạo trước khi nấu giúp hạt gạo nhanh nở bung đều và nước cháo sánh mịn thơm ngon hơn mà không bị vữa.', 5),
('imp-d90dc5bbe2891a12_v4_step_2', 'imp-d90dc5bbe2891a12', 2, 'marinate', 'Ướp thịt heo xay mềm tơi', 'Cho 200 g thịt heo xay vào tô, ướp cùng 15 ml xì dầu, 3 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn thực vật. Trộn đều rồi để ướp trong 15 phút cho thịt ngấm vị và giữ được độ mềm ẩm.', NULL, 15),
('imp-d90dc5bbe2891a12_v4_step_3', 'imp-d90dc5bbe2891a12', 3, 'cook', 'Ninh gạo với hành tím đến khi cháo sánh nhừ', 'Đun sôi 1800 ml nước lọc trong nồi lớn, đổ gạo đã rang và hành tím khô thái lát vào khuấy đều. Khi nước sôi lại, hạ lửa nhỏ, đậy vung hé và ninh liu riu khoảng 30 phút cho đến khi hạt gạo nở bung mềm mịn; thỉnh thoảng khuấy đều đáy nồi để cháo không bị khét.', 'Có thể châm thêm 100–150 ml nước sôi nếu thấy cháo sánh đặc hơn sở thích trong quá trình ninh.', 30),
('imp-d90dc5bbe2891a12_v4_step_4', 'imp-d90dc5bbe2891a12', 4, 'cook', 'Thả thịt heo xay và nấu chín kỹ', 'Khi cháo đã đạt độ sánh mịn, cho từng ít thịt heo xay đã ướp vào nồi đồng thời dùng vá khuấy liên tục để thịt rã tơi đều, không bị vón cục. Nấu tiếp trên lửa nhỏ 8–10 phút đến khi thịt chín kỹ hoàn toàn và quyện ngọt vào nước cháo.', 'Cho thịt bằm vào từng ít một kết hợp khuấy đều tay ngay lập tức là cách giúp thịt tơi mịn hoàn toàn trong nồi cháo.', 9),
('imp-d90dc5bbe2891a12_v4_step_5', 'imp-d90dc5bbe2891a12', 5, 'cook', 'Nêm gia vị và tạo vân trứng gà mượt', 'Nêm vào nồi cháo 10 ml xì dầu còn lại, 3 g muối ăn và 3 g hạt nêm còn lại, khuấy đều rồi nếm lại vừa miệng. Đánh tan 2 quả trứng gà trong chén, giữ nồi cháo sôi lăn tăn rồi rót trứng từ từ theo dòng mỏng đồng thời khuấy nhẹ một chiều khoảng 1–2 phút để tạo vân trứng mịn đẹp và chín đều.', NULL, 2),
('imp-d90dc5bbe2891a12_v4_step_6', 'imp-d90dc5bbe2891a12', 6, 'finish', 'Chia tô cùng gừng sợi và thưởng thức nóng', 'Tắt bếp. Xếp gừng tươi thái sợi chỉ vào đáy từng tô trước rồi múc cháo nóng hổi phủ lên trên để gừng dậy mùi cay ấm tự nhiên. Rắc hành lá thái nhỏ, 1 g tiêu đen xay còn lại và rưới 5 ml dầu mè thơm lên mặt, trộn đều ăn nóng ngay.', NULL, NULL),
('imp-b23ab24915e52866_v4_step_1', 'imp-b23ab24915e52866', 1, 'prep', 'Sơ chế nhân tôm thịt, lạp xưởng và rau củ', 'Ướp 150 g tôm tươi bóc vỏ thái hạt lựu với 1 g muối ăn, 1 g đường cát trắng và 0,5 g tiêu đen xay; ướp 100 g thịt heo xay với 2 g hạt nêm và 0,5 g tiêu đen xay trong 10 phút. Luộc chín 60 g lạp xưởng Quảng Đông trong 5 phút rồi để nguội, thái hạt lựu. Cà rốt và đậu cô ve thái hạt lựu, luộc sơ với 2 g muối ăn trong 2 phút rồi vớt ngâm nước lạnh và để ráo.', NULL, 10),
('imp-b23ab24915e52866_v4_step_2', 'imp-b23ab24915e52866', 2, 'prep', 'Trộn cơm vàng và tráng trứng cắt hạt lựu', 'Đánh tơi 600 g cơm trắng nguội. Tách 1 lòng đỏ trứng gà trộn đều vào cơm cùng 5 ml xì dầu nhạt và 1 g hạt nêm cho từng hạt cơm ánh vàng. Phần trứng gà còn lại đánh tan với 1 g hạt nêm, tráng chín vàng hai mặt trên chảo với 10 ml dầu ăn thực vật trong 3 phút rồi gắp ra thái hạt lựu.', 'Trộn lòng đỏ trứng vào cơm nguội trước khi chiên giúp từng hạt cơm tơi rời và lên màu vàng óng đều rất đẹp.', 3),
('imp-b23ab24915e52866_v4_step_3', 'imp-b23ab24915e52866', 3, 'cook', 'Xào chín tôm, thịt bằm và lạp xưởng', 'Làm nóng 10 ml dầu ăn thực vật trong chảo lớn, phi thơm một nửa tỏi khô băm rồi cho tôm vào xào nhanh lửa lớn 2 phút đến khi tôm chuyển hồng săn chắc hoàn toàn, trút ra đĩa. Tiếp tục cho thịt heo xay vào đảo tơi 2 phút cho chín đều, thả lạp xưởng thái hạt lựu vào đảo thêm 1 phút cho dậy mùi rồi trút chung ra đĩa.', 'Xào riêng từng nguyên liệu rồi mới trộn chung ở cuối giúp tôm giữ độ giòn ngọt và lạp xưởng không bị cháy xém.', 5),
('imp-b23ab24915e52866_v4_step_4', 'imp-b23ab24915e52866', 4, 'cook', 'Rang cơm tơi săn trên lửa lớn', 'Làm nóng 20 ml dầu ăn thực vật còn lại, phi thơm phần tỏi băm còn lại rồi cho cà rốt và đậu cô ve vào đảo 1 phút. Trút toàn bộ cơm đã trộn trứng vào chảo, đảo đều liên tục trên lửa lớn khoảng 5 phút cho đến khi hạt cơm nóng săn, tơi ráo và hơi nhảy nhẹ trên mặt chảo.', 'Giữ lửa lớn và đảo đều tay liên tục giúp cơm tơi giòn bên ngoài mà bên trong vẫn giữ được độ dẻo mềm.', 5),
('imp-b23ab24915e52866_v4_step_5', 'imp-b23ab24915e52866', 5, 'cook', 'Trộn quyện nhân thập cẩm và nêm gia vị', 'Cho toàn bộ tôm, thịt heo xay, lạp xưởng và trứng chiên cắt hạt lựu trở lại chảo cơm. Nêm 10 ml xì dầu nhạt còn lại, 2 g hạt nêm còn lại, 3 g đường cát trắng và phần tiêu đen xay còn lại, đảo đều thêm 2 phút cho mọi nguyên liệu quyện nóng đậm đà.', NULL, 2),
('imp-b23ab24915e52866_v4_step_6', 'imp-b23ab24915e52866', 6, 'finish', 'Rắc hành lá và trình bày nóng', 'Rắc hành lá tươi thái nhỏ vào chảo cơm, đảo nhanh thêm 20 giây cho hành dậy mùi thơm rồi tắt bếp. Múc cơm chiên Dương Châu ra đĩa, rắc thêm chút tiêu xay nếu thích và dùng nóng ngay.', NULL, NULL),
('imp-e83f58ebb9b02fbd_v4_step_1', 'imp-e83f58ebb9b02fbd', 1, 'prep', 'Rang giã hoa tiêu và sơ chế nguyên liệu', 'Rang khô 2 g hoa tiêu Tứ Xuyên trên chảo lửa nhỏ khoảng 2–3 phút đến khi dậy hương thơm rồi giã nhuyễn thành bột mịn. Băm thật nhuyễn tỏi khô; thái nhỏ hành lá tươi; giã dập 20 g đậu phộng rang; rửa sạch cải thìa tươi và chẻ đôi gốc.', NULL, 3),
('imp-e83f58ebb9b02fbd_v4_step_2', 'imp-e83f58ebb9b02fbd', 2, 'sauce', 'Pha sốt trộn Đan Đan vào 2 tô', 'Chia đều vào 2 tô ăn mì các gia vị gồm: 15 g sốt tương mè Tahini, 15 ml xì dầu nhạt, 2 g đường cát trắng, 1 g ngũ vị hương, bột hoa tiêu Tứ Xuyên vừa giã, 20 ml dầu ớt Tứ Xuyên, 6 ml dầu mè thơm, 10 ml giấm đen Trấn Giang, tỏi băm và một nửa hành lá thái nhỏ.', 'Pha sốt trực tiếp ở đáy tô giúp sợi mì nóng khi vớt vào sẽ dễ dàng quyện đều gia vị từ dưới lên.', NULL),
('imp-e83f58ebb9b02fbd_v4_step_3', 'imp-e83f58ebb9b02fbd', 3, 'cook', 'Xào thịt heo băm khô săn đậm vị', 'Đun nóng 10 ml dầu ăn thực vật trong chảo trên lửa vừa, trút 120 g thịt heo xay vào dùng sạn dằm tơi và xào khoảng 4–5 phút đến khi thịt săn vàng đều. Nêm 15 ml rượu Thiệu Hưng, 5 ml xì dầu đặc, 10 ml xì dầu nhạt còn lại và 2 g đường cát trắng còn lại, tiếp tục đảo 3 phút cho đến khi nước cạn ráo và thịt chín khô thơm. Tắt bếp để riêng.', 'Xào thịt đến khi cạn ráo hoàn toàn chất lỏng giúp thịt tơi giòn, dậy mùi xì dầu cháy cạnh đặc trưng cho mì Đan Đan.', 7),
('imp-e83f58ebb9b02fbd_v4_step_4', 'imp-e83f58ebb9b02fbd', 4, 'cook', 'Luộc mì và chần xanh cải thìa', 'Đun sôi 800 ml nước lọc trong nồi lớn, thả 200 g mì sợi lúa mì khô vào luộc khoảng 3–4 phút (hoặc theo hướng dẫn bao bì) đến khi sợi mì vừa chín dai. Trong 45 giây cuối, thả toàn bộ cải thìa tươi vào chần chung cho chín xanh giòn. Trước khi vớt, múc giữ lại 60 ml nước luộc mì nóng.', NULL, 4),
('imp-e83f58ebb9b02fbd_v4_step_5', 'imp-e83f58ebb9b02fbd', 5, 'finish', 'Hòa loãng sốt và xếp mì vào tô', 'Rót 30 ml nước luộc mì nóng vào mỗi tô sốt, khuấy kỹ cho sốt tương mè Tahini tan sánh mượt. Vớt mì cho vào tô, xếp cải thìa chần lên cạnh bên và múc thịt heo xào thơm phủ lên trên.', 'Nước luộc mì nóng giúp tương mè tan mịn ngay lập tức và tạo độ bóng mượt cho nước trộn.', NULL),
('imp-e83f58ebb9b02fbd_v4_step_6', 'imp-e83f58ebb9b02fbd', 6, 'finish', 'Rắc đậu phộng, hành lá và trộn đều thưởng thức', 'Rắc đậu phộng rang giã dập và phần hành lá tươi còn lại lên mặt mỗi tô mì. Dùng đũa trộn thật đều từ đáy tô trước khi thưởng thức nóng.', NULL, NULL),
('imp-04d477399e49fe8e_v4_step_1', 'imp-04d477399e49fe8e', 1, 'marinate', 'Thái lát và ướp mềm thịt bò kiểu Quảng Đông', 'Thấm khô 300 g thịt bò thăn, thái lát mỏng 2–3 mm ngang thớ thịt. Trộn đều thịt bò với 2 g Baking soda, 10 ml xì dầu nhạt, 10 g bột bắp, 1 g tiêu trắng xay, 10 ml dầu ăn thực vật và 15 ml nước lọc; để ướp 20 phút cho thịt mềm mọng. Pha sẵn chén sốt gồm 15 ml xì dầu nhạt còn lại, 8 ml xì dầu đặc, 20 ml dầu hào, 15 ml rượu Thiệu Hưng, 6 g đường cát trắng, 1 g tiêu trắng xay còn lại và 30 ml nước lọc.', 'Thái ngang thớ kết hợp ướp baking soda và bột bắp là bí quyết giúp thịt bò mềm mượt như ngoài hàng.', 20),
('imp-04d477399e49fe8e_v4_step_2', 'imp-04d477399e49fe8e', 2, 'prep', 'Sơ chế rau và luộc trụng mì trứng', 'Rửa sạch để ráo giá đỗ tươi và đậu Hà Lan quả ngọt đã tước xơ; cắt khúc 5 cm hành lá tươi tách riêng đầu trắng và lá xanh; băm nhỏ tỏi khô. Đun sôi 1000 ml nước lọc với 2 g muối ăn, thả 300 g mì trứng sợi dai vào luộc 2–3 phút đến khi vừa chín tới còn độ dai, vớt ra xả ráo rồi trộn ngay với 5 ml dầu ăn thực vật cho tơi sợi.', NULL, 3),
('imp-04d477399e49fe8e_v4_step_3', 'imp-04d477399e49fe8e', 3, 'cook', 'Áp chảo xém vàng sợi mì trứng', 'Làm nóng chảo sâu lòng trên lửa lớn đến khi hơi bốc khói, tráng 10 ml dầu ăn thực vật rồi dàn đều mì trứng thành lớp mỏng, áp chảo khoảng 2 phút mỗi mặt đến khi sợi mì săn ráo và hơi xém vàng thơm, sau đó gắp mì ra đĩa riêng.', 'Áp chảo sơ giúp sợi mì săn chắc, không bị nát và dậy mùi thơm chảo nóng khi trộn sốt.', 4),
('imp-04d477399e49fe8e_v4_step_4', 'imp-04d477399e49fe8e', 4, 'cook', 'Xào nhanh thịt bò chín tái trên lửa lớn', 'Thêm 5 ml dầu ăn thực vật vào chảo đang nóng già, dàn đều thịt bò đã ướp vào giữ yên 20 giây rồi đảo nhanh tay trên lửa lớn 1–2 phút đến khi thịt bò săn tái khoảng 80%, lập tức trút ra đĩa riêng.', 'Chỉ xào bò vừa tái khoảng 80% rồi trút ra ngay để giữ độ mềm mọng, bò sẽ chín hoàn hảo khi đảo lại ở bước cuối.', 2),
('imp-04d477399e49fe8e_v4_step_5', 'imp-04d477399e49fe8e', 5, 'cook', 'Xào rau giòn và trộn quyện mì với sốt', 'Cho 5 ml dầu ăn thực vật còn lại vào chảo, phi thơm tỏi băm và đầu hành trắng 15 giây, thả đậu Hà Lan quả ngọt và giá đỗ tươi vào đảo nhanh lửa lớn 1 phút cho rau vừa chín giữ độ giòn. Trút mì trứng trở lại chảo, rưới đều chén sốt đã pha và đảo nhanh 1–2 phút cho mì ngấm đều màu nâu bóng.', NULL, 2),
('imp-04d477399e49fe8e_v4_step_6', 'imp-04d477399e49fe8e', 6, 'finish', 'Trộn thịt bò, hành lá và hoàn thiện', 'Cho thịt bò xào và phần lá hành xanh vào chảo, đảo đều thêm 30 giây trên lửa lớn để thịt bò chín hoàn toàn và nóng quyện cùng sợi mì. Tắt bếp, rưới 5 ml dầu mè thơm lên trên, đảo một lượt cuối và dọn nóng ra đĩa.', NULL, NULL),
('imp-a22f9257b0fd7a46_v4_step_1', 'imp-a22f9257b0fd7a46', 1, 'prep', 'Chần sơ nguyên tảng thịt ba chỉ', 'Cạo sạch phần bì của 800 g thịt ba chỉ heo nguyên tảng. Đun sôi 1000 ml nước lọc trong nồi lớn, thả nguyên tảng thịt vào chần nhanh trong 2 phút để loại bỏ tạp chất và giúp khối thịt săn chắc dễ cắt. Vớt ra xả sạch dưới vòi nước lạnh rồi thấm khô.', 'Chần nguyên tảng trước khi cắt giúp các khối thịt vuông vắn, không bị co méo lệch lạc.', 2),
('imp-a22f9257b0fd7a46_v4_step_2', 'imp-a22f9257b0fd7a46', 2, 'prep', 'Cắt khối vuông và buộc dây giữ dáng', 'Cắt tảng thịt thành 5–6 khối vuông kích thước khoảng 6–7 cm. Dùng dây lạt hoặc chỉ buộc thực phẩm quấn chữ thập chắc tay quanh từng khối thịt để thịt không bị vỡ nát trong suốt quá trình om lâu.', NULL, NULL),
('imp-a22f9257b0fd7a46_v4_step_3', 'imp-a22f9257b0fd7a46', 3, 'prep', 'Lót đáy nồi với hành lá và gừng lát', 'Xếp toàn bộ hành lá tươi cắt khúc lót kín đều khắp đáy nồi đất hoặc nồi gang thành dày, rải đều 40 g gừng tươi thái lát lên trên. Đặt từng khối thịt ba chỉ với mặt bì úp xuống dưới xếp khít nhau trên lớp hành gừng.', 'Lớp hành lá dày dưới đáy vừa chống cháy khét phần bì suốt nhiều giờ om, vừa giúp phần thịt thấm hương thơm ngọt tự nhiên.', NULL),
('imp-a22f9257b0fd7a46_v4_step_4', 'imp-a22f9257b0fd7a46', 4, 'cook', 'Đổ rượu xì dầu và om liu riu lần một', 'Rưới đều 360 ml rượu Thiệu Hưng, 150 ml xì dầu nhạt và 35 ml xì dầu đặc lên thịt, thả 80 g đường phèn cùng hoa hồi khô, quế thanh khô và lá nguyệt quế khô (nếu dùng) vào. Đậy nắp kín, đun lửa vừa lớn cho đến khi sôi rồi lập tức hạ lửa nhỏ nhất, om liu riu 90 phút.', NULL, 90),
('imp-a22f9257b0fd7a46_v4_step_5', 'imp-a22f9257b0fd7a46', 5, 'cook', 'Lật mặt bì ngửa lên và om mềm tan', 'Mở nắp, nhẹ tay lật từng khối thịt cho mặt bì hướng lên trên để mặt bì bóng đẹp không bị bở. Đậy nắp kín lại và tiếp tục om lửa nhỏ thêm 75–90 phút nữa đến khi phần mỡ trong như thạch và xiên đũa qua thịt dễ dàng; nếu nước kho cạn quá nửa thì châm thêm ít nước lọc đun sôi.', 'Tuyệt đối chỉ châm thêm nước sôi nếu nước kho cạn, vì nước lạnh sẽ làm thớ thịt bị co cứng lại.', 80),
('imp-a22f9257b0fd7a46_v4_step_6', 'imp-a22f9257b0fd7a46', 6, 'finish', 'Cô sánh nước sốt và hoàn thiện', 'Nhẹ nhàng gắp các khối thịt ra đĩa sâu lòng, dùng kéo cắt bỏ dây buộc. Lọc phần nước kho trong nồi qua rây bỏ xác hành gừng, vớt bỏ thật sạch lớp mỡ tiết ra nổi trên mặt; trích khoảng một nửa lượng nước kho (phần nước kho mặn còn lại chắt bỏ hoặc giữ riêng làm nước nền) đun sôi trên lửa vừa khoảng 5 phút cho cô sánh lại vừa đủ phủ bóng mặt muỗng rồi rưới đều lên các khối thịt. Dùng nóng với cơm trắng.', NULL, 5),
('imp-5f8d0890bd6d0a76_v4_step_1', 'imp-5f8d0890bd6d0a76', 1, 'prep', 'Sơ chế củ năng, cải thảo và gừng hành', 'Đập dập rồi băm nhuyễn 100 g củ năng tươi (hoặc đóng hộp) để giữ độ giòn sần sật. Rửa sạch cải thảo tươi, cắt khúc dài 5–6 cm. Gọt vỏ 20 g gừng tươi: băm nhuyễn 10 g để trộn thịt và thái lát mỏng 10 g còn lại; hành lá tươi băm nhuyễn 1/3 để trộn thịt, phần còn lại cắt khúc 5 cm tách riêng đầu trắng và lá xanh.', NULL, NULL),
('imp-5f8d0890bd6d0a76_v4_step_2', 'imp-5f8d0890bd6d0a76', 2, 'marinate', 'Quết dẻo thịt heo với gia vị và củ năng', 'Trộn 450 g thịt heo xay với gừng băm, hành lá băm, 1 quả trứng gà, 25 g bột chiên xù khô, 15 ml rượu Thiệu Hưng, 15 ml xì dầu nhạt, 12 ml dầu hào, 1,5 g tiêu trắng xay, 1 g ngũ vị hương (nếu dùng), 5 g bột bắp và 60 ml nước lọc. Dùng tay quết mạnh theo một chiều khoảng 10 phút đến khi thịt dẻo quánh nhạt màu rồi trộn tiếp củ năng băm thêm 3 phút.', 'Quết thịt thật kỹ theo một chiều giúp viên thịt cỡ lớn có độ đàn hồi chắc chắn mà bên trong vẫn mềm xốp.', 13),
('imp-5f8d0890bd6d0a76_v4_step_3', 'imp-5f8d0890bd6d0a76', 3, 'cook', 'Vo 4 viên lớn và chiên vàng định hình', 'Thoa chút dầu ăn thực vật lên tay, chia thịt thành 4 phần đều nhau và vo thành 4 viên tròn lớn láng mịn. Đun nóng khoảng 385 ml dầu ăn thực vật trong nồi nhỏ đến 175°C, thả từng viên thịt vào chiên lửa vừa lớn khoảng 3 phút đến khi bề mặt vàng đều định hình chắc chắn thì vớt ra để ráo dầu.', 'Chiên nhanh ở nhiệt độ cao chỉ để tạo lớp vỏ vàng định hình, giúp viên thịt giữ nguyên dáng tròn đẹp khi kho lâu.', 3),
('imp-5f8d0890bd6d0a76_v4_step_4', 'imp-5f8d0890bd6d0a76', 4, 'cook', 'Phi thơm gừng hành và nấu nước kho', 'Làm nóng 15 ml dầu ăn thực vật trong chảo trên lửa nhỏ, phi thơm 10 g gừng thái lát và đầu hành trắng 1 phút, thả 10 g đường phèn vào đảo nhẹ đến khi đường tan hết. Đổ vào 15 ml rượu Thiệu Hưng, 20 ml xì dầu nhạt, 3 ml xì dầu đặc, 13 ml dầu hào, 1,5 g muối ăn (tùy khẩu vị) và 350 ml nước dùng gà, đun sôi nhẹ.', NULL, 3),
('imp-5f8d0890bd6d0a76_v4_step_5', 'imp-5f8d0890bd6d0a76', 5, 'cook', 'Kho mềm viên thịt trên lớp cải thảo', 'Xếp toàn bộ cải thảo tươi cắt khúc lót xuống đáy nồi đất hoặc nồi dày, đặt 4 viên thịt lên trên rồi chan toàn bộ nước kho nóng vào nồi. Đậy nắp kín, kho liu riu trên lửa nhỏ trong 18–20 phút (lật nhẹ viên thịt một lần giữa chừng) cho đến khi viên thịt chín mềm hoàn toàn bên trong và cải thảo ngấm ngọt.', 'Giữ lửa nhỏ sôi liu riu giúp cải thảo chín mềm mà không bị nhũn nát và viên thịt thấm sâu vị kho.', 18),
('imp-5f8d0890bd6d0a76_v4_step_6', 'imp-5f8d0890bd6d0a76', 6, 'finish', 'Sánh nước sốt, rưới dầu mè và hoàn thiện', 'Gắp cải thảo và 4 viên Sư Tử Đầu ra đĩa sâu lòng. Hòa tan 3 g bột bắp còn lại với 15 ml nước lọc, rót vào phần nước kho trong nồi và khuấy 2–3 phút trên lửa vừa đến khi sốt sánh bóng bám lưng muỗng. Tắt bếp, khuấy 3 ml dầu mè thơm và phần lá hành xanh vào rồi rưới đều sốt lên các viên thịt, dùng nóng với cơm trắng.', NULL, 3),
('imp-ece7da4660b63e9d_v4_step_1', 'imp-ece7da4660b63e9d', 1, 'prep', 'Thái thịt bò và sơ chế cà chua cùng gia vị thơm', 'Thấm thật khô thịt bò thăn bằng khăn giấy rồi thái lát mỏng ngang thớ dày khoảng 5–6 mm. Cà chua chín đỏ rửa sạch, bỏ cuống, bổ múi cau vừa ăn. Tỏi bóc vỏ băm nhỏ; gừng tươi thái lát mỏng; hành tím thái lát mỏng; hành lá cắt khúc 5 cm, tách riêng phần đầu trắng và phần lá xanh.', 'Thái thịt bò ngang thớ và giữ lát thịt đều độ dày giúp thịt chín đồng đều trong vài chục giây mà không bị dai.', NULL),
('imp-ece7da4660b63e9d_v4_step_2', 'imp-ece7da4660b63e9d', 2, 'marinate', 'Ướp mềm thịt bò theo kỹ thuật giữ ẩm', 'Cho thịt bò vào tô cùng 15 ml nước lọc, 6 g bột bắp và 1,2 g baking soda, trộn đều tay cho đến khi thịt hút hết nước. Tiếp tục thêm 10 ml dầu hào và 5 ml dầu ăn để khóa ẩm, trộn đều rồi ướp tối thiểu 20–30 phút trong ngăn mát tủ lạnh.', 'Kết hợp baking soda với nước và bột bắp giúp phá nhẹ cấu trúc sợi cơ và tạo lớp màng giữ nước, giữ thịt bò mềm mượt sau khi xào lửa lớn.', 25),
('imp-ece7da4660b63e9d_v4_step_3', 'imp-ece7da4660b63e9d', 3, 'sauce', 'Pha sẵn nước sốt và hỗn hợp bột bắp làm sánh', 'Trộn đều 22 ml xì dầu nhạt, 4 g đường cát trắng, 2,5 ml dầu mè và 0,5 g tiêu trắng xay trong một chén nhỏ cho tan hết gia vị. Ở chén khác, hòa tan 3 g bột bắp còn lại với 15 ml nước lọc rồi để sẵn cạnh bếp.', NULL, NULL),
('imp-ece7da4660b63e9d_v4_step_4', 'imp-ece7da4660b63e9d', 4, 'cook', 'Áp chảo sơ thịt bò trên lửa lớn', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn đến khi dầu nóng già và hơi gợn khói. Dàn thịt bò thành một lớp mỏng đều khắp mặt chảo, áp chảo khoảng 1 phút cho mặt thịt săn tái rồi đảo nhanh thêm 20 giây đến khi bò chín khoảng 80%, lập tức trút ra tô để riêng.', 'Không xào thịt bò chín kỹ ở bước này vì thịt sẽ tiếp tục chín khi đảo chung với sốt cà chua ở cuối.', 2),
('imp-ece7da4660b63e9d_v4_step_5', 'imp-ece7da4660b63e9d', 5, 'cook', 'Phi thơm gừng, tỏi, hành và xào nền cà chua', 'Cho 15 ml dầu ăn còn lại vào chảo trên lửa vừa, thả gừng tươi vào phi 10 giây cho xém cạnh thơm lừng. Tăng lên lửa lớn, cho tỏi băm, hành tím và đầu hành trắng vào đảo nhanh 10 giây, tiếp tục cho 22 ml tương cà (và 15 g cà chua cô đặc nếu dùng) vào xào 30 giây cho dậy màu đỏ đẹp. Thả cà chua múi cau vào đảo 15 giây rồi rưới 10 ml rượu Thiệu Hưng quanh thành chảo nóng.', NULL, 2),
('imp-ece7da4660b63e9d_v4_step_6', 'imp-ece7da4660b63e9d', 6, 'finish', 'Hòa sốt, đảo quyện thịt bò và làm sánh hoàn thiện', 'Gạt nhẹ cà chua sang một bên chảo, đổ chén nước sốt đã pha vào khoảng trống, đun sôi lăn tăn cho vị hòa quyện. Trút thịt bò (kèm cả nước tiết ra trong tô) trở lại chảo, đảo đều trên lửa lớn khoảng 30 giây cho thịt bò chín hẳn bên trong nhưng vẫn mềm mọng. Cho phần lá xanh hành lá vào, khuấy đều chén bột bắp rồi rưới từ từ vào chảo đến khi sốt sánh bóng bám đều miếng thịt, đun thêm 15 giây cho bột chín, nêm thêm 1,5 g muối ăn vừa miệng rồi dọn nóng ngay.', 'Đảo nhẹ tay ở bước cuối để miếng cà chua vẫn giữ nguyên múi đẹp mắt và không bị nát nhừ.', NULL),
('imp-b9d222a8c523b8e4_v4_step_1', 'imp-b9d222a8c523b8e4', 1, 'prep', 'Đập dập và cắt miếng dưa leo', 'Rửa sạch 3 quả dưa leo tươi, lau khô vỏ bằng khăn sạch rồi cắt bỏ hai đầu. Đặt mặt phẳng bản dao lớn nằm ngang lên từng quả dưa, dùng lòng bàn tay ấn vỗ dứt khoát cho thân dưa nứt tách làm 4 dải dài nhưng không bị nát vụn. Dựng các dải dưa lên rồi cắt chéo góc 45 độ thành miếng vừa ăn dài khoảng 3 cm.', 'Đập dập tạo các mép vỡ gồ ghề giúp nước sốt bám sâu vào thịt dưa hơn hẳn so với cách thái lát phẳng thông thường.', NULL),
('imp-b9d222a8c523b8e4_v4_step_2', 'imp-b9d222a8c523b8e4', 2, 'marinate', 'Ướp muối rút bớt nước giúp dưa giòn lâu', 'Cho dưa leo vào tô lớn, rắc đều 6 g muối ăn vào xóc nhẹ rồi để yên 15–20 phút cho dưa tiết bớt nước hăng. Sau khi ướp, chắt bỏ toàn bộ phần nước muối đã tiết ra và vắt nhẹ tay để miếng dưa ráo hẳn.', 'Nếu thử thấy miếng dưa hơi đậm vị muối, có thể tráng thật nhanh qua nước đun sôi để nguội rồi thấm khô trước khi trộn sốt.', 20);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-b9d222a8c523b8e4_v4_step_3', 'imp-b9d222a8c523b8e4', 3, 'prep', 'Băm tỏi, thái ớt và rang thơm mè trắng', 'Trong lúc chờ ướp dưa, băm nhuyễn tỏi khô và thái lát mỏng ớt hiểm đỏ. Bắc chảo khô lên bếp lửa nhỏ, cho hạt mè trắng vào đảo đều khoảng 2 phút đến khi mè ngả vàng thơm thì trút ra chén để nguội. Nếu dùng tiêu Tứ Xuyên, rang cùng mè khoảng 30 giây cho dậy mùi rồi giã dập.', NULL, 3),
('imp-b9d222a8c523b8e4_v4_step_4', 'imp-b9d222a8c523b8e4', 4, 'sauce', 'Pha hỗn hợp nước sốt giấm đen Tứ Xuyên', 'Trong một chén vừa, hòa tan 20 ml xì dầu nhạt, 30 ml giấm đen Trấn Giang và 12 g đường cát trắng, khuấy đều tay cho đến khi đường tan hoàn toàn. Tiếp tục rót 15 ml dầu mè và 15 ml dầu ớt Tứ Xuyên vào khuấy hòa quyện.', 'Khuấy tan hết đường trước khi trộn vào dưa giúp vị chua, ngọt, mặn phân bố đồng đều trên từng miếng dưa leo.', NULL),
('imp-b9d222a8c523b8e4_v4_step_5', 'imp-b9d222a8c523b8e4', 5, 'cook', 'Trộn dưa leo với tỏi ớt và nước sốt', 'Cho tỏi băm, ớt hiểm thái lát và tiêu Tứ Xuyên giã dập (nếu dùng) vào tô dưa leo đã ráo nước. Rưới toàn bộ chén nước sốt lên trên, dùng đũa hoặc tay đeo găng trộn nhẹ nhàng từ dưới lên trong 1 phút cho từng miếng dưa áo đều gia vị.', NULL, NULL),
('imp-b9d222a8c523b8e4_v4_step_6', 'imp-b9d222a8c523b8e4', 6, 'finish', 'Ướp lạnh ngắn, rắc mè rang và thưởng thức', 'Đậy kín tô dưa rồi ướp trong ngăn mát tủ lạnh khoảng 10–15 phút cho dưa ngấm sốt và giòn mát. Gắp dưa ra đĩa, rưới thêm phần nước sốt dưới đáy tô, rắc hạt mè trắng rang và ngò rí thái khúc lên trên rồi dùng ngay.', 'Không nên trộn sốt trước quá lâu vì muối và giấm sẽ tiếp tục làm dưa ra nước khiến món ăn bị nhũn và loãng vị.', NULL),
('imp-51f6c12eefee914d_v4_step_1', 'imp-51f6c12eefee914d', 1, 'prep', 'Sơ chế bắp cải, nấm kim châm và cắt đậu phụ', 'Tách rời lá bắp cải trắng, cắt miếng vuông vừa ăn, rửa sạch rồi để ráo hoàn toàn. Nấm kim châm cắt bỏ phần gốc rễ, tách thành từng cụm nhỏ, rửa nhẹ tay và để ráo. Đậu phụ trắng thấm khô bề mặt, cắt thành miếng vuông dày khoảng 3–4 cm. Tỏi băm nhỏ, hành lá cắt khúc 2–3 cm.', 'Thấm thật khô miếng đậu phụ trước khi chiên để không bị bắn dầu và giúp lớp vỏ ngoài nhanh vàng giòn.', NULL),
('imp-51f6c12eefee914d_v4_step_2', 'imp-51f6c12eefee914d', 2, 'cook', 'Chiên vàng các mặt đậu phụ', 'Đun nóng 40 ml dầu ăn trong chảo chống dính trên lửa vừa. Nhẹ nhàng xếp từng miếng đậu phụ vào chảo, chiên mỗi mặt khoảng 2–3 phút đến khi vàng giòn đều các mặt thì gắp ra đĩa lót giấy thấm dầu, chắt bớt phần dầu dư trong chảo chỉ chừa lại khoảng 1 muỗng canh.', 'Chiên vàng mặt đậu trước khi kho tạo lớp vỏ dai nhẹ, giúp đậu giữ nguyên miếng không bị nát và hút nước kho tốt hơn.', 6),
('imp-51f6c12eefee914d_v4_step_3', 'imp-51f6c12eefee914d', 3, 'cook', 'Phi thơm tỏi và xào sơ nấm cùng bắp cải', 'Sử dụng phần dầu còn lại trong chảo trên lửa vừa, cho tỏi băm vào phi khoảng 30 giây cho dậy mùi thơm vàng. Thả nấm kim châm vào đảo nhanh 1 phút cho săn lại, tiếp tục cho bắp cải vào đảo đều thêm 2 phút trên lửa lớn để rau áo lớp dầu thơm.', NULL, 3),
('imp-51f6c12eefee914d_v4_step_4', 'imp-51f6c12eefee914d', 4, 'sauce', 'Nêm gia vị và om mềm bắp cải', 'Cho 25 ml xì dầu nhạt, 5 ml xì dầu đặc, 15 ml dầu hào chay, 5 g đường cát trắng, 3 g muối ăn, 4 g hạt nêm chay và 150 ml nước lọc vào chảo. Đảo đều cho gia vị hòa tan, đậy nắp và hạ lửa nhỏ đun khoảng 6–8 phút cho bắp cải chín mềm và tiết nước ngọt.', 'Không nên đổ quá nhiều nước ngay từ đầu vì bắp cải và nấm kim châm sẽ tiết thêm nước trong quá trình đun.', 7),
('imp-51f6c12eefee914d_v4_step_5', 'imp-51f6c12eefee914d', 5, 'cook', 'Kho đậu phụ thấm đẫm nước sốt', 'Xếp phần đậu phụ đã chiên vàng vào chảo bắp cải, dùng vá nhẹ nhàng đảo đều để đậu ngập trong phần nước kho. Tiếp tục kho liu riu thêm 4–5 phút cho đậu phụ phồng mềm và thấm sâu hương vị nước tương.', NULL, 5),
('imp-51f6c12eefee914d_v4_step_6', 'imp-51f6c12eefee914d', 6, 'finish', 'Hoàn thiện với tiêu đen, dầu mè và hành lá', 'Nêm nếm lại nước kho cho vừa khẩu vị, rưới 5 ml dầu mè thơm, rắc 1 g tiêu đen xay và hành lá cắt khúc lên mặt chảo rồi tắt bếp. Dọn món ăn ra đĩa sâu lòng và dùng nóng với cơm trắng.', NULL, NULL),
('imp-6d3fa354c64cf8b1_v4_step_1', 'imp-6d3fa354c64cf8b1', 1, 'prep', 'Thấm thật khô cá, khía mình và phủ bột bắp mỏng', 'Làm sạch hoàn toàn vảy, mang và màng đen trong bụng cá rô phi. Dùng khăn giấy thấm thật khô cả bên ngoài lẫn trong bụng cá, dùng dao sắc khía 3 đường chéo song song trên mỗi bên thân cá. Nếu thích, xát nhẹ 1,5 g muối ăn và 1 g tiêu trắng xay vào mình cá rồi phủ một lớp 6 g bột bắp thật mỏng đều khắp hai mặt.', 'Thấm cá thật khô và chỉ phủ lớp bột bắp thật mỏng là bí quyết giúp da cá vàng giòn, không bị dính và tróc da khi áp chảo.', NULL),
('imp-6d3fa354c64cf8b1_v4_step_2', 'imp-6d3fa354c64cf8b1', 2, 'cook', 'Phi thơm gừng tươi chống dính chảo', 'Làm nóng chảo sâu lòng lớn trên lửa lớn đến khi mặt chảo hơi bốc khói, đổ 45 ml dầu ăn và thả 6 lát gừng tươi vào rồi hạ xuống lửa vừa. Phi gừng khoảng 1 phút cho dậy mùi thơm và các lát gừng chuyển vàng nhẹ thì gắp gừng ra chén để riêng.', 'Chà nhẹ mặt chảo bằng gừng và dầu nóng giúp tạo lớp chống dính tự nhiên, rất hiệu quả khi chiên cá nguyên con.', NULL),
('imp-6d3fa354c64cf8b1_v4_step_3', 'imp-6d3fa354c64cf8b1', 3, 'cook', 'Áp chảo mặt thứ nhất của cá không đảo lật sớm', 'Nhẹ nhàng đặt con cá vào chảo dầu nóng trên lửa vừa. Giữ nguyên vị trí cá, tuyệt đối không đẩy hay lật cá trong 5 phút đầu tiên; chỉ thỉnh thoảng nghiêng nhẹ chảo cho dầu láng đều quanh thân cá để mặt dưới chín vàng giòn.', 'Nếu xê dịch cá khi da chưa chín giòn, lớp da rất dễ bám chặt vào đáy chảo và bị rách.', 5),
('imp-6d3fa354c64cf8b1_v4_step_4', 'imp-6d3fa354c64cf8b1', 4, 'cook', 'Lật mặt và áp chảo vàng đều mặt còn lại', 'Sau 5 phút, lắc nhẹ chảo để kiểm tra cá đã tự róc khỏi đáy. Dùng hai xẻng rộng bản nhẹ nhàng lật cá sang mặt còn lại và tiếp tục áp chảo trên lửa vừa thêm 5 phút nữa đến khi hai mặt da cá vàng đều đẹp mắt.', NULL, 5),
('imp-6d3fa354c64cf8b1_v4_step_5', 'imp-6d3fa354c64cf8b1', 5, 'sauce', 'Rưới rượu Thiệu Hưng, giấm đen và nước tương kho cá', 'Cho gừng đã phi trở lại chảo cùng hành lá cắt khúc (thêm tỏi thái lát và ớt hiểm đỏ nếu dùng). Rưới đều 120 ml rượu Thiệu Hưng, 35 ml giấm đen Trấn Giang, 15 ml xì dầu đặc, 15 ml xì dầu nhạt và 25 g đường cát trắng quanh mình cá, giữ lửa vừa cho hỗn hợp sôi bùng lên rồi hạ lửa vừa-nhỏ.', NULL, NULL),
('imp-6d3fa354c64cf8b1_v4_step_6', 'imp-6d3fa354c64cf8b1', 6, 'finish', 'Om sánh sốt, rưới đều hai mặt và dọn nóng', 'Liên tục dùng muôi múc nước sốt rưới đều lên thân cá, kho mỗi mặt khoảng 4–5 phút đến khi nước sốt cạn sánh lại gần như siro và thịt cá ở phần dày nhất tách róc dễ dàng khỏi xương. Nhẹ nhàng gắp cá ra đĩa lớn, rưới toàn bộ phần sốt nâu đỏ óng ánh lên trên và dùng nóng với cơm trắng.', 'Tránh lật trở cá quá nhiều lần khi kho để giữ nguyên hình dáng đẹp mắt; thay vào đó hãy múc nước sốt rưới liên tục lên thân cá.', 9),
('imp-03577e7fa7667ab8_v4_step_1', 'imp-03577e7fa7667ab8', 1, 'prep', 'Sơ chế đậu phụ, nấm đùi gà, cà rốt và đánh tan trứng', 'Cắt đậu phụ trắng thành miếng vuông hoặc thanh mảnh cỡ 1,5 cm; thái sợi mỏng nấm đùi gà và cà rốt. Gừng tươi thái sợi chỉ, tỏi băm nhỏ, ớt hiểm đỏ thái lát và hành lá thái nhỏ. Đập 2 quả trứng gà vào chén, đánh tan đều. Hòa tan 20 g bột bắp với 60 ml nước lọc lạnh để sẵn.', NULL, NULL),
('imp-03577e7fa7667ab8_v4_step_2', 'imp-03577e7fa7667ab8', 2, 'sauce', 'Pha chén gia vị giấm đen và tiêu trắng', 'Trong một chén nhỏ, trộn đều 45 ml giấm đen Trấn Giang, 15 ml xì dầu, 5 g đường cát trắng, 4 g muối ăn và 3 g tiêu trắng xay; khuấy kỹ cho đường và muối tan hoàn toàn, để riêng cho bước hoàn thiện.', 'Chuẩn bị sẵn hỗn hợp gia vị và chỉ cho giấm vào lúc tắt bếp giúp giữ nguyên vị chua thanh và mùi thơm đặc trưng của giấm đen.', NULL),
('imp-03577e7fa7667ab8_v4_step_3', 'imp-03577e7fa7667ab8', 3, 'cook', 'Nấu sôi nước dùng gà với gừng, tỏi, nấm và cà rốt', 'Đổ 1,2 lít nước dùng gà vào nồi lớn, đun sôi trên lửa lớn rồi thả gừng sợi và tỏi băm vào nấu 2 phút cho thơm. Tiếp tục cho cà rốt và nấm đùi gà thái sợi vào, hạ lửa vừa nấu thêm 5 phút cho rau nấm chín mềm và tiết vị ngọt.', NULL, 7),
('imp-03577e7fa7667ab8_v4_step_4', 'imp-03577e7fa7667ab8', 4, 'cook', 'Thả đậu phụ và tạo độ sánh mượt cho súp', 'Nhẹ nhàng thả đậu phụ trắng vào nồi súp, nấu thêm 3 phút trên lửa vừa và tránh khuấy mạnh làm vỡ đậu. Khuấy đều lại chén bột bắp rồi rót từ từ từng chút vào nồi, vừa rót vừa khuấy nhẹ theo vòng tròn đến khi nước súp sánh mượt vừa ý.', 'Khuấy đều lại chén bột bắp ngay trước khi rót vào nồi để tinh bột không bị lắng cặn làm súp bị vón.', 3),
('imp-03577e7fa7667ab8_v4_step_5', 'imp-03577e7fa7667ab8', 5, 'cook', 'Kéo vân trứng gà tơ mềm trong nước sôi mạnh', 'Tăng lên lửa lớn cho nồi súp sôi bùng trở lại. Đưa chén trứng gà đánh tan lên cao, rót thành dòng thật mỏng vào nồi trong khi tay còn lại khuấy nhẹ theo một chiều để tạo thành những dải vân trứng tơ mỏng đẹp mắt.', 'Nước súp phải đang sôi mạnh mới giúp trứng định hình ngay thành từng sợi mảnh thay vì bị đục nước hay vón cục lớn.', NULL),
('imp-03577e7fa7667ab8_v4_step_6', 'imp-03577e7fa7667ab8', 6, 'finish', 'Tắt bếp, nêm giấm đen và hoàn thiện tô canh', 'Tắt bếp ngay sau khi kéo vân trứng, đổ chén hỗn hợp giấm đen gia vị vào khuấy nhẹ cho hòa quyện. Thêm 5 ml dầu mè thơm và ớt hiểm đỏ thái lát, nếm lại để cân bằng vị chua cay mặn ngọt, múc ra tô lớn rồi rắc hành lá lên trên để dùng nóng.', NULL, NULL),
('imp-62ebe8dd18b15b5e_v4_step_1', 'imp-62ebe8dd18b15b5e', 1, 'prep', 'Làm sạch, khía hoa mực và sơ chế gừng hành', 'Rút bỏ phần đầu, túi mực, mắt, răng và lột sạch lớp màng tím ngoài ống mực ống tươi rồi rửa sạch. Mở phẳng thân mực, dùng dao nghiêng lưỡi khía ca-rô mặt trong không đứt da rồi cắt miếng chữ nhật 3x4 cm; phần râu cắt khúc vừa ăn. Gừng chia 10 g thái lát, 20 g thái sợi; hành lá cắt khúc tách trắng và xanh; tỏi băm nhỏ; cà rốt thái sợi nếu dùng.', 'Lột sạch lớp màng tím giúp mực sau khi xào trắng đẹp, giòn ngọt và hoàn toàn không bị tanh.', NULL),
('imp-62ebe8dd18b15b5e_v4_step_2', 'imp-62ebe8dd18b15b5e', 2, 'cook', 'Chần sơ mực với nước gừng sôi để giữ độ giòn', 'Đun sôi một nồi nước nhỏ, thả 10 g gừng thái lát vào trước rồi trút toàn bộ mực vào chần nhanh đúng 15–20 giây đến khi từng miếng mực vừa cuộn cong lại. Vớt ngay mực ra ngâm nhanh vào nước lạnh hoặc để ráo hoàn toàn trên rổ.', 'Chỉ chần mực thật nhanh để mực cuộn hoa và rút bớt nước, tránh chần lâu khiến mực bị ra nước và dai khi xào tiếp.', 1),
('imp-62ebe8dd18b15b5e_v4_step_3', 'imp-62ebe8dd18b15b5e', 3, 'sauce', 'Pha sẵn chén nước sốt dầu hào bột bắp', 'Trộn đều 22 ml rượu Thiệu Hưng, 22 ml xì dầu nhạt, 22 ml dầu hào, 5 ml xì dầu đặc, 6 g đường cát trắng, 2,3 g tiêu đen xay, 5 g bột bắp và 25 ml nước lọc (thêm 4 g hạt nêm và 1,5 g muối ăn nếu muốn đậm vị). Khuấy kỹ đến khi đường và bột bắp tan hoàn toàn.', NULL, NULL),
('imp-62ebe8dd18b15b5e_v4_step_4', 'imp-62ebe8dd18b15b5e', 4, 'cook', 'Phi thơm gừng sợi, tỏi và xào nhanh rau củ', 'Đặt chảo sâu lòng lên bếp lửa lớn nhất, đổ 30 ml dầu ăn vào đun đến khi dầu nóng già hơi bốc khói nhẹ. Thả 20 g gừng thái sợi, tỏi băm và phần đầu hành trắng vào phi thơm khoảng 20 giây, tiếp tục cho cà rốt thái sợi (nếu dùng) vào đảo nhanh 1 phút cho vừa chín giòn.', NULL, 1),
('imp-62ebe8dd18b15b5e_v4_step_5', 'imp-62ebe8dd18b15b5e', 5, 'cook', 'Xào nhanh mực trên lửa lớn với nước sốt', 'Trút mực đã ráo nước vào chảo, đảo đều tay trên lửa lớn nhất khoảng 45–60 giây cho đến khi thịt mực săn trắng hoàn toàn và chín đều. Khuấy đều lại chén sốt rồi rưới thẳng vào chảo, đảo liên tục trong 20 giây cho đến khi sốt sánh bóng bám đều lên từng miếng mực.', 'Luôn giữ lửa lớn và khuấy lại chén sốt ngay trước khi rưới để bột bắp không bị lắng cặn dưới đáy chén.', 1),
('imp-62ebe8dd18b15b5e_v4_step_6', 'imp-62ebe8dd18b15b5e', 6, 'finish', 'Thêm phần xanh hành lá và dọn nóng', 'Thả phần lá xanh hành lá vào chảo, đảo nhanh thêm 10 giây cho hành vừa chín tái giữ màu xanh mướt rồi tắt bếp ngay. Trút mực xào gừng hành ra đĩa và thưởng thức nóng cùng cơm trắng.', NULL, NULL);
